INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90400, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "把事情写在书或文件里。", "primary_collocate": null, "pronunciation": "jì zǎi", "ipa": "tɕi˥˩ tsaɪ˨˩˦", "syllable_count": 2, "sentences": [{"text": "这本书里记载着很多老故事。", "target_word": "记载", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "历史书记载了这件事。", "target_word": "记载", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "爷爷把家里的事记载在本子上。", "target_word": "记载", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师说，书上没有记载过这个人。", "target_word": "记载", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "报纸上都记载了这个城市的变化。", "target_word": "记载", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "古书记载，这里以前有一条大河。", "target_word": "记载", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "医生把病人的情况记载在文件里。", "target_word": "记载", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这份文件详细记载了每天的花费。", "target_word": "记载", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "书上记载的名字，我一个也不认识。", "target_word": "记载", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这座桥的故事，书里早就记载了。", "target_word": "记载", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "记载了", "label": "体标"}, {"form": "记载着", "label": "体标"}, {"form": "记载过", "label": "体标"}], "register": "书面语", "sense_fingerprint": "把事情写进书或文件", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7a2fe6d8-52b1-452f-96cb-d31675d4d84f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90400, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "记载", "is_correct": true, "explanation": "正确。“记载”指把事情写在书里，与“这本书里”和“老故事”相符。"}, {"text": "修补", "is_correct": false, "explanation": "语义：“修补”的对象是破损的东西，不能用来说书里的故事。"}, {"text": "播放", "is_correct": false, "explanation": "搭配：书本不会“播放”，“播放”不能与“这本书里”搭配。"}, {"text": "烹饪", "is_correct": false, "explanation": "语义：“烹饪”指做饭做菜，与书里的故事毫无关系。"}], "explanations": {"记载": "正确。“记载”指把事情写在书里，与“这本书里”和“老故事”相符。", "修补": "语义：“修补”的对象是破损的东西，不能用来说书里的故事。", "播放": "搭配：书本不会“播放”，“播放”不能与“这本书里”搭配。", "烹饪": "语义：“烹饪”指做饭做菜，与书里的故事毫无关系。"}, "sentence_index": 0, "correct_answer": "记载"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我要把他的样子永远记载在脑子里。", "explanation": "这里应该用〈记住〉。“记住”指留在脑子里，“记载”指写成文字，不能说“记载在脑子里”。"}, {"text": "这辆卡车记载了很多货物。", "explanation": "这里应该用〈装载〉。“装载”指把货物放到车船上，“记载”只表示把事情写下来。"}, {"text": "来宾在门口记载了雨伞。", "explanation": "这里应该用〈寄存〉。“寄存”指把物品暂时存放在别处，“记载”指写下事情，不能用于雨伞。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9e7b0af3-9608-4a9f-a53c-dff8ea87eee2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90400, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "记载", "is_correct": true, "explanation": "正确。“记载”指把情况写进文件，与“医生把病人的情况”相符。"}, {"text": "诊断", "is_correct": false, "explanation": "语义：“诊断”指判断病情，不是把情况写下来。"}, {"text": "治疗", "is_correct": false, "explanation": "搭配：“治疗”的对象是病，不能说“治疗情况”。"}, {"text": "检查", "is_correct": false, "explanation": "配价：“检查”不带“在文件里”这类处所补语，不能这样组句。"}], "explanations": {"记载": "正确。“记载”指把情况写进文件，与“医生把病人的情况”相符。", "诊断": "语义：“诊断”指判断病情，不是把情况写下来。", "治疗": "搭配：“治疗”的对象是病，不能说“治疗情况”。", "检查": "配价：“检查”不带“在文件里”这类处所补语，不能这样组句。"}, "sentence_index": 6, "correct_answer": "记载"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他记载了很多古董。", "explanation": "这里应该用〈收藏〉。“收藏”指把物品留下来，“记载”指把事情写下来，不用于说收集古董。"}, {"text": "工人们正在记载一座新桥。", "explanation": "这里应该用〈修建〉。“修建”指动工建造，“记载”指写下来，不能用于建造。"}, {"text": "老人向孩子们记载战争的故事。", "explanation": "这里应该用〈讲述〉。“讲述”是口头说，“记载”是写下来，不能对着人“记载”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9e7b0af3-9608-4a9f-a53c-dff8ea87eee2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90400, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他把这件事记载日记里。", "corrected_sentence": "他把这件事记载在日记里。", "error_description": "“记载”后的处所宾语前要加“在”，应说“记载在日记里”，不能省去“在”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9e7b0af3-9608-4a9f-a53c-dff8ea87eee2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90400, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这份报告详记载了事故经过。", "corrected_sentence": "这份报告详细记载了事故经过。", "error_description": "“详细”是双音词，修饰“记载”时不能拆开，应说“详细记载”，不能说“详记载”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9e7b0af3-9608-4a9f-a53c-dff8ea87eee2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
