INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90401, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "二次是第二回，不是第一回。", "primary_collocate": null, "pronunciation": "èr cì", "ipa": "aɚ˥˩ tsʰɨ˥˩", "syllable_count": 2, "sentences": [{"text": "这是我二次来北京，上次没逛够。", "target_word": "二次", "complexity_tier": "T3", "furigana": "èr cì", "sentence_source": "generated"}, {"text": "第一次我没去，第二次我就去了。", "target_word": "二次", "complexity_tier": "T3", "furigana": "èr cì", "sentence_source": "generated"}, {"text": "头一次太紧张，第二次就好多了。", "target_word": "二次", "complexity_tier": "T3", "furigana": "èr cì", "sentence_source": "generated"}, {"text": "她第二次参加比赛，拿了第一名。", "target_word": "二次", "complexity_tier": "T3", "furigana": "èr cì", "sentence_source": "generated"}, {"text": "这本书我看过一次，今天要再看第二次。", "target_word": "二次", "complexity_tier": "T3", "furigana": "èr cì", "sentence_source": "generated"}, {"text": "去一次不够，我想再去第二次。", "target_word": "二次", "complexity_tier": "T3", "furigana": "èr cì", "sentence_source": "generated"}, {"text": "医生二次检查了他的耳朵。", "target_word": "二次", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师说二次考试可以带词典。", "target_word": "二次", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他第二次打电话，妈妈才接。", "target_word": "二次", "complexity_tier": "T3", "furigana": "èr cì", "sentence_source": "generated"}, {"text": "第一次下雨我没带伞，第二次我带了伞。", "target_word": "二次", "complexity_tier": "T3", "furigana": "èr cì", "sentence_source": "generated"}], "morphological_forms": [{"form": "第二次", "label": "序数"}], "register": "口语", "sense_fingerprint": "第二回、第二遍（序数，口语里常单用）", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fa4685f5-ad94-4d17-9baf-c335d6e4d059') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90401, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "二次", "is_correct": true, "explanation": "正确：二次（èr cì）指第二回、第二遍。"}, {"text": "二册", "is_correct": false, "explanation": "cì（第四声）与 cè（第四声）韵母不同（i 与 e），意思是二册（两册）。"}, {"text": "二字", "is_correct": false, "explanation": "c 与 z 声母不同，意思是二字（两个字）。"}, {"text": "二至", "is_correct": false, "explanation": "c 与 zh 声母不同，意思是二至（夏至和冬至）。"}], "explanations": {"二次": "正确：二次（èr cì）指第二回、第二遍。", "二册": "cì（第四声）与 cè（第四声）韵母不同（i 与 e），意思是二册（两册）。", "二字": "c 与 z 声母不同，意思是二字（两个字）。", "二至": "c 与 zh 声母不同，意思是二至（夏至和冬至）。"}, "sentence_index": null, "correct_answer": "二次"}, "level_3": {"options": [{"text": "二次", "is_correct": true, "explanation": "正确：二次，第二回。句中“这是我二次来北京”表示第二次来。"}, {"text": "初次", "is_correct": false, "explanation": "语义：“初次”指第一次，与“上次没逛够”所说的之前去过的语境矛盾。"}, {"text": "首次", "is_correct": false, "explanation": "语义：“首次”指第一次，与“上次没逛够”所说的之前去过的语境矛盾。"}, {"text": "一次", "is_correct": false, "explanation": "搭配：“一次”作状语表示一趟完成，“这是我一次来北京”不成句。"}], "explanations": {"二次": "正确：二次，第二回。句中“这是我二次来北京”表示第二次来。", "初次": "语义：“初次”指第一次，与“上次没逛够”所说的之前去过的语境矛盾。", "首次": "语义：“首次”指第一次，与“上次没逛够”所说的之前去过的语境矛盾。", "一次": "搭配：“一次”作状语表示一趟完成，“这是我一次来北京”不成句。"}, "sentence_index": 0, "correct_answer": "二次"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "她参加比赛，拿了二次名。", "explanation": "这里应该用〈第二〉。二次指第二回，不用于表示名次，应说“第二名”。"}, {"text": "我的二次朋友很多，大家都很喜欢。", "explanation": "这里“二次”取“次要”之义，指不重要的朋友，与第二回的意思不符。"}, {"text": "这是我的二次名字，你记住了吗？", "explanation": "这里应该用〈别名〉。二次不表示人的名字或别称。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e4ce1f16-9a73-4f36-b888-2e2b9126069b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90401, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "二次", "is_correct": true, "explanation": "正确：二次，第二回。句中“医生二次检查”表示第二次检查。"}, {"text": "大声", "is_correct": false, "explanation": "搭配：“大声”多修饰说话、喊叫，不修饰“检查”，“医生大声检查了他的耳朵”不合常理。"}, {"text": "狠狠", "is_correct": false, "explanation": "语义：“狠狠”含凶狠、猛烈之意，与医生为病人诊查的语境相反。"}, {"text": "大肆", "is_correct": false, "explanation": "语义：“大肆”指放纵地、无所顾忌地进行，含贬义，与医生正常检查的语境不合。"}], "explanations": {"二次": "正确：二次，第二回。句中“医生二次检查”表示第二次检查。", "大声": "搭配：“大声”多修饰说话、喊叫，不修饰“检查”，“医生大声检查了他的耳朵”不合常理。", "狠狠": "语义：“狠狠”含凶狠、猛烈之意，与医生为病人诊查的语境相反。", "大肆": "语义：“大肆”指放纵地、无所顾忌地进行，含贬义，与医生正常检查的语境不合。"}, "sentence_index": 6, "correct_answer": "二次"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他的二次方法很有用。", "explanation": "这里“二次”取“派生”之义，指派生出的方法，与第二回的意思不符。"}, {"text": "我二次去北京，是第一次来。", "explanation": "这里应该用〈第一次〉。二次只表示第二回，不能用来指第一回。"}, {"text": "她二次获奖，这是她第一次拿奖。", "explanation": "这里应该用〈首次〉。二次表示第二回，不能用来指首次获奖。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e4ce1f16-9a73-4f36-b888-2e2b9126069b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90401, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这是我第二次个看这部电影。", "corrected_sentence": "这是我第二次看这部电影。", "error_description": "错误形式是“第二次个看”，正确形式是“第二次看”。“次”本身已是量词，“第二次”后面不能再加“个”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e4ce1f16-9a73-4f36-b888-2e2b9126069b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
