INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90402, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "由某一过程或事物派生出来的；次要的、间接的。", "primary_collocate": null, "pronunciation": "èr cì", "ipa": "aɚ˥˩ tsʰɨ˥˩", "syllable_count": 2, "sentences": [{"text": "这种垃圾会造成二次污染。", "target_word": "二次", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "旧衣服可以二次利用。", "target_word": "二次", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这种鱼要经过二次加工。", "target_word": "二次", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这些废料还要经过二次处理。", "target_word": "二次", "complexity_tier": "T3", "furigana": "èr cì", "sentence_source": "generated"}, {"text": "电力是二次能源。", "target_word": "二次", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这张照片需要二次编辑。", "target_word": "二次", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "二次装修会花很多钱。", "target_word": "二次", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请不要对病人造成二次伤害。", "target_word": "二次", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这些纸箱可以二次使用。", "target_word": "二次", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他的画是二次创作，不是原创。", "target_word": "二次", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "第二次", "label": "序数"}], "register": "中性", "sense_fingerprint": "作定语：派生的、次要的（二次污染、二次能源）", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fa4685f5-ad94-4d17-9baf-c335d6e4d059') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90402, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "二次", "is_correct": true, "explanation": "正确：二次（èr cì）指派生的、次要的。"}, {"text": "二册", "is_correct": false, "explanation": "cì（第四声）与 cè（第四声）韵母不同（i 与 e），意思是二册（两册）。"}, {"text": "二字", "is_correct": false, "explanation": "c 与 z 声母不同，意思是二字（两个字）。"}, {"text": "二至", "is_correct": false, "explanation": "c 与 zh 声母不同，意思是二至（夏至和冬至）。"}], "explanations": {"二次": "正确：二次（èr cì）指派生的、次要的。", "二册": "cì（第四声）与 cè（第四声）韵母不同（i 与 e），意思是二册（两册）。", "二字": "c 与 z 声母不同，意思是二字（两个字）。", "二至": "c 与 zh 声母不同，意思是二至（夏至和冬至）。"}, "sentence_index": null, "correct_answer": "二次"}, "level_3": {"options": [{"text": "二次", "is_correct": true, "explanation": "正确：二次，派生的。句中“造成二次污染”指污染是由前一过程派生的。"}, {"text": "清洁", "is_correct": false, "explanation": "语义：“清洁污染”自相矛盾，与“污染”的含义冲突。"}, {"text": "无害", "is_correct": false, "explanation": "语义：“无害污染”与“污染”的含义相反。"}, {"text": "干净", "is_correct": false, "explanation": "搭配：“干净”不能修饰“污染”，“干净污染”不成词组。"}], "explanations": {"二次": "正确：二次，派生的。句中“造成二次污染”指污染是由前一过程派生的。", "清洁": "语义：“清洁污染”自相矛盾，与“污染”的含义冲突。", "无害": "语义：“无害污染”与“污染”的含义相反。", "干净": "搭配：“干净”不能修饰“污染”，“干净污染”不成词组。"}, "sentence_index": 0, "correct_answer": "二次"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我买了一辆二次车。", "explanation": "这里应该用〈二手〉。二次表示派生、次要，不用来指已经用过的旧车。"}, {"text": "二次的他今天很努力。", "explanation": "这里“二次”取“次要”之义去修饰人，但“二次”只修饰事物或行为，不说“二次的人”。"}, {"text": "这家店卖二次衣服。", "explanation": "这里应该用〈旧货〉。二次表示派生、次要，不用来指旧货。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e4ce1f16-9a73-4f36-b888-2e2b9126069b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90402, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "二次", "is_correct": true, "explanation": "正确：二次，派生的、次要的。句中“二次装修”指在已有装修之后的再次装修。"}, {"text": "免费", "is_correct": false, "explanation": "语义：“免费装修”与“会花很多钱”的语境矛盾。"}, {"text": "便宜", "is_correct": false, "explanation": "语义：“便宜装修”与“会花很多钱”的语境矛盾。"}, {"text": "安静", "is_correct": false, "explanation": "搭配：“安静”不能修饰“装修”，“安静装修”不成词组。"}], "explanations": {"二次": "正确：二次，派生的、次要的。句中“二次装修”指在已有装修之后的再次装修。", "免费": "语义：“免费装修”与“会花很多钱”的语境矛盾。", "便宜": "语义：“便宜装修”与“会花很多钱”的语境矛盾。", "安静": "搭配：“安静”不能修饰“装修”，“安静装修”不成词组。"}, "sentence_index": 6, "correct_answer": "二次"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我家有一台二次冰箱。", "explanation": "这里应该用〈二手〉。二次表示派生、次要，不用来指已经用过的旧冰箱。"}, {"text": "二次的他没有来上课。", "explanation": "这里“二次”取“次要”之义去修饰人，但“二次”只修饰事物或行为，不说“二次的人”。"}, {"text": "他卖掉了一台二次洗衣机。", "explanation": "这里应该用〈旧的〉。二次表示派生、次要，不用来指使用过的旧物。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e4ce1f16-9a73-4f36-b888-2e2b9126069b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
