INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90411, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "通讯是人和人把消息传给对方，比如打电话、发信息。", "primary_collocate": null, "pronunciation": "tōng xùn", "ipa": "tʰʊŋ˥ ɕyn˥˩", "syllable_count": 2, "sentences": [{"text": "山里的通讯不太方便。", "target_word": "通讯", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "手机让通讯变得很快。", "target_word": "通讯", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这里的通讯很好，打电话没问题。", "target_word": "通讯", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他的工作和网络通讯有关。", "target_word": "通讯", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "下大雨以后，通讯断了。", "target_word": "通讯", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "电话是人们常用的通讯工具。", "target_word": "通讯", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "爷爷年轻时，通讯没有现在方便。", "target_word": "通讯", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "新的基站建好以后，这一带的通讯变得稳定了。", "target_word": "通讯", "complexity_tier": "T3", "furigana": "tōng xùn", "sentence_source": "generated"}, {"text": "地震后，这个地方的通讯停了两天。", "target_word": "通讯", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "现在的通讯很快，发信息一秒就到。", "target_word": "通讯", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "通讯录", "label": "复合词"}, {"form": "通讯工具", "label": "复合词"}], "register": "通用", "sense_fingerprint": "人与人之间打电话、发信息来传递消息", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7a2fe6d8-52b1-452f-96cb-d31675d4d84f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90411, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "通讯", "is_correct": true, "explanation": "正确：“通讯”指人与人之间传递消息，山里电话、网络不方便，所以说“通讯不太方便”。"}, {"text": "温度", "is_correct": false, "explanation": "搭配：“方便”用于交通、设施等，不能说温度方便。"}, {"text": "人口", "is_correct": false, "explanation": "语义：“人口”指人的数量，不能用“方便”来评价。"}, {"text": "河流", "is_correct": false, "explanation": "语义：“河流”是自然水体，不能说“不太方便”。"}], "explanations": {"通讯": "正确：“通讯”指人与人之间传递消息，山里电话、网络不方便，所以说“通讯不太方便”。", "温度": "搭配：“方便”用于交通、设施等，不能说温度方便。", "人口": "语义：“人口”指人的数量，不能用“方便”来评价。", "河流": "语义：“河流”是自然水体，不能说“不太方便”。"}, "sentence_index": 0, "correct_answer": "通讯"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "下大雨后，这段路的车辆通讯了半天才过去。", "explanation": "这里应该用〈通行〉。通行指车辆、行人能够通过，“通讯”指传递消息，不能用来说车辆能否通过。"}, {"text": "这条路的通讯很宽敞，两辆车能并排走。", "explanation": "这里应该用〈交通〉。交通指车辆、道路的运输，“通讯”指人与人之间传递消息，不能用来形容道路。"}, {"text": "我家离公司很远，每天通讯要一个小时。", "explanation": "这里应该用〈通勤〉。通勤指上下班往来，“通讯”指传递消息，不能用来说路上花的时间。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9e7b0af3-9608-4a9f-a53c-dff8ea87eee2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90411, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "通讯", "is_correct": true, "explanation": "正确：“通讯”指传递消息，爷爷年轻时的通讯条件不如现在，符合句意。"}, {"text": "年龄", "is_correct": false, "explanation": "语义：“年龄”指人的岁数，不能用“方便”来比较。"}, {"text": "身高", "is_correct": false, "explanation": "体貌：“身高”是人的外形特征，不能说“没有现在方便”。"}, {"text": "视力", "is_correct": false, "explanation": "搭配：“方便”不能用来形容视力。"}], "explanations": {"通讯": "正确：“通讯”指传递消息，爷爷年轻时的通讯条件不如现在，符合句意。", "年龄": "语义：“年龄”指人的岁数，不能用“方便”来比较。", "身高": "体貌：“身高”是人的外形特征，不能说“没有现在方便”。", "视力": "搭配：“方便”不能用来形容视力。"}, "sentence_index": 6, "correct_answer": "通讯"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这个通讯很窄，只能一个人走。", "explanation": "这里应该用〈通道〉。通道指可以通过的路，“通讯”指传递消息，不能用来形容路的宽窄。"}, {"text": "我们班这次全部通讯了考试。", "explanation": "这里应该用〈通过〉。通过指考试合格，“通讯”指传递消息，不能用来说考试及格。"}, {"text": "这篇通讯很长，我们读了一个小时。", "explanation": "这里应该用〈文章〉。文章指文字作品，“通讯”指人与人之间传递消息，不能用来指一篇文章。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9e7b0af3-9608-4a9f-a53c-dff8ea87eee2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90411, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我们用电话进行了一个通讯。", "corrected_sentence": "我们用电话进行了一次通讯。", "error_description": "量词错误：“通讯”作为一次交流时用量词“次”，应为“一次通讯”，不能说“一个通讯”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9e7b0af3-9608-4a9f-a53c-dff8ea87eee2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90411, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "天气好转以后，通讯变很顺畅。", "corrected_sentence": "天气好转以后，通讯变得很顺畅。", "error_description": "补语错误：“变”后应加补语标记“得”，应为“变得很顺畅”，“变很顺畅”不成立。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9e7b0af3-9608-4a9f-a53c-dff8ea87eee2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
