INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90423, 1, 'prompt1_core', '{"pos": "副词", "semantic_class": "function", "definition": "一块是大家在一起，一起做事。", "primary_collocate": null, "pronunciation": "yí kuài", "ipa": "i˧˥ kʰwai˥˩", "syllable_count": 2, "sentences": [{"text": "大家一块唱歌吧。", "target_word": "一块", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "我和哥哥一块打扫房间。", "target_word": "一块", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "老师和学生一块做游戏。", "target_word": "一块", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "今天晚上你跟我们一块吃吧。", "target_word": "一块", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "咱们一块想办法吧。", "target_word": "一块", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "同事们一块加班到很晚。", "target_word": "一块", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "一家人一块去海边玩儿。", "target_word": "一块", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "我们一块把房间收拾干净吧。", "target_word": "一块", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "周日他跟爸爸一块洗了车。", "target_word": "一块", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "她常和朋友一块跑步。", "target_word": "一块", "complexity_tier": "T1", "sentence_source": "generated"}], "morphological_forms": [{"form": "一块儿", "label": "儿化"}], "register": "口语", "sense_fingerprint": "副词：大家在一起，一起做事", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3e55a90f-bee7-49d4-adc2-7ec13ce55273') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90423, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "一块", "is_correct": true, "explanation": "正确：“一块”表示大家在一起，与“吧”的提议语气相合。"}, {"text": "曾经", "is_correct": false, "explanation": "语义：“曾经”指过去的经历，不能用于劝大家一起做事的句子。"}, {"text": "忽然", "is_correct": false, "explanation": "搭配：“忽然”表示突然发生，不能用于商量性的提议。"}, {"text": "故意", "is_correct": false, "explanation": "语义：“故意”表示有意而为，与大家一起唱歌的提议不符。"}], "explanations": {"一块": "正确：“一块”表示大家在一起，与“吧”的提议语气相合。", "曾经": "语义：“曾经”指过去的经历，不能用于劝大家一起做事的句子。", "忽然": "搭配：“忽然”表示突然发生，不能用于商量性的提议。", "故意": "语义：“故意”表示有意而为，与大家一起唱歌的提议不符。"}, "sentence_index": 0, "correct_answer": "一块"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他一块完成了工作。", "explanation": "这里应该用〈独自〉。“独自”指一个人做事，与“他”单独完成的意思相符；“一块”表示和别人一起，与此矛盾。"}, {"text": "他养了一块猫。", "explanation": "这里应该用〈只〉。猫用“只”作量词，“块”不能用来数猫。"}, {"text": "一块有五个人报名。", "explanation": "这里应该用〈总共〉。“一块”表示一起，不能表示人数的总数；数报名人数要用“总共”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '25231ecd-b38e-4013-b8b0-2f67ce0365af') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90423, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "一块", "is_correct": true, "explanation": "正确：“一块”表示一起去，与“一家人”的全家同行语境相符。"}, {"text": "独自", "is_correct": false, "explanation": "搭配：“独自”指一个人，与“一家人”的复数主语不符。"}, {"text": "白白", "is_correct": false, "explanation": "语义：“白白”表示徒劳无益，与“去海边玩儿”的休闲语境不合。"}, {"text": "猛然", "is_correct": false, "explanation": "语域：“猛然”是书面语的突然义副词，口语里说“一家人猛然去海边玩儿”很不自然。"}], "explanations": {"一块": "正确：“一块”表示一起去，与“一家人”的全家同行语境相符。", "独自": "搭配：“独自”指一个人，与“一家人”的复数主语不符。", "白白": "语义：“白白”表示徒劳无益，与“去海边玩儿”的休闲语境不合。", "猛然": "语域：“猛然”是书面语的突然义副词，口语里说“一家人猛然去海边玩儿”很不自然。"}, "sentence_index": 6, "correct_answer": "一块"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他一块考上了大学。", "explanation": "这里应该用〈居然〉。“一块”表示和别人一起做事，“他”一人考上大学不能用它；“居然”可直接修饰“考上”，表示意外。"}, {"text": "她买了一块鞋。", "explanation": "这里应该用〈双〉。鞋用“双”作量词，“块”不能用来数鞋。"}, {"text": "他买了一块房子。", "explanation": "这里应该用〈套〉。房子用“套”作量词，“块”不能用来数房子。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '25231ecd-b38e-4013-b8b0-2f67ce0365af') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
