INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90423, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "朋友们一块的看了比赛。", "corrected_sentence": "朋友们一块看了比赛。", "error_description": "错误形式：“一块的看”；正确形式：“一块看”。“一块”修饰动词作状语，后面不加“的”，“的”用于名词性定语。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '25231ecd-b38e-4013-b8b0-2f67ce0365af') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
