INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90424, 1, 'prompt1_core', '{"pos": "副词", "semantic_class": "function", "definition": "副词，表示在同一处所或一起做某事。", "primary_collocate": null, "pronunciation": "yí kuài", "ipa": "i˧˥ kʰwai˥˩", "syllable_count": 2, "sentences": [{"text": "我们一块去吃饭吧。", "target_word": "一块", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "明天你和我一块去公园。", "target_word": "一块", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "他们每天一块走路回家。", "target_word": "一块", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "周末我想跟朋友一块看电影。", "target_word": "一块", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "妈妈和我一块做了晚饭。", "target_word": "一块", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "下课以后，我们一块回宿舍。", "target_word": "一块", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "你去商店吗？我跟你一块去。", "target_word": "一块", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他和同学一块学习汉语。", "target_word": "一块", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "孩子们一块在院子里玩儿。", "target_word": "一块", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我们一块坐地铁去上班吧。", "target_word": "一块", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "一块儿", "label": "儿化"}], "register": "口语", "sense_fingerprint": "副词：在同一处所或一起做某事", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3e55a90f-bee7-49d4-adc2-7ec13ce55273') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90424, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "一块", "is_correct": true, "explanation": "正确：“一块”是副词，表示一起，与“吧”的建议语气相合。"}, {"text": "已经", "is_correct": false, "explanation": "语义：“已经”表示动作已经完成，与提议去吃饭的语气相矛盾。"}, {"text": "忽然", "is_correct": false, "explanation": "搭配：“忽然”表示突然发生，不能用于商量性的提议。"}, {"text": "故意", "is_correct": false, "explanation": "语义：“故意”表示有意为之，与一起吃饭的提议不符。"}], "explanations": {"一块": "正确：“一块”是副词，表示一起，与“吧”的建议语气相合。", "已经": "语义：“已经”表示动作已经完成，与提议去吃饭的语气相矛盾。", "忽然": "搭配：“忽然”表示突然发生，不能用于商量性的提议。", "故意": "语义：“故意”表示有意为之，与一起吃饭的提议不符。"}, "sentence_index": 0, "correct_answer": "一块"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我买了一块书。", "explanation": "这里应该用〈本〉。“一块”是用于块状物的量词，书应用“一本”，不能用“块”来数。"}, {"text": "一块有十个人参加。", "explanation": "这里应该用〈一共〉。“一块”表示一起做事，不能表示总数；说总人数要用“一共”。"}, {"text": "我有一块朋友。", "explanation": "这里应该用〈个〉。“朋友”用“个”作量词，“块”不能用来数人。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '25231ecd-b38e-4013-b8b0-2f67ce0365af') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90424, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "一块", "is_correct": true, "explanation": "正确：“一块”表示一起去，与“跟你”的同行意思相合。"}, {"text": "独自", "is_correct": false, "explanation": "语义：“独自”指单独一人，与“跟你”的同行意思矛盾。"}, {"text": "格外", "is_correct": false, "explanation": "搭配：“格外”表示程度超出，不能修饰同行的动作。"}, {"text": "猛然", "is_correct": false, "explanation": "语域：“猛然”是书面语的突然义副词，口语里说“我跟你猛然去”很不自然。"}], "explanations": {"一块": "正确：“一块”表示一起去，与“跟你”的同行意思相合。", "独自": "语义：“独自”指单独一人，与“跟你”的同行意思矛盾。", "格外": "搭配：“格外”表示程度超出，不能修饰同行的动作。", "猛然": "语域：“猛然”是书面语的突然义副词，口语里说“我跟你猛然去”很不自然。"}, "sentence_index": 6, "correct_answer": "一块"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他一块睡着了。", "explanation": "这里应该用〈一下子〉。“一块”表示大家共同做某事，需要多人一起；只有“他”一人时，表示很快地、突然地应说“一下子”。"}, {"text": "我买了一块衣服。", "explanation": "这里应该用〈件〉。衣服用“件”作量词，“块”不能用来数衣服。"}, {"text": "我们看了一块电影。", "explanation": "这里应该用〈部〉。电影用“部”作量词，“块”不能用来数电影。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '25231ecd-b38e-4013-b8b0-2f67ce0365af') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90424, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我们一块的去看电影吧。", "corrected_sentence": "我们一块去看电影吧。", "error_description": "错误形式：“一块的去看”；正确形式：“一块去看”。“一块”是副词，修饰动词时不加“的”，“的”用于名词性定语。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '25231ecd-b38e-4013-b8b0-2f67ce0365af') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
