INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90433, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "开办学校、公司等机构，使其从无到有地建立起来。", "primary_collocate": null, "pronunciation": "chuàng bàn", "ipa": "ʈʂʰuɑŋ˥˩ pan˥˩", "syllable_count": 2, "sentences": [{"text": "他二十岁就创办了一家公司。", "target_word": "创办", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这所学校是王先生创办的。", "target_word": "创办", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她想创办一家小书店。", "target_word": "创办", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我爷爷创办过一个小工厂。", "target_word": "创办", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这家医院是十年前创办的。", "target_word": "创办", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们打算创办一所新学校。", "target_word": "创办", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "谁创办了这家有名的公司？", "target_word": "创办", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她创办的咖啡店很受欢迎。", "target_word": "创办", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他和朋友一起创办了这家店。", "target_word": "创办", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师创办了一个中文学习班。", "target_word": "创办", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "创办了", "label": "完成体"}, {"form": "创办过", "label": "经历体"}, {"form": "创办人", "label": "复合"}, {"form": "创办者", "label": "复合"}], "register": "中性", "sense_fingerprint": "首先办起学校、公司等机构", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fa4685f5-ad94-4d17-9baf-c335d6e4d059') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90433, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "创办", "is_correct": true, "explanation": "创办：开办公司，与“二十岁就”开始创业的语境相符。"}, {"text": "洗", "is_correct": false, "explanation": "搭配：“洗”不能以公司为宾语，“洗了一家公司”不成词组。"}, {"text": "倒闭", "is_correct": false, "explanation": "配价：倒闭是不及物动词，不能带“一家公司”作宾语。"}, {"text": "拆除", "is_correct": false, "explanation": "搭配：拆除多用于建筑物，公司不能被拆除。"}], "explanations": {"创办": "创办：开办公司，与“二十岁就”开始创业的语境相符。", "洗": "搭配：“洗”不能以公司为宾语，“洗了一家公司”不成词组。", "倒闭": "配价：倒闭是不及物动词，不能带“一家公司”作宾语。", "拆除": "搭配：拆除多用于建筑物，公司不能被拆除。"}, "sentence_index": 0, "correct_answer": "创办"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "工人们创办了这座大桥。", "explanation": "这里应该用〈建造〉。创办指开办学校、公司等机构，大桥是建造出来的实物，不能说创办。"}, {"text": "妈妈创办了一锅好汤。", "explanation": "这里应该用〈煮〉。创办用于机构或事业，做汤要用煮。"}, {"text": "厨师创办了一桌好菜。", "explanation": "这里应该用〈烧〉。创办是开办机构或事业，做菜要用烧。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e4ce1f16-9a73-4f36-b888-2e2b9126069b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90433, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "创办", "is_correct": true, "explanation": "创办：开办公司，与“谁……这家有名的公司”的问句相符。"}, {"text": "叫醒", "is_correct": false, "explanation": "语义：叫醒的对象是人，公司不能被叫醒。"}, {"text": "保修", "is_correct": false, "explanation": "搭配：保修用于产品的维修，公司不能被保修。"}, {"text": "绣", "is_correct": false, "explanation": "语义：绣是用针线做图案，公司不能被绣。"}], "explanations": {"创办": "创办：开办公司，与“谁……这家有名的公司”的问句相符。", "叫醒": "语义：叫醒的对象是人，公司不能被叫醒。", "保修": "搭配：保修用于产品的维修，公司不能被保修。", "绣": "语义：绣是用针线做图案，公司不能被绣。"}, "sentence_index": 6, "correct_answer": "创办"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "工人创办了一台新电脑。", "explanation": "这里应该用〈组装〉。电脑是组装而成的，创办指开办机构或事业，不说创办电脑。"}, {"text": "农民创办了一缸好酒。", "explanation": "这里应该用〈酿〉。酒要用酿造，创办用于机构或事业。"}, {"text": "他创办了一首好诗。", "explanation": "这里应该用〈写〉。写诗是创作作品，创办不能用于诗歌。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e4ce1f16-9a73-4f36-b888-2e2b9126069b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90433, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "她去年创办了过一家小书店。", "corrected_sentence": "她去年创办了一家小书店。", "error_description": "错误：“了”与“过”不能同用，表示经历要用“过”，应去掉“了”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e4ce1f16-9a73-4f36-b888-2e2b9126069b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90433, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "她没创办了公司。", "corrected_sentence": "她没创办过公司。", "error_description": "错误：“没”与“了”不能同用，表示没有过的经历要用“过”。应为“没创办过公司”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e4ce1f16-9a73-4f36-b888-2e2b9126069b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
