INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90434, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "开创并建立。", "primary_collocate": null, "pronunciation": "chuàng bàn", "ipa": "ʈʂʰuɑŋ˥˩ pan˥˩", "syllable_count": 2, "sentences": [{"text": "这位作家创办了一本杂志。", "target_word": "创办", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们创办了一个爱心基金会。", "target_word": "创办", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "学生们创办了一个读书会。", "target_word": "创办", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她创办的网站帮助了很多人。", "target_word": "创办", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "几位老人创办了社区合唱团。", "target_word": "创办", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个协会是谁创办的？", "target_word": "创办", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他回国后创办了自己的事业。", "target_word": "创办", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "学校创办了一份校报。", "target_word": "创办", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "大家决定创办一个环保小组。", "target_word": "创办", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这家基金会由几位老师创办，至今已有十年。", "target_word": "创办", "complexity_tier": "T3", "furigana": "zhè jiā jī jīn huì yóu jǐ wèi lǎo shī chuàng bàn zhì jīn yǐ yǒu shí nián", "sentence_source": "generated"}], "morphological_forms": [{"form": "创办了", "label": "完成体"}, {"form": "创办过", "label": "经历体"}, {"form": "创办人", "label": "复合"}, {"form": "创办者", "label": "复合"}], "register": "中性", "sense_fingerprint": "开创并建立杂志、基金会、协会、事业等", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fa4685f5-ad94-4d17-9baf-c335d6e4d059') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90434, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "创办", "is_correct": true, "explanation": "创办：开办杂志，与“作家”办刊的语境相符。"}, {"text": "吃掉", "is_correct": false, "explanation": "语义：吃掉是把食物咽下，杂志不能被吃掉。"}, {"text": "摘", "is_correct": false, "explanation": "搭配：摘多用于果实、花朵，杂志不能被摘。"}, {"text": "修剪", "is_correct": false, "explanation": "搭配：修剪用于树枝、头发，杂志不能被修剪。"}], "explanations": {"创办": "创办：开办杂志，与“作家”办刊的语境相符。", "吃掉": "语义：吃掉是把食物咽下，杂志不能被吃掉。", "摘": "搭配：摘多用于果实、花朵，杂志不能被摘。", "修剪": "搭配：修剪用于树枝、头发，杂志不能被修剪。"}, "sentence_index": 0, "correct_answer": "创办"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "公司创办了一款新软件。", "explanation": "这里应该用〈开发〉。软件是开发出来的，创办指开办机构或事业，不说创办软件。"}, {"text": "作者创办了一篇论文。", "explanation": "这里应该用〈撰写〉。论文是撰写出来的，创办不用于文章的写作。"}, {"text": "他在院子里创办了一棵树。", "explanation": "这里应该用〈种〉。树是种植的，创办不能用于植物。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e4ce1f16-9a73-4f36-b888-2e2b9126069b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90434, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "创办", "is_correct": true, "explanation": "创办：开创事业，与“回国后”的语境相符。"}, {"text": "哭泣", "is_correct": false, "explanation": "配价：哭泣是不及物动词，不能带“自己的事业”作宾语。"}, {"text": "烘焙", "is_correct": false, "explanation": "语义：“烘焙”指用火烤制食物，与事业无关。"}, {"text": "切开", "is_correct": false, "explanation": "语义：切开是把实物分割，事业不能被切开。"}], "explanations": {"创办": "创办：开创事业，与“回国后”的语境相符。", "哭泣": "配价：哭泣是不及物动词，不能带“自己的事业”作宾语。", "烘焙": "语义：“烘焙”指用火烤制食物，与事业无关。", "切开": "语义：切开是把实物分割，事业不能被切开。"}, "sentence_index": 6, "correct_answer": "创办"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "工人创办了一条路。", "explanation": "这里应该用〈修〉。路是修出来的，创办指开办机构或事业，不说创办一条路。"}, {"text": "她创办了一幅画。", "explanation": "这里应该用〈绘制〉。画是绘制出来的，创办指开办机构或事业，不能用于绘画作品。"}, {"text": "他创办了一首歌。", "explanation": "这里应该用〈录制〉。歌是录制出来的，创办指开办机构或事业，不能用于录音作品。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e4ce1f16-9a73-4f36-b888-2e2b9126069b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90434, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这位作家创办很成功，杂志销量很好。", "corrected_sentence": "这位作家创办得很成功，杂志销量很好。", "error_description": "错误：“创办”后表示程度的补语要用“得”连接，缺少“得”。应为“创办得很成功”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e4ce1f16-9a73-4f36-b888-2e2b9126069b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90434, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他正在创办了一个俱乐部，想让大家一起运动。", "corrected_sentence": "他正在创办一个俱乐部，想让大家一起运动。", "error_description": "错误：“正在”表示动作进行中，不能与“了”同用。应为“正在创办一个俱乐部”，去掉“了”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e4ce1f16-9a73-4f36-b888-2e2b9126069b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
