INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90439, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "让人或东西受到伤害、变坏。", "primary_collocate": null, "pronunciation": "wēi hài", "ipa": "weɪ˥ xaɪ˥˩", "syllable_count": 2, "sentences": [{"text": "抽烟会危害你的健康。", "target_word": "危害", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "污水危害了河里的鱼。", "target_word": "危害", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "长时间玩手机会危害眼睛。", "target_word": "危害", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这种虫子会危害树木。", "target_word": "危害", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "空气不好，会危害孩子的身体。", "target_word": "危害", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "太多的糖会危害牙齿。", "target_word": "危害", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "垃圾危害着海里的动物。", "target_word": "危害", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "吃太多这种药危害过不少人。", "target_word": "危害", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "吸烟不但危害自己，还危害别人。", "target_word": "危害", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "熬夜太多会危害心脏。", "target_word": "危害", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "危害了", "label": "体标"}, {"form": "危害着", "label": "体标"}, {"form": "危害过", "label": "体标"}], "register": "书面", "sense_fingerprint": "使人的身体或事物受到伤害、变坏", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '91fb0def-17e1-49a7-8369-e06c80e75a82') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90439, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "保护", "is_correct": false, "explanation": "语义：“保护”是保全，与“抽烟”损害健康的意思相反，“抽烟会保护你的健康”说不通。"}, {"text": "危害", "is_correct": true, "explanation": "“危害”指使健康受到伤害，与“抽烟”的后果相合。"}, {"text": "锻炼", "is_correct": false, "explanation": "搭配：“锻炼”的对象是身体或体能，不说“锻炼健康”，且与“抽烟”的语义不合。"}, {"text": "增进", "is_correct": false, "explanation": "语义：“增进”是促进、提高，与“抽烟”会使人受损的意思相反。"}], "explanations": {"保护": "语义：“保护”是保全，与“抽烟”损害健康的意思相反，“抽烟会保护你的健康”说不通。", "危害": "“危害”指使健康受到伤害，与“抽烟”的后果相合。", "锻炼": "搭配：“锻炼”的对象是身体或体能，不说“锻炼健康”，且与“抽烟”的语义不合。", "增进": "语义：“增进”是促进、提高，与“抽烟”会使人受损的意思相反。"}, "sentence_index": 0, "correct_answer": "危害"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他的话危害了我的感情。", "explanation": "这里应该用〈伤害〉。危害多指对健康、安全、利益等的严重损害，说“感情”要用伤害。"}, {"text": "他危害了我的排队位置，还要把我的秘密告诉老师。", "explanation": "这里应该用〈抢〉。危害指使人或东西受到伤害、变坏，排队位置被占走要用抢。"}, {"text": "他的一句话危害了我的好心情。", "explanation": "这里应该用〈破坏〉。危害多用于健康、安全、利益，“好心情”被扰乱要用破坏。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5e9b95af-f526-4674-ab65-567f5b1a2aea') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90439, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "喂养", "is_correct": false, "explanation": "搭配：“喂养”的施事应是养育者，不说“垃圾喂养动物”。"}, {"text": "危害", "is_correct": true, "explanation": "“危害”表示使动物受到伤害，与“垃圾”的坏作用相合。"}, {"text": "帮助", "is_correct": false, "explanation": "语义：“帮助”是有益的行为，与“垃圾”对海洋动物造成的伤害相反。"}, {"text": "收留", "is_correct": false, "explanation": "语义：“收留”指接纳并安置，垃圾不能收留动物。"}], "explanations": {"喂养": "搭配：“喂养”的施事应是养育者，不说“垃圾喂养动物”。", "危害": "“危害”表示使动物受到伤害，与“垃圾”的坏作用相合。", "帮助": "语义：“帮助”是有益的行为，与“垃圾”对海洋动物造成的伤害相反。", "收留": "语义：“收留”指接纳并安置，垃圾不能收留动物。"}, "sentence_index": 6, "correct_answer": "危害"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "堵车危害了我们的行程。", "explanation": "这里应该用〈妨碍〉。妨碍指阻挡或影响事情进行，危害指严重损害人、健康或安全，行程顺不顺要用妨碍。"}, {"text": "我不小心危害了你的生日。", "explanation": "这里应该用〈错过〉。危害指使人或东西受到伤害、变坏，生日是时间点，不能被危害，应说错过。"}, {"text": "我危害了你的休息，真抱歉。", "explanation": "这里应该用〈打扰〉。危害指造成严重损害，打扰指妨碍别人休息或安静，此处不能用危害。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5e9b95af-f526-4674-ab65-567f5b1a2aea') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90439, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这种农药会危害得鸟类。", "corrected_sentence": "这种农药会危害鸟类。", "error_description": "助词错误：“危害”后直接带宾语，不能加“得”，应说“这种农药会危害鸟类”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5e9b95af-f526-4674-ab65-567f5b1a2aea') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90439, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这种农药以后会危害过河里的鱼。", "corrected_sentence": "这种农药以后会危害河里的鱼。", "error_description": "错误：在将来时“以后会”之后加了“过”。“过”表示已经经历的动作，与将来的时间不合。应说“以后会危害河里的鱼”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5e9b95af-f526-4674-ab65-567f5b1a2aea') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
