INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90440, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5e9b95af-f526-4674-ab65-567f5b1a2aea') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90440, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "使受到损害；损害。", "primary_collocate": null, "pronunciation": "wēi hài", "ipa": "weɪ˥ xaɪ˥˩", "syllable_count": 2, "sentences": [{"text": "这种做法危害了公司的利益。", "target_word": "危害", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他的行为危害公共安全。", "target_word": "危害", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "假货危害消费者的权利。", "target_word": "危害", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "谁也不能做危害国家的事。", "target_word": "危害", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "坏消息危害了学校的名声。", "target_word": "危害", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "不要做危害别人利益的事。", "target_word": "危害", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这种行为会危害他人的生命安全。", "target_word": "危害", "complexity_tier": "T3", "furigana": "zhè zhǒng xíng wéi huì wēi hài tā rén de shēng mìng ān quán", "sentence_source": "generated"}, {"text": "乱扔垃圾危害城市的环境。", "target_word": "危害", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他说的话危害了朋友的名誉。", "target_word": "危害", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这种广告危害青少年的成长。", "target_word": "危害", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "危害了", "label": "体标"}, {"form": "危害着", "label": "体标"}, {"form": "危害过", "label": "体标"}], "register": "书面", "sense_fingerprint": "损害利益、安全、名誉等抽象事物", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '91fb0def-17e1-49a7-8369-e06c80e75a82') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90440, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "感动", "is_correct": false, "explanation": "配价：“感动”的对象应是人，“利益”不能被感动，句子说不通。"}, {"text": "危害", "is_correct": true, "explanation": "“危害”表示使利益受到损害，与“这种做法”的负面结果相合。"}, {"text": "遵守", "is_correct": false, "explanation": "搭配：“遵守”的对象是规则或法律，不说“遵守公司的利益”。"}, {"text": "欣赏", "is_correct": false, "explanation": "语义：“欣赏”是喜爱、赞赏，与“做法”损害公司利益的语境相反。"}], "explanations": {"感动": "配价：“感动”的对象应是人，“利益”不能被感动，句子说不通。", "危害": "“危害”表示使利益受到损害，与“这种做法”的负面结果相合。", "遵守": "搭配：“遵守”的对象是规则或法律，不说“遵守公司的利益”。", "欣赏": "语义：“欣赏”是喜爱、赞赏，与“做法”损害公司利益的语境相反。"}, "sentence_index": 0, "correct_answer": "危害"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他的话危害了朋友回家。", "explanation": "这里应该用〈妨碍〉。危害的对象是人、利益或安全，朋友回家这样的行为不能被危害，应说妨碍。"}, {"text": "他危害了朋友的秘密，还要说出去。", "explanation": "这里应该用〈泄露〉。危害指对利益、安全、名誉的损害，秘密被说出去要用泄露。"}, {"text": "堵车危害了我们的行程。", "explanation": "这里应该用〈妨碍〉。妨碍指阻挡或影响事情进行，危害指严重损害人或安全，行程的顺利与否要用妨碍。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5e9b95af-f526-4674-ab65-567f5b1a2aea') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90440, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "思考", "is_correct": false, "explanation": "语义：“思考”是人的思维活动，不能用来处理“生命安全”，句子说不通。"}, {"text": "危害", "is_correct": true, "explanation": "“危害”表示使他人的生命安全受到威胁，与“这种行为”的语境相合。"}, {"text": "体会", "is_correct": false, "explanation": "语义：“体会”指亲身感受，行为本身不能去体会他人的生命安全。"}, {"text": "感激", "is_correct": false, "explanation": "配价：“感激”的对象应是人或恩情，不能感激“生命安全”。"}], "explanations": {"思考": "语义：“思考”是人的思维活动，不能用来处理“生命安全”，句子说不通。", "危害": "“危害”表示使他人的生命安全受到威胁，与“这种行为”的语境相合。", "体会": "语义：“体会”指亲身感受，行为本身不能去体会他人的生命安全。", "感激": "配价：“感激”的对象应是人或恩情，不能感激“生命安全”。"}, "sentence_index": 6, "correct_answer": "危害"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "妈妈的决定危害了我的意愿。", "explanation": "这里应该用〈违背〉。违背指不顺从别人的意愿，危害指造成损害，意愿不能被危害，此处应说违背。"}, {"text": "我危害了你的午睡，真抱歉。", "explanation": "这里应该用〈打扰〉。危害指造成严重损害，打扰指妨碍别人休息，此处不能用危害。"}, {"text": "他不小心危害了那场考试。", "explanation": "这里应该用〈耽误〉。危害指造成严重损害，此处是考试被耽误，应说耽误。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5e9b95af-f526-4674-ab65-567f5b1a2aea') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90440, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这种行为很危害了社会秩序。", "corrected_sentence": "这种行为严重危害了社会秩序。", "error_description": "错误：副词“很”不能修饰动词“危害”，应改为“严重”。应说“这种行为严重危害了社会秩序”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5e9b95af-f526-4674-ab65-567f5b1a2aea') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90440, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这种广告以后正在危害青少年的成长。", "corrected_sentence": "这种广告以后会危害青少年的成长。", "error_description": "错误：“正在”表示当下正在进行，与表示将来的“以后”冲突，应说“以后会危害青少年的成长”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5e9b95af-f526-4674-ab65-567f5b1a2aea') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90445, 1, 'llm_types_A', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c9fbfa16-5c04-4f15-a69f-0e7a6ec7f15c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
