INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90445, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "人死了，不再活着，这是一种好听的说法。", "primary_collocate": null, "pronunciation": "qù shì", "ipa": "tɕʰy˥˩ ʂʐ̩˥˩", "syllable_count": 2, "sentences": [{"text": "爷爷去年冬天去世了。", "target_word": "去世", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他父亲三年前去世了。", "target_word": "去世", "complexity_tier": "T3", "furigana": "tā fùqīn sān nián qián qù shì le", "sentence_source": "generated"}, {"text": "奶奶去世后，家里变得很安静。", "target_word": "去世", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "听说老师的妈妈昨天去世了。", "target_word": "去世", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他十岁时，爷爷就去世了。", "target_word": "去世", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "外公去世的那天，下着大雨。", "target_word": "去世", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她的丈夫五十岁就去世了。", "target_word": "去世", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老人去世前，把家人都叫到身边。", "target_word": "去世", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这位作家在北京去世，活了九十岁。", "target_word": "去世", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我叔叔去世以后，我们常去看婶婶。", "target_word": "去世", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "去世了", "label": "体标（了）"}], "register": "委婉", "sense_fingerprint": "去世：人死亡的好听说法", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ed4809b0-ba75-480f-b901-0e7163480787') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90445, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "去世", "is_correct": true, "explanation": "去世 qù shì：正确答案，指人死亡，是委婉的说法。"}, {"text": "驱使", "is_correct": false, "explanation": "驱使 qūshǐ：两个音节都只是声调不同，第一个是第一声，第二个是第三声，意思是支使、役使，不是去世。"}, {"text": "句式", "is_correct": false, "explanation": "句式 jùshì：j 与 q 声母不同，其余音节和声调都相同，意思是句子的结构形式。"}, {"text": "叙事", "is_correct": false, "explanation": "叙事 xùshì：x 与 q 声母不同，声调相同，意思是叙述事情。"}, {"text": "曲式", "is_correct": false, "explanation": "曲式 qǔshì：第一个音节 qǔ 是第三声，与 qù（第四声）声调不同，意思是乐曲的结构形式。"}], "explanations": {"去世": "去世 qù shì：正确答案，指人死亡，是委婉的说法。", "驱使": "驱使 qūshǐ：两个音节都只是声调不同，第一个是第一声，第二个是第三声，意思是支使、役使，不是去世。", "句式": "句式 jùshì：j 与 q 声母不同，其余音节和声调都相同，意思是句子的结构形式。", "叙事": "叙事 xùshì：x 与 q 声母不同，声调相同，意思是叙述事情。", "曲式": "曲式 qǔshì：第一个音节 qǔ 是第三声，与 qù（第四声）声调不同，意思是乐曲的结构形式。"}, "sentence_index": null, "correct_answer": "去世"}, "level_3": {"options": [{"text": "出生", "is_correct": false, "explanation": "语义：“出生”指刚来到世上，爷爷去年冬天出生，与常理不符。"}, {"text": "去世", "is_correct": true, "explanation": "去世：人死亡的委婉说法，与“爷爷”和“去年冬天”搭配自然。"}, {"text": "变成", "is_correct": false, "explanation": "配价：“变成”后面要带出结果，“爷爷去年冬天变成了”句子不完整。"}, {"text": "毕业", "is_correct": false, "explanation": "语义：“毕业”指学业结束，爷爷去年毕业与语境不符。"}], "explanations": {"出生": "语义：“出生”指刚来到世上，爷爷去年冬天出生，与常理不符。", "去世": "去世：人死亡的委婉说法，与“爷爷”和“去年冬天”搭配自然。", "变成": "配价：“变成”后面要带出结果，“爷爷去年冬天变成了”句子不完整。", "毕业": "语义：“毕业”指学业结束，爷爷去年毕业与语境不符。"}, "sentence_index": 0, "correct_answer": "去世"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "那只小鸡昨天去世了。", "explanation": "这里应该用〈死〉。去世是对人的委婉说法，小鸡等动物死亡只说“死”。"}, {"text": "那棵老槐树去年去世了。", "explanation": "这里应该用〈枯死〉。去世只用于人，树木因枯萎死亡要说“枯死”。"}, {"text": "那座老房子去年去世了。", "explanation": "这里应该用〈拆除〉。去世只用于人，房屋被拆掉要说“拆除”，不能说“去世”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c9fbfa16-5c04-4f15-a69f-0e7a6ec7f15c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90445, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "长大", "is_correct": false, "explanation": "语义：“长大”指成长，丈夫五十岁才“长大”，与“五十岁就”的语境矛盾。"}, {"text": "怀孕", "is_correct": false, "explanation": "搭配：“怀孕”只能用于女性，不能用于“她的丈夫”。"}, {"text": "去世", "is_correct": true, "explanation": "去世：人死亡的委婉说法，“五十岁就去世了”说法自然。"}, {"text": "出嫁", "is_correct": false, "explanation": "搭配：“出嫁”指女子结婚到夫家，不能用于男子“丈夫”。"}], "explanations": {"长大": "语义：“长大”指成长，丈夫五十岁才“长大”，与“五十岁就”的语境矛盾。", "怀孕": "搭配：“怀孕”只能用于女性，不能用于“她的丈夫”。", "去世": "去世：人死亡的委婉说法，“五十岁就去世了”说法自然。", "出嫁": "搭配：“出嫁”指女子结婚到夫家，不能用于男子“丈夫”。"}, "sentence_index": 6, "correct_answer": "去世"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "那朵玫瑰昨天去世了。", "explanation": "这里应该用〈凋谢〉。去世只用于人，花草凋谢要说“凋谢”。"}, {"text": "蜡烛在风里去世了。", "explanation": "这里应该用〈熄灭〉。去世只用于人，蜡烛、火焰熄灭要说“熄灭”。"}, {"text": "那家工厂去年去世了。", "explanation": "这里应该用〈倒闭〉。去世只用于人，企业停止经营要说“倒闭”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c9fbfa16-5c04-4f15-a69f-0e7a6ec7f15c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90445, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我外婆前年去世着，我一直很想她。", "corrected_sentence": "我外婆前年去世了，我一直很想她。", "error_description": "“去世着”错误，应为“去世了”：去世表示已经发生的变化，要用“了”，不用“着”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c9fbfa16-5c04-4f15-a69f-0e7a6ec7f15c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90445, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我舅舅去年很去世了，大家都很难过。", "corrected_sentence": "我舅舅去年去世了，大家都很难过。", "error_description": "“去世”是表示死亡的动词，不能用程度副词“很”修饰，应删去“很”，说“去年去世了”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c9fbfa16-5c04-4f15-a69f-0e7a6ec7f15c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
