INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90457, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "准是说得对，一点也不差。", "primary_collocate": null, "pronunciation": "zhǔn", "ipa": "ʈʂuən˨˩˦", "syllable_count": 1, "sentences": [{"text": "你猜得真准！", "target_word": "准", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "天气预报说得很准，今天真的下雨了。", "target_word": "准", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他看人看得很准，从来不会选错人。", "target_word": "准", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这位老医生诊断得很准，我的病果然好了。", "target_word": "准", "complexity_tier": "T3", "furigana": "zhè wèi lǎo yī shēng zhěn duàn de hěn zhǔn wǒ de bìng guǒ rán hǎo le", "sentence_source": "generated"}, {"text": "他预测比赛结果预测得很准，大家都说他是神算。", "target_word": "准", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "你说得不准，他不是昨天来的，是前天来的。", "target_word": "准", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我的感觉一向很准，他一定会赢。", "target_word": "准", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "奶奶看天气看得准，她说会下雨就一定下。", "target_word": "准", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他的判断很准，大家都相信他。", "target_word": "准", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这次考试的题目，你估计得真准。", "target_word": "准", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "準", "label": "繁体"}, {"form": "准确", "label": "复合"}], "register": "中性", "sense_fingerprint": "猜测、预报、判断等说得对，和实际一点不差", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cc24a53f-6254-4aa5-8e47-0703e4066dea') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90457, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "准", "is_correct": true, "explanation": "正确：“准”表示猜测说得对，与“你猜得真……！”的语境相符。"}, {"text": "亮", "is_correct": false, "explanation": "语义：“亮”指光线明亮，与猜测说得对无关，不能用来评价猜测。"}, {"text": "厚", "is_correct": false, "explanation": "搭配：“厚”形容物体的厚度，不能用来形容猜测的准确程度。"}, {"text": "圆", "is_correct": false, "explanation": "搭配：“圆”形容形状，不能用来评价猜测是否说得对。"}], "explanations": {"准": "正确：“准”表示猜测说得对，与“你猜得真……！”的语境相符。", "亮": "语义：“亮”指光线明亮，与猜测说得对无关，不能用来评价猜测。", "厚": "搭配：“厚”形容物体的厚度，不能用来形容猜测的准确程度。", "圆": "搭配：“圆”形容形状，不能用来评价猜测是否说得对。"}, "sentence_index": 0, "correct_answer": "准"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "你的头发很准。", "explanation": "这里应该用〈整齐〉。“准”只用于猜测、判断或说得对，头发不能用“准”来形容。"}, {"text": "你的心情很准，我一眼就看出来了。", "explanation": "这里应该用〈猜〉。心情不是猜测或判断的对象，“准”只用于猜测、判断说得对。"}, {"text": "他的成绩很准，老师都很满意。", "explanation": "这里应该用〈好〉。成绩不是猜测或判断的对象，“准”不能用来形容成绩。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f710dbc2-d2ea-4067-9e4f-b056b043fa1c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90457, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "准", "is_correct": true, "explanation": "正确：“准”表示判断说得对，与“我的感觉一向很……，他一定会赢”的语境相符。"}, {"text": "慢", "is_correct": false, "explanation": "搭配：“慢”说速度，不能用来形容感觉。"}, {"text": "薄", "is_correct": false, "explanation": "搭配：“薄”形容物体的厚度，不能用来形容感觉的准确。"}, {"text": "轻", "is_correct": false, "explanation": "语义：“轻”指分量小，与感觉是否灵验无关，且与“一定会赢”的判断语义不符。"}], "explanations": {"准": "正确：“准”表示判断说得对，与“我的感觉一向很……，他一定会赢”的语境相符。", "慢": "搭配：“慢”说速度，不能用来形容感觉。", "薄": "搭配：“薄”形容物体的厚度，不能用来形容感觉的准确。", "轻": "语义：“轻”指分量小，与感觉是否灵验无关，且与“一定会赢”的判断语义不符。"}, "sentence_index": 6, "correct_answer": "准"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他的笑容很准。", "explanation": "这里应该用〈甜〉。“准”只用于猜测、判断或说得对，笑容不能用“准”来形容。"}, {"text": "这次考试的场地很准，大家都很满意。", "explanation": "这里应该用〈宽敞〉。“准”不用于形容场地，场地只能说宽敞或狭小。"}, {"text": "他的脾气很准，大家都不敢惹他。", "explanation": "这里应该用〈大〉或〈坏〉。脾气不是猜测或判断的对象，“准”不能用来形容脾气。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f710dbc2-d2ea-4067-9e4f-b056b043fa1c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
