INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90458, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "正确，精确；符合标准。", "primary_collocate": null, "pronunciation": "zhǔn", "ipa": "ʈʂuən˨˩˦", "syllable_count": 1, "sentences": [{"text": "这个钟很准，从来不快也不慢。", "target_word": "准", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他的发音很准，像中国人一样。", "target_word": "准", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这张地图画得不准，我们走错路了。", "target_word": "准", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我的手表不准，快了五分钟。", "target_word": "准", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "用这个尺子量，才能量得准。", "target_word": "准", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "他的汉语声调很准，老师常常表扬他。", "target_word": "准", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "导航不准，把我们带到了别的地方。", "target_word": "准", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这家店的电子秤很准，买东西不会吃亏。", "target_word": "准", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "翻译要准，不能随便改原来的意思。", "target_word": "准", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他口算又快又准，同学们都很佩服。", "target_word": "准", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "準", "label": "繁体"}, {"form": "准确", "label": "复合"}], "register": "中性", "sense_fingerprint": "仪器、发音、翻译等精确，符合标准", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cc24a53f-6254-4aa5-8e47-0703e4066dea') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
