INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90458, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "准", "is_correct": true, "explanation": "正确：“准”表示精确、可靠，与“导航不准，把我们带到了别的地方”的语境相符。"}, {"text": "热", "is_correct": false, "explanation": "搭配：“热”形容温度，不能用来形容导航的精确程度。"}, {"text": "软", "is_correct": false, "explanation": "搭配：“软”形容质地，不能用来形容导航的精确程度。"}, {"text": "咸", "is_correct": false, "explanation": "语义：“咸”指味道，与导航能否准确指路无关。"}], "explanations": {"准": "正确：“准”表示精确、可靠，与“导航不准，把我们带到了别的地方”的语境相符。", "热": "搭配：“热”形容温度，不能用来形容导航的精确程度。", "软": "搭配：“软”形容质地，不能用来形容导航的精确程度。", "咸": "语义：“咸”指味道，与导航能否准确指路无关。"}, "sentence_index": 6, "correct_answer": "准"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他的汗水很准。", "explanation": "这里应该用〈多〉。“准”形容精确或正确，汗水的多少不能用“准”来形容。"}, {"text": "这个月的工资很准。", "explanation": "这里应该用〈高〉。“准”形容精确或正确，工资的多少不能用“准”来形容。"}, {"text": "这次口算题很难，大家都很累。", "explanation": "这里应该用〈难〉。“准”形容精确或正确，题目的难易不能用“准”来形容。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f710dbc2-d2ea-4067-9e4f-b056b043fa1c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
