INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90462, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '54d136a2-1535-496c-b74e-b1f72dabe9c2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90462, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "结为配偶的男女；丈夫和妻子。", "primary_collocate": null, "pronunciation": "fū qī", "ipa": "fu˥ tɕʰi˥", "syllable_count": 2, "sentences": [{"text": "夫妻之间应该互相帮助。", "target_word": "夫妻", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们做了十年夫妻，从来没有吵过架。", "target_word": "夫妻", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "好夫妻要多说话，多听对方的想法。", "target_word": "夫妻", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "夫妻二人一起把房子打扫干净了。", "target_word": "夫妻", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这对夫妻的感情非常好。", "target_word": "夫妻", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "医生请夫妻两个人一起来谈谈。", "target_word": "夫妻", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们结婚后，就成了夫妻。", "target_word": "夫妻", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "夫妻吵架以后，很快就会和好。", "target_word": "夫妻", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这对夫妻每个周末都去看爷爷奶奶。", "target_word": "夫妻", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "年轻夫妻买房子，需要很多钱。", "target_word": "夫妻", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "一对夫妻", "label": "量词搭配"}, {"form": "夫妻俩", "label": "复合词"}, {"form": "夫妻关系", "label": "复合词"}, {"form": "小夫妻", "label": "复合词"}], "register": "中性", "sense_fingerprint": "丈夫和妻子之间的配偶关系", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5ac86440-8f5a-4834-8135-427d86e72be0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90462, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "桌子", "is_correct": false, "explanation": "语义：“桌子”没有行为能力，不能“互相帮助”。"}, {"text": "夫妻", "is_correct": true, "explanation": "夫妻：配偶关系中的双方，“夫妻之间”与“互相帮助”语境相符。"}, {"text": "手机", "is_correct": false, "explanation": "语义：“手机”不能“互相帮助”，与“应该”的主体不符。"}, {"text": "石头", "is_correct": false, "explanation": "搭配：“互相帮助”要求有行动能力的主体，“石头”不能搭配。"}], "explanations": {"桌子": "语义：“桌子”没有行为能力，不能“互相帮助”。", "夫妻": "夫妻：配偶关系中的双方，“夫妻之间”与“互相帮助”语境相符。", "手机": "语义：“手机”不能“互相帮助”，与“应该”的主体不符。", "石头": "搭配：“互相帮助”要求有行动能力的主体，“石头”不能搭配。"}, "sentence_index": 0, "correct_answer": "夫妻"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我们还没有领证，还是夫妻，只是在谈恋爱。", "explanation": "这里应该用〈情侣〉。夫妻指已经结婚的关系，还没领证、只是谈恋爱的要用“情侣”。"}, {"text": "我和父母是夫妻，关系很亲近。", "explanation": "夫妻指配偶关系，父母与子女是亲子关系，不能说“夫妻”。"}, {"text": "我们结婚十年，是一个夫妻。", "explanation": "这里应该用〈对〉。夫妻指一对配偶，量词要用“对”，不能用“个”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '54d136a2-1535-496c-b74e-b1f72dabe9c2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90462, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "学生", "is_correct": false, "explanation": "语义：结婚后不会变成“学生”，与语境矛盾。"}, {"text": "夫妻", "is_correct": true, "explanation": "夫妻：结婚后双方就成为配偶，与“结婚后”相符。"}, {"text": "司机", "is_correct": false, "explanation": "语义：“结婚”不会使人成为“司机”。"}, {"text": "礼物", "is_correct": false, "explanation": "搭配：“成了”后接“礼物”与结婚的语境不符，不能搭配。"}], "explanations": {"学生": "语义：结婚后不会变成“学生”，与语境矛盾。", "夫妻": "夫妻：结婚后双方就成为配偶，与“结婚后”相符。", "司机": "语义：“结婚”不会使人成为“司机”。", "礼物": "搭配：“成了”后接“礼物”与结婚的语境不符，不能搭配。"}, "sentence_index": 6, "correct_answer": "夫妻"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他今天生病了，他的夫妻也没来上班。", "explanation": "夫妻指一对配偶，不能只指其中一个人；这里应该说“他的妻子”或“他的丈夫”。"}, {"text": "他们离婚三年了，现在还是夫妻。", "explanation": "这里应该用〈前夫〉或〈前妻〉。夫妻指现在有婚姻关系的一对人，离婚后就不再是夫妻了。"}, {"text": "我和同学是夫妻，每天一起上课。", "explanation": "夫妻只指配偶关系，同学之间不能说“夫妻”，应说“朋友”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '54d136a2-1535-496c-b74e-b1f72dabe9c2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90462, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他们做的夫妻已经十年了。", "corrected_sentence": "他们做夫妻已经十年了。", "error_description": "结构助词错误：“做夫妻”是动宾结构，中间不能加“的”，应说“他们做夫妻已经十年了”；加“的”会把“做夫妻”变成修饰语，句子不通。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '54d136a2-1535-496c-b74e-b1f72dabe9c2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90462, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "结婚以后，他们很快就成了一个夫妻。", "corrected_sentence": "结婚以后，他们很快就成了一对夫妻。", "error_description": "量词错误：“夫妻”指一对人，应说“一对夫妻”，不能说“一个夫妻”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '54d136a2-1535-496c-b74e-b1f72dabe9c2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
