INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90468, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "丈夫和妻子（多用于较正式的场合）。", "primary_collocate": null, "pronunciation": "fū fù", "ipa": "fu˥ fu˥˩", "syllable_count": 2, "sentences": [{"text": "王先生夫妇今天来参加会议。", "target_word": "夫妇", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这对夫妇在北京工作了十年。", "target_word": "夫妇", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "欢迎李教授夫妇来我们学校。", "target_word": "夫妇", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "那对夫妇给孩子们捐了很多书。", "target_word": "夫妇", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "校长请张先生夫妇一起吃饭。", "target_word": "夫妇", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这对夫妇都是医生，工作很忙。", "target_word": "夫妇", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们邀请了陈先生夫妇参加晚会。", "target_word": "夫妇", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "那对夫妇住在学校旁边的小楼里。", "target_word": "夫妇", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这对夫妇十分热心，常帮助邻居。", "target_word": "夫妇", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "那对老年夫妇手拉着手走进公园。", "target_word": "夫妇", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "一对夫妇", "label": "量词（对）"}, {"form": "老年夫妇", "label": "复合"}], "register": "正式", "sense_fingerprint": "丈夫和妻子，用于较正式的场合", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e6865c18-9c19-4131-8be9-c03230977fc2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90468, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "夫妇", "is_correct": true, "explanation": "正确。“王先生夫妇”指王先生和他的妻子两人，可以一起来参加会议。"}, {"text": "店铺", "is_correct": false, "explanation": "语义：店铺是物，不能与“王先生”并列作为会议的参加者。"}, {"text": "书", "is_correct": false, "explanation": "语义：书不能参加会议，与“王先生”也不能构成参加者。"}, {"text": "孤儿", "is_correct": false, "explanation": "搭配：“王先生孤儿”不成立，“孤儿”不能与“王先生”这样的称谓并列。"}], "explanations": {"夫妇": "正确。“王先生夫妇”指王先生和他的妻子两人，可以一起来参加会议。", "店铺": "语义：店铺是物，不能与“王先生”并列作为会议的参加者。", "书": "语义：书不能参加会议，与“王先生”也不能构成参加者。", "孤儿": "搭配：“王先生孤儿”不成立，“孤儿”不能与“王先生”这样的称谓并列。"}, "sentence_index": 0, "correct_answer": "夫妇"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "那个夫妇给孩子们捐了很多书。", "explanation": "这里应该用〈对〉。夫妇是成对计算的，应说“一对夫妇”，用“个”不对。"}, {"text": "那对夫妇是兄弟俩。", "explanation": "这里误用了夫妇的指称范围：它只指结了婚的丈夫和妻子，不能用于同胞关系。"}, {"text": "王太太是王先生的夫妇。", "explanation": "这里应该用〈夫人〉。夫妇指一对夫妻，只说一个人时要用“夫人”或“妻子”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b9f84982-8648-42e8-bc52-311a344324e8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90468, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "夫妇", "is_correct": true, "explanation": "正确。“陈先生夫妇”指陈先生和他的妻子，可以一同被邀请参加晚会。"}, {"text": "车", "is_correct": false, "explanation": "语义：车是物，不能被邀请参加晚会，与“陈先生”搭配不通。"}, {"text": "学校", "is_correct": false, "explanation": "搭配：“陈先生学校”不成立，“学校”不能与“陈先生”构成被邀请的对象。"}, {"text": "胖子", "is_correct": false, "explanation": "语义：“陈先生胖子”不成立，与“陈先生”并列指被邀请者语义上不通。"}], "explanations": {"夫妇": "正确。“陈先生夫妇”指陈先生和他的妻子，可以一同被邀请参加晚会。", "车": "语义：车是物，不能被邀请参加晚会，与“陈先生”搭配不通。", "学校": "搭配：“陈先生学校”不成立，“学校”不能与“陈先生”构成被邀请的对象。", "胖子": "语义：“陈先生胖子”不成立，与“陈先生”并列指被邀请者语义上不通。"}, "sentence_index": 6, "correct_answer": "夫妇"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "那对老年夫妇还没有结婚。", "explanation": "这里应该用〈伴侣〉。夫妇要求两人已经结婚，未婚的一对只能称为“伴侣”或“情侣”。"}, {"text": "那对老年夫妇是两个小学生。", "explanation": "这里误用了夫妇的指称对象：它指成年的丈夫和妻子，不能用于未成年的人。"}, {"text": "那对老年夫妇是两位邻居，各住一套房子。", "explanation": "这里误用了夫妇的指称对象：夫妇只指结了婚的丈夫和妻子，两位各住一套房子的邻居不是夫妇，应说“两位邻居”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b9f84982-8648-42e8-bc52-311a344324e8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90468, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "那个夫妇昨天请我们吃饭。", "corrected_sentence": "那对夫妇昨天请我们吃饭。", "error_description": "量词用错。“夫妇”应该用量词“对”，不能用“个”，应说“那对夫妇”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b9f84982-8648-42e8-bc52-311a344324e8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
