INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90469, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "塔是又高又尖的大房子，一层一层往上盖。", "primary_collocate": null, "pronunciation": "tǎ", "ipa": "tʰa˨˩˦", "syllable_count": 1, "sentences": [{"text": "这座塔很高。", "target_word": "塔", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "山上有一座白色的塔。", "target_word": "塔", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "我们爬上塔，看见了整个城市。", "target_word": "塔", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这座塔有七层，每一层都很大。", "target_word": "塔", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "晚上塔上的灯亮了，非常漂亮。", "target_word": "塔", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "小朋友在塔前面照相。", "target_word": "塔", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "那座塔已经有一千年的历史了。", "target_word": "塔", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他每天都看着那座塔，想起家乡。", "target_word": "塔", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "塔的旁边有一个小公园。", "target_word": "塔", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "我想把这座塔画下来。", "target_word": "塔", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "一座塔", "label": "量词"}, {"form": "铁塔", "label": "复合"}, {"form": "宝塔", "label": "复合"}], "register": "通用", "sense_fingerprint": "塔：又高又尖、一层一层盖起来的高大建筑", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f55774ed-ddc3-49eb-a960-56e3f2d39f09') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90469, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "塔", "is_correct": true, "explanation": "正确答案。塔（第三声）指又高又尖、一层一层往上盖的建筑。"}, {"text": "他", "is_correct": false, "explanation": "他 tā（第一声）与 tǎ（第三声）声调不同，意思是“他”（人称代词）。"}, {"text": "踏", "is_correct": false, "explanation": "踏 tà（第四声）与 tǎ（第三声）声调不同，意思是“踩”。"}, {"text": "哪", "is_correct": false, "explanation": "哪 nǎ 与 tǎ 声母不同（n 与 t），意思是“哪里”。"}, {"text": "把", "is_correct": false, "explanation": "把 bǎ 与 tǎ 声母不同（b 与 t），意思是“把手”或“把握”。"}, {"text": "躺", "is_correct": false, "explanation": "躺 tǎng 与 tǎ 韵母不同（多了 ng），意思是“躺下”。"}], "explanations": {"塔": "正确答案。塔（第三声）指又高又尖、一层一层往上盖的建筑。", "他": "他 tā（第一声）与 tǎ（第三声）声调不同，意思是“他”（人称代词）。", "踏": "踏 tà（第四声）与 tǎ（第三声）声调不同，意思是“踩”。", "哪": "哪 nǎ 与 tǎ 声母不同（n 与 t），意思是“哪里”。", "把": "把 bǎ 与 tǎ 声母不同（b 与 t），意思是“把手”或“把握”。", "躺": "躺 tǎng 与 tǎ 韵母不同（多了 ng），意思是“躺下”。"}, "sentence_index": null, "correct_answer": "塔"}, "level_3": {"options": [{"text": "塔", "is_correct": true, "explanation": "正确。“这座”的量词用于大型建筑，“很高”描述塔的高度，与句意一致。"}, {"text": "书", "is_correct": false, "explanation": "语义：书没有“很高”的高度义，“这座书”也不成立。"}, {"text": "河", "is_correct": false, "explanation": "语义：河的特征是长、宽，不说“很高”。"}, {"text": "桌子", "is_correct": false, "explanation": "搭配：“桌子”用量词“张”，不能用“座”。"}], "explanations": {"塔": "正确。“这座”的量词用于大型建筑，“很高”描述塔的高度，与句意一致。", "书": "语义：书没有“很高”的高度义，“这座书”也不成立。", "河": "语义：河的特征是长、宽，不说“很高”。", "桌子": "搭配：“桌子”用量词“张”，不能用“座”。"}, "sentence_index": 0, "correct_answer": "塔"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这座塔很长，连接着河的两岸。", "explanation": "这里应该用〈桥〉。桥横跨河流、连接两岸；塔是又高又尖的建筑，不能用来连接两岸。"}, {"text": "我每天坐塔去上班。", "explanation": "这里应该用〈地铁〉（或其他交通工具）。塔是建筑，不能当作交通工具乘坐。"}, {"text": "我家是一座塔，只有一层。", "explanation": "这里应该用〈平房〉。平房是一层的低矮房子；塔又高又尖、一层一层往上盖，不能用来指只有一层的房子。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '71686fda-6fd9-4849-9233-e16873699209') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90469, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "塔", "is_correct": true, "explanation": "正确答案。塔（第三声）指又高又尖、一层一层往上盖的建筑。"}, {"text": "她", "is_correct": false, "explanation": "她 tā（第一声）与 tǎ（第三声）声调不同，意思是“她”（女性人称代词）。"}, {"text": "打", "is_correct": false, "explanation": "打 dǎ 与 tǎ 声母不同（d 与 t），意思是“打”。"}, {"text": "卡", "is_correct": false, "explanation": "卡 kǎ 与 tǎ 声母不同（k 与 t），意思是“卡住”或“卡片”。"}, {"text": "讨", "is_correct": false, "explanation": "讨 tǎo 与 tǎ 韵母不同（多了 o），意思是“讨论”或“讨好”。"}], "explanations": {"塔": "正确答案。塔（第三声）指又高又尖、一层一层往上盖的建筑。", "她": "她 tā（第一声）与 tǎ（第三声）声调不同，意思是“她”（女性人称代词）。", "打": "打 dǎ 与 tǎ 声母不同（d 与 t），意思是“打”。", "卡": "卡 kǎ 与 tǎ 声母不同（k 与 t），意思是“卡住”或“卡片”。", "讨": "讨 tǎo 与 tǎ 韵母不同（多了 o），意思是“讨论”或“讨好”。"}, "sentence_index": null, "correct_answer": "塔"}, "level_3": {"options": [{"text": "塔", "is_correct": true, "explanation": "正确。“那座”指古老的建筑，“有一千年的历史”符合塔的特点。"}, {"text": "人", "is_correct": false, "explanation": "语义：人的寿命不能说“有一千年的历史”。"}, {"text": "书", "is_correct": false, "explanation": "搭配：量词“座”用于建筑、山等，不用于书；“那座书”不成立，应为“那本书”。"}, {"text": "菜", "is_correct": false, "explanation": "语义：菜不以“一千年的历史”计，句子的意思不通。"}], "explanations": {"塔": "正确。“那座”指古老的建筑，“有一千年的历史”符合塔的特点。", "人": "语义：人的寿命不能说“有一千年的历史”。", "书": "搭配：量词“座”用于建筑、山等，不用于书；“那座书”不成立，应为“那本书”。", "菜": "语义：菜不以“一千年的历史”计，句子的意思不通。"}, "sentence_index": 6, "correct_answer": "塔"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "公园的塔很长，把整个公园都围了起来。", "explanation": "这里应该用〈围墙〉。围墙用来把一个地方围起来；塔是又高又尖的建筑，不能围住公园。"}, {"text": "工厂里有一座很高的塔，工人们把衣服挂在塔上晾干。", "explanation": "这里应该用〈晾衣架〉。晾衣架用来晾晒衣服；塔是又高又尖的建筑，不能用来晾衣服。"}, {"text": "大厅中间有一座很粗的塔，把屋顶撑了起来。", "explanation": "这里应该用〈柱子〉。柱子是立在屋里撑住屋顶的粗柱；塔是又高又尖的建筑，不能立在屋里撑屋顶。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '71686fda-6fd9-4849-9233-e16873699209') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90469, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我去看了一只塔。", "corrected_sentence": "我去看了一座塔。", "error_description": "“塔”是建筑，量词应用“座”，“只”只用于动物。“一只塔”应改为“一座塔”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '71686fda-6fd9-4849-9233-e16873699209') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90469, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "那片塔在山顶上，很多人都来看。", "corrected_sentence": "那座塔在山顶上，很多人都来看。", "error_description": "量词错误：“塔”是建筑，量词应用“座”；“片”用于云、叶子等平面或成片的事物。“那片塔”应改为“那座塔”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '71686fda-6fd9-4849-9233-e16873699209') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90470, 1, 'llm_types_A', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '71686fda-6fd9-4849-9233-e16873699209') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90470, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '71686fda-6fd9-4849-9233-e16873699209') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90470, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "一种高耸的建筑物，多为多层，常用于佛教或观景。", "primary_collocate": null, "pronunciation": "tǎ", "ipa": "tʰa˨˩˦", "syllable_count": 1, "sentences": [{"text": "寺里有一座塔。", "target_word": "塔", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "这座塔是和尚们盖的。", "target_word": "塔", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "很多人来塔上看风景。", "target_word": "塔", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "站在塔上，能看到远处的河。", "target_word": "塔", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这座塔一共有九层。", "target_word": "塔", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "我去过那座塔两次。", "target_word": "塔", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "游客们都想爬上塔看看。", "target_word": "塔", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "山里的寺庙旁边有一座很老的塔。", "target_word": "塔", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "塔里面很安静，也有点儿黑。", "target_word": "塔", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他拿着相机，站在塔下等朋友。", "target_word": "塔", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "一座塔", "label": "量词"}, {"form": "铁塔", "label": "复合"}, {"form": "宝塔", "label": "复合"}], "register": "通用", "sense_fingerprint": "塔：多层高耸建筑，用于佛教或登高观景", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f55774ed-ddc3-49eb-a960-56e3f2d39f09') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90470, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "塔", "is_correct": true, "explanation": "正确答案。塔（第三声）指多层、高耸的建筑，常用于佛教或观景。"}, {"text": "他", "is_correct": false, "explanation": "他 tā（第一声）与 tǎ（第三声）声调不同，意思是“他”（人称代词）。"}, {"text": "踏", "is_correct": false, "explanation": "踏 tà（第四声）与 tǎ（第三声）声调不同，意思是“踩”。"}, {"text": "哪", "is_correct": false, "explanation": "哪 nǎ 与 tǎ 声母不同（n 与 t），意思是“哪里”。"}, {"text": "躺", "is_correct": false, "explanation": "躺 tǎng 与 tǎ 韵母不同（多了 ng），意思是“躺下”。"}], "explanations": {"塔": "正确答案。塔（第三声）指多层、高耸的建筑，常用于佛教或观景。", "他": "他 tā（第一声）与 tǎ（第三声）声调不同，意思是“他”（人称代词）。", "踏": "踏 tà（第四声）与 tǎ（第三声）声调不同，意思是“踩”。", "哪": "哪 nǎ 与 tǎ 声母不同（n 与 t），意思是“哪里”。", "躺": "躺 tǎng 与 tǎ 韵母不同（多了 ng），意思是“躺下”。"}, "sentence_index": null, "correct_answer": "塔"}, "level_3": {"options": [{"text": "塔", "is_correct": true, "explanation": "正确。“寺里有一座”的量词“座”用于建筑，塔符合句意。"}, {"text": "人", "is_correct": false, "explanation": "搭配：量词“座”不用于人，“一座人”不成立。"}, {"text": "河", "is_correct": false, "explanation": "语义：河是水道，不会在寺里“有一座”。"}, {"text": "书", "is_correct": false, "explanation": "语义：书应说“有一本”，而且不是建筑，不能说“寺里有一座书”。"}], "explanations": {"塔": "正确。“寺里有一座”的量词“座”用于建筑，塔符合句意。", "人": "搭配：量词“座”不用于人，“一座人”不成立。", "河": "语义：河是水道，不会在寺里“有一座”。", "书": "语义：书应说“有一本”，而且不是建筑，不能说“寺里有一座书”。"}, "sentence_index": 0, "correct_answer": "塔"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这座塔很长，横跨在河面上，连接两岸。", "explanation": "这里应该用〈桥〉。桥横跨河流、连接两岸；塔是高耸的建筑，不能用来连接两岸。"}, {"text": "我每天坐塔去学校。", "explanation": "这里应该用〈地铁〉（或其他交通工具）。塔是建筑，不能当作交通工具乘坐。"}, {"text": "这座塔很软，可以拿来当枕头睡觉。", "explanation": "这里应该用〈枕头〉。枕头柔软，用来睡觉；塔是坚硬高耸的建筑，不能当枕头。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '71686fda-6fd9-4849-9233-e16873699209') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90470, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "塔", "is_correct": true, "explanation": "正确答案。塔（第三声）指多层、高耸的建筑，常用于佛教或观景。"}, {"text": "她", "is_correct": false, "explanation": "她 tā（第一声）与 tǎ（第三声）声调不同，意思是“她”（女性人称代词）。"}, {"text": "打", "is_correct": false, "explanation": "打 dǎ 与 tǎ 声母不同（d 与 t），意思是“打”。"}, {"text": "卡", "is_correct": false, "explanation": "卡 kǎ 与 tǎ 声母不同（k 与 t），意思是“卡住”或“卡片”。"}, {"text": "讨", "is_correct": false, "explanation": "讨 tǎo 与 tǎ 韵母不同（多了 o），意思是“讨论”或“讨好”。"}, {"text": "把", "is_correct": false, "explanation": "把 bǎ 与 tǎ 声母不同（b 与 t），意思是“把手”或“把握”。"}], "explanations": {"塔": "正确答案。塔（第三声）指多层、高耸的建筑，常用于佛教或观景。", "她": "她 tā（第一声）与 tǎ（第三声）声调不同，意思是“她”（女性人称代词）。", "打": "打 dǎ 与 tǎ 声母不同（d 与 t），意思是“打”。", "卡": "卡 kǎ 与 tǎ 声母不同（k 与 t），意思是“卡住”或“卡片”。", "讨": "讨 tǎo 与 tǎ 韵母不同（多了 o），意思是“讨论”或“讨好”。", "把": "把 bǎ 与 tǎ 声母不同（b 与 t），意思是“把手”或“把握”。"}, "sentence_index": null, "correct_answer": "塔"}, "level_3": {"options": [{"text": "塔", "is_correct": true, "explanation": "正确。“爬上”的对象是可以攀登的高大建筑，塔符合句意。"}, {"text": "水", "is_correct": false, "explanation": "语义：水不能被“爬上”去看，“爬上水看看”不通。"}, {"text": "书", "is_correct": false, "explanation": "搭配：“爬上”的对象应是可攀爬的物体，书不说“爬上书”。"}, {"text": "字", "is_correct": false, "explanation": "语义：字是写下来的符号，不能爬上去看看。"}], "explanations": {"塔": "正确。“爬上”的对象是可以攀登的高大建筑，塔符合句意。", "水": "语义：水不能被“爬上”去看，“爬上水看看”不通。", "书": "搭配：“爬上”的对象应是可攀爬的物体，书不说“爬上书”。", "字": "语义：字是写下来的符号，不能爬上去看看。"}, "sentence_index": 6, "correct_answer": "塔"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "公园中间有一座塔，大家在里面下棋。", "explanation": "这里应该用〈亭子〉。亭子有顶、四面通风，供人休息下棋；塔是高耸的多层建筑，供佛教或观景，不作下棋场所。"}, {"text": "寺庙的塔很长，把整个院子都围了起来。", "explanation": "这里应该用〈围墙〉。围墙用来把地方围起来；塔是高耸的建筑，不能围住院子。"}, {"text": "工厂门口有一座很高的塔，工人们把衣服挂在塔上晾干。", "explanation": "这里应该用〈晾衣架〉。晾衣架用来晾晒衣服；塔是用于佛教或观景的高耸建筑，不能用来晾衣服。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '71686fda-6fd9-4849-9233-e16873699209') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90470, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我去寺里看了一只塔。", "corrected_sentence": "我去寺里看了一座塔。", "error_description": "“塔”是建筑，量词应用“座”，“只”只用于动物。“一只塔”应改为“一座塔”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '71686fda-6fd9-4849-9233-e16873699209') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90470, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "游客们都想爬上一只塔看看。", "corrected_sentence": "游客们都想爬上一座塔看看。", "error_description": "“塔”是建筑，量词应用“座”，“只”只用于动物。“一只塔”应改为“一座塔”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '71686fda-6fd9-4849-9233-e16873699209') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90475, 1, 'llm_types_A', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1bc53ff7-a51d-4d12-b1a0-8dd6064ac128') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90475, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1bc53ff7-a51d-4d12-b1a0-8dd6064ac128') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90475, 1, 'prompt1_core', '{"pos": "副词", "semantic_class": "function", "definition": "副词，表示数量或幅度很大，程度深。", "primary_collocate": null, "pronunciation": "dà dà", "ipa": "ta˥˩ ta˥˩", "syllable_count": 2, "sentences": [{"text": "今年的游客人数大大增加了。", "target_word": "大大", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个月的雨水比去年大大减少。", "target_word": "大大", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他的收入大大超过了我们的想象。", "target_word": "大大", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "坐地铁比开车大大节省了时间。", "target_word": "大大", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "新路修好后，路上的时间大大缩短了。", "target_word": "大大", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "超市打折以后，客人大大增多。", "target_word": "大大", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "天气变冷，出门的人大大减少了。", "target_word": "大大", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这次考试的成绩大大高于平时。", "target_word": "大大", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "工作的机会比以前大大增加了。", "target_word": "大大", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们的差距大大缩小了。", "target_word": "大大", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "中性", "sense_fingerprint": "副词；修饰增减、缩短等动词，表示数量或幅度很大", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4da068f4-1758-479c-9a13-02dccfe2d5c0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90475, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "大大", "is_correct": true, "explanation": "正确答案：大大（dà dà），副词，表示程度深、幅度大。"}, {"text": "大地", "is_correct": false, "explanation": "后一音节 dà 与 dì 韵母不同（a 与 i），意思是大地。"}, {"text": "嗒嗒", "is_correct": false, "explanation": "两个音节均为第一声（dā dā），与 dà dà 仅声调不同，是象声词，形容轻敲或马蹄的声音。"}, {"text": "大打", "is_correct": false, "explanation": "后一音节 dà 与 dǎ（第三声）仅声调不同，意思是猛烈地打（如“大打出手”）。"}, {"text": "打打", "is_correct": false, "explanation": "两个音节均为第三声（dǎ dǎ），与 dà dà 仅声调不同；作动词重叠，表示动作短暂随意，如“打打球”。"}], "explanations": {"大大": "正确答案：大大（dà dà），副词，表示程度深、幅度大。", "大地": "后一音节 dà 与 dì 韵母不同（a 与 i），意思是大地。", "嗒嗒": "两个音节均为第一声（dā dā），与 dà dà 仅声调不同，是象声词，形容轻敲或马蹄的声音。", "大打": "后一音节 dà 与 dǎ（第三声）仅声调不同，意思是猛烈地打（如“大打出手”）。", "打打": "两个音节均为第三声（dǎ dǎ），与 dà dà 仅声调不同；作动词重叠，表示动作短暂随意，如“打打球”。"}, "sentence_index": null, "correct_answer": "大大"}, "level_3": {"options": [{"text": "大大", "is_correct": true, "explanation": "正确：“大大”修饰“增加”，表示增加的幅度很大。"}, {"text": "永远", "is_correct": false, "explanation": "语义：“永远”表示长久不变，与“今年”这一具体时段冲突。"}, {"text": "通常", "is_correct": false, "explanation": "体貌：“通常”表示习惯性，不能与表示完成的“增加了”搭配。"}, {"text": "偶尔", "is_correct": false, "explanation": "语义：“偶尔”表示不常发生，与游客人数持续增加的语义相冲突。"}], "explanations": {"大大": "正确：“大大”修饰“增加”，表示增加的幅度很大。", "永远": "语义：“永远”表示长久不变，与“今年”这一具体时段冲突。", "通常": "体貌：“通常”表示习惯性，不能与表示完成的“增加了”搭配。", "偶尔": "语义：“偶尔”表示不常发生，与游客人数持续增加的语义相冲突。"}, "sentence_index": 0, "correct_answer": "大大"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我的成绩大大提高了一点。", "explanation": "这里应该用〈稍微〉。“大大”表示幅度很大，与“一点”的轻微程度矛盾，轻微的提高要说稍微。"}, {"text": "我大大只买了一本书。", "explanation": "这里〈大大〉表示数量多、程度深，与只买一本这种少量的情况冲突，此处应表达少量，不能用大大。"}, {"text": "他们俩的身高大大一样。", "explanation": "这里应该用〈大大不一样〉。大大修饰有程度差别的变化或比较，身高相同没有程度差别，不能与一样搭配。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1bc53ff7-a51d-4d12-b1a0-8dd6064ac128') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90475, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "大大", "is_correct": true, "explanation": "正确答案：大大（dà dà），副词，表示程度深、幅度大。"}, {"text": "带带", "is_correct": false, "explanation": "两个音节均为 dài，与 dà 仅韵母多一个 i（ai 与 a），声调相同；口语动词，意为带领、照应。"}, {"text": "荡荡", "is_correct": false, "explanation": "两个音节均为 dàng，与 dà 仅韵母多一个鼻音 ng（ang 与 a），声调相同；形容词，意为广阔、开阔。"}, {"text": "达达", "is_correct": false, "explanation": "两个音节均为第二声 dá，与 dà dà 仅声调不同；音译词，如“达达主义”。"}], "explanations": {"大大": "正确答案：大大（dà dà），副词，表示程度深、幅度大。", "带带": "两个音节均为 dài，与 dà 仅韵母多一个 i（ai 与 a），声调相同；口语动词，意为带领、照应。", "荡荡": "两个音节均为 dàng，与 dà 仅韵母多一个鼻音 ng（ang 与 a），声调相同；形容词，意为广阔、开阔。", "达达": "两个音节均为第二声 dá，与 dà dà 仅声调不同；音译词，如“达达主义”。"}, "sentence_index": null, "correct_answer": "大大"}, "level_3": {"options": [{"text": "大大", "is_correct": true, "explanation": "正确：“大大”修饰“减少”，表示减少的幅度很大，与“天气变冷”相合。"}, {"text": "一起", "is_correct": false, "explanation": "语义：“一起”表示共同，不能修饰“人数减少”这种各自发生的变化。"}, {"text": "顺便", "is_correct": false, "explanation": "语义：“顺便”表示附带，与天气变冷导致的整体变化不合。"}, {"text": "没有", "is_correct": false, "explanation": "否定：“没有”与已发生的“减少了”相矛盾，“没有……了”不成立，与天气变冷后的实际变化不合。"}], "explanations": {"大大": "正确：“大大”修饰“减少”，表示减少的幅度很大，与“天气变冷”相合。", "一起": "语义：“一起”表示共同，不能修饰“人数减少”这种各自发生的变化。", "顺便": "语义：“顺便”表示附带，与天气变冷导致的整体变化不合。", "没有": "否定：“没有”与已发生的“减少了”相矛盾，“没有……了”不成立，与天气变冷后的实际变化不合。"}, "sentence_index": 6, "correct_answer": "大大"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我大大地去过一次北京。", "explanation": "“大大”修饰程度，与表示次数的“一次”不协调，说次数要用“多次”。"}, {"text": "这次考试我大大及格了。", "explanation": "这里应该用〈考得很好〉。及格只表示合格与否，没有程度差别，不能用大大修饰。"}, {"text": "这件事大大地没有发生过。", "explanation": "这里应该用〈根本〉：这件事根本没有发生过。大大表示程度深，修饰否定时语义不通。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1bc53ff7-a51d-4d12-b1a0-8dd6064ac128') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90475, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这家店的顾客大大很增加了。", "corrected_sentence": "这家店的顾客大大增加了。", "error_description": "错误：「大大」本身已表示程度，前面又加程度副词「很」，两者叠用是错误的。应删去「很」，说「大大增加了」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1bc53ff7-a51d-4d12-b1a0-8dd6064ac128') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90475, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这家公司的利润大大大增加了。", "corrected_sentence": "这家公司的利润大大增加了。", "error_description": "错误：「大大」是一个副词，不能重复成「大大大」。应说「大大增加了」，多出的「大」是错误的。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1bc53ff7-a51d-4d12-b1a0-8dd6064ac128') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
