INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90480, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "function", "definition": "好像；像……一样。", "primary_collocate": null, "pronunciation": "rú tóng", "ipa": "ɻu˧˥ tʰʊŋ˧˥", "syllable_count": 2, "sentences": [{"text": "她对我如同亲姐姐一样。", "target_word": "如同", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这里的夏天如同火炉一样热。", "target_word": "如同", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师对学生如同朋友。", "target_word": "如同", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他如同变了一个人。", "target_word": "如同", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "时间如同流水，一去不回。", "target_word": "如同", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "邻居们相处得如同一家人。", "target_word": "如同", "complexity_tier": "T3", "furigana": "lín jū men xiāng chǔ de rú tóng yī jiā rén.", "sentence_source": "generated"}, {"text": "孩子的笑声如同音乐一样好听。", "target_word": "如同", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这座城市如同一幅画。", "target_word": "如同", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "奶奶照顾我，如同照顾自己的孩子。", "target_word": "如同", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "新同学的发音如同中国人一样标准。", "target_word": "如同", "complexity_tier": "T3", "furigana": "xīn tóng xué de fā yīn rú tóng zhōng guó rén yí yàng biāo zhǔn.", "sentence_source": "generated"}], "morphological_forms": [{"form": "如同……一样", "label": "固定搭配"}], "register": "书面", "sense_fingerprint": "表示比喻，相当于“好像……一样”", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e6865c18-9c19-4131-8be9-c03230977fc2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90480, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "如同", "is_correct": true, "explanation": "“如同”引出比拟对象，与句末的“一样”呼应，表示“好像……一样”。"}, {"text": "讨厌", "is_correct": false, "explanation": "语义：“讨厌”表示反感，与“亲姐姐一样”的亲近态度矛盾。"}, {"text": "变成", "is_correct": false, "explanation": "语义：“变成”表示转变为另一种状态，句意是比拟，不是转变。"}, {"text": "充当", "is_correct": false, "explanation": "语义：“充当”指担任某种角色，与“对我……一样”表示的情感比拟不合。"}], "explanations": {"如同": "“如同”引出比拟对象，与句末的“一样”呼应，表示“好像……一样”。", "讨厌": "语义：“讨厌”表示反感，与“亲姐姐一样”的亲近态度矛盾。", "变成": "语义：“变成”表示转变为另一种状态，句意是比拟，不是转变。", "充当": "语义：“充当”指担任某种角色，与“对我……一样”表示的情感比拟不合。"}, "sentence_index": 0, "correct_answer": "如同"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我喜欢吃水果，如同苹果。", "explanation": "这里应该用〈比如〉。如同表示比拟，不能用来举例说明，举例要用“比如”。"}, {"text": "我们先吃饭，如同去散步。", "explanation": "这里应该用〈然后〉。如同表示比拟，不能表示动作的先后顺序。"}, {"text": "如同明天下雨，我们就不去了。", "explanation": "这里应该用〈如果〉。如同表示比拟，不能引出假设条件，假设要用“如果……就……”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b9f84982-8648-42e8-bc52-311a344324e8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90480, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "如同", "is_correct": true, "explanation": "“如同”表示比拟，与“一样好听”呼应，符合句意。"}, {"text": "成为", "is_correct": false, "explanation": "语义：“成为”表示变为某种身份或状态，句中要的是比拟，不是变化。"}, {"text": "看作", "is_correct": false, "explanation": "搭配：“看作”要接“把……看作……”的判断宾语，不能与“笑声”和“一样好听”的比拟搭配。"}, {"text": "具有", "is_correct": false, "explanation": "配价：“具有”后接属性名词，不能直接带“音乐一样好听”这样的比拟结构。"}], "explanations": {"如同": "“如同”表示比拟，与“一样好听”呼应，符合句意。", "成为": "语义：“成为”表示变为某种身份或状态，句中要的是比拟，不是变化。", "看作": "搭配：“看作”要接“把……看作……”的判断宾语，不能与“笑声”和“一样好听”的比拟搭配。", "具有": "配价：“具有”后接属性名词，不能直接带“音乐一样好听”这样的比拟结构。"}, "sentence_index": 6, "correct_answer": "如同"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "如同考试，她每天复习到深夜。", "explanation": "这里应该用〈为了〉。如同表示比拟，不能引出目的，目的要用“为了”。"}, {"text": "如同天冷，我们取消了郊游。", "explanation": "这里应该用〈因为〉。如同表示比拟，不能引出原因，因果关系要用“因为”。"}, {"text": "他很努力，如同没考好。", "explanation": "这里应该用〈但是〉。如同表示比拟，不能表示转折，转折要用“但是”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b9f84982-8648-42e8-bc52-311a344324e8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90480, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这个孩子说话很如同大人一样。", "corrected_sentence": "这个孩子说话如同大人一样。", "error_description": "错误：“很”修饰了“如同”。“如同”表示比拟，不能被程度副词修饰；应去掉“很”，写作“这个孩子说话如同大人一样。”", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b9f84982-8648-42e8-bc52-311a344324e8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90480, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这个小镇的夜晚如同童话安静。", "corrected_sentence": "这个小镇的夜晚如同童话一样安静。", "error_description": "错误：漏掉了“一样”。“如同……一样”后接形容词时，书面语通常保留“一样”，此句漏掉后不通顺；应在“童话”之后补上“一样”，写作“这个小镇的夜晚如同童话一样安静。”", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b9f84982-8648-42e8-bc52-311a344324e8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90483, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "小号", "is_correct": true, "explanation": "正确。小号与大号是尺寸上相对的一对反义词。"}, {"text": "尺码", "is_correct": false, "explanation": "不构成反义：尺码只是尺寸的标号，本身并不与“大号”相对。"}, {"text": "尺寸", "is_correct": false, "explanation": "不构成反义：尺寸泛指大小，与“大号”不是相对的一对词。"}, {"text": "码数", "is_correct": false, "explanation": "不构成反义：码数只是尺码的数字说法，不与“大号”相对。"}], "correct_answer": "小号", "explanations": {"小号": "正确。小号与大号是尺寸上相对的一对反义词。", "尺码": "不构成反义：尺码只是尺寸的标号，本身并不与“大号”相对。", "尺寸": "不构成反义：尺寸泛指大小，与“大号”不是相对的一对词。", "码数": "不构成反义：码数只是尺码的数字说法，不与“大号”相对。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1bc53ff7-a51d-4d12-b1a0-8dd6064ac128') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90483, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "小号", "is_correct": true, "explanation": "正确。小号与大号是尺寸上相对的一对反义词。"}, {"text": "体积", "is_correct": false, "explanation": "不构成反义：体积指物体所占的空间，与“大号”不是相对的词。"}, {"text": "容量", "is_correct": false, "explanation": "不构成反义：容量说能装多少，不与“大号”相对。"}, {"text": "尺度", "is_correct": false, "explanation": "不构成反义：尺度指衡量的标准，不与“大号”相对。"}], "correct_answer": "小号", "explanations": {"小号": "正确。小号与大号是尺寸上相对的一对反义词。", "体积": "不构成反义：体积指物体所占的空间，与“大号”不是相对的词。", "容量": "不构成反义：容量说能装多少，不与“大号”相对。", "尺度": "不构成反义：尺度指衡量的标准，不与“大号”相对。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1bc53ff7-a51d-4d12-b1a0-8dd6064ac128') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90483, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "property", "definition": "大号是比一般的更大的尺寸。", "primary_collocate": null, "pronunciation": "dà hào", "ipa": "ta˥˩ xɑʊ˥˩", "syllable_count": 2, "sentences": [{"text": "这件外套有大号和小号。", "target_word": "大号", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "商店里没有大号的运动鞋了。", "target_word": "大号", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我想买一个大号的书包。", "target_word": "大号", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他个子高，要穿大号的衬衫。", "target_word": "大号", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这家店的大号披萨很便宜。", "target_word": "大号", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子穿不了大号的衣服。", "target_word": "大号", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请问这种帽子有大号吗？", "target_word": "大号", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她把大号的盒子放在最下面。", "target_word": "大号", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "大号的雨伞可以两个人用。", "target_word": "大号", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个杯子是大号的，能装很多水。", "target_word": "大号", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "大號", "label": "繁体"}], "register": "中性", "sense_fingerprint": "名词；衣物、用品等比一般更大的尺寸", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4da068f4-1758-479c-9a13-02dccfe2d5c0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90483, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "大号", "is_correct": true, "explanation": "正确。大号指衣物、用品等比一般更大的尺寸。"}, {"text": "代号", "is_correct": false, "explanation": "dài 与 dà 只差韵母（多一个 i），意思是代号，指代替真实名称的符号。"}, {"text": "大豪", "is_correct": false, "explanation": "háo（第二声）与 hào（第四声）声调不同，意思是大豪，指有权势的大人物。"}, {"text": "打好", "is_correct": false, "explanation": "dǎ hǎo 与 dà hào 两个音节的声调都不同，意思是打好，即做好。"}], "explanations": {"大号": "正确。大号指衣物、用品等比一般更大的尺寸。", "代号": "dài 与 dà 只差韵母（多一个 i），意思是代号，指代替真实名称的符号。", "大豪": "háo（第二声）与 hào（第四声）声调不同，意思是大豪，指有权势的大人物。", "打好": "dǎ hǎo 与 dà hào 两个音节的声调都不同，意思是打好，即做好。"}, "sentence_index": null, "correct_answer": "大号"}, "level_3": {"options": [{"text": "大号", "is_correct": true, "explanation": "正确。“有大号和小号”是衣物的两种尺寸并列，“大号”正好填入。"}, {"text": "长袖", "is_correct": false, "explanation": "语义：“长袖”说袖子的长短，与“小号”不是同类尺寸，不能并列。"}, {"text": "红色", "is_correct": false, "explanation": "语义：“红色”说颜色，与“小号”不能并列为同类选项。"}, {"text": "圆领", "is_correct": false, "explanation": "搭配：“和小号”并列的必须是尺码，“圆领”是领口形状，不作尺码。"}], "explanations": {"大号": "正确。“有大号和小号”是衣物的两种尺寸并列，“大号”正好填入。", "长袖": "语义：“长袖”说袖子的长短，与“小号”不是同类尺寸，不能并列。", "红色": "语义：“红色”说颜色，与“小号”不能并列为同类选项。", "圆领": "搭配：“和小号”并列的必须是尺码，“圆领”是领口形状，不作尺码。"}, "sentence_index": 0, "correct_answer": "大号"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他每天在乐队里吹大号，声音很响亮。", "explanation": "这里的“大号”指铜管乐器，与衬衫的尺寸无关。"}, {"text": "这个大号的任务很难完成。", "explanation": "“大号”只用于衣服、用品等有尺码的物品，不能修饰任务；任务难度大应说“艰巨”。"}, {"text": "他想买一双大号的雨伞。", "explanation": "量词错误。雨伞不用“双”（双指成对的东西），应说“把”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1bc53ff7-a51d-4d12-b1a0-8dd6064ac128') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90483, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "大号", "is_correct": true, "explanation": "正确。大号指衣物、用品等比一般更大的尺寸。"}, {"text": "大道", "is_correct": false, "explanation": "dào 与 hào 声母不同（d 与 h），意思是大道，即光明正大的道理。"}, {"text": "大祸", "is_correct": false, "explanation": "huò 与 hào 韵母不同（uo 与 ao），意思是大祸，指重大的灾祸。"}, {"text": "大好", "is_correct": false, "explanation": "hǎo（第三声）与 hào（第四声）声调不同，意思是大好，即很好、极好。"}], "explanations": {"大号": "正确。大号指衣物、用品等比一般更大的尺寸。", "大道": "dào 与 hào 声母不同（d 与 h），意思是大道，即光明正大的道理。", "大祸": "huò 与 hào 韵母不同（uo 与 ao），意思是大祸，指重大的灾祸。", "大好": "hǎo（第三声）与 hào（第四声）声调不同，意思是大好，即很好、极好。"}, "sentence_index": null, "correct_answer": "大号"}, "level_3": {"options": [{"text": "大号", "is_correct": true, "explanation": "正确。问的是这种帽子有没有大号的尺寸。"}, {"text": "袜子", "is_correct": false, "explanation": "语义：帽子不是袜子，“这种帽子有袜子吗”说不通。"}, {"text": "鞋号", "is_correct": false, "explanation": "搭配：“鞋号”是鞋的尺码，不能用于帽子。"}, {"text": "身高", "is_correct": false, "explanation": "语义：帽子没有“身高”这一规格，问“有没有身高”说不通。"}], "explanations": {"大号": "正确。问的是这种帽子有没有大号的尺寸。", "袜子": "语义：帽子不是袜子，“这种帽子有袜子吗”说不通。", "鞋号": "搭配：“鞋号”是鞋的尺码，不能用于帽子。", "身高": "语义：帽子没有“身高”这一规格，问“有没有身高”说不通。"}, "sentence_index": 6, "correct_answer": "大号"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我用大号在网上发了一条消息。", "explanation": "这里的“大号”指网络上的主要账号，是另一个义项，与杯子的尺寸无关。"}, {"text": "他的成绩有大号的进步。", "explanation": "这里的“大号”只说物品尺寸，不能形容进步的程度；进步大要说“大幅进步”或“进步很大”。"}, {"text": "这个杯子是一条大号的，能装很多水。", "explanation": "量词错误。杯子不用“条”（条多用于细长的东西），应说“个”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1bc53ff7-a51d-4d12-b1a0-8dd6064ac128') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90483, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这件毛衣大号的一点，我穿着正好。", "corrected_sentence": "这件毛衣大号一点，我穿着正好。", "error_description": "错误：形容词“大号”与数量补语“一点”之间多加了“的”。正确：应说“大号一点”，中间不加“的”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1bc53ff7-a51d-4d12-b1a0-8dd6064ac128') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90483, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我想买一条大号的背包。", "corrected_sentence": "我想买一个大号的背包。", "error_description": "错误：“背包”用量词“条”，“条”多用于细长的东西，应用“个”。正确：应说“一个大号的背包”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1bc53ff7-a51d-4d12-b1a0-8dd6064ac128') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
