INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90491, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "找出一个东西在哪里。", "primary_collocate": null, "pronunciation": "dìng wèi", "ipa": "tiŋ˥˩ weɪ˥˩", "syllable_count": 2, "sentences": [{"text": "手机可以帮你定位朋友在哪里。", "target_word": "定位", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我的手机丢了，请帮我定位一下。", "target_word": "定位", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "警察用手机信号定位了那辆车。", "target_word": "定位", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "打开地图，先定位你现在的位置。", "target_word": "定位", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们靠卫星定位到了迷路的船。", "target_word": "定位", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "救援队很快定位了山里的游客。", "target_word": "定位", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个软件能定位你的家人在哪儿。", "target_word": "定位", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我用地图定位过那家小店。", "target_word": "定位", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请把你的位置发给我，我来定位。", "target_word": "定位", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "医生用机器定位了病人身体里的小石头。", "target_word": "定位", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "定位了", "label": "体标（了）"}, {"form": "定位过", "label": "体标（过）"}, {"form": "定位系统", "label": "复合词"}], "register": "中性", "sense_fingerprint": "用手机、卫星等找出人或物所在的位置", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e6865c18-9c19-4131-8be9-c03230977fc2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90491, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "定位", "is_correct": true, "explanation": "“定位”表示找出位置，与“帮你……朋友在哪里”的语义吻合。"}, {"text": "拍照", "is_correct": false, "explanation": "搭配：“拍照”的对象是人或景物，不能带“朋友在哪里”这种位置结构。"}, {"text": "聊天", "is_correct": false, "explanation": "配价：“聊天”是不及物动词，不能带“朋友在哪里”这样的宾语。"}, {"text": "安排", "is_correct": false, "explanation": "语义：“安排”指布置事务，与“找出朋友在哪里”的意思不合。"}], "explanations": {"定位": "“定位”表示找出位置，与“帮你……朋友在哪里”的语义吻合。", "拍照": "搭配：“拍照”的对象是人或景物，不能带“朋友在哪里”这种位置结构。", "聊天": "配价：“聊天”是不及物动词，不能带“朋友在哪里”这样的宾语。", "安排": "语义：“安排”指布置事务，与“找出朋友在哪里”的意思不合。"}, "sentence_index": 0, "correct_answer": "定位"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我们先定位会议的时间，再通知大家。", "explanation": "这里应该用〈确定〉。定位表示找出位置，不用于确定时间。"}, {"text": "学校定位上课不能迟到。", "explanation": "这里应该用〈规定〉。定位表示找出位置，不能用来表示规定。"}, {"text": "我定位明天去看海。", "explanation": "这里应该用〈决定〉。定位表示找出位置，不能用于决定行动。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b9f84982-8648-42e8-bc52-311a344324e8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90491, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "定位", "is_correct": true, "explanation": "“定位”表示找出位置，与“你的家人在哪儿”相合，符合句意。"}, {"text": "修理", "is_correct": false, "explanation": "语义：“修理”指修复物品，不能用来指找人的位置。"}, {"text": "翻译", "is_correct": false, "explanation": "搭配：“翻译”的对象是语言或文字，不能带“你的家人在哪儿”这样的宾语。"}, {"text": "批准", "is_correct": false, "explanation": "语义：“批准”指同意某事，与句中找人位置的语境不合。"}], "explanations": {"定位": "“定位”表示找出位置，与“你的家人在哪儿”相合，符合句意。", "修理": "语义：“修理”指修复物品，不能用来指找人的位置。", "翻译": "搭配：“翻译”的对象是语言或文字，不能带“你的家人在哪儿”这样的宾语。", "批准": "语义：“批准”指同意某事，与句中找人位置的语境不合。"}, "sentence_index": 6, "correct_answer": "定位"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "电视正在定位新闻。", "explanation": "这里应该用〈播放〉。定位表示找出位置，不能表示放映或播送内容。"}, {"text": "他在钢琴旁定位一首曲子。", "explanation": "这里应该用〈演奏〉。定位表示找出位置，不能用于演奏乐曲。"}, {"text": "妈妈在厨房定位晚饭。", "explanation": "这里应该用〈烧〉。定位表示找出位置，不能用于烹饪。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b9f84982-8648-42e8-bc52-311a344324e8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90491, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "快递员已经定位了了那个包裹。", "corrected_sentence": "快递员已经定位了那个包裹。", "error_description": "错误：“定位”后多加了一个“了”。“了”只用一次，应为“快递员已经定位了那个包裹。”", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b9f84982-8648-42e8-bc52-311a344324e8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90491, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "工程师用仪器定位了了那根地下管道。", "corrected_sentence": "工程师用仪器定位了那根地下管道。", "error_description": "错误：“了”重复。“定位”后只用一个“了”，表示动作完成；多写的一个“了”应删去，应为“工程师用仪器定位了那根地下管道。”", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b9f84982-8648-42e8-bc52-311a344324e8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
