INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90492, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "确定某人、品牌、产品或课程等的地位和作用。", "primary_collocate": null, "pronunciation": "dìng wèi", "ipa": "tiŋ˥˩ weɪ˥˩", "syllable_count": 2, "sentences": [{"text": "这家公司把自己定位为高端品牌。", "target_word": "定位", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们要先给这个产品定位。", "target_word": "定位", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他把这家小店定位成家庭餐厅。", "target_word": "定位", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这家店定位为年轻人的咖啡馆。", "target_word": "定位", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这款手机定位为学生用的便宜手机。", "target_word": "定位", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师把这门课定位为入门课。", "target_word": "定位", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们没有把自己定位清楚。", "target_word": "定位", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "政府把这座城市定位为旅游城市。", "target_word": "定位", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你要先想清楚怎么给自己定位。", "target_word": "定位", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个新品牌想把自己定位成平价时尚，不走高端路线。", "target_word": "定位", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "定位了", "label": "体标（了）"}, {"form": "定位过", "label": "体标（过）"}, {"form": "定位为", "label": "动补搭配"}], "register": "中性", "sense_fingerprint": "给人、品牌、产品、课程等确定地位和作用", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e6865c18-9c19-4131-8be9-c03230977fc2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90492, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "定位", "is_correct": true, "explanation": "“定位”表示确定自己的地位，与“为高端品牌”搭配，符合句意。"}, {"text": "检查", "is_correct": false, "explanation": "语义：“检查”指查看是否合格，不能表示确定身份或地位。"}, {"text": "喂养", "is_correct": false, "explanation": "搭配：“喂养”的对象是动物或婴幼儿，不能用于公司自身的定位。"}, {"text": "清洗", "is_correct": false, "explanation": "语义：“清洗”指洗涤，与“把自己……为高端品牌”的身份确定不合。"}], "explanations": {"定位": "“定位”表示确定自己的地位，与“为高端品牌”搭配，符合句意。", "检查": "语义：“检查”指查看是否合格，不能表示确定身份或地位。", "喂养": "搭配：“喂养”的对象是动物或婴幼儿，不能用于公司自身的定位。", "清洗": "语义：“清洗”指洗涤，与“把自己……为高端品牌”的身份确定不合。"}, "sentence_index": 0, "correct_answer": "定位"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "老师定位了我的作文。", "explanation": "这里应该用〈评价〉。定位表示确定地位或作用，不能用于对作文作出评价。"}, {"text": "这位设计师定位了一个新标志。", "explanation": "这里应该用〈设计〉。定位表示确定地位或作用，不能用来指制作标志。"}, {"text": "他定位了明天的会议。", "explanation": "这里应该用〈安排〉。定位表示确定地位或作用，不用于安排日程。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b9f84982-8648-42e8-bc52-311a344324e8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90492, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "定位", "is_correct": true, "explanation": "“定位”表示确定自己的位置或作用，与“清楚”搭配，符合句意。"}, {"text": "锻炼", "is_correct": false, "explanation": "搭配：“锻炼”指身体或能力的训练，不能与“清楚”搭配表示确定地位。"}, {"text": "装饰", "is_correct": false, "explanation": "搭配：“装饰”指美化外观，不能与“清楚”搭配。"}, {"text": "涂抹", "is_correct": false, "explanation": "语义：“涂抹”指把颜料或东西抹上，与“没有把自己……清楚”的语义不合。"}], "explanations": {"定位": "“定位”表示确定自己的位置或作用，与“清楚”搭配，符合句意。", "锻炼": "搭配：“锻炼”指身体或能力的训练，不能与“清楚”搭配表示确定地位。", "装饰": "搭配：“装饰”指美化外观，不能与“清楚”搭配。", "涂抹": "语义：“涂抹”指把颜料或东西抹上，与“没有把自己……清楚”的语义不合。"}, "sentence_index": 6, "correct_answer": "定位"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "姐姐每天定位碗筷。", "explanation": "这里应该用〈摆〉。定位表示确定地位或作用，不能表示摆放餐具。"}, {"text": "妈妈定位了一锅粥。", "explanation": "这里应该用〈煮〉。定位表示确定地位或作用，不能用于烹煮食物。"}, {"text": "我们每天定位教室。", "explanation": "这里应该用〈打扫〉。定位表示确定地位或作用，不能表示清扫场所。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b9f84982-8648-42e8-bc52-311a344324e8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90492, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这家书店把自己定位为的文化中心。", "corrected_sentence": "这家书店把自己定位为文化中心。", "error_description": "错误：“定位为”后多加了一个“的”。“为”后直接接所定的地位，应为“这家书店把自己定位为文化中心。”", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b9f84982-8648-42e8-bc52-311a344324e8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90492, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这座小镇把自己定位避暑胜地。", "corrected_sentence": "这座小镇把自己定位为避暑胜地。", "error_description": "错误：“定位”后漏掉了“为”。应为“定位为……”，“为”紧接在“定位”之后，引出所定的地位，应写作“这座小镇把自己定位为避暑胜地。”", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b9f84982-8648-42e8-bc52-311a344324e8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
