INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90497, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "马上就要死了。", "primary_collocate": null, "pronunciation": "jiāng sǐ", "ipa": "tɕjɑŋ˥ sɹ̩˨˩˦", "syllable_count": 2, "sentences": [{"text": "将死的老人想再见一次孙子。", "target_word": "将死", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "医生说这位病人将死，家人都哭了。", "target_word": "将死", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他知道自己将死，反而很平静。", "target_word": "将死", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这只将死的小鸟躺在树下。", "target_word": "将死", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "将死之人最想见的是家人。", "target_word": "将死", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她陪着将死的母亲说了一夜话。", "target_word": "将死", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "那棵树将死，叶子全都黄了。", "target_word": "将死", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "医院里有很多将死的病人。", "target_word": "将死", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他觉得自己将死，就写了一封信。", "target_word": "将死", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老人将死时，身边没有一个人。", "target_word": "将死", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "将死了", "label": "体标（了）"}], "register": "中性", "sense_fingerprint": "人或动植物马上就要死亡", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e6865c18-9c19-4131-8be9-c03230977fc2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90497, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "将死", "is_correct": true, "explanation": "正确答案。将死（jiāng sǐ）指人或动植物马上就要死亡。"}, {"text": "将是", "is_correct": false, "explanation": "shì（第四声）与 sǐ（第三声）声母不同且声调不同，意思是“将来会是”。"}, {"text": "僵尸", "is_correct": false, "explanation": "shī（第一声）与 sǐ（第三声）声母不同且声调不同，意思是僵硬的尸体。"}, {"text": "姜丝", "is_correct": false, "explanation": "sī（第一声）与 sǐ（第三声）声调不同，意思是姜切成的细丝。"}, {"text": "姜汁", "is_correct": false, "explanation": "zhī（第一声）与 sǐ（第三声）声母不同且声调不同，意思是姜榨出的汁。"}], "explanations": {"将死": "正确答案。将死（jiāng sǐ）指人或动植物马上就要死亡。", "将是": "shì（第四声）与 sǐ（第三声）声母不同且声调不同，意思是“将来会是”。", "僵尸": "shī（第一声）与 sǐ（第三声）声母不同且声调不同，意思是僵硬的尸体。", "姜丝": "sī（第一声）与 sǐ（第三声）声调不同，意思是姜切成的细丝。", "姜汁": "zhī（第一声）与 sǐ（第三声）声母不同且声调不同，意思是姜榨出的汁。"}, "sentence_index": null, "correct_answer": "将死"}, "level_3": {"options": [{"text": "将死", "is_correct": true, "explanation": "正确。“将死的老人”指快要去世的老人，与“想再见一次孙子”相符。"}, {"text": "病死", "is_correct": false, "explanation": "语义：已经病死的人无法再想见谁，与句意矛盾。"}, {"text": "饿死", "is_correct": false, "explanation": "语义：饿死的人已经死去，无法想再见孙子。"}, {"text": "淹死", "is_correct": false, "explanation": "搭配：“淹死”多指在水中死去，与这里老人想见孙子的语境不搭。"}], "explanations": {"将死": "正确。“将死的老人”指快要去世的老人，与“想再见一次孙子”相符。", "病死": "语义：已经病死的人无法再想见谁，与句意矛盾。", "饿死": "语义：饿死的人已经死去，无法想再见孙子。", "淹死": "搭配：“淹死”多指在水中死去，与这里老人想见孙子的语境不搭。"}, "sentence_index": 0, "correct_answer": "将死"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "猎人用枪把老虎将死了。", "explanation": "“将死”只表示即将死亡，不能用来表示用武器杀死一只动物。"}, {"text": "他用石头把那只兔子将死了。", "explanation": "“将死”不表示动手致死的动作，这里说的是用石头打死兔子，不符合它的意思。"}, {"text": "这份文件将死了，我们不用再处理它了。", "explanation": "这里应该用〈作废〉。将死只用于人或动植物，文件不能用此词。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b9f84982-8648-42e8-bc52-311a344324e8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90497, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "将死", "is_correct": true, "explanation": "正确答案。将死（jiāng sǐ）指人或动植物马上就要死亡。"}, {"text": "将士", "is_correct": false, "explanation": "shì（第四声）与 sǐ（第三声）声母不同且声调不同，意思是将领和士兵。"}, {"text": "将使", "is_correct": false, "explanation": "shǐ（第三声）与 sǐ（第三声）声母不同，意思是“将会让”。"}, {"text": "将试", "is_correct": false, "explanation": "shì（第四声）与 sǐ（第三声）声母不同且声调不同，意思是即将测试。"}, {"text": "将驶", "is_correct": false, "explanation": "shǐ（第三声）与 sǐ（第三声）声母不同，意思是船或车即将开行。"}], "explanations": {"将死": "正确答案。将死（jiāng sǐ）指人或动植物马上就要死亡。", "将士": "shì（第四声）与 sǐ（第三声）声母不同且声调不同，意思是将领和士兵。", "将使": "shǐ（第三声）与 sǐ（第三声）声母不同，意思是“将会让”。", "将试": "shì（第四声）与 sǐ（第三声）声母不同且声调不同，意思是即将测试。", "将驶": "shǐ（第三声）与 sǐ（第三声）声母不同，意思是船或车即将开行。"}, "sentence_index": null, "correct_answer": "将死"}, "level_3": {"options": [{"text": "将死", "is_correct": true, "explanation": "正确。“那棵树将死”指树快要枯死，与“叶子全都黄了”相符。"}, {"text": "返青", "is_correct": false, "explanation": "语义：返青指重新变绿，与“叶子全都黄了”的描述矛盾。"}, {"text": "发芽", "is_correct": false, "explanation": "语义：发芽表示生长，与“叶子全都黄了”的描述矛盾。"}, {"text": "长青", "is_correct": false, "explanation": "语义：“长青”指一直保持绿色，与“叶子全都黄了”的描述矛盾。"}], "explanations": {"将死": "正确。“那棵树将死”指树快要枯死，与“叶子全都黄了”相符。", "返青": "语义：返青指重新变绿，与“叶子全都黄了”的描述矛盾。", "发芽": "语义：发芽表示生长，与“叶子全都黄了”的描述矛盾。", "长青": "语义：“长青”指一直保持绿色，与“叶子全都黄了”的描述矛盾。"}, "sentence_index": 6, "correct_answer": "将死"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他把老人将死了，然后去吃饭。", "explanation": "“将死”只表示即将死亡，不能用来表示动手致死。"}, {"text": "这间屋子将死时，我们正在吃饭。", "explanation": "这里应该用〈倒塌〉。将死只用于人或动植物，房屋不能用此词。"}, {"text": "这块石头将死了，所以工人们把它搬走了。", "explanation": "将死只用于人或动植物，石头没有生命，不能用此词。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b9f84982-8648-42e8-bc52-311a344324e8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90497, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "老人将死了了，家人都在身边。", "corrected_sentence": "老人将死了，家人都在身边。", "error_description": "“将死了”后面多加了一个“了”，应去掉多余的“了”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b9f84982-8648-42e8-bc52-311a344324e8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90497, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "那棵老树将死着，叶子也都黄了。", "corrected_sentence": "那棵老树将死，叶子也都黄了。", "error_description": "“将死”后面多加了“着”。“将死”是快要死亡的状态，不能用“着”表示持续，应去掉“着”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b9f84982-8648-42e8-bc52-311a344324e8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
