INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90498, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b9f84982-8648-42e8-bc52-311a344324e8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90498, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "下棋时将军，使对方的王无路可走，棋局随之结束。", "primary_collocate": null, "pronunciation": "jiāng sǐ", "ipa": "tɕjɑŋ˥ sɹ̩˨˩˦", "syllable_count": 2, "sentences": [{"text": "他走了一步棋，把我的王将死了。", "target_word": "将死", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "再走一步，我就能将死对方了。", "target_word": "将死", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这盘棋你已经将死我了。", "target_word": "将死", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他用马将死了对方的王。", "target_word": "将死", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这局棋他布置得很巧，一步步逼近，最后将死了对方。", "target_word": "将死", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这步棋看起来很平淡，其实暗藏玄机，能将死对方。", "target_word": "将死", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他看准了这个空档，这一步就能将死对方的王。", "target_word": "将死", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "下棋时，一步好棋就能将死对手。", "target_word": "将死", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他看出这一步能将死对方，于是很平静地落子。", "target_word": "将死", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师说，这步棋会将死黑方。", "target_word": "将死", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "将死了", "label": "体标（了）"}], "register": "中性", "sense_fingerprint": "下棋时将对方的王逼到无路可走（将杀）", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e6865c18-9c19-4131-8be9-c03230977fc2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90498, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "将死", "is_correct": true, "explanation": "正确答案。将死（jiāng sǐ）指下棋时把对方的王逼到无路可走。"}, {"text": "将是", "is_correct": false, "explanation": "shì（第四声）与 sǐ（第三声）声母不同且声调不同，意思是“将来会是”。"}, {"text": "僵尸", "is_correct": false, "explanation": "shī（第一声）与 sǐ（第三声）声母不同且声调不同，意思是僵硬的尸体。"}, {"text": "姜丝", "is_correct": false, "explanation": "sī（第一声）与 sǐ（第三声）声调不同，意思是姜切成的细丝。"}, {"text": "姜汁", "is_correct": false, "explanation": "zhī（第一声）与 sǐ（第三声）声母不同且声调不同，意思是姜榨出的汁。"}], "explanations": {"将死": "正确答案。将死（jiāng sǐ）指下棋时把对方的王逼到无路可走。", "将是": "shì（第四声）与 sǐ（第三声）声母不同且声调不同，意思是“将来会是”。", "僵尸": "shī（第一声）与 sǐ（第三声）声母不同且声调不同，意思是僵硬的尸体。", "姜丝": "sī（第一声）与 sǐ（第三声）声调不同，意思是姜切成的细丝。", "姜汁": "zhī（第一声）与 sǐ（第三声）声母不同且声调不同，意思是姜榨出的汁。"}, "sentence_index": null, "correct_answer": "将死"}, "level_3": {"options": [{"text": "将死", "is_correct": true, "explanation": "正确。“把我的王将死了”指下棋时把对方的王逼到绝路，棋局随之结束。"}, {"text": "饿死", "is_correct": false, "explanation": "语义：“饿死”指因缺少食物而死，棋子不会挨饿，与棋局无关。"}, {"text": "咬死", "is_correct": false, "explanation": "搭配：“咬死”用于动物或人被咬致死，不能用来说棋子的王被咬死。"}, {"text": "闷死", "is_correct": false, "explanation": "语义：“闷死”指因窒息而死，与下棋的动作无关。"}], "explanations": {"将死": "正确。“把我的王将死了”指下棋时把对方的王逼到绝路，棋局随之结束。", "饿死": "语义：“饿死”指因缺少食物而死，棋子不会挨饿，与棋局无关。", "咬死": "搭配：“咬死”用于动物或人被咬致死，不能用来说棋子的王被咬死。", "闷死": "语义：“闷死”指因窒息而死，与下棋的动作无关。"}, "sentence_index": 0, "correct_answer": "将死"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "猎人用枪把老虎将死了。", "explanation": "“将死”只用于下棋时将死对方的王，不能用来表示用武器杀死一只动物。"}, {"text": "他把我的车将死了。", "explanation": "这里应该用〈吃〉。将死只针对对方的王，吃掉对方的棋子要说“吃”，不能说将死。"}, {"text": "他把自己的王将死了。", "explanation": "这里误用了将死的方向：将死只针对对方的王，把己方的王陷入绝境属于违规，不能用“将死”来描述。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b9f84982-8648-42e8-bc52-311a344324e8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90498, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "将死", "is_correct": true, "explanation": "正确答案。将死（jiāng sǐ）指下棋时把对方的王逼到无路可走。"}, {"text": "将士", "is_correct": false, "explanation": "shì（第四声）与 sǐ（第三声）声母不同且声调不同，意思是将领和士兵。"}, {"text": "将使", "is_correct": false, "explanation": "shǐ（第三声）与 sǐ（第三声）声母不同，意思是“将会让”。"}, {"text": "将试", "is_correct": false, "explanation": "shì（第四声）与 sǐ（第三声）声母不同且声调不同，意思是即将测试。"}, {"text": "将驶", "is_correct": false, "explanation": "shǐ（第三声）与 sǐ（第三声）声母不同，意思是船或车即将开行。"}], "explanations": {"将死": "正确答案。将死（jiāng sǐ）指下棋时把对方的王逼到无路可走。", "将士": "shì（第四声）与 sǐ（第三声）声母不同且声调不同，意思是将领和士兵。", "将使": "shǐ（第三声）与 sǐ（第三声）声母不同，意思是“将会让”。", "将试": "shì（第四声）与 sǐ（第三声）声母不同且声调不同，意思是即将测试。", "将驶": "shǐ（第三声）与 sǐ（第三声）声母不同，意思是船或车即将开行。"}, "sentence_index": null, "correct_answer": "将死"}, "level_3": {"options": [{"text": "将死", "is_correct": true, "explanation": "正确。“这一步就能将死对方的王”指下棋时把对方的王逼到绝路，与句意相符。"}, {"text": "救活", "is_correct": false, "explanation": "语义：“救活”指使人或物从危险中恢复，与下棋时逼死对方的王的意思相反。"}, {"text": "放走", "is_correct": false, "explanation": "语义：“放走”指让人或物离开，不能表示把对方的王逼入绝境。"}, {"text": "复活", "is_correct": false, "explanation": "语义：“复活”指死而复生，与将对方的王逼入绝境的意思不合。"}], "explanations": {"将死": "正确。“这一步就能将死对方的王”指下棋时把对方的王逼到绝路，与句意相符。", "救活": "语义：“救活”指使人或物从危险中恢复，与下棋时逼死对方的王的意思相反。", "放走": "语义：“放走”指让人或物离开，不能表示把对方的王逼入绝境。", "复活": "语义：“复活”指死而复生，与将对方的王逼入绝境的意思不合。"}, "sentence_index": 6, "correct_answer": "将死"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这步棋会把黑方的马将死。", "explanation": "这里应该用〈吃〉。将死只针对王，吃掉对方的棋子要说“吃”，不能说将死。"}, {"text": "这只猫把老鼠将死了。", "explanation": "“将死”只用于下棋时将死对方的王，不能用来表示杀死一只老鼠。"}, {"text": "这步棋让黑方的兵将死。", "explanation": "这里应该用〈吃〉。将死只针对王，吃掉对方的棋子要说“吃”，不能说将死。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b9f84982-8648-42e8-bc52-311a344324e8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90498, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "对方的马跳过来，把我的王将死着。", "corrected_sentence": "对方的马跳过来，把我的王将死了。", "error_description": "“将死”指一步棋造成的结果，是一次性完成的，不能加“着”表示持续，应把“着”改为“了”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b9f84982-8648-42e8-bc52-311a344324e8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90498, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这步棋会把黑方的王将死了了。", "corrected_sentence": "这步棋会把黑方的王将死。", "error_description": "“将死”后面多加了一个“了”。“将死”本身已表示结果，不能再加“了”，应去掉多余的“了”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b9f84982-8648-42e8-bc52-311a344324e8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90503, 1, 'llm_types_A', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '71686fda-6fd9-4849-9233-e16873699209') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90503, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '71686fda-6fd9-4849-9233-e16873699209') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90503, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "去信是写信寄给别人。", "primary_collocate": null, "pronunciation": "qù xìn", "ipa": "tɕʰy˥˩ ɕin˥˩", "syllable_count": 2, "sentences": [{"text": "我想给老同学去信。", "target_word": "去信", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "他每个月都给家里去信。", "target_word": "去信", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "我去信向他道谢。", "target_word": "去信", "complexity_tier": "T3", "furigana": "wǒ qù xìn xiàng tā dào xiè", "sentence_source": "generated"}, {"text": "她去信邀请朋友来玩。", "target_word": "去信", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "我昨天给王先生去信了。", "target_word": "去信", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他去信向我借书。", "target_word": "去信", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "爷爷不会用手机，只能去信联系老朋友。", "target_word": "去信", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你有什么问题，就去信问我吧。", "target_word": "去信", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "学生们去信感谢那位老师。", "target_word": "去信", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我去信问了他两次，他还没回信。", "target_word": "去信", "complexity_tier": "T3", "furigana": "wǒ qù xìn wèn le tā liǎng cì, tā hái méi huí xìn", "sentence_source": "generated"}], "morphological_forms": [{"form": "去信了", "label": "体标"}], "register": "书面", "sense_fingerprint": "去信：写信并寄给别人", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f55774ed-ddc3-49eb-a960-56e3f2d39f09') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90503, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "去信", "is_correct": true, "explanation": "正确。“我想给老同学去信”表示想写信寄给老同学，符合句意。"}, {"text": "笑", "is_correct": false, "explanation": "搭配：“笑”不能与“给老同学”组合，句子不通。"}, {"text": "哭", "is_correct": false, "explanation": "搭配：“哭”不能与“给老同学”组合，句子不通。"}, {"text": "睡", "is_correct": false, "explanation": "语义：“睡”是不及物动词，不能带“给老同学”这样的间接对象，句子不通。"}], "explanations": {"去信": "正确。“我想给老同学去信”表示想写信寄给老同学，符合句意。", "笑": "搭配：“笑”不能与“给老同学”组合，句子不通。", "哭": "搭配：“哭”不能与“给老同学”组合，句子不通。", "睡": "语义：“睡”是不及物动词，不能带“给老同学”这样的间接对象，句子不通。"}, "sentence_index": 0, "correct_answer": "去信"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我每天晚上都去信日记。", "explanation": "这里应该用〈写〉。去信指写信寄给别人，日记不寄给别人，应说“写日记”。"}, {"text": "我昨天给妈妈去信，聊了很久。", "explanation": "这里应该用〈打电话〉。去信是书面寄信，不能用于边聊边说。"}, {"text": "我把礼物去信给了奶奶。", "explanation": "这里应该用〈寄〉。去信指写信，礼物要用“寄”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '71686fda-6fd9-4849-9233-e16873699209') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90503, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "去信", "is_correct": true, "explanation": "正确。“只能去信联系老朋友”表示用写信的方式联系，符合句意。"}, {"text": "唱", "is_correct": false, "explanation": "语义：唱歌不能用来联系老朋友。"}, {"text": "笑", "is_correct": false, "explanation": "搭配：“笑”无法与“联系”搭配，句子不通。"}, {"text": "看", "is_correct": false, "explanation": "语义：看只能看到，不能用来“联系”老朋友。"}], "explanations": {"去信": "正确。“只能去信联系老朋友”表示用写信的方式联系，符合句意。", "唱": "语义：唱歌不能用来联系老朋友。", "笑": "搭配：“笑”无法与“联系”搭配，句子不通。", "看": "语义：看只能看到，不能用来“联系”老朋友。"}, "sentence_index": 6, "correct_answer": "去信"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我们约好明天去信，一起吃饭。", "explanation": "这里应该用〈见面〉。去信是寄信，不能用来约定见面吃饭。"}, {"text": "我很喜欢这首歌，每天都去信它。", "explanation": "这里应该用〈听〉。去信指写信寄给对方，不能用来指听歌。"}, {"text": "这篇文章很长，我花了一个小时才去信完。", "explanation": "这里应该用〈读〉。去信指写信寄给对方，不能用来指读文章。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '71686fda-6fd9-4849-9233-e16873699209') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90503, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我昨天给小王去信着。", "corrected_sentence": "我昨天给小王去信了。", "error_description": "体标错误：“昨天”指已完成的动作，应用“了”，不用表示持续或状态的“着”。“我昨天给小王去信着”应改为“我昨天给小王去信了”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '71686fda-6fd9-4849-9233-e16873699209') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90503, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我给他去信三个了。", "corrected_sentence": "我给他去信三次了。", "error_description": "动量词错误：“去信”计算次数要用动量词“次”，不用名量词“个”。应说“去信三次”，不说“去信三个”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '71686fda-6fd9-4849-9233-e16873699209') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
