INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90515, 1, 'prompt1_core', '{"pos": "代词", "semantic_class": "function", "definition": "用来问事情是怎样做的，或者为什么。", "primary_collocate": null, "pronunciation": "zěn", "ipa": "tsən˨˩˦", "syllable_count": 1, "sentences": [{"text": "你怎不早说呢？", "target_word": "怎", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这么晚了，你怎还不睡？", "target_word": "怎", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他怎没来上课？", "target_word": "怎", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这么简单的题，你怎还做不对？", "target_word": "怎", "complexity_tier": "T3", "furigana": "zhè me jiǎn dān de tí, nǐ zěn hái zuò bú duì?", "sentence_source": "generated"}, {"text": "天这么冷，你怎只穿一件衣服？", "target_word": "怎", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这么大的事，你怎没提前告诉我？", "target_word": "怎", "complexity_tier": "T3", "furigana": "zhè me dà de shì, nǐ zěn méi tíqián gàosu wǒ?", "sentence_source": "generated"}, {"text": "天都黑了，你怎还在外面玩？", "target_word": "怎", "complexity_tier": "T3", "furigana": "tiān dōu hēi le, nǐ zěn hái zài wài miàn wán?", "sentence_source": "generated"}, {"text": "她怎不接我的电话？", "target_word": "怎", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这么重的书，我一个人怎拿得动？", "target_word": "怎", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这么远的路，你怎还不坐车？", "target_word": "怎", "complexity_tier": "T3", "furigana": "zhè me yuǎn de lù, nǐ zěn hái bú zuò chē?", "sentence_source": "generated"}], "morphological_forms": [{"form": "怎么", "label": "复合词"}, {"form": "怎样", "label": "复合词"}, {"form": "怎么样", "label": "复合词"}], "register": "口语", "sense_fingerprint": "疑问代词，问方式或原因，后面直接接动词或助动词", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5ac86440-8f5a-4834-8135-427d86e72be0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90515, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "谁", "is_correct": false, "explanation": "语义：“谁”问人，不问原因，与“不早说”的语境不符。"}, {"text": "怎", "is_correct": true, "explanation": "怎：疑问代词，问原因，与“不早说”搭配。"}, {"text": "什么", "is_correct": false, "explanation": "语义：“什么”问事物，不能表示“为什么不早说”。"}, {"text": "这么", "is_correct": false, "explanation": "搭配：“这么”表示程度或方式，不能用来问原因。"}], "explanations": {"谁": "语义：“谁”问人，不问原因，与“不早说”的语境不符。", "怎": "怎：疑问代词，问原因，与“不早说”搭配。", "什么": "语义：“什么”问事物，不能表示“为什么不早说”。", "这么": "搭配：“这么”表示程度或方式，不能用来问原因。"}, "sentence_index": 0, "correct_answer": "怎"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我不知道他的怎，就走了。", "explanation": "〈怎〉是疑问代词，不能做名词，也不能接在“的”后面。"}, {"text": "这是怎的一本书？", "explanation": "〈怎〉不能修饰名词，问性质要用“什么样的”。"}, {"text": "我怎很多书要读。", "explanation": "〈怎〉不能放在“很多”前面表示数量，应说“有很多书要读”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '54d136a2-1535-496c-b74e-b1f72dabe9c2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90515, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "哪", "is_correct": false, "explanation": "语义：“哪”表示地点或选择，不能问“为什么还在外面玩”。"}, {"text": "那么", "is_correct": false, "explanation": "搭配：“那么”后不能接“还在外面玩”，句子不通。"}, {"text": "怎", "is_correct": true, "explanation": "怎：问原因，与“天都黑了还在外面玩”的语境相符。"}, {"text": "何", "is_correct": false, "explanation": "语域：“何”是书面语，口语里不说“你何还在外面玩”。"}], "explanations": {"哪": "语义：“哪”表示地点或选择，不能问“为什么还在外面玩”。", "那么": "搭配：“那么”后不能接“还在外面玩”，句子不通。", "怎": "怎：问原因，与“天都黑了还在外面玩”的语境相符。", "何": "语域：“何”是书面语，口语里不说“你何还在外面玩”。"}, "sentence_index": 6, "correct_answer": "怎"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他因为感冒，怎没来上课。", "explanation": "〈怎〉表示疑问，与“因为感冒”已说明的原因相冲突，应直接说“他因为感冒没来上课”。"}, {"text": "这件衣服怎很好看。", "explanation": "〈怎〉不能放在“很”前面修饰形容词，程度要说“怎么这么”。"}, {"text": "我买了怎三个苹果。", "explanation": "〈怎〉不能用来表示数量，问数量要用“几”或“多少”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '54d136a2-1535-496c-b74e-b1f72dabe9c2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90515, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他还怎没吃饭？", "corrected_sentence": "他怎还没吃饭？", "error_description": "词序错误：“怎”要放在“还”前面，应说“怎还”，不能说“还怎”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '54d136a2-1535-496c-b74e-b1f72dabe9c2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90515, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这道菜你怎了还不吃？", "corrected_sentence": "这道菜你怎还不吃？", "error_description": "多余成分：“怎”后面不能加“了”，删去“了”即可。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '54d136a2-1535-496c-b74e-b1f72dabe9c2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
