INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90528, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "用手或工具牢牢握住；捉住。", "primary_collocate": null, "pronunciation": "zhuā zhù", "ipa": "ʈʂu̯a˥ ʈʂu˥˩", "syllable_count": 2, "sentences": [{"text": "警察在路口抓住了小偷。", "target_word": "抓住", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小猫用爪子抓住了老鼠。", "target_word": "抓住", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他用网抓住了一条大鱼。", "target_word": "抓住", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子想抓住飞来飞去的蝴蝶。", "target_word": "抓住", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "农民用夹子抓住了偷吃粮食的老鼠。", "target_word": "抓住", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我终于抓住了那只跑进厨房的小鸟。", "target_word": "抓住", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他用工具抓住了地上的蛇。", "target_word": "抓住", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "保安抓住了想翻墙的人。", "target_word": "抓住", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "奶奶一下子抓住了溜走的小鸡。", "target_word": "抓住", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小朋友用小网抓住了一只青蛙。", "target_word": "抓住", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "抓住了", "label": "完成体"}, {"form": "抓住过", "label": "经历体"}], "register": "中性", "sense_fingerprint": "抓住：用手或工具牢牢握住；捉住", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd3f4d125-09bd-4a29-83b8-15c3ccd853c7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90528, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "抓住", "is_correct": true, "explanation": "正确：「抓住」表示捉住，与「警察在路口」抓获小偷的句意相符。"}, {"text": "搬", "is_correct": false, "explanation": "搭配：「搬」通常接物品，不能用来说「搬了小偷」。"}, {"text": "养", "is_correct": false, "explanation": "语义：「养」指饲养或抚养，与警察抓获小偷的情境完全不合。"}, {"text": "请", "is_correct": false, "explanation": "语义：「请」是邀请或请客的意思，与警察在路口抓获小偷的语境不符。"}], "explanations": {"抓住": "正确：「抓住」表示捉住，与「警察在路口」抓获小偷的句意相符。", "搬": "搭配：「搬」通常接物品，不能用来说「搬了小偷」。", "养": "语义：「养」指饲养或抚养，与警察抓获小偷的情境完全不合。", "请": "语义：「请」是邀请或请客的意思，与警察在路口抓获小偷的语境不符。"}, "sentence_index": 0, "correct_answer": "抓住"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "孩子用沙子抓住了那只蝴蝶。", "explanation": "这里应该用〈埋住〉。埋是用沙土盖住，抓住要求用手或工具握紧，沙子不能“抓”蝴蝶。"}, {"text": "奶奶用手抓住了一把空气，想把它装进瓶子里。", "explanation": "这里应该用〈收集〉。空气无法被握住，「抓住」说不通；把空气装进瓶子应说收集。"}, {"text": "工人用水泥抓住了洞口。", "explanation": "这里应该用〈堵住〉。堵是填住或挡住，表示封闭；「抓住洞口」说不通，不是捉住的意思。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '884bc76d-2bca-4740-b392-561903b984d1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90528, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "抓住", "is_correct": true, "explanation": "正确：「抓住」表示用工具捉住，与「用工具」捉蛇的句意相符。"}, {"text": "吃", "is_correct": false, "explanation": "语义：「吃」是咽下食物，与「用工具」去捉地上的蛇的动作不符。"}, {"text": "唱", "is_correct": false, "explanation": "搭配：「唱」的对象是歌曲等，不能用来表示捉蛇。"}, {"text": "穿", "is_correct": false, "explanation": "搭配：「穿」接的是衣物、鞋袜等，不能用来表示捉蛇。"}], "explanations": {"抓住": "正确：「抓住」表示用工具捉住，与「用工具」捉蛇的句意相符。", "吃": "语义：「吃」是咽下食物，与「用工具」去捉地上的蛇的动作不符。", "唱": "搭配：「唱」的对象是歌曲等，不能用来表示捉蛇。", "穿": "搭配：「穿」接的是衣物、鞋袜等，不能用来表示捉蛇。"}, "sentence_index": 6, "correct_answer": "抓住"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他用力抓住了那只老鼠的影子。", "explanation": "这里应该用〈盯住〉。影子无法被握住，「抓住」说不通；表示目光注视应说盯住。"}, {"text": "农民抓住了一阵风，把它挡在门外。", "explanation": "这里应该用〈挡〉。风无法被握住，「抓住」说不通；阻止风进入应说挡。"}, {"text": "他抓住了那首歌的旋律，很快就唱了出来。", "explanation": "这里应该用〈记住〉。「抓住」用于具体的握持或捕捉，不用于抽象的旋律，应说记住。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '884bc76d-2bca-4740-b392-561903b984d1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90528, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "警察在路上把小偷抓住了了。", "corrected_sentence": "警察在路上把小偷抓住了。", "error_description": "错误：「抓住了了」，「了」重复；正确：「抓住了」。「了」只用一次，放在「把」字句的动词「抓住」之后。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '884bc76d-2bca-4740-b392-561903b984d1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90528, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他用工具把地上的蛇抓住了了。", "corrected_sentence": "他用工具把地上的蛇抓住了。", "error_description": "错误：「抓住了了」，「了」重复；正确：「抓住了」。「了」只用一次，接在复合动词「抓住」之后，表示动作已经完成。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '884bc76d-2bca-4740-b392-561903b984d1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
