INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90537, 1, 'prompt1_core', '{"pos": "副词", "semantic_class": "function", "definition": "必是一定会这样，不会不这样。", "primary_collocate": null, "pronunciation": "bì", "ipa": "pi˥˩", "syllable_count": 1, "sentences": [{"text": "他说话算数，说了必来。", "target_word": "必", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "你好好学习，必会进步。", "target_word": "必", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "骄傲的人必会失败。", "target_word": "必", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "春天到了，花必会开。", "target_word": "必", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他这么用功，考试必能通过。", "target_word": "必", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "好人必有好报。", "target_word": "必", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "下这么大的雨，比赛必会取消。", "target_word": "必", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "坚持练习，你的汉语必有进步。", "target_word": "必", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他说今天必来，可是没来。", "target_word": "必", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "冬天一到，这里必下大雪。", "target_word": "必", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "必然", "label": "复合词"}, {"form": "必须", "label": "复合词"}], "register": "书面语", "sense_fingerprint": "必：副词，表示推断一定会这样", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a7cb592a-ebe9-461b-8879-76b618f34d38') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90537, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "必", "is_correct": true, "explanation": "正确答案：必（bì，第四声），意思是一定。"}, {"text": "比", "is_correct": false, "explanation": "bǐ（第三声）与 bì（第四声）声调不同，意思是比较。"}, {"text": "鼻", "is_correct": false, "explanation": "bí（第二声）与 bì（第四声）声调不同，意思是鼻子。"}, {"text": "逼", "is_correct": false, "explanation": "bī（第一声）与 bì（第四声）声调不同，意思是逼迫。"}, {"text": "布", "is_correct": false, "explanation": "bù 与 bì 韵母不同（ù 与 ì），声调都是第四声，意思是布匹。"}], "explanations": {"必": "正确答案：必（bì，第四声），意思是一定。", "比": "bǐ（第三声）与 bì（第四声）声调不同，意思是比较。", "鼻": "bí（第二声）与 bì（第四声）声调不同，意思是鼻子。", "逼": "bī（第一声）与 bì（第四声）声调不同，意思是逼迫。", "布": "bù 与 bì 韵母不同（ù 与 ì），声调都是第四声，意思是布匹。"}, "sentence_index": null, "correct_answer": "必"}, "level_3": {"options": [{"text": "必", "is_correct": true, "explanation": "“必”表示一定会这样，与“说话算数”的承诺语气相符。"}, {"text": "偶尔", "is_correct": false, "explanation": "语义：“偶尔”表示不常发生，与“说话算数”的承诺相悖。"}, {"text": "几乎", "is_correct": false, "explanation": "语义：“几乎”表示接近但未达到，与“说话算数、说了必来”所表达的确定承诺不符。"}, {"text": "从不", "is_correct": false, "explanation": "语义：“从不”表示从未如此，与“说了……来”的承诺相矛盾。"}], "explanations": {"必": "“必”表示一定会这样，与“说话算数”的承诺语气相符。", "偶尔": "语义：“偶尔”表示不常发生，与“说话算数”的承诺相悖。", "几乎": "语义：“几乎”表示接近但未达到，与“说话算数、说了必来”所表达的确定承诺不符。", "从不": "语义：“从不”表示从未如此，与“说了……来”的承诺相矛盾。"}, "sentence_index": 0, "correct_answer": "必"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我没有把握，但这个答案必对。", "explanation": "这里是把“必”当作“也许”的不确定义来用。“必”表示一定，与“没有把握”矛盾；推测不定时应用〈也许〉。"}, {"text": "会议请必准时到场。", "explanation": "这里应该用〈务必〉。“务必”表示一定要做到，用于请求或叮嘱；“必”单用时不能用来请求别人。"}, {"text": "明天的天气说不准，但明天必下雨。", "explanation": "这里是把“必”当作“可能”的不确定义来用。“必”表示一定会，与“说不准”矛盾；表示不确定应用〈可能〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd3a268d3-f614-4983-a57d-533698cf7a82') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90537, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "必", "is_correct": true, "explanation": "正确答案：必（bì，第四声），意思是一定。"}, {"text": "笔", "is_correct": false, "explanation": "bǐ（第三声）与 bì（第四声）声调不同，意思是笔。"}, {"text": "步", "is_correct": false, "explanation": "bù 与 bì 韵母不同（ù 与 ì），声调都是第四声，意思是脚步。"}, {"text": "不", "is_correct": false, "explanation": "bù 与 bì 韵母不同（ù 与 ì），声调都是第四声，意思是不。"}, {"text": "部", "is_correct": false, "explanation": "bù 与 bì 韵母不同（ù 与 ì），声调都是第四声，意思是部分、部门。"}], "explanations": {"必": "正确答案：必（bì，第四声），意思是一定。", "笔": "bǐ（第三声）与 bì（第四声）声调不同，意思是笔。", "步": "bù 与 bì 韵母不同（ù 与 ì），声调都是第四声，意思是脚步。", "不": "bù 与 bì 韵母不同（ù 与 ì），声调都是第四声，意思是不。", "部": "bù 与 bì 韵母不同（ù 与 ì），声调都是第四声，意思是部分、部门。"}, "sentence_index": null, "correct_answer": "必"}, "level_3": {"options": [{"text": "必", "is_correct": true, "explanation": "“必”表示推断一定会发生，与“下这么大的雨”的因果判断相符。"}, {"text": "刚", "is_correct": false, "explanation": "语义：“刚”表示刚发生，与“会”所表示的将来推断不相容。"}, {"text": "很", "is_correct": false, "explanation": "语义：“很”表示程度高，不表示推断；“比赛很会取消”的意思不通，与“下这么大的雨”的推断语境也不相符。"}, {"text": "已", "is_correct": false, "explanation": "语义：“已”表示已经发生，与“会取消”的将来推断相矛盾。"}], "explanations": {"必": "“必”表示推断一定会发生，与“下这么大的雨”的因果判断相符。", "刚": "语义：“刚”表示刚发生，与“会”所表示的将来推断不相容。", "很": "语义：“很”表示程度高，不表示推断；“比赛很会取消”的意思不通，与“下这么大的雨”的推断语境也不相符。", "已": "语义：“已”表示已经发生，与“会取消”的将来推断相矛盾。"}, "sentence_index": 6, "correct_answer": "必"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这个消息我还没核实，但它必是真的。", "explanation": "这里是把“必”当作“也许”的不确定义来用。“必”表示确定无疑，与“没核实”矛盾；不确定应用〈也许〉。"}, {"text": "这次比赛的结果还没有人知道，但他必赢。", "explanation": "这里是把“必”当作“不确定”的意思来用。“必”表示一定，与“还没有人知道”矛盾；表示不确定应用〈也许〉。"}, {"text": "我们明天去不去还没定，却必去。", "explanation": "这里是把“必”当作“也许”的不确定义来用。“必”表示一定会，与“还没定”矛盾；不确定应用〈也许〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd3a268d3-f614-4983-a57d-533698cf7a82')