INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90547, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "战士是保护国家的人，他们穿着军装，很勇敢。", "primary_collocate": null, "pronunciation": "zhàn shì", "ipa": "ʈʂan˥˩ ʂʅ˥˩", "syllable_count": 2, "sentences": [{"text": "这位战士穿着绿色的军装。", "target_word": "战士", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "战士们站在雨里，一动不动。", "target_word": "战士", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他从小就想当一名战士。", "target_word": "战士", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "战士保护着国家和人民。", "target_word": "战士", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "那名年轻的战士非常勇敢。", "target_word": "战士", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "战士们每天早上都要跑步。", "target_word": "战士", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小明长大后想做保护国家的战士。", "target_word": "战士", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "一位战士把水送给了老人。", "target_word": "战士", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "战士们在山上守了一夜。", "target_word": "战士", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "看到战士走过来，孩子们都笑了。", "target_word": "战士", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "名", "label": "量词"}, {"form": "位", "label": "量词"}, {"form": "戰士", "label": "繁体"}], "register": "中性", "sense_fingerprint": "名词；穿军装、保护国家的勇敢的士兵", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4da068f4-1758-479c-9a13-02dccfe2d5c0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90547, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "战士", "is_correct": true, "explanation": "正确。战士指保护国家、穿军装的军人。"}, {"text": "战时", "is_correct": false, "explanation": "shí（第二声）与 shì（第四声）声调不同，意思是战时，即战争时期。"}, {"text": "战史", "is_correct": false, "explanation": "shǐ（第三声）与 shì 声调不同，意思是战史，即战争的历史。"}, {"text": "展示", "is_correct": false, "explanation": "zhǎn（第三声）与 zhàn（第四声）只差声调，意思是展示，即摆出来给人看。"}], "explanations": {"战士": "正确。战士指保护国家、穿军装的军人。", "战时": "shí（第二声）与 shì（第四声）声调不同，意思是战时，即战争时期。", "战史": "shǐ（第三声）与 shì 声调不同，意思是战史，即战争的历史。", "展示": "zhǎn（第三声）与 zhàn（第四声）只差声调，意思是展示，即摆出来给人看。"}, "sentence_index": null, "correct_answer": "战士"}, "level_3": {"options": [{"text": "战士", "is_correct": true, "explanation": "正确。“这位”指一个穿着绿色军装的人，正是战士。"}, {"text": "空姐", "is_correct": false, "explanation": "搭配：空姐的制服不是军装，不说“穿着绿色的军装”。"}, {"text": "厨师", "is_correct": false, "explanation": "语义：厨师穿白色的厨师服，不会穿绿色的军装。"}, {"text": "园丁", "is_correct": false, "explanation": "语义：园丁不穿军装，“这位园丁穿着绿色的军装”说不通。"}], "explanations": {"战士": "正确。“这位”指一个穿着绿色军装的人，正是战士。", "空姐": "搭配：空姐的制服不是军装，不说“穿着绿色的军装”。", "厨师": "语义：厨师穿白色的厨师服，不会穿绿色的军装。", "园丁": "语义：园丁不穿军装，“这位园丁穿着绿色的军装”说不通。"}, "sentence_index": 0, "correct_answer": "战士"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他是班里的战士，遇到不公平的事就站出来说话。", "explanation": "这里的“战士”指为正义奋斗的人，是另一个义项，不指穿军装的军人。"}, {"text": "这只战士正在站岗。", "explanation": "量词错误。指人的“战士”不用“只”（只多用于动物），应说“这名战士”。"}, {"text": "这辆战士开得很快。", "explanation": "量词错误。指人的“战士”不用“辆”（辆用于车），应说“这名战士”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1bc53ff7-a51d-4d12-b1a0-8dd6064ac128') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90547, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "战士", "is_correct": true, "explanation": "正确。“保护国家的”修饰的正是战士，符合句意。"}, {"text": "园丁", "is_correct": false, "explanation": "语义：园丁与保护国家无关，句子说不通。"}, {"text": "会计", "is_correct": false, "explanation": "搭配：“保护国家的”不能修饰会计，这种说法不成立。"}, {"text": "歌手", "is_correct": false, "explanation": "语义：歌手不保护国家，与前面的“保护国家的”不相符。"}], "explanations": {"战士": "正确。“保护国家的”修饰的正是战士，符合句意。", "园丁": "语义：园丁与保护国家无关，句子说不通。", "会计": "搭配：“保护国家的”不能修饰会计，这种说法不成立。", "歌手": "语义：歌手不保护国家，与前面的“保护国家的”不相符。"}, "sentence_index": 6, "correct_answer": "战士"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我们班的小美是个战士，每次都替大家说话。", "explanation": "这里的“战士”指为某种事业奋斗的人，是另一个义项，不指军人。"}, {"text": "看到一条战士走过来，孩子们都笑了。", "explanation": "量词错误。指人的“战士”不用“条”（条多用于细长的东西），应说“一名战士”。"}, {"text": "她是这次活动的战士，负责组织大家。", "explanation": "这里的“战士”是比喻义，与军人的本义不符。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1bc53ff7-a51d-4d12-b1a0-8dd6064ac128') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90547, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "那只战士在门口站岗。", "corrected_sentence": "那名战士在门口站岗。", "error_description": "错误：指人的“战士”用量词“名”，不用“只”。正确：应说“那名战士”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1bc53ff7-a51d-4d12-b1a0-8dd6064ac128') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90547, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他长大后想当一只战士。", "corrected_sentence": "他长大后想当一名战士。", "error_description": "错误：指人的“战士”用量词“名”，不用“只”。正确：应说“一名战士”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1bc53ff7-a51d-4d12-b1a0-8dd6064ac128') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
