INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90551, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "属于一个大公司或一个人管着的。", "primary_collocate": null, "pronunciation": "qí xià", "ipa": "tɕʰi˧˥ ɕja˥˩", "syllable_count": 2, "sentences": [{"text": "这家公司旗下有三个品牌。", "target_word": "旗下", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她是这家娱乐公司旗下的歌手。", "target_word": "旗下", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个手机牌子是那家大公司旗下的。", "target_word": "旗下", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他旗下有两家饭店和一家酒店。", "target_word": "旗下", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这位老板旗下有五十多个员工。", "target_word": "旗下", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "那家汽车公司旗下有很多车型。", "target_word": "旗下", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我最喜欢这个集团旗下的牛奶。", "target_word": "旗下", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他刚从旗下的小公司调到总公司。", "target_word": "旗下", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这家食品公司旗下的工厂都很干净。", "target_word": "旗下", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "大学旗下的出版社出了一本新书。", "target_word": "旗下", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "中性", "sense_fingerprint": "归大公司或某个人管理的范围之内", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e6865c18-9c19-4131-8be9-c03230977fc2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90551, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "年龄", "is_correct": false, "explanation": "语义：“年龄”指人或动物的岁数，不能说公司有品牌。"}, {"text": "旗下", "is_correct": true, "explanation": "正确：“旗下”指归公司管辖的所属范围，与“有三个品牌”搭配。"}, {"text": "身材", "is_correct": false, "explanation": "体貌：“身材”指人的体形，不能用来指公司。"}, {"text": "性格", "is_correct": false, "explanation": "语义：“性格”只用于人的心理特点，与公司的品牌无关。"}], "explanations": {"年龄": "语义：“年龄”指人或动物的岁数，不能说公司有品牌。", "旗下": "正确：“旗下”指归公司管辖的所属范围，与“有三个品牌”搭配。", "身材": "体貌：“身材”指人的体形，不能用来指公司。", "性格": "语义：“性格”只用于人的心理特点，与公司的品牌无关。"}, "sentence_index": 0, "correct_answer": "旗下"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这家公司旗下的上午很忙。", "explanation": "这里把“旗下”当成了表示范围的〈之下〉。旗下只表示所属关系，上午是时间，不能作所属者。"}, {"text": "这条河旗下有很多鱼。", "explanation": "这里把“旗下”当成了表示处所的〈里〉。旗下只用于机构、品牌或人的所属关系，河不是所属的主体，应说“河里有很多鱼”。"}, {"text": "这首歌旗下有三段旋律。", "explanation": "这里应该用〈包含〉。旗下表示所属关系，歌曲不是所属的主体；歌的组成部分要用包含。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b9f84982-8648-42e8-bc52-311a344324e8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90551, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "脚步", "is_correct": false, "explanation": "语义：“脚步”指走路的动作，不能修饰牛奶。"}, {"text": "旗下", "is_correct": true, "explanation": "正确：“旗下”指集团管辖的所属范围，与“牛奶”的归属关系相合。"}, {"text": "心情", "is_correct": false, "explanation": "语义：“心情”指人的情绪，不能修饰牛奶。"}, {"text": "身高", "is_correct": false, "explanation": "体貌：“身高”指人的高矮，不能用于集团的牛奶。"}], "explanations": {"脚步": "语义：“脚步”指走路的动作，不能修饰牛奶。", "旗下": "正确：“旗下”指集团管辖的所属范围，与“牛奶”的归属关系相合。", "心情": "语义：“心情”指人的情绪，不能修饰牛奶。", "身高": "体貌：“身高”指人的高矮，不能用于集团的牛奶。"}, "sentence_index": 6, "correct_answer": "旗下"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我的钥匙在房间旗下。", "explanation": "这里把“旗下”当成了表示处所的〈底下〉。旗下只用于机构、品牌或人的所属关系，钥匙不属于某个所属对象，应说“钥匙在房间里”。"}, {"text": "这个节日旗下有很多活动。", "explanation": "这里把“旗下”当成了表示时间范围的〈期间〉。旗下只用于机构、品牌或人的所属关系，节日是时间，应说“节日期间有很多活动”。"}, {"text": "这张桌子旗下有三条腿。", "explanation": "这里把“旗下”用成了表示组成的意思。桌腿是桌子的部件，应说“这张桌子由三条腿组成”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b9f84982-8648-42e8-bc52-311a344324e8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90551, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他是这家唱片公司旗下的的作曲人。", "corrected_sentence": "他是这家唱片公司旗下的作曲人。", "error_description": "“的”重复：“旗下的”后只用一个“的”，“旗下的的作曲人”应去掉一个“的”，应为“这家唱片公司旗下的作曲人”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b9f84982-8648-42e8-bc52-311a344324e8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90551, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这家报社旗下被有几家网站。", "corrected_sentence": "这家报社旗下有几家网站。", "error_description": "“有”表示存在，不能用“被”引出，应去掉“被”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b9f84982-8648-42e8-bc52-311a344324e8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
