INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90552, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "某机构、品牌或某人的名下；所属。", "primary_collocate": null, "pronunciation": "qí xià", "ipa": "tɕʰi˧˥ ɕja˥˩", "syllable_count": 2, "sentences": [{"text": "这个咖啡品牌在那家公司旗下。", "target_word": "旗下", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他的名字在这家公司旗下的艺人名单里。", "target_word": "旗下", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这家银行旗下有一个很大的基金。", "target_word": "旗下", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我常去他旗下的那家面包店。", "target_word": "旗下", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这家网站旗下还有一个新闻软件。", "target_word": "旗下", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这位导演旗下的公司拍了很多电影。", "target_word": "旗下", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "那家酒店也在这个集团旗下。", "target_word": "旗下", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这家出版社旗下有二十多本杂志。", "target_word": "旗下", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他把几家小店都放到了自己旗下。", "target_word": "旗下", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个电视台旗下的节目很受欢迎。", "target_word": "旗下", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "中性", "sense_fingerprint": "某机构、品牌或某人名下所属的部分", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e6865c18-9c19-4131-8be9-c03230977fc2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90552, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "身上", "is_correct": false, "explanation": "语义：“身上”指人或动物的身体表面，咖啡品牌不在公司身上。"}, {"text": "旗下", "is_correct": true, "explanation": "正确：“旗下”指归某公司所属的范围，与咖啡品牌的归属关系相合。"}, {"text": "脚下", "is_correct": false, "explanation": "语义：“脚下”指脚所踩的地方，与品牌的归属关系不合。"}, {"text": "体内", "is_correct": false, "explanation": "体貌：“体内”指人或动物身体的内部，不能说品牌在公司体内。"}], "explanations": {"身上": "语义：“身上”指人或动物的身体表面，咖啡品牌不在公司身上。", "旗下": "正确：“旗下”指归某公司所属的范围，与咖啡品牌的归属关系相合。", "脚下": "语义：“脚下”指脚所踩的地方，与品牌的归属关系不合。", "体内": "体貌：“体内”指人或动物身体的内部，不能说品牌在公司体内。"}, "sentence_index": 0, "correct_answer": "旗下"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这本书旗下有三十页。", "explanation": "这里把“旗下”当成了表示组成的意思，应该用〈共有〉。书页是书的部件，旗下只表示所属，应说“这本书共有三十页”。"}, {"text": "这把椅子旗下有一条腿。", "explanation": "这里把“旗下”当成了表示组成的意思，应该用〈组成〉。椅子腿是椅子的部件，应说“这把椅子由一条腿组成”。"}, {"text": "这棵树旗下有很多叶子。", "explanation": "这里应该用〈长着〉。旗下只表示所属，叶子是树的组成部分，应说“这棵树上长着很多叶子”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b9f84982-8648-42e8-bc52-311a344324e8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90552, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "海上", "is_correct": false, "explanation": "语义：“海上”指海面，酒店不能在海上属于这个集团。"}, {"text": "旗下", "is_correct": true, "explanation": "正确：“旗下”指集团管辖的所属范围，与“那家酒店也在这个集团”相合。"}, {"text": "心中", "is_correct": false, "explanation": "语域：“心中”偏书面，此处语境不合，且集团不能在心中。"}, {"text": "课堂", "is_correct": false, "explanation": "语义：“课堂”指上课的地方，与集团的归属关系不合。"}], "explanations": {"海上": "语义：“海上”指海面，酒店不能在海上属于这个集团。", "旗下": "正确：“旗下”指集团管辖的所属范围，与“那家酒店也在这个集团”相合。", "心中": "语域：“心中”偏书面，此处语境不合，且集团不能在心中。", "课堂": "语义：“课堂”指上课的地方，与集团的归属关系不合。"}, "sentence_index": 6, "correct_answer": "旗下"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这个电视台旗下的晚上很热闹。", "explanation": "这里把“旗下”当成了表示时间范围的〈期间〉。旗下只表示所属，晚上是时间，不能作所属者。"}, {"text": "这个电视台旗下的春天很美。", "explanation": "这里把“旗下”当成了表示时期的〈时期〉。旗下只表示所属，春天是时间，不能作所属者。"}, {"text": "这个电视台旗下的星期天很忙。", "explanation": "这里把“旗下”当成了表示日子的〈当天〉。旗下只表示所属，星期天是时间，不能作所属者。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b9f84982-8648-42e8-bc52-311a344324e8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90552, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我常去他旗下的的那家超市。", "corrected_sentence": "我常去他旗下的那家超市。", "error_description": "“的”重复：“旗下的”后只用一个“的”，“他旗下的的那家超市”应去掉一个“的”，应为“他旗下的那家超市”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b9f84982-8648-42e8-bc52-311a344324e8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90552, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这家网站把旗下有三个论坛。", "corrected_sentence": "这家网站旗下有三个论坛。", "error_description": "“把”字句中“有”不能作谓语，应去掉“把”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b9f84982-8648-42e8-bc52-311a344324e8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
