INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90557, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "和重要的客人见面谈话。", "primary_collocate": null, "pronunciation": "huì jiàn", "ipa": "xwei˥˩ tɕjɛn˥˩", "syllable_count": 2, "sentences": [{"text": "总统明天会见来访的外国客人。", "target_word": "会见", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "经理在办公室会见了一位重要客人。", "target_word": "会见", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "王校长正在会见来学校参观的老师。", "target_word": "会见", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "市长今天下午要会见外国商人。", "target_word": "会见", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们会见过几位有名的科学家。", "target_word": "会见", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老板会见客人时，不喜欢别人打扰。", "target_word": "会见", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "外交部长会见了两国的代表。", "target_word": "会见", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "昨天上午，校长会见了来访的家长。", "target_word": "会见", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "公司经理想会见那位重要的客户。", "target_word": "会见", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "主席把会见客人的时间改到了明天。", "target_word": "会见", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "会见了", "label": "体标"}, {"form": "会见过", "label": "体标"}], "register": "正式", "sense_fingerprint": "接待重要客人并与其见面谈话", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '91fb0def-17e1-49a7-8369-e06c80e75a82') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90557, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "会见", "is_correct": true, "explanation": "会见是正确答案，指接待重要客人并与其见面谈话。"}, {"text": "回见", "is_correct": false, "explanation": "huí（第二声）与 huì（第四声）声调不同，意思是再见、回头见。"}, {"text": "汇进", "is_correct": false, "explanation": "jìn 与 jiàn 韵母不同（-in 与 -ian），意思是把款项汇入。"}, {"text": "会间", "is_correct": false, "explanation": "jiān（第一声）与 jiàn（第四声）声调不同，意思是会议期间。"}], "explanations": {"会见": "会见是正确答案，指接待重要客人并与其见面谈话。", "回见": "huí（第二声）与 huì（第四声）声调不同，意思是再见、回头见。", "汇进": "jìn 与 jiàn 韵母不同（-in 与 -ian），意思是把款项汇入。", "会间": "jiān（第一声）与 jiàn（第四声）声调不同，意思是会议期间。"}, "sentence_index": null, "correct_answer": "会见"}, "level_3": {"options": [{"text": "会见", "is_correct": true, "explanation": "正确：会见指正式地与客人见面谈话，与“总统”“来访的外国客人”相合。"}, {"text": "修", "is_correct": false, "explanation": "搭配：“修”用于修理物品，不能接人作宾语。"}, {"text": "煮", "is_correct": false, "explanation": "语义：“煮”指用水加热做食物，与“外国客人”不合。"}, {"text": "赶", "is_correct": false, "explanation": "语义：“赶”指驱逐，与“来访”的礼貌语境相反。"}], "explanations": {"会见": "正确：会见指正式地与客人见面谈话，与“总统”“来访的外国客人”相合。", "修": "搭配：“修”用于修理物品，不能接人作宾语。", "煮": "语义：“煮”指用水加热做食物，与“外国客人”不合。", "赶": "语义：“赶”指驱逐，与“来访”的礼貌语境相反。"}, "sentence_index": 0, "correct_answer": "会见"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "周末我去医院会见生病的奶奶。", "explanation": "这里应该用〈看望〉。会见是正式的见面谈话，探望病人要说看望。"}, {"text": "他去美国会见了一个月。", "explanation": "这里应该用〈访问〉。会见是与人会面，不能用来表示一段时间。"}, {"text": "路上我会见了老同学。", "explanation": "这里应该用〈遇见〉。会见是事先约定的正式会面，偶然碰到老同学要说遇见。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5e9b95af-f526-4674-ab65-567f5b1a2aea') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90557, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "会见", "is_correct": true, "explanation": "正确：会见指接待客人并与其会面，与“外交部长”“两国的代表”相合。"}, {"text": "洗", "is_correct": false, "explanation": "搭配：“洗”不能以人作宾语，不能说洗代表。"}, {"text": "踢", "is_correct": false, "explanation": "语义：“踢”指用脚击打，与外交场合不合。"}, {"text": "拆", "is_correct": false, "explanation": "语义：“拆”指拆开、拆除，不能用于人。"}], "explanations": {"会见": "正确：会见指接待客人并与其会面，与“外交部长”“两国的代表”相合。", "洗": "搭配：“洗”不能以人作宾语，不能说洗代表。", "踢": "语义：“踢”指用脚击打，与外交场合不合。", "拆": "语义：“拆”指拆开、拆除，不能用于人。"}, "sentence_index": 6, "correct_answer": "会见"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我昨晚会见了一场电影。", "explanation": "这里应该用〈看〉。会见的对象必须是人，看的是电影，不能换成会见。"}, {"text": "我昨天会见了一个电话。", "explanation": "这里应该用〈打〉。会见只能以人为对象，打出去的电话不能作会见的宾语。"}, {"text": "我们会见了博物馆。", "explanation": "这里应该用〈参观〉。会见的对象是人，参观的对象可以是地点。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5e9b95af-f526-4674-ab65-567f5b1a2aea') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90557, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "市长昨天会见着外国记者。", "corrected_sentence": "市长昨天会见了外国记者。", "error_description": "错误在“会见”后的“着”。“着”表示状态持续，而这里说的是昨天已经发生的会面，应该用“了”，说“会见了”，不能说“会见着”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5e9b95af-f526-4674-ab65-567f5b1a2aea') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90557, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "总理前天在人民大会堂会见着代表团。", "corrected_sentence": "总理前天在人民大会堂会见了代表团。", "error_description": "体标错误：“着”表示状态持续，而前天已经完成的会见应用“了”，应说“会见了代表团”，不说“会见着代表团”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5e9b95af-f526-4674-ab65-567f5b1a2aea') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
