INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90567, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "自己住的这个国家。", "primary_collocate": null, "pronunciation": "běn guó", "ipa": "pən˨˩ kwo˧˥", "syllable_count": 2, "sentences": [{"text": "他爱本国，也尊重别的国家。", "target_word": "本国", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "本国货比进口货便宜很多。", "target_word": "本国", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "在本国，十八岁就可以开车。", "target_word": "本国", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "留学三年后，她回到了本国。", "target_word": "本国", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这位老师常给学生讲本国的历史。", "target_word": "本国", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "本国的天气比外国热得多。", "target_word": "本国", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他在本国读完大学，再去外国工作。", "target_word": "本国", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "本国的学生也可以申请这个奖学金。", "target_word": "本国", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这些药只能在本国买到，国外没有。", "target_word": "本国", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "外国朋友问我本国有哪些节日。", "target_word": "本国", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "本國", "label": "繁体"}], "register": "中性", "sense_fingerprint": "自己居住的这个国家，与别的国家相对", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '91fb0def-17e1-49a7-8369-e06c80e75a82') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90567, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "公司", "is_correct": false, "explanation": "语义：“他爱公司，也尊重别的国家”说不通，句中是在说对国家的感情。"}, {"text": "本国", "is_correct": true, "explanation": "“本国”指自己居住的国家，与“别的国家”形成对比，语境相合。"}, {"text": "学校", "is_correct": false, "explanation": "语义：学校不能与“别的国家”构成对比，句意不通。"}, {"text": "公园", "is_correct": false, "explanation": "语义：“爱”后可接“公园”，但后半句“也尊重别的国家”要求与“本国”构成对比，“公园”无法与“别的国家”对照，句意不合。"}], "explanations": {"公司": "语义：“他爱公司，也尊重别的国家”说不通，句中是在说对国家的感情。", "本国": "“本国”指自己居住的国家，与“别的国家”形成对比，语境相合。", "学校": "语义：学校不能与“别的国家”构成对比，句意不通。", "公园": "语义：“爱”后可接“公园”，但后半句“也尊重别的国家”要求与“本国”构成对比，“公园”无法与“别的国家”对照，句意不合。"}, "sentence_index": 0, "correct_answer": "本国"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "她刚到英国，很快就适应了本国的生活。", "explanation": "这里应该用〈当地〉。本国指自己居住的国家，身在英国时要说“当地的生活”。"}, {"text": "我是中国人，在日本工作，每天都坐本国的地铁上班。", "explanation": "这里应该用〈当地〉。本国指自己的国家，日本的地铁属于当地，不能说成本国的地铁。"}, {"text": "我是中国人，在德国读书，每天都去本国的超市买菜。", "explanation": "这里不能用“本国”。超市在德国，属于当地，与本国无关，这里的用法与所在地矛盾。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5e9b95af-f526-4674-ab65-567f5b1a2aea') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90567, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "图书馆", "is_correct": false, "explanation": "搭配：“读完大学”一般在学校进行，不说在图书馆读完大学。"}, {"text": "本国", "is_correct": true, "explanation": "“本国”指自己居住的国家，与后句“去外国工作”形成对比，语境相合。"}, {"text": "医院", "is_correct": false, "explanation": "语义：在医院读完大学不合常理，与“读大学”的情境不符。"}, {"text": "厨房", "is_correct": false, "explanation": "语义：厨房不是读大学的地方，句意不通。"}], "explanations": {"图书馆": "搭配：“读完大学”一般在学校进行，不说在图书馆读完大学。", "本国": "“本国”指自己居住的国家，与后句“去外国工作”形成对比，语境相合。", "医院": "语义：在医院读完大学不合常理，与“读大学”的情境不符。", "厨房": "语义：厨房不是读大学的地方，句意不通。"}, "sentence_index": 6, "correct_answer": "本国"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我在加拿大生活，周末常去本国的公园散步。", "explanation": "这里应该用〈当地〉。身在加拿大，公园属于当地，不能说成说话人本国的公园，应说“当地的公园”。"}, {"text": "他去泰国出差，每天都去本国的酒店住宿。", "explanation": "这里应该用〈当地〉。身在泰国，酒店属于当地，不能说成说话人本国的酒店，应说“当地的酒店”。"}, {"text": "这座城市的本国历史很悠久。", "explanation": "这里应该用〈本地〉。本国指整个国家，描述一座城市的历史应说“本地的历史”，不能用本国。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5e9b95af-f526-4674-ab65-567f5b1a2aea') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90567, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他一直本国工作，从没出过国。", "corrected_sentence": "他一直在本国工作，从没出过国。", "error_description": "错误：表示处所的“本国”前漏掉了“在”。应说“在本国工作”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5e9b95af-f526-4674-ab65-567f5b1a2aea') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90567, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他带回了本国们的特产。", "corrected_sentence": "他带回了本国的特产。", "error_description": "错误：“们”是指人的复数后缀，不能加在“本国”后面。应说“本国的特产”，去掉“们”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5e9b95af-f526-4674-ab65-567f5b1a2aea') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
