INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90570, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "军队驻扎的地方。", "primary_collocate": null, "pronunciation": "yíng", "ipa": "iŋ˧˥", "syllable_count": 1, "sentences": [{"text": "士兵们每天早上在营里训练。", "target_word": "营", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "士兵们列队走出了营。", "target_word": "营", "complexity_tier": "T3", "furigana": "shì bīng men liè duì zǒu chū le yíng", "sentence_source": "generated"}, {"text": "战士们昨天晚上回到了营里。", "target_word": "营", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "敌人离我们的营只有五里路。", "target_word": "营", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "将军走进营，看了看士兵们。", "target_word": "营", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这个营里住着五百名战士。", "target_word": "营", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "夜里，营外很黑，营里却亮着灯。", "target_word": "营", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他在营里当了三年兵。", "target_word": "营", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "天亮以前，部队已经离开了营。", "target_word": "营", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "哨兵守在营外，不让陌生人进去。", "target_word": "营", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "军营", "label": "复合"}, {"form": "兵营", "label": "复合"}, {"form": "个", "label": "量词"}, {"form": "營", "label": "繁体"}], "register": "中性", "sense_fingerprint": "营：军队驻扎的营地", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '53f807e0-8acf-42ca-93b2-48cbb7eb4cad') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90570, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "营", "is_correct": true, "explanation": "营（yíng，第二声）：军队驻扎的地方。"}, {"text": "影", "is_correct": false, "explanation": "影（yǐng，第三声）与营（yíng，第二声）声调不同，意思是影子。"}, {"text": "硬", "is_correct": false, "explanation": "硬（yìng，第四声）与营声调不同，意思是坚硬。"}, {"text": "应", "is_correct": false, "explanation": "应（yīng，第一声）与营声调不同，意思是应该或应答。"}, {"text": "银", "is_correct": false, "explanation": "银（yín）与营声调相同，韵尾不同（n 与 ng），意思是银子。"}, {"text": "英", "is_correct": false, "explanation": "英（yīng，第一声）与营声调不同，意思是英勇。"}], "explanations": {"营": "营（yíng，第二声）：军队驻扎的地方。", "影": "影（yǐng，第三声）与营（yíng，第二声）声调不同，意思是影子。", "硬": "硬（yìng，第四声）与营声调不同，意思是坚硬。", "应": "应（yīng，第一声）与营声调不同，意思是应该或应答。", "银": "银（yín）与营声调相同，韵尾不同（n 与 ng），意思是银子。", "英": "英（yīng，第一声）与营声调不同，意思是英勇。"}, "sentence_index": null, "correct_answer": "营"}, "level_3": {"options": [{"text": "营", "is_correct": true, "explanation": "正确：营是军队驻扎的地方，“在营里训练”与句意相符。"}, {"text": "书", "is_correct": false, "explanation": "语义：书里不能进行部队训练，与“训练”冲突。"}, {"text": "店", "is_correct": false, "explanation": "语义：店铺不是士兵每天训练的地方，与“训练”冲突。"}, {"text": "饭", "is_correct": false, "explanation": "搭配：“在……里训练”要求场所词，“饭”不能作训练的场所。"}], "explanations": {"营": "正确：营是军队驻扎的地方，“在营里训练”与句意相符。", "书": "语义：书里不能进行部队训练，与“训练”冲突。", "店": "语义：店铺不是士兵每天训练的地方，与“训练”冲突。", "饭": "搭配：“在……里训练”要求场所词，“饭”不能作训练的场所。"}, "sentence_index": 0, "correct_answer": "营"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "营下班了，医生们回家了。", "explanation": "这里应该用〈医院〉。下班是医院等单位的说法，军营不会下班。"}, {"text": "我每周去营借书。", "explanation": "这里应该用〈图书馆〉。借书要去图书馆，军营不办借书。"}, {"text": "我们学校的营有五十个学生。", "explanation": "这里应该用〈班〉。营是军队的编制单位，不用来指学生班级。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '718050bc-321d-406a-9188-a4a097c777a8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90570, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "营", "is_correct": true, "explanation": "营（yíng，第二声）：军队驻扎的地方。"}, {"text": "灵", "is_correct": false, "explanation": "灵（líng）与营声母不同（l 与 y），声调相同，意思是灵活。"}, {"text": "映", "is_correct": false, "explanation": "映（yìng，第四声）与营声调不同，意思是照射。"}, {"text": "印", "is_correct": false, "explanation": "印（yìn）与营韵尾不同（n 与 ng），声调也不同，意思是印章。"}, {"text": "因", "is_correct": false, "explanation": "因（yīn）与营韵尾不同，声调也不同，意思是因为。"}], "explanations": {"营": "营（yíng，第二声）：军队驻扎的地方。", "灵": "灵（líng）与营声母不同（l 与 y），声调相同，意思是灵活。", "映": "映（yìng，第四声）与营声调不同，意思是照射。", "印": "印（yìn）与营韵尾不同（n 与 ng），声调也不同，意思是印章。", "因": "因（yīn）与营韵尾不同，声调也不同，意思是因为。"}, "sentence_index": null, "correct_answer": "营"}, "level_3": {"options": [{"text": "营", "is_correct": true, "explanation": "正确：营是驻扎部队的地方，“营外很黑，营里却亮着灯”前后呼应。"}, {"text": "灯", "is_correct": false, "explanation": "语义：灯是光源，“灯外很黑”与后面的“亮着灯”矛盾。"}, {"text": "桌", "is_correct": false, "explanation": "语义：桌子不是能形成夜里“外面”和“里面”的地方，句子不通。"}, {"text": "饭", "is_correct": false, "explanation": "语义：饭不是可以“在外”“在里”的空间，“饭里却亮着灯”说不通。"}], "explanations": {"营": "正确：营是驻扎部队的地方，“营外很黑，营里却亮着灯”前后呼应。", "灯": "语义：灯是光源，“灯外很黑”与后面的“亮着灯”矛盾。", "桌": "语义：桌子不是能形成夜里“外面”和“里面”的地方，句子不通。", "饭": "语义：饭不是可以“在外”“在里”的空间，“饭里却亮着灯”说不通。"}, "sentence_index": 6, "correct_answer": "营"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我去营取钱。", "explanation": "这里应该用〈银行〉。取钱要去银行，军营不办存取款。"}, {"text": "我把营放在桌子上。", "explanation": "这里应该用〈书〉。营是地方，不能放在桌上，要说“书”这类物品。"}, {"text": "营里结满了苹果。", "explanation": "这里应该用〈果园〉。结满果实是果园或树木的事，营不会结苹果。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '718050bc-321d-406a-9188-a4a097c777a8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90570, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这只营驻扎在山脚下。", "corrected_sentence": "这个营驻扎在山脚下。", "error_description": "错误形式是“这只营”，正确形式是“这个营”。“营”是驻扎的地方，量词应用“个”，不用“只”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '718050bc-321d-406a-9188-a4a097c777a8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90570, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "士兵们营里休息。", "corrected_sentence": "士兵们在营里休息。", "error_description": "错误在于漏掉了“在”。表示地点时应说“在营里休息”，不能说“营里休息”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '718050bc-321d-406a-9188-a4a097c777a8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90575, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "弯", "is_correct": true, "explanation": "正确：“弯”与“直”在“不弯曲”义上互为反义。"}, {"text": "慢", "is_correct": false, "explanation": "与“直”无反义关系，“慢”说速度快慢。"}, {"text": "宽", "is_correct": false, "explanation": "与“直”无反义关系，“宽”说宽度。"}, {"text": "白", "is_correct": false, "explanation": "与“直”无反义关系，“白”说颜色。"}], "correct_answer": "弯", "explanations": {"弯": "正确：“弯”与“直”在“不弯曲”义上互为反义。", "慢": "与“直”无反义关系，“慢”说速度快慢。", "宽": "与“直”无反义关系，“宽”说宽度。", "白": "与“直”无反义关系，“白”说颜色。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f710dbc2-d2ea-4067-9e4f-b056b043fa1c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90575, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "弯", "is_correct": true, "explanation": "正确：“弯”与“直”在“不弯曲”义上互为反义。"}, {"text": "深", "is_correct": false, "explanation": "与“直”无反义关系，“深”说深浅。"}, {"text": "粗", "is_correct": false, "explanation": "与“直”无反义关系，“粗”说粗细。"}, {"text": "短", "is_correct": false, "explanation": "与“直”无反义关系，“短”说长度，与“长”相对。"}], "correct_answer": "弯", "explanations": {"弯": "正确：“弯”与“直”在“不弯曲”义上互为反义。", "深": "与“直”无反义关系，“深”说深浅。", "粗": "与“直”无反义关系，“粗”说粗细。", "短": "与“直”无反义关系，“短”说长度，与“长”相对。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f710dbc2-d2ea-4067-9e4f-b056b043fa1c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90575, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "直是不弯，一条线从头到尾都是平平的。", "primary_collocate": null, "pronunciation": "zhí", "ipa": "ʈʂʅ˧˥", "syllable_count": 1, "sentences": [{"text": "这条路又长又直。", "target_word": "直", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "他站得很直，像一棵小树。", "target_word": "直", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "这棵树长得很直，可以做房子的柱子。", "target_word": "直", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "请你坐直，不要靠在桌子上。", "target_word": "直", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他的头发很直，不用烫就很好看。", "target_word": "直", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "这条河不直，弯来弯去，很长。", "target_word": "直", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "马路修得很直，开车一点也不累。", "target_word": "直", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "弟弟用尺子画了一条直的线。", "target_word": "直", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "你看，这些树长得真直啊。", "target_word": "直", "complexity_tier": "T3", "furigana": "nǐ kàn, zhèxiē shù zhǎng de zhēn zhí a.", "sentence_source": "generated"}, {"text": "这根铁管不直，要把它弄直才能用。", "target_word": "直", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "直直的", "label": "重叠"}, {"form": "笔直", "label": "复合"}], "register": "中性", "sense_fingerprint": "道路、树木、身体等从头到尾不弯", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cc24a53f-6254-4aa5-8e47-0703e4066dea') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90575, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "直", "is_correct": true, "explanation": "正确：直（zhí）指线条或物体不弯曲，成直线。"}, {"text": "只", "is_correct": false, "explanation": "zhǐ（第三声）与 zhí（第二声）声调不同，意思是仅、只。"}, {"text": "十", "is_correct": false, "explanation": "shí 与 zhí 声母不同（sh 与 zh），意思是数字十。"}, {"text": "迟", "is_correct": false, "explanation": "chí 与 zhí 声母不同（ch 与 zh），意思是慢、晚。"}, {"text": "质", "is_correct": false, "explanation": "zhì（第四声）与 zhí（第二声）声调不同，意思是性质、品质。"}], "explanations": {"直": "正确：直（zhí）指线条或物体不弯曲，成直线。", "只": "zhǐ（第三声）与 zhí（第二声）声调不同，意思是仅、只。", "十": "shí 与 zhí 声母不同（sh 与 zh），意思是数字十。", "迟": "chí 与 zhí 声母不同（ch 与 zh），意思是慢、晚。", "质": "zhì（第四声）与 zhí（第二声）声调不同，意思是性质、品质。"}, "sentence_index": null, "correct_answer": "直"}, "level_3": {"options": [{"text": "直", "is_correct": true, "explanation": "正确：“又长又直”说路线平直，符合“直”的不弯曲义。"}, {"text": "高", "is_correct": false, "explanation": "搭配：“高”说上下的高度，不用来说路线的平直。"}, {"text": "粗", "is_correct": false, "explanation": "搭配：“粗”说物体的粗细，不用来形容路。"}, {"text": "亮", "is_correct": false, "explanation": "语义：“亮”说光线明暗，与路线是否笔直无关。"}], "explanations": {"直": "正确：“又长又直”说路线平直，符合“直”的不弯曲义。", "高": "搭配：“高”说上下的高度，不用来说路线的平直。", "粗": "搭配：“粗”说物体的粗细，不用来形容路。", "亮": "语义：“亮”说光线明暗，与路线是否笔直无关。"}, "sentence_index": 0, "correct_answer": "直"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他听到这个消息后，心情很直，一句话也没说。", "explanation": "这里应该用〈平静〉。“直”说线条或物体不弯，形容心情安定要用“平静”。"}, {"text": "这块地很直，很适合种菜。", "explanation": "这里应该用〈平〉。直说线条或物体不弯，平说表面没有起伏，形容地面要用“平”。"}, {"text": "这块饼干很直，咬起来很脆。", "explanation": "这里应该用〈方〉。饼干的形状说“方”，“直”只说线条或物体不弯，不能用来形容饼干。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f710dbc2-d2ea-4067-9e4f-b056b043fa1c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90575, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "直", "is_correct": true, "explanation": "正确：直（zhí）指线条或物体不弯曲，成直线。"}, {"text": "纸", "is_correct": false, "explanation": "zhǐ（第三声）与 zhí（第二声）声调不同，意思是纸张。"}, {"text": "知", "is_correct": false, "explanation": "zhī（第一声）与 zhí（第二声）声调不同，意思是知道。"}, {"text": "池", "is_correct": false, "explanation": "chí 与 zhí 声母不同（ch 与 zh），意思是水池。"}, {"text": "治", "is_correct": false, "explanation": "zhì（第四声）与 zhí（第二声）声调不同，意思是治理、医治。"}], "explanations": {"直": "正确：直（zhí）指线条或物体不弯曲，成直线。", "纸": "zhǐ（第三声）与 zhí（第二声）声调不同，意思是纸张。", "知": "zhī（第一声）与 zhí（第二声）声调不同，意思是知道。", "池": "chí 与 zhí 声母不同（ch 与 zh），意思是水池。", "治": "zhì（第四声）与 zhí（第二声）声调不同，意思是治理、医治。"}, "sentence_index": null, "correct_answer": "直"}, "level_3": {"options": [{"text": "直", "is_correct": true, "explanation": "正确：“马路修得很直”说路面笔直，开车才不累。"}, {"text": "矮", "is_correct": false, "explanation": "搭配：“矮”说高低，不用来描述修路的结果。"}, {"text": "深", "is_correct": false, "explanation": "搭配：“深”说深浅，马路不能修得深。"}, {"text": "重", "is_correct": false, "explanation": "语义：“重”说分量，与路的形状无关，也与“开车不累”矛盾。"}], "explanations": {"直": "正确：“马路修得很直”说路面笔直，开车才不累。", "矮": "搭配：“矮”说高低，不用来描述修路的结果。", "深": "搭配：“深”说深浅，马路不能修得深。", "重": "语义：“重”说分量，与路的形状无关，也与“开车不累”矛盾。"}, "sentence_index": 6, "correct_answer": "直"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这个箱子很直，装得很满。", "explanation": "这里应该用〈方〉。箱子的形状说“方”，“直”只说线条或物体不弯，不能形容箱子。"}, {"text": "这块肉很直，切起来很方便。", "explanation": "这里应该用〈厚〉。肉的厚薄要用“厚”，“直”只说线条或物体不弯，不能用来形容肉。"}, {"text": "这条河的波浪很直，很好看。", "explanation": "这里应该用〈起伏〉。波浪是起伏的，“直”只说线条不弯，形容波浪要说“起伏”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f710dbc2-d2ea-4067-9e4f-b056b043fa1c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90575, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他写字时坐很直，腰也不弯。", "corrected_sentence": "他写字时坐得很直，腰也不弯。", "error_description": "错误：“坐很直”；正确：“坐得很直”。动词后面接形容词作补语时要用“得”，漏掉“得”是常见错误。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f710dbc2-d2ea-4067-9e4f-b056b043fa1c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90575, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这条路修得直很，走起来很方便。", "corrected_sentence": "这条路修得很直，走起来很方便。", "error_description": "错误：“直很”语序颠倒；正确：“很直”。“很”修饰形容词，要放在形容词前面，不能放在后面。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f710dbc2-d2ea-4067-9e4f-b056b043fa1c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90576, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "弯", "is_correct": true, "explanation": "正确：“弯”与“直”在“不弯曲”义上互为反义。"}, {"text": "低", "is_correct": false, "explanation": "与“直”无反义关系，“低”与“高”相对，不是“直”的反义。"}, {"text": "圆", "is_correct": false, "explanation": "与“直”无反义关系，“圆”说形状，不是“直”的对立面。"}, {"text": "宽", "is_correct": false, "explanation": "与“直”无反义关系，“宽”说宽度。"}], "correct_answer": "弯", "explanations": {"弯": "正确：“弯”与“直”在“不弯曲”义上互为反义。", "低": "与“直”无反义关系，“低”与“高”相对，不是“直”的反义。", "圆": "与“直”无反义关系，“圆”说形状，不是“直”的对立面。", "宽": "与“直”无反义关系，“宽”说宽度。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f710dbc2-d2ea-4067-9e4f-b056b043fa1c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90576, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "弯", "is_correct": true, "explanation": "正确：“弯”与“直”在“不弯曲”义上互为反义。"}, {"text": "慢", "is_correct": false, "explanation": "与“直”无反义关系，“慢”说速度。"}, {"text": "粗", "is_correct": false, "explanation": "与“直”无反义关系，“粗”说粗细。"}, {"text": "深", "is_correct": false, "explanation": "与“直”无反义关系，“深”说深浅。"}], "correct_answer": "弯", "explanations": {"弯": "正确：“弯”与“直”在“不弯曲”义上互为反义。", "慢": "与“直”无反义关系，“慢”说速度。", "粗": "与“直”无反义关系，“粗”说粗细。", "深": "与“直”无反义关系，“深”说深浅。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f710dbc2-d2ea-4067-9e4f-b056b043fa1c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90576, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "不弯曲；成直线的。", "primary_collocate": null, "pronunciation": "zhí", "ipa": "ʈʂʅ˧˥", "syllable_count": 1, "sentences": [{"text": "这条路很直，走十分钟就到学校了。", "target_word": "直", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "请把背挺得直一点。", "target_word": "直", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他的腿又长又直，很适合跳舞。", "target_word": "直", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "旗杆立在操场中间，又高又直。", "target_word": "直", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "画这条线的时候，手要稳，线才会直。", "target_word": "直", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这条小河一点也不直，转了好几个弯。", "target_word": "直", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "把这根弯铁丝拉直，再放进盒子里。", "target_word": "直", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这段铁路很直，火车可以开得很快。", "target_word": "直", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他走路时背很直，一看就是军人。", "target_word": "直", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这把尺子的边很直，可以用来画线。", "target_word": "直", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "直直的", "label": "重叠"}, {"form": "笔直", "label": "复合"}], "register": "中性", "sense_fingerprint": "物体或线条不弯曲，呈直线", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cc24a53f-6254-4aa5-8e47-0703e4066dea') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90576, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "直", "is_correct": true, "explanation": "正确：直（zhí）指不弯曲，成直线。"}, {"text": "指", "is_correct": false, "explanation": "zhǐ（第三声）与 zhí（第二声）声调不同，意思是手指。"}, {"text": "石", "is_correct": false, "explanation": "shí 与 zhí 声母不同（sh 与 zh），意思是石头。"}, {"text": "持", "is_correct": false, "explanation": "chí 与 zhí 声母不同（ch 与 zh），意思是坚持、保持。"}, {"text": "志", "is_correct": false, "explanation": "zhì（第四声）与 zhí（第二声）声调不同，意思是志向。"}], "explanations": {"直": "正确：直（zhí）指不弯曲，成直线。", "指": "zhǐ（第三声）与 zhí（第二声）声调不同，意思是手指。", "石": "shí 与 zhí 声母不同（sh 与 zh），意思是石头。", "持": "chí 与 zhí 声母不同（ch 与 zh），意思是坚持、保持。", "志": "zhì（第四声）与 zhí（第二声）声调不同，意思是志向。"}, "sentence_index": null, "correct_answer": "直"}, "level_3": {"options": [{"text": "直", "is_correct": true, "explanation": "正确：“这条路很直”说路线平直，与“走十分钟就到学校”相符。"}, {"text": "粗", "is_correct": false, "explanation": "搭配：“粗”说粗细，不用来形容路的走法。"}, {"text": "甜", "is_correct": false, "explanation": "语义：“甜”说味道，与路的长短和平直无关。"}, {"text": "矮", "is_correct": false, "explanation": "搭配：“矮”说高低，不用来说路线本身。"}], "explanations": {"直": "正确：“这条路很直”说路线平直，与“走十分钟就到学校”相符。", "粗": "搭配：“粗”说粗细，不用来形容路的走法。", "甜": "语义：“甜”说味道，与路的长短和平直无关。", "矮": "搭配：“矮”说高低，不用来说路线本身。"}, "sentence_index": 0, "correct_answer": "直"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这片操场很直，适合跑步。", "explanation": "这里应该用〈平〉。直说线条不弯，平说表面没有起伏，形容操场要用“平”。"}, {"text": "这个西瓜很直，又大又甜。", "explanation": "这里应该用〈圆〉。西瓜是圆的，“直”只说线条或物体不弯，不能用来形容西瓜。"}, {"text": "这个池塘很直，很漂亮。", "explanation": "这里应该用〈平静〉。池塘的水面说“平静”，“直”只说线条或物体不弯，不能形容池塘。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f710dbc2-d2ea-4067-9e4f-b056b043fa1c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90576, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "直", "is_correct": true, "explanation": "正确：直（zhí）指不弯曲，成直线。"}, {"text": "止", "is_correct": false, "explanation": "zhǐ（第三声）与 zhí（第二声）声调不同，意思是停止。"}, {"text": "时", "is_correct": false, "explanation": "shí 与 zhí 声母不同（sh 与 zh），意思是时间。"}, {"text": "池", "is_correct": false, "explanation": "chí 与 zhí 声母不同（ch 与 zh），意思是水池。"}, {"text": "至", "is_correct": false, "explanation": "zhì（第四声）与 zhí（第二声）声调不同，意思是到达、极。"}], "explanations": {"直": "正确：直（zhí）指不弯曲，成直线。", "止": "zhǐ（第三声）与 zhí（第二声）声调不同，意思是停止。", "时": "shí 与 zhí 声母不同（sh 与 zh），意思是时间。", "池": "chí 与 zhí 声母不同（ch 与 zh），意思是水池。", "至": "zhì（第四声）与 zhí（第二声）声调不同，意思是到达、极。"}, "sentence_index": null, "correct_answer": "直"}, "level_3": {"options": [{"text": "直", "is_correct": true, "explanation": "正确：“拉直”说把弯铁丝变平直，与后面“放进盒子里”相符。"}, {"text": "宽", "is_correct": false, "explanation": "搭配：“宽”说宽度，铁丝不能拉宽。"}, {"text": "厚", "is_correct": false, "explanation": "语义：“厚”说厚薄，与“拉”使铁丝变细的动作不合。"}, {"text": "深", "is_correct": false, "explanation": "搭配：“深”说深浅，铁丝不能拉深。"}], "explanations": {"直": "正确：“拉直”说把弯铁丝变平直，与后面“放进盒子里”相符。", "宽": "搭配：“宽”说宽度，铁丝不能拉宽。", "厚": "语义：“厚”说厚薄，与“拉”使铁丝变细的动作不合。", "深": "搭配：“深”说深浅，铁丝不能拉深。"}, "sentence_index": 6, "correct_answer": "直"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这根香蕉很直，黄得很可爱。", "explanation": "这里应该用〈弯〉。香蕉是弯的，“直”只说线条不弯，形容香蕉要用“弯”。"}, {"text": "这块蛋糕很直，切开很好看。", "explanation": "这里应该用〈方〉。蛋糕的形状说“方”，“直”只说线条或物体不弯，不能用来形容蛋糕。"}, {"text": "这颗鸡蛋很直，放在桌上很稳。", "explanation": "这里应该用〈椭圆〉。鸡蛋是椭圆的，“直”只说线条不弯，不能用来形容鸡蛋。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f710dbc2-d2ea-4067-9e4f-b056b043fa1c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90576, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这条小巷修很直，走起来很顺。", "corrected_sentence": "这条小巷修得很直，走起来很顺。", "error_description": "错误：“修很直”；正确：“修得很直”。动词后面接形容词作补语时要用“得”，漏掉“得”是常见错误。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f710dbc2-d2ea-4067-9e4f-b056b043fa1c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90576, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "把这根铁丝直，再挂起来。", "corrected_sentence": "把这根铁丝弄直，再挂起来。", "error_description": "错误：“把……直”；正确：“把……弄直”。“把”字句中形容词不能直接作谓语，要加动词“弄”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f710dbc2-d2ea-4067-9e4f-b056b043fa1c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90579, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "背对", "is_correct": true, "explanation": "反义：“背对”指背朝着，与“正对”正面相对的意思相反。"}, {"text": "进入", "is_correct": false, "explanation": "无关：“进入”指从外到内，与朝向的意思没有反义关系。"}, {"text": "搬运", "is_correct": false, "explanation": "无关：“搬运”指搬动物品，与朝向无关。"}, {"text": "收藏", "is_correct": false, "explanation": "无关：“收藏”指保存物品，与朝向无关。"}], "correct_answer": "背对", "explanations": {"背对": "反义：“背对”指背朝着，与“正对”正面相对的意思相反。", "进入": "无关：“进入”指从外到内，与朝向的意思没有反义关系。", "搬运": "无关：“搬运”指搬动物品，与朝向无关。", "收藏": "无关：“收藏”指保存物品，与朝向无关。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a3add40c-8f3f-4998-a40b-9a4f24bdf4f0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90579, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "背对", "is_correct": true, "explanation": "反义：“背对”指背朝着，与“正对”正面相对的意思相反。"}, {"text": "融化", "is_correct": false, "explanation": "无关：“融化”指固体变成液体，与方位朝向无关。"}, {"text": "挖掘", "is_correct": false, "explanation": "无关：“挖掘”指向下刨土，与方位朝向无关。"}, {"text": "倾倒", "is_correct": false, "explanation": "无关：“倾倒”指把东西倒出，与方位朝向无关。"}], "correct_answer": "背对", "explanations": {"背对": "反义：“背对”指背朝着，与“正对”正面相对的意思相反。", "融化": "无关：“融化”指固体变成液体，与方位朝向无关。", "挖掘": "无关：“挖掘”指向下刨土，与方位朝向无关。", "倾倒": "无关：“倾倒”指把东西倒出，与方位朝向无关。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a3add40c-8f3f-4998-a40b-9a4f24bdf4f0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90579, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "脸或东西直直地对着一个方向。", "primary_collocate": null, "pronunciation": "zhèng duì", "ipa": "ʈʂəŋ˥˩ tweɪ˥˩", "syllable_count": 2, "sentences": [{"text": "他正对着镜子整理头发。", "target_word": "正对", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请你正对着我，不要看别处。", "target_word": "正对", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "电风扇正对着我吹，有点冷。", "target_word": "正对", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她正对着大家，大声地说话。", "target_word": "正对", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "照相的时候，请正对着镜头。", "target_word": "正对", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "灯正对着我的眼睛，太亮了。", "target_word": "正对", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他把椅子转过来，正对着老师坐下。", "target_word": "正对", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "空调正对着床，晚上会冷。", "target_word": "正对", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子正对着妈妈，开心地笑。", "target_word": "正对", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "手机摄像头要正对着书页。", "target_word": "正对", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "正对着", "label": "体标"}], "register": "中性", "sense_fingerprint": "正对：脸或物体直直朝向某个方向", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6e70502b-b805-4b8c-a302-573ca6cc38cd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90579, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "正对", "is_correct": true, "explanation": "正确：“正对着镜子”表示正朝着镜子，与整理头发的动作相符。"}, {"text": "摔碎", "is_correct": false, "explanation": "语义：“摔碎”表示破裂，与整理头发的动作不相容。"}, {"text": "挂", "is_correct": false, "explanation": "配价：“挂”需要挂在某处的宾语，句子无法这样成立。"}, {"text": "拆开", "is_correct": false, "explanation": "语义：“拆开”指打开包装，与“镜子”搭配不当，句子意思不通。"}], "explanations": {"正对": "正确：“正对着镜子”表示正朝着镜子，与整理头发的动作相符。", "摔碎": "语义：“摔碎”表示破裂，与整理头发的动作不相容。", "挂": "配价：“挂”需要挂在某处的宾语，句子无法这样成立。", "拆开": "语义：“拆开”指打开包装，与“镜子”搭配不当，句子意思不通。"}, "sentence_index": 0, "correct_answer": "正对"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他正对我的话，只是点点头。", "explanation": "这里应该用〈理睬〉。“理睬”指对别人的话作出反应，“正对”只表示朝向，不能用于回应话语。"}, {"text": "孩子正对妈妈的话，只是笑了笑。", "explanation": "这里应该用〈回答〉。“回答”针对话语或问题，“正对”只表示朝向，不能用于回应话语。"}, {"text": "他正对老师的建议，马上照做了。", "explanation": "这里应该用〈接受〉。“接受”表示采纳意见，“正对”不能表示接受。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a3add40c-8f3f-4998-a40b-9a4f24bdf4f0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90579, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "正对", "is_correct": true, "explanation": "正确：“正对着老师”表示椅子朝向老师，与“坐下”相符。"}, {"text": "推开", "is_correct": false, "explanation": "语义：“推开”指用力使分离，与“转过来”的朝向动作不符，句子意思不通。"}, {"text": "收拾", "is_correct": false, "explanation": "语义：“收拾”指整理物品，不能指朝向老师，句子意思不通。"}, {"text": "拖动", "is_correct": false, "explanation": "配价：“拖动”需要被拖动的物体，“老师”不能被拖动。"}], "explanations": {"正对": "正确：“正对着老师”表示椅子朝向老师，与“坐下”相符。", "推开": "语义：“推开”指用力使分离，与“转过来”的朝向动作不符，句子意思不通。", "收拾": "语义：“收拾”指整理物品，不能指朝向老师，句子意思不通。", "拖动": "配价：“拖动”需要被拖动的物体，“老师”不能被拖动。"}, "sentence_index": 6, "correct_answer": "正对"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他正对我们的请求，很快就点了头。", "explanation": "这里应该用〈答应〉。“答应”表示同意请求，“正对”只表示朝向，不能用来表示同意。"}, {"text": "妈妈正对我的成绩很满意。", "explanation": "这里应该用〈对于〉。“对于”引出评价的对象，“正对”表示朝向，不能引出满意的对象。"}, {"text": "他正对每件事，很认真。", "explanation": "这里应该用〈对待〉。“认真对待”指处理事情的态度，“正对”不能表示态度。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a3add40c-8f3f-4998-a40b-9a4f24bdf4f0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90579, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "她正对了窗户化妆。", "corrected_sentence": "她正对着窗户化妆。", "error_description": "体标错误：表示持续的朝向状态要用“着”，说“正对了”不通顺。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a3add40c-8f3f-4998-a40b-9a4f24bdf4f0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90579, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "小猫正对在门口坐着。", "corrected_sentence": "小猫正对着门口坐着。", "error_description": "介词误用：表示朝向要用“着”，“在”不能接在“正对”之后。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a3add40c-8f3f-4998-a40b-9a4f24bdf4f0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90580, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "背对", "is_correct": true, "explanation": "反义：“背对”指背朝着，与“正对”正面相对的意思相反。"}, {"text": "穿越", "is_correct": false, "explanation": "无关：“穿越”指从一端通过到另一端，与朝向的意思没有反义关系。"}, {"text": "搬运", "is_correct": false, "explanation": "无关：“搬运”指搬动物品，与方位朝向无关。"}, {"text": "收藏", "is_correct": false, "explanation": "无关：“收藏”指保存物品，与方位朝向无关。"}], "correct_answer": "背对", "explanations": {"背对": "反义：“背对”指背朝着，与“正对”正面相对的意思相反。", "穿越": "无关：“穿越”指从一端通过到另一端，与朝向的意思没有反义关系。", "搬运": "无关：“搬运”指搬动物品，与方位朝向无关。", "收藏": "无关：“收藏”指保存物品，与方位朝向无关。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a3add40c-8f3f-4998-a40b-9a4f24bdf4f0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90580, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "背对", "is_correct": true, "explanation": "反义：“背对”指背朝着，与“正对”正面相对的意思相反。"}, {"text": "漂浮", "is_correct": false, "explanation": "无关：“漂浮”指浮在液体或空中，与方位朝向无关。"}, {"text": "融化", "is_correct": false, "explanation": "无关：“融化”指固体变成液体，与方位朝向无关。"}, {"text": "挖掘", "is_correct": false, "explanation": "无关：“挖掘”指向下刨土，与方位朝向无关。"}], "correct_answer": "背对", "explanations": {"背对": "反义：“背对”指背朝着，与“正对”正面相对的意思相反。", "漂浮": "无关：“漂浮”指浮在液体或空中，与方位朝向无关。", "融化": "无关：“融化”指固体变成液体，与方位朝向无关。", "挖掘": "无关：“挖掘”指向下刨土，与方位朝向无关。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a3add40c-8f3f-4998-a40b-9a4f24bdf4f0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90580, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "正面相对；直对着。", "primary_collocate": null, "pronunciation": "zhèng duì", "ipa": "ʈʂəŋ˥˩ tweɪ˥˩", "syllable_count": 2, "sentences": [{"text": "我家的窗户正对着公园。", "target_word": "正对", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "学校大门正对着一条大街。", "target_word": "正对", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这间教室正对着操场。", "target_word": "正对", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "商店的门正对着车站。", "target_word": "正对", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他的房子正对着我家的大门。", "target_word": "正对", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "桌子正对着窗户，光线很好。", "target_word": "正对", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "医院正对着一座小山。", "target_word": "正对", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们的座位正对着舞台。", "target_word": "正对", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "那家饭店正对着地铁站的出口。", "target_word": "正对", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "酒店的房间正对着大海，风景很美。", "target_word": "正对", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "正对着", "label": "体标"}], "register": "中性", "sense_fingerprint": "正对：建筑、位置正面相对", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6e70502b-b805-4b8c-a302-573ca6cc38cd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90580, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "正对", "is_correct": true, "explanation": "正确：“正对着”表示窗户朝向公园，正面相对。"}, {"text": "进入", "is_correct": false, "explanation": "语义：“进入”指从外到内，窗户不能进入公园，与朝向的意思不符。"}, {"text": "搬运", "is_correct": false, "explanation": "配价：“搬运”需要可以搬动的物体作宾语，“窗户”和“公园”都不能被搬运。"}, {"text": "收藏", "is_correct": false, "explanation": "语义：“收藏”需要有人作主语、有可保存的物品，与窗户的朝向不相容。"}], "explanations": {"正对": "正确：“正对着”表示窗户朝向公园，正面相对。", "进入": "语义：“进入”指从外到内，窗户不能进入公园，与朝向的意思不符。", "搬运": "配价：“搬运”需要可以搬动的物体作宾语，“窗户”和“公园”都不能被搬运。", "收藏": "语义：“收藏”需要有人作主语、有可保存的物品，与窗户的朝向不相容。"}, "sentence_index": 0, "correct_answer": "正对"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他勇敢地正对着困难。", "explanation": "这里应该用〈面对〉。“面对”可以用于困难等抽象事物，“正对”只表示位置上的正面相对。"}, {"text": "我们正对着新的一年。", "explanation": "这里应该用〈迎接〉。“迎接”指迎来新的时期，“正对”只能表示空间上的朝向，不能用于时间。"}, {"text": "公司正对着破产的危险。", "explanation": "这里应该用〈面临〉。“面临”指遇到困难或危险，“正对”只表示物理方向。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a3add40c-8f3f-4998-a40b-9a4f24bdf4f0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90580, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "正对", "is_correct": true, "explanation": "正确：“正对着”表示医院朝向小山，正面相对。"}, {"text": "离开", "is_correct": false, "explanation": "语义：“离开”指脱离，医院不能离开小山，与朝向的意思不符。"}, {"text": "倒塌", "is_correct": false, "explanation": "语义：“倒塌”指崩坏，与朝向无关，句子意思不通。"}, {"text": "拆除", "is_correct": false, "explanation": "搭配：“拆除”的对象通常是建筑，与“小山”搭配不当，也不能表示朝向。"}], "explanations": {"正对": "正确：“正对着”表示医院朝向小山，正面相对。", "离开": "语义：“离开”指脱离，医院不能离开小山，与朝向的意思不符。", "倒塌": "语义：“倒塌”指崩坏，与朝向无关，句子意思不通。", "拆除": "搭配：“拆除”的对象通常是建筑，与“小山”搭配不当，也不能表示朝向。"}, "sentence_index": 6, "correct_answer": "正对"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他正对我们的问题给出了答案。", "explanation": "这里应该用〈针对〉。“针对”指对问题有所指向，“正对”只表示正面相对的方位，不能用来给问题作答。"}, {"text": "他正对同学的批评，只是笑了笑。", "explanation": "这里应该用〈面对〉。“面对”可以用于批评等抽象事物，“正对”只表示位置上的正面相对。"}, {"text": "他正对工作很认真。", "explanation": "这里应该用〈对待〉。“对待”指对事情所持的态度，“正对”只表示朝向。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a3add40c-8f3f-4998-a40b-9a4f24bdf4f0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90580, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这条路正对了山顶。", "corrected_sentence": "这条路正对着山顶。", "error_description": "体标错误：表示持续的朝向状态要用“着”，说“正对了”不通顺。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a3add40c-8f3f-4998-a40b-9a4f24bdf4f0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
