INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90582, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "研究并开发新产品、新技术。", "primary_collocate": null, "pronunciation": "yán fā", "ipa": "jɛn˧˥ fa˥", "syllable_count": 2, "sentences": [{"text": "这家药厂研发新药已经十年了。", "target_word": "研发", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她在公司负责研发新技术。", "target_word": "研发", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "为了研发电池，他们做了很多试验。", "target_word": "研发", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们每天在实验室里研发新材料。", "target_word": "研发", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这家公司每年花很多钱研发新产品。", "target_word": "研发", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们研发过一种很小的相机。", "target_word": "研发", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "大学和公司一起研发了新的电池技术。", "target_word": "研发", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "公司决定研发一种更便宜的机器。", "target_word": "研发", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我哥哥在汽车公司研发新型发动机。", "target_word": "研发", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们研发了三年，终于成功了。", "target_word": "研发", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "研发了", "label": "体标"}, {"form": "研发过", "label": "体标"}, {"form": "研发中心", "label": "复合"}], "register": "中性", "sense_fingerprint": "研发：研究并开发新产品、新技术", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '53f807e0-8acf-42ca-93b2-48cbb7eb4cad') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90582, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "研发", "is_correct": true, "explanation": "研发（yán fā）：研究并开发新产品、新技术，是本题的目标词。"}, {"text": "盐巴", "is_correct": false, "explanation": "盐巴（yán bā）与研发（yán fā）只有第二个音节声母不同（b/f），意思是盐。"}, {"text": "盐分", "is_correct": false, "explanation": "盐分（yán fèn）与研发（yán fā）第二个音节韵母和声调不同（en/a，第四声与第一声），意思是盐的含量。"}, {"text": "严防", "is_correct": false, "explanation": "严防（yán fáng）与研发（yán fā）第二个音节韵母和声调不同（ang/a，第二声与第一声），意思是严密防备。"}, {"text": "养发", "is_correct": false, "explanation": "养发（yǎng fā）与研发（yán fā）第一个音节韵母和声调不同（ang/an，第三声与第二声），意思是护理头发。"}], "explanations": {"研发": "研发（yán fā）：研究并开发新产品、新技术，是本题的目标词。", "盐巴": "盐巴（yán bā）与研发（yán fā）只有第二个音节声母不同（b/f），意思是盐。", "盐分": "盐分（yán fèn）与研发（yán fā）第二个音节韵母和声调不同（en/a，第四声与第一声），意思是盐的含量。", "严防": "严防（yán fáng）与研发（yán fā）第二个音节韵母和声调不同（ang/a，第二声与第一声），意思是严密防备。", "养发": "养发（yǎng fā）与研发（yán fā）第一个音节韵母和声调不同（ang/an，第三声与第二声），意思是护理头发。"}, "sentence_index": null, "correct_answer": "研发"}, "level_3": {"options": [{"text": "修理", "is_correct": false, "explanation": "搭配：“修理”的对象是机器、设备等，不能修理新药。"}, {"text": "吃", "is_correct": false, "explanation": "语义：“吃”的动作由人或动物完成，药厂不能吃新药。"}, {"text": "研发", "is_correct": true, "explanation": "研发：研制新药，与“这家药厂”和“新药”搭配，符合句意。"}, {"text": "写", "is_correct": false, "explanation": "搭配：“写”的对象是文字、文章，不能说写新药。"}], "explanations": {"修理": "搭配：“修理”的对象是机器、设备等，不能修理新药。", "吃": "语义：“吃”的动作由人或动物完成，药厂不能吃新药。", "研发": "研发：研制新药，与“这家药厂”和“新药”搭配，符合句意。", "写": "搭配：“写”的对象是文字、文章，不能说写新药。"}, "sentence_index": 0, "correct_answer": "研发"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "政府研发了一片新区。", "explanation": "这里应该用〈开发〉。研发侧重研制产品、技术；新区这类地域的建设要用开发。"}, {"text": "他们在图书馆研发历史。", "explanation": "这里应该用〈研究〉。研发指研制产品、技术，历史是要研究的对象。"}, {"text": "农民研发了一片小麦。", "explanation": "这里应该用〈种植〉。研发指研制新产品、新技术，小麦这类作物要用种植。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '718050bc-321d-406a-9188-a4a097c777a8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90582, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "熬", "is_correct": false, "explanation": "搭配：“熬”多用于汤、药等，不能与“技术”搭配。"}, {"text": "拆除", "is_correct": false, "explanation": "搭配：“拆除”的对象是建筑、设施，技术不能被拆除。"}, {"text": "研发", "is_correct": true, "explanation": "研发：研制新技术，与“新的电池技术”搭配，符合句意。"}, {"text": "点燃", "is_correct": false, "explanation": "语义：“点燃”的对象是火、火柴等，技术不能被点燃。"}], "explanations": {"熬": "搭配：“熬”多用于汤、药等，不能与“技术”搭配。", "拆除": "搭配：“拆除”的对象是建筑、设施，技术不能被拆除。", "研发": "研发：研制新技术，与“新的电池技术”搭配，符合句意。", "点燃": "语义：“点燃”的对象是火、火柴等，技术不能被点燃。"}, "sentence_index": 6, "correct_answer": "研发"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "学校研发了一份新的学习计划。", "explanation": "这里应该用〈制订〉。研发针对产品、技术；学习计划这类方案要用制订。"}, {"text": "作家研发了一部小说。", "explanation": "这里应该用〈创作〉。研发指研制产品、技术；小说这类文学作品要用创作。"}, {"text": "工人研发了一条新路。", "explanation": "这里应该用〈修建〉。研发指研制产品、技术；道路这类工程要用修建。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '718050bc-321d-406a-9188-a4a097c777a8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90582, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这家药厂研发着成功了一种新药。", "corrected_sentence": "这家药厂研发成功了一种新药。", "error_description": "错误：“研发着成功了”。正确：“研发成功了”。“着”表示持续，不能插在动词“研发”和结果补语“成功”之间；去掉“着”即可。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '718050bc-321d-406a-9188-a4a097c777a8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90582, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这家公司研发了过一种新的电池。", "corrected_sentence": "这家公司研发过一种新的电池。", "error_description": "错误：“研发了过”。正确：“研发过”。“过”表示曾经做过某事，直接附在动词后，不能再加“了”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '718050bc-321d-406a-9188-a4a097c777a8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
