INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90588, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "人本来具有的品质和修养。", "primary_collocate": null, "pronunciation": "sù zhì", "ipa": "su˥˩ ʈʂʐ̩˥˩", "syllable_count": 2, "sentences": [{"text": "在公共场所大声说话，说明他的素质不高。", "target_word": "素质", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他从不插队，也不乱扔垃圾，素质真高。", "target_word": "素质", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "一个人的素质，在小事上最容易看出来。", "target_word": "素质", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "大家的素质提高了，城市也变得更干净了。", "target_word": "素质", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他说话很客气，一看就是素质很好的人。", "target_word": "素质", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "对老人这样说话，真是没有素质。", "target_word": "素质", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "父母的素质会影响孩子，所以要做好榜样。", "target_word": "素质", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这家餐厅的服务员素质很高，对谁都有礼貌。", "target_word": "素质", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她讲话很有分寸，待人也客气，素质真好。", "target_word": "素质", "complexity_tier": "T3", "furigana": "tā jiǎnghuà hěn yǒu fēncùn, dàirén yě kèqi, sùzhì zhēn hǎo.", "sentence_source": "generated"}, {"text": "她很有素质，别人说错了，她也不生气。", "target_word": "素质", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "素質", "label": "繁体"}, {"form": "国民素质", "label": "复合"}, {"form": "素质教育", "label": "复合"}], "register": "中性", "sense_fingerprint": "人的品质和修养", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cc24a53f-6254-4aa5-8e47-0703e4066dea') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90588, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "素质", "is_correct": true, "explanation": "正确：“素质不高”说明人的修养差，与“大声说话”相符。"}, {"text": "声音", "is_correct": false, "explanation": "语义：“声音不高”指说话声音小，与前句“大声说话”矛盾。"}, {"text": "颜色", "is_correct": false, "explanation": "搭配：“颜色”不说高低，“不高”不能修饰颜色。"}, {"text": "脾气", "is_correct": false, "explanation": "搭配：“脾气”说好坏，不说“不高”。"}], "explanations": {"素质": "正确：“素质不高”说明人的修养差，与“大声说话”相符。", "声音": "语义：“声音不高”指说话声音小，与前句“大声说话”矛盾。", "颜色": "搭配：“颜色”不说高低，“不高”不能修饰颜色。", "脾气": "搭配：“脾气”说好坏，不说“不高”。"}, "sentence_index": 0, "correct_answer": "素质"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这个班的素质有三十人，老师很满意。", "explanation": "这里应该用〈人数〉。班里有多少人要说“人数”，“素质”不能用来计算人数。"}, {"text": "这次考试他的素质排第一，老师很满意。", "explanation": "这里应该用〈名次〉。考试的排列说“名次”，“素质”指人的修养和品质，不能用来说排名。"}, {"text": "他的钢琴素质很深，弹得很有感情。", "explanation": "这里应该用〈功底〉。技能的底子说“功底”，“素质”不说深浅。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f710dbc2-d2ea-4067-9e4f-b056b043fa1c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90588, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "素质", "is_correct": true, "explanation": "正确：“素质”指父母的品行和修养，与“做好榜样”相符。"}, {"text": "味道", "is_correct": false, "explanation": "语义：“味道”说气味或口感，与“影响孩子”的品行无关。"}, {"text": "字体", "is_correct": false, "explanation": "语义：“字体”说字的样式，不能用来说影响孩子的品行。"}, {"text": "发型", "is_correct": false, "explanation": "体貌：“发型”是外在样式，与“做好榜样”的品行不搭。"}], "explanations": {"素质": "正确：“素质”指父母的品行和修养，与“做好榜样”相符。", "味道": "语义：“味道”说气味或口感，与“影响孩子”的品行无关。", "字体": "语义：“字体”说字的样式，不能用来说影响孩子的品行。", "发型": "体貌：“发型”是外在样式，与“做好榜样”的品行不搭。"}, "sentence_index": 6, "correct_answer": "素质"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他的素质很壮，能扛起重物。", "explanation": "这里应该用〈体格〉。“壮”形容体格，“素质”不说壮。"}, {"text": "他素质很大，从不计较。", "explanation": "这里应该用〈气量〉。形容度量大要说“气量”，“素质”不说“大”。"}, {"text": "他的素质已经很老了，走路都慢了。", "explanation": "这里应该用〈年纪〉。形容人年纪大要说“年纪”，“素质”指人的修养和本事，不能说“老”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f710dbc2-d2ea-4067-9e4f-b056b043fa1c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90588, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这位同学有很好素质，老师很喜欢。", "corrected_sentence": "这位同学有很好的素质，老师很喜欢。", "error_description": "错误：“很好素质”；正确：“很好的素质”。形容词修饰名词时中间要加“的”，漏掉“的”是常见错误。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f710dbc2-d2ea-4067-9e4f-b056b043fa1c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90588, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这家公司的员工素质很大，服务态度也好。", "corrected_sentence": "这家公司的员工素质很高，服务态度也好。", "error_description": "搭配错误：“素质很大”；正确：“素质很高”。素质说高低，不说大小，形容素质的程度要用“高”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f710dbc2-d2ea-4067-9e4f-b056b043fa1c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
