INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90591, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "健谈", "is_correct": true, "explanation": "正确。「健谈」指爱说话、善于交谈，与「沉默」寡言的性格意思相反。"}, {"text": "勇敢", "is_correct": false, "explanation": "无反义关系：「勇敢」指不怕困难、有胆量，与「沉默」的意思不相对。"}, {"text": "聪明", "is_correct": false, "explanation": "无反义关系：「聪明」指头脑灵活，与「沉默」的意思不相对。"}, {"text": "高兴", "is_correct": false, "explanation": "无反义关系：「高兴」指心情愉快，与「沉默」描述的性格或环境无关。"}], "correct_answer": "健谈", "explanations": {"健谈": "正确。「健谈」指爱说话、善于交谈，与「沉默」寡言的性格意思相反。", "勇敢": "无反义关系：「勇敢」指不怕困难、有胆量，与「沉默」的意思不相对。", "聪明": "无反义关系：「聪明」指头脑灵活，与「沉默」的意思不相对。", "高兴": "无反义关系：「高兴」指心情愉快，与「沉默」描述的性格或环境无关。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '17403514-88bd-43ce-bf3d-11fb4f8b017e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90591, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "不说话，很安静。", "primary_collocate": null, "pronunciation": "chén mò", "ipa": "ʈʂʰən˧˥ mɔ˥˩", "syllable_count": 2, "sentences": [{"text": "他是个很沉默的人。", "target_word": "沉默", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我的同桌性格沉默，很少笑。", "target_word": "沉默", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个孩子比以前沉默多了。", "target_word": "沉默", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "那天车上的人都很沉默，只有雨声。", "target_word": "沉默", "complexity_tier": "T3", "furigana": "nà tiān chē shang de rén dōu hěn chénmò, zhǐ yǒu yǔ shēng.", "sentence_source": "generated"}, {"text": "沉默的山谷里没有一点声音。", "target_word": "沉默", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他看上去有点沉默。", "target_word": "沉默", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她从小就很沉默，不爱说话。", "target_word": "沉默", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "晚饭时大家都很沉默。", "target_word": "沉默", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "沉默的夜晚，我一个人坐着。", "target_word": "沉默", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "爷爷年纪大了，变得越来越沉默。", "target_word": "沉默", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "沉默了", "label": "体标"}, {"form": "沉默寡言", "label": "复合"}], "register": "中性", "sense_fingerprint": "人少言寡语，或场合、环境安静无声", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5cea4ba9-e5df-4d1b-8c6e-7471ef55d20e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90591, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "沉默", "is_correct": true, "explanation": "正确。「沉默」形容人不爱说话，与「他是个很……的人」相符。"}, {"text": "潮湿", "is_correct": false, "explanation": "语义：「潮湿」形容空气或物体含水多，不能用来形容一个人。"}, {"text": "方形", "is_correct": false, "explanation": "语义：「方形」指形状，不能用来形容人的性格，句子说不通。"}, {"text": "咸", "is_correct": false, "explanation": "搭配：「咸」形容味道，不能与「人」搭配来描述性格。"}], "explanations": {"沉默": "正确。「沉默」形容人不爱说话，与「他是个很……的人」相符。", "潮湿": "语义：「潮湿」形容空气或物体含水多，不能用来形容一个人。", "方形": "语义：「方形」指形状，不能用来形容人的性格，句子说不通。", "咸": "搭配：「咸」形容味道，不能与「人」搭配来描述性格。"}, "sentence_index": 0, "correct_answer": "沉默"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "她沉默地向我们介绍了这里的风景。", "explanation": "这里应该用〈热情〉。沉默指不说话、很安静，与「介绍风景」要开口矛盾；形容态度友好、主动要用〈热情〉。"}, {"text": "他沉默地讲了一个小时的笑话。", "explanation": "这里应该用〈滔滔不绝〉。沉默指不说话，与「讲了一个小时」要开口矛盾；形容说话不停要用〈滔滔不绝〉。"}, {"text": "他很沉默地说出了答案。", "explanation": "这里应该用〈沉着〉。沉默指不说话，「沉默地说出答案」前后矛盾；形容镇定、不慌张要用〈沉着〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '17403514-88bd-43ce-bf3d-11fb4f8b017e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90591, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "沉默", "is_correct": true, "explanation": "正确。「沉默」形容性格不爱说话，与「不爱说话」相符。"}, {"text": "饥饿", "is_correct": false, "explanation": "语义：「饥饿」形容肚子空、想吃东西，不能用来形容性格。"}, {"text": "漆黑", "is_correct": false, "explanation": "语义：「漆黑」形容颜色或光线，不能用来形容一个人的性格。"}, {"text": "滚烫", "is_correct": false, "explanation": "搭配：「滚烫」多用于温度和物体，不与「性格」搭配。"}], "explanations": {"沉默": "正确。「沉默」形容性格不爱说话，与「不爱说话」相符。", "饥饿": "语义：「饥饿」形容肚子空、想吃东西，不能用来形容性格。", "漆黑": "语义：「漆黑」形容颜色或光线，不能用来形容一个人的性格。", "滚烫": "搭配：「滚烫」多用于温度和物体，不与「性格」搭配。"}, "sentence_index": 6, "correct_answer": "沉默"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这个派对很沉默，大家又唱又跳。", "explanation": "这里应该用〈热闹〉。沉默指不说话、很安静，与「又唱又跳」矛盾；形容场面喧闹要用〈热闹〉。"}, {"text": "他很沉默，一开口就停不下来。", "explanation": "这里应该用〈健谈〉。沉默指不爱说话，与「一开口就停不下来」矛盾；形容爱说话要用〈健谈〉。"}, {"text": "街上很沉默，到处都是叫卖声。", "explanation": "这里应该用〈嘈杂〉。沉默指不出声、很安静，与「到处都是叫卖声」矛盾；形容声音吵闹要用〈嘈杂〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '17403514-88bd-43ce-bf3d-11fb4f8b017e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90591, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "班上新来的同学很很沉默。", "corrected_sentence": "班上新来的同学很沉默。", "error_description": "程度副词重复：「很」只能用一次，应说「很沉默」，错句中多写了一个「很」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '17403514-88bd-43ce-bf3d-11fb4f8b017e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90591, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这两年他越来沉默了。", "corrected_sentence": "这两年他越来越沉默了。", "error_description": "程度副词错误：「越来越」是固定格式，应说「越来越沉默了」，错句中漏掉了一个「越」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '17403514-88bd-43ce-bf3d-11fb4f8b017e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
