INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90592, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "不说话；不出声。", "primary_collocate": null, "pronunciation": "chén mò", "ipa": "ʈʂʰən˧˥ mɔ˥˩", "syllable_count": 2, "sentences": [{"text": "老师问他话，他一直沉默。", "target_word": "沉默", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "听到这个问题，大家都沉默了。", "target_word": "沉默", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他沉默了很久，才开口说话。", "target_word": "沉默", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她低着头，沉默着不回答。", "target_word": "沉默", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你为什么沉默？说说你的想法。", "target_word": "沉默", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "会议上他一直保持沉默。", "target_word": "沉默", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "爸爸听完，沉默了一会儿。", "target_word": "沉默", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "面对问题，我们不能沉默。", "target_word": "沉默", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们俩吵架后沉默了一整天。", "target_word": "沉默", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "房间里的人都沉默着，没人说话。", "target_word": "沉默", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "沉默了", "label": "体标"}, {"form": "沉默着", "label": "体标"}, {"form": "沉默不语", "label": "复合"}], "register": "中性", "sense_fingerprint": "在某个时刻不开口、不回答", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5cea4ba9-e5df-4d1b-8c6e-7471ef55d20e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90592, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "沉默", "is_correct": true, "explanation": "正确。「沉默」指不开口、不回答，与「老师问他话」的语境相符。"}, {"text": "高兴", "is_correct": false, "explanation": "语义：「高兴」说心情愉快，与「老师问话却不回答」的情境不符。"}, {"text": "高大", "is_correct": false, "explanation": "体貌：「高大」描写身材，不能用来说明面对提问时的状态。"}, {"text": "勇敢", "is_correct": false, "explanation": "语义：「勇敢」说不怕困难，与「老师问他话」这一情境不相干。"}], "explanations": {"沉默": "正确。「沉默」指不开口、不回答，与「老师问他话」的语境相符。", "高兴": "语义：「高兴」说心情愉快，与「老师问话却不回答」的情境不符。", "高大": "体貌：「高大」描写身材，不能用来说明面对提问时的状态。", "勇敢": "语义：「勇敢」说不怕困难，与「老师问他话」这一情境不相干。"}, "sentence_index": 0, "correct_answer": "沉默"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "面对记者，他显得很沉默，对答如流。", "explanation": "这里应该用〈沉着〉。沉默指不说话，与「对答如流」矛盾；形容镇定、从容要用〈沉着〉。"}, {"text": "他沉默地喊了一声，把大家都吓了一跳。", "explanation": "这里应该用〈大声〉。沉默指不出声，与「喊了一声」矛盾；形容声音响亮要用〈大声〉。"}, {"text": "他沉默地朗读了课文。", "explanation": "这里应该用〈流利〉。沉默指不出声，与「朗读」要出声矛盾；形容朗读顺畅要用〈流利〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '17403514-88bd-43ce-bf3d-11fb4f8b017e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90592, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "沉默", "is_correct": true, "explanation": "正确。「沉默了一会儿」指一段时间不开口，与「听完」的情境相符。"}, {"text": "聪明", "is_correct": false, "explanation": "语义：「聪明」说头脑灵活，「听完之后聪明了一会儿」说不通。"}, {"text": "漂亮", "is_correct": false, "explanation": "语义：「漂亮」形容外貌或事物美观，与「听完」之后的状态不相干。"}, {"text": "瘦小", "is_correct": false, "explanation": "体貌：「瘦小」描写身材，不能用来形容听完后的状态。"}], "explanations": {"沉默": "正确。「沉默了一会儿」指一段时间不开口，与「听完」的情境相符。", "聪明": "语义：「聪明」说头脑灵活，「听完之后聪明了一会儿」说不通。", "漂亮": "语义：「漂亮」形容外貌或事物美观，与「听完」之后的状态不相干。", "瘦小": "体貌：「瘦小」描写身材，不能用来形容听完后的状态。"}, "sentence_index": 6, "correct_answer": "沉默"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "孩子们沉默地唱起了歌。", "explanation": "这里应该用〈兴奋〉。沉默指不出声，与「唱起了歌」矛盾；形容情绪高涨要用〈兴奋〉。"}, {"text": "她沉默地向大家讲述了旅行经历。", "explanation": "这里应该用〈滔滔不绝〉。沉默指不说话，与「讲述」要开口矛盾；形容说话不停要用〈滔滔不绝〉。"}, {"text": "护士沉默地叮嘱病人要按时吃药。", "explanation": "这里应该用〈温柔〉。沉默指不说话，与「叮嘱」要开口矛盾；形容语气柔和要用〈温柔〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '17403514-88bd-43ce-bf3d-11fb4f8b017e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90592, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "她一直沉默了着，没有回答。", "corrected_sentence": "她一直沉默着，没有回答。", "error_description": "体标错误：「沉默」后接「着」表示持续，不能同时加「了」。应说「沉默着」，错句中多出的「了」应删去。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '17403514-88bd-43ce-bf3d-11fb4f8b017e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90592, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "吃完饭后，爸爸沉默厉害。", "corrected_sentence": "吃完饭后，爸爸沉默得厉害。", "error_description": "补语错误：程度补语前要加结构助词「得」，应说「沉默得厉害」，错句中漏掉了「得」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '17403514-88bd-43ce-bf3d-11fb4f8b017e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
