INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90594, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "妻子对丈夫的称呼，口语用法。", "primary_collocate": null, "pronunciation": "lǎo gōng", "ipa": "lau̯˨˩˦ kʊŋ˥", "syllable_count": 2, "sentences": [{"text": "我老公喜欢踢足球。", "target_word": "老公", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老公，今晚我们吃面条吧。", "target_word": "老公", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "昨天是我和老公结婚十年的日子。", "target_word": "老公", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她让老公去超市买牛奶。", "target_word": "老公", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我老公比我大两岁。", "target_word": "老公", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老公睡着了，请小声一点。", "target_word": "老公", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "邻居的老公是一位医生。", "target_word": "老公", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她常常和老公一起散步。", "target_word": "老公", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老公给我买了一束花。", "target_word": "老公", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我老公不会做菜，但会洗碗。", "target_word": "老公", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "一个老公", "label": "量词"}], "register": "口语", "sense_fingerprint": "老公：妻子对丈夫的口语称呼", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd3f4d125-09bd-4a29-83b8-15c3ccd853c7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.va