INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90594, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "老公", "is_correct": true, "explanation": "正确：老公是妻子口语中对丈夫的称呼，“邻居的老公是医生”成立。"}, {"text": "窗户", "is_correct": false, "explanation": "语义：窗户不能当医生，“邻居的窗户是一位医生”说不通。"}, {"text": "树木", "is_correct": false, "explanation": "语义：树木不能当医生，句子说不通。"}, {"text": "黑板", "is_correct": false, "explanation": "语义：黑板不能当医生，“邻居的黑板是一位医生”说不通。"}], "explanations": {"老公": "正确：老公是妻子口语中对丈夫的称呼，“邻居的老公是医生”成立。", "窗户": "语义：窗户不能当医生，“邻居的窗户是一位医生”说不通。", "树木": "语义：树木不能当医生，句子说不通。", "黑板": "语义：黑板不能当医生，“邻居的黑板是一位医生”说不通。"}, "sentence_index": 6, "correct_answer": "老公"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "丈夫在厨房里对妻子喊：“老公，帮我拿一下碗。”", "explanation": "老公是妻子称呼丈夫的词，丈夫不能用它称呼妻子。"}, {"text": "我老公是个女生，最喜欢逛街。", "explanation": "老公指男性配偶，不能指女性，这里用来指女性是错误的。"}, {"text": "我的老公是一只小猫，每天陪我一起睡觉。", "explanation": "这里不能用〈老公〉。它指人类配偶，不能用来指小猫。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '884bc76d-2bca-4740-b392-561903b984d1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90594, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "她嫁了一只老公，在银行上班。", "corrected_sentence": "她嫁了一个老公，在银行上班。", "error_description": "量词错误：老公指人，量词应用“个”，不能用“只”。正确说法是“一个老公”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '884bc76d-2bca-4740-b392-561903b984d1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90594, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "几个老公们周末一起踢球。", "corrected_sentence": "几个老公周末一起踢球。", "error_description": "复数错误：前面有“几个”表示数量，名词后不能再加“们”。正确说法是“几个老公”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '884bc76d-2bca-4740-b392-561903b984d1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
