INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90597, 1, 'prompt1_core', '{"pos": "副词", "semantic_class": "function", "definition": "自行是自己做，不用别人帮忙。", "primary_collocate": null, "pronunciation": "zì xíng", "ipa": "tsɨ˥˩ ɕiŋ˧˥", "syllable_count": 2, "sentences": [{"text": "作业请自行完成，不要抄别人的。", "target_word": "自行", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他不想麻烦别人，自行去了医院。", "target_word": "自行", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "门票要自行购买。", "target_word": "自行", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "水果可以自行挑选。", "target_word": "自行", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "出了问题，你先自行想办法。", "target_word": "自行", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他自行安排了周末的时间。", "target_word": "自行", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "孩子们自行收拾好了房间。", "target_word": "自行", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "天太晚了，我自行打车回家。", "target_word": "自行", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "会议的资料请自行下载。", "target_word": "自行", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我们没有人带路，只好自行找地方。", "target_word": "自行", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "书面", "sense_fingerprint": "自行：自己做，不用别人帮忙", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '53f807e0-8acf-42ca-93b2-48cbb7eb4cad') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90597, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "自行", "is_correct": true, "explanation": "自行（zì xíng）：自己做，不用别人帮忙，是本题的目标词。"}, {"text": "自省", "is_correct": false, "explanation": "自省（zì xǐng）与自行（zì xíng）只有第二个音节声调不同（第三声与第二声），意思是反省自己。"}, {"text": "自信", "is_correct": false, "explanation": "自信（zì xìn）与自行（zì xíng）第二个音节韵尾和声调不同（n/ng，第四声与第二声），意思是相信自己。"}, {"text": "执行", "is_correct": false, "explanation": "执行（zhí xíng）与自行（zì xíng）第一个音节声母和声调不同（zh/z，第二声与第四声），意思是实施。"}, {"text": "直行", "is_correct": false, "explanation": "直行（zhí xíng）与自行（zì xíng）第一个音节声母和声调不同（zh/z，第二声与第四声），意思是一直向前走。"}], "explanations": {"自行": "自行（zì xíng）：自己做，不用别人帮忙，是本题的目标词。", "自省": "自省（zì xǐng）与自行（zì xíng）只有第二个音节声调不同（第三声与第二声），意思是反省自己。", "自信": "自信（zì xìn）与自行（zì xíng）第二个音节韵尾和声调不同（n/ng，第四声与第二声），意思是相信自己。", "执行": "执行（zhí xíng）与自行（zì xíng）第一个音节声母和声调不同（zh/z，第二声与第四声），意思是实施。", "直行": "直行（zhí xíng）与自行（zì xíng）第一个音节声母和声调不同（zh/z，第二声与第四声），意思是一直向前走。"}, "sentence_index": null, "correct_answer": "自行"}, "level_3": {"options": [{"text": "已经", "is_correct": false, "explanation": "体貌：“已经”表示动作已完成，与表示提醒的“请”冲突。"}, {"text": "自行", "is_correct": true, "explanation": "自行：自己做，不靠别人，与“作业请……完成”搭配，符合句意。"}, {"text": "竟然", "is_correct": false, "explanation": "语义：“竟然”表示出乎意料，不能用于要求别人完成作业的语境。"}, {"text": "业已", "is_correct": false, "explanation": "语域：“业已”是书面语，与这里的口头提醒语气不协调。"}], "explanations": {"已经": "体貌：“已经”表示动作已完成，与表示提醒的“请”冲突。", "自行": "自行：自己做，不靠别人，与“作业请……完成”搭配，符合句意。", "竟然": "语义：“竟然”表示出乎意料，不能用于要求别人完成作业的语境。", "业已": "语域：“业已”是书面语，与这里的口头提醒语气不协调。"}, "sentence_index": 0, "correct_answer": "自行"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我自行看见了这一幕。", "explanation": "这里应该用〈亲眼〉。亲眼强调用自己的眼睛看到；“自行”只说明不靠别人，不用于看见这类感知动词。"}, {"text": "我自行听到了老师的表扬。", "explanation": "这里应该用〈亲耳〉。亲耳强调用自己的耳朵听到；“自行”不用来说听到，这里要用亲耳。"}, {"text": "他自行请人替他对我讲了这件事。", "explanation": "这里应该用〈亲口〉。亲口强调本人亲自说出；“自行请人替他讲”自相矛盾，“自行”与请人代劳冲突。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '718050bc-321d-406a-9188-a4a097c777a8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90597, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "务必", "is_correct": false, "explanation": "体貌：“务必”表示必须去做，与已经完成的“收拾好了”冲突。"}, {"text": "自行", "is_correct": true, "explanation": "自行：自己做，不靠别人，与“孩子们……收拾好了房间”搭配，符合句意。"}, {"text": "乱", "is_correct": false, "explanation": "语义：“乱”表示没有秩序，与“收拾好”的结果相反。"}, {"text": "通常", "is_correct": false, "explanation": "体貌：“通常”表示习惯性的情况，与一次完成的“收拾好了”不相符。"}], "explanations": {"务必": "体貌：“务必”表示必须去做，与已经完成的“收拾好了”冲突。", "自行": "自行：自己做，不靠别人，与“孩子们……收拾好了房间”搭配，符合句意。", "乱": "语义：“乱”表示没有秩序，与“收拾好”的结果相反。", "通常": "体貌：“通常”表示习惯性的情况，与一次完成的“收拾好了”不相符。"}, "sentence_index": 6, "correct_answer": "自行"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "她自行一人去了超市。", "explanation": "这里应该用〈独自〉。独自强调单独一人，常与“一人”“一个人”搭配；“自行”不说“自行一人”。"}, {"text": "他自行经历了那场战争。", "explanation": "这里应该用〈亲身〉。亲身强调本人亲自经历；“自行”只说明不靠别人，不能用来说经历战争这类事。"}, {"text": "这幅字是他自行找人代写的。", "explanation": "这里应该用〈亲笔〉。亲笔强调本人亲手书写，多用于字画、信件；“自行找人代写”自相矛盾，“自行”表示不靠别人。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '718050bc-321d-406a-9188-a4a097c777a8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90597, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这个问题你要自行的解决。", "corrected_sentence": "这个问题你要自行解决。", "error_description": "错误：“自行的解决”。正确：“自行解决”。“自行”是副词，直接修饰动词作状语，后面不加“的”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '718050bc-321d-406a-9188-a4a097c777a8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90597, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这份报告我们自行的整理。", "corrected_sentence": "这份报告我们自行整理。", "error_description": "错误：“自行的整理”。正确：“自行整理”。“自行”是副词，直接修饰动词作状语，后面不加“的”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '718050bc-321d-406a-9188-a4a097c777a8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
