INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90598, 1, 'prompt1_core', '{"pos": "副词", "semantic_class": "function", "definition": "副词，表示由自己来做，不靠别人。", "primary_collocate": null, "pronunciation": "zì xíng", "ipa": "tsɨ˥˩ ɕiŋ˧˥", "syllable_count": 2, "sentences": [{"text": "请大家自行回家。", "target_word": "自行", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "学生可以自行选择课程。", "target_word": "自行", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "吃完饭，客人自行离开了。", "target_word": "自行", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "手机坏了，请自行联系商店。", "target_word": "自行", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "房间里没有人，你可以自行进去。", "target_word": "自行", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们不提供午饭，请自行准备。", "target_word": "自行", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小伤口过几天会自行恢复。", "target_word": "自行", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "同学们自行分成了三个小组。", "target_word": "自行", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "车票请自行保管，不要弄丢。", "target_word": "自行", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "到了公园，大家可以自行安排一个小时的活动。", "target_word": "自行", "complexity_tier": "T3", "furigana": "dào le gōng yuán, dà jiā kě yǐ zì xíng ān pái yí gè xiǎo shí de huó dòng.", "sentence_source": "generated"}], "morphological_forms": [], "register": "书面", "sense_fingerprint": "自行：副词，由自己来做，不靠别人", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '53f807e0-8acf-42ca-93b2-48cbb7eb4cad') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90598, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "自行", "is_correct": true, "explanation": "自行（zì xíng）：由自己来做，不靠别人，是本题的目标词。"}, {"text": "自省", "is_correct": false, "explanation": "自省（zì xǐng）与自行（zì xíng）只有第二个音节声调不同（第三声与第二声），意思是反省自己。"}, {"text": "自信", "is_correct": false, "explanation": "自信（zì xìn）与自行（zì xíng）第二个音节韵尾和声调不同（n/ng，第四声与第二声），意思是相信自己。"}, {"text": "执行", "is_correct": false, "explanation": "执行（zhí xíng）与自行（zì xíng）第一个音节声母和声调不同（zh/z，第二声与第四声），意思是实施。"}, {"text": "直行", "is_correct": false, "explanation": "直行（zhí xíng）与自行（zì xíng）第一个音节声母和声调不同（zh/z，第二声与第四声），意思是一直向前走。"}], "explanations": {"自行": "自行（zì xíng）：由自己来做，不靠别人，是本题的目标词。", "自省": "自省（zì xǐng）与自行（zì xíng）只有第二个音节声调不同（第三声与第二声），意思是反省自己。", "自信": "自信（zì xìn）与自行（zì xíng）第二个音节韵尾和声调不同（n/ng，第四声与第二声），意思是相信自己。", "执行": "执行（zhí xíng）与自行（zì xíng）第一个音节声母和声调不同（zh/z，第二声与第四声），意思是实施。", "直行": "直行（zhí xíng）与自行（zì xíng）第一个音节声母和声调不同（zh/z，第二声与第四声），意思是一直向前走。"}, "sentence_index": null, "correct_answer": "自行"}, "level_3": {"options": [{"text": "竟然", "is_correct": false, "explanation": "语义：“竟然”表示出乎意料，不能用于“请大家……回家”这样的请求。"}, {"text": "自行", "is_correct": true, "explanation": "自行：由自己来做，不靠别人，与“请大家……回家”搭配，符合句意。"}, {"text": "已经", "is_correct": false, "explanation": "体貌：“已经”表示动作已完成，与表示请求的“请”冲突。"}, {"text": "通常", "is_correct": false, "explanation": "语义：“通常”表示习惯性的情况，与一次性的请求不相符。"}], "explanations": {"竟然": "语义：“竟然”表示出乎意料，不能用于“请大家……回家”这样的请求。", "自行": "自行：由自己来做，不靠别人，与“请大家……回家”搭配，符合句意。", "已经": "体貌：“已经”表示动作已完成，与表示请求的“请”冲突。", "通常": "语义：“通常”表示习惯性的情况，与一次性的请求不相符。"}, "sentence_index": 0, "correct_answer": "自行"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我自行看见了那场车祸。", "explanation": "这里应该用〈亲眼〉。亲眼强调用自己的眼睛看到；“自行”只说明不靠别人，不用于看见、听见这类感知动词。"}, {"text": "我自行听到了他的解释。", "explanation": "这里应该用〈亲耳〉。亲耳强调用自己的耳朵听到；“自行”不用来说听到，这里要用亲耳。"}, {"text": "他自行对我说了谢谢。", "explanation": "这里应该用〈亲口〉。亲口强调本人亲自用嘴说出；“自行”只说明不靠别人，不能替代这种亲口表达。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '718050bc-321d-406a-9188-a4a097c777a8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90598, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "故意", "is_correct": false, "explanation": "语义：“故意”表示有意去做，伤口无法有意恢复。"}, {"text": "自行", "is_correct": true, "explanation": "自行：不靠外力，自己慢慢恢复，符合伤口自愈的语境。"}, {"text": "偶尔", "is_correct": false, "explanation": "语义：“偶尔”表示间或发生，与“会恢复”这种持续的变化不符。"}, {"text": "业已", "is_correct": false, "explanation": "语域：“业已”是书面语，与这句口语化的叙述不协调。"}], "explanations": {"故意": "语义：“故意”表示有意去做，伤口无法有意恢复。", "自行": "自行：不靠外力，自己慢慢恢复，符合伤口自愈的语境。", "偶尔": "语义：“偶尔”表示间或发生，与“会恢复”这种持续的变化不符。", "业已": "语域：“业已”是书面语，与这句口语化的叙述不协调。"}, "sentence_index": 6, "correct_answer": "自行"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他自行一人住在山里。", "explanation": "这里应该用〈独自〉。独自强调单独一人，常与“一人”“一个人”搭配；“自行”不说“自行一人”。"}, {"text": "妈妈自行经历了那场大地震。", "explanation": "这里应该用〈亲身〉。亲身强调本人亲自经历；“自行”只说明不靠别人，不能用来说经历灾难这类事。"}, {"text": "这封信是他自行找人代写的。", "explanation": "这里应该用〈亲笔〉。亲笔强调本人亲手书写，多用于信件、字画；“自行找人代写”自相矛盾，“自行”表示不靠别人。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '718050bc-321d-406a-9188-a4a097c777a8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90598, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "请你自行的处理这件事。", "corrected_sentence": "请你自行处理这件事。", "error_description": "错误：“自行的处理”。正确：“自行处理”。“自行”是副词，直接修饰动词作状语，后面不加“的”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '718050bc-321d-406a-9188-a4a097c777a8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90598, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这次活动大家可以自行的报名。", "corrected_sentence": "这次活动大家可以自行报名。", "error_description": "错误：“自行的报名”。正确：“自行报名”。“自行”是副词，直接修饰动词作状语，后面不加“的”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '718050bc-321d-406a-9188-a4a097c777a8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
