INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90600, 1, 'prompt1_core', '{"pos": "副词", "semantic_class": "function", "definition": "（书面）没有门路；无从。", "primary_collocate": null, "pronunciation": "wú yóu", "ipa": "u˧˥ jou˧˥", "syllable_count": 2, "sentences": [{"text": "心中的苦闷，他无由向人诉说。", "target_word": "无由", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "想看望老师，却无由成行。", "target_word": "无由", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "两人分隔两地，相见无由。", "target_word": "无由", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "对于这件事的真相，大家无由得知。", "target_word": "无由", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他们搬走以后，我无由再见到他们。", "target_word": "无由", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "大雨封了山路，外人无由进入。", "target_word": "无由", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他没留联系方式，我想道谢也无由。", "target_word": "无由", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "知道朋友生病，可是路远，我无由探望。", "target_word": "无由", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "没有地址，信件无由寄出。", "target_word": "无由", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "年轻时家里很穷，想读书而无由入学。", "target_word": "无由", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "無由", "label": "繁体"}], "register": "书面", "sense_fingerprint": "无由-书面，没有门路，无从", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5ac86440-8f5a-4834-8135-427d86e72be0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90600, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "无由", "is_correct": true, "explanation": "无由：wú yóu，书面副词，表示没有门路、无从。"}, {"text": "无忧", "is_correct": false, "explanation": "yōu（第一声）与 yóu（第二声）声调不同，意思是没有忧愁。"}, {"text": "乌有", "is_correct": false, "explanation": "wū 与 wú 声调不同，yǒu（第三声）与 yóu（第二声）声调也不同，意思是不存在。"}, {"text": "无有", "is_correct": false, "explanation": "yǒu（第三声）与 yóu（第二声）声调不同，意思是没有。"}, {"text": "无友", "is_correct": false, "explanation": "yǒu（第三声）与 yóu（第二声）声调不同，意思是没有朋友。"}], "explanations": {"无由": "无由：wú yóu，书面副词，表示没有门路、无从。", "无忧": "yōu（第一声）与 yóu（第二声）声调不同，意思是没有忧愁。", "乌有": "wū 与 wú 声调不同，yǒu（第三声）与 yóu（第二声）声调也不同，意思是不存在。", "无有": "yǒu（第三声）与 yóu（第二声）声调不同，意思是没有。", "无友": "yǒu（第三声）与 yóu（第二声）声调不同，意思是没有朋友。"}, "sentence_index": null, "correct_answer": "无由"}, "level_3": {"options": [{"text": "无由", "is_correct": true, "explanation": "无由表示没有门路、无从，“苦闷”无处倾诉，与句意相符。"}, {"text": "而且", "is_correct": false, "explanation": "语法：“而且”是连词，不能作状语修饰“诉说”，此处不通。"}, {"text": "因为", "is_correct": false, "explanation": "语法：“因为”是连词，不能作状语修饰“诉说”，此处不通。"}, {"text": "欣然", "is_correct": false, "explanation": "语义：欣然表示高兴，与“苦闷”的情绪相反。"}], "explanations": {"无由": "无由表示没有门路、无从，“苦闷”无处倾诉，与句意相符。", "而且": "语法：“而且”是连词，不能作状语修饰“诉说”，此处不通。", "因为": "语法：“因为”是连词，不能作状语修饰“诉说”，此处不通。", "欣然": "语义：欣然表示高兴，与“苦闷”的情绪相反。"}, "sentence_index": 0, "correct_answer": "无由"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这件事很简单，我无由下手。", "explanation": "这里“无由”表示没有门路，与“很简单”矛盾。〈无从下手〉只用于事情复杂、不知从何着手。"}, {"text": "我们每天一起上课，却无由相识。", "explanation": "这里应该用〈无缘〉。两人天天同班，〈无由〉（没有门路）与此矛盾，应说〈无缘相识〉。"}, {"text": "这份资料就放在桌上，我却无由查看。", "explanation": "这里“无由”表示没有门路；资料就在桌上，有门路可查，应说〈可以〉查看，不能用〈无由〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '54d136a2-1535-496c-b74e-b1f72dabe9c2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90600, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "无由", "is_correct": true, "explanation": "无由表示没有门路，前句说没留联系方式，与句意相符。"}, {"text": "不必", "is_correct": false, "explanation": "语义：不必表示无须，与“我想道谢”的意愿相反。"}, {"text": "未必", "is_correct": false, "explanation": "语义：未必表示不一定，与“我想道谢”的明确意愿不符。"}, {"text": "不再", "is_correct": false, "explanation": "搭配：“不再”表示已经停止，与“我想道谢”的未发生的意愿不搭。"}], "explanations": {"无由": "无由表示没有门路，前句说没留联系方式，与句意相符。", "不必": "语义：不必表示无须，与“我想道谢”的意愿相反。", "未必": "语义：未必表示不一定，与“我想道谢”的明确意愿不符。", "不再": "搭配：“不再”表示已经停止，与“我想道谢”的未发生的意愿不搭。"}, "sentence_index": 6, "correct_answer": "无由"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他有很多办法，却无由可施。", "explanation": "这里“无由”表示没有门路，与“有很多办法”矛盾。应说〈无计可施〉。"}, {"text": "这道题很简单，我却无由解答。", "explanation": "这里应该用〈无法〉。前文说题目简单，〈无由〉表示没有门路，不能说“无由解答”。"}, {"text": "他身体很好，却无由下床。", "explanation": "这里应该用〈无力〉。前文说身体很好，〈无由〉（没有门路）不能表示身体无力。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '54d136a2-1535-496c-b74e-b1f72dabe9c2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90600, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "消息被封锁了，我无由的得知真相。", "corrected_sentence": "消息被封锁了，我无由得知真相。", "error_description": "“无由”是副词，后面不能加“的”修饰动词。“无由的得知”错误，应说“无由得知真相”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '54d136a2-1535-496c-b74e-b1f72dabe9c2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
