INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90603, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "不长的一段时间。", "primary_collocate": null, "pronunciation": "duǎn qī", "ipa": "tuan˨˩˦ tɕʰi˥˥", "syllable_count": 2, "sentences": [{"text": "这是一份短期工作。", "target_word": "短期", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "短期内，这里的天气不会变。", "target_word": "短期", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他报了一个短期课程。", "target_word": "短期", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个短期计划只有两周。", "target_word": "短期", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "短期来看，价格不会涨。", "target_word": "短期", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我只想找短期的工作，不想长期做。", "target_word": "短期", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她参加了一个短期的汉语班。", "target_word": "短期", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这次是短期旅行，下周就回家。", "target_word": "短期", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我短期内不打算买新车。", "target_word": "短期", "complexity_tier": "T3", "furigana": "duǎn qī", "sentence_source": "generated"}, {"text": "这笔钱只是短期借用，下个月还你。", "target_word": "短期", "complexity_tier": "T3", "furigana": "duǎn qī", "sentence_source": "generated"}], "morphological_forms": [{"form": "短期内", "label": "复合"}, {"form": "短期计划", "label": "复合"}], "register": "中性", "sense_fingerprint": "短期：不长的一段时间，与长期相对", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd3f4d125-09bd-4a29-83b8-15c3ccd853c7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90603, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "短期", "is_correct": true, "explanation": "正确：duǎn qī 指不长的一段时间。"}, {"text": "断气", "is_correct": false, "explanation": "duàn（第四声）与 duǎn（第三声）声调不同，qì 与 qī 声调也不同，意思是停止呼吸。"}, {"text": "远期", "is_correct": false, "explanation": "yuǎn 与 duǎn 声母不同（y 与 d），意思是遥远的将来。"}, {"text": "缓期", "is_correct": false, "explanation": "huǎn 与 duǎn 声母不同（h 与 d），意思是推迟、延后的时期。"}], "explanations": {"短期": "正确：duǎn qī 指不长的一段时间。", "断气": "duàn（第四声）与 duǎn（第三声）声调不同，qì 与 qī 声调也不同，意思是停止呼吸。", "远期": "yuǎn 与 duǎn 声母不同（y 与 d），意思是遥远的将来。", "缓期": "huǎn 与 duǎn 声母不同（h 与 d），意思是推迟、延后的时期。"}, "sentence_index": null, "correct_answer": "短期"}, "level_3": {"options": [{"text": "短期", "is_correct": true, "explanation": "正确：短期修饰“工作”，指时间较短的工作。"}, {"text": "石头", "is_correct": false, "explanation": "语义：石头不是工作的性质，“这是一份石头工作”说不通。"}, {"text": "春天", "is_correct": false, "explanation": "语义：春天是季节，不能用来描述工作，句子说不通。"}, {"text": "红色", "is_correct": false, "explanation": "搭配：“红色”不能修饰“工作”，应说红色的东西，不说红色工作。"}], "explanations": {"短期": "正确：短期修饰“工作”，指时间较短的工作。", "石头": "语义：石头不是工作的性质，“这是一份石头工作”说不通。", "春天": "语义：春天是季节，不能用来描述工作，句子说不通。", "红色": "搭配：“红色”不能修饰“工作”，应说红色的东西，不说红色工作。"}, "sentence_index": 0, "correct_answer": "短期"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这是一个短期的瞬间，转眼就过去了。", "explanation": "这里应该用〈短暂〉。短期指一段时间，不能用来修饰一瞬间。"}, {"text": "她给了我一个短期的笑容，很快就消失了。", "explanation": "这里应该用〈短暂〉。短期修饰时间段，不用来形容笑容这类瞬间。"}, {"text": "这个短期的习惯已经坚持了十年。", "explanation": "这里应该用〈长期〉。短期指时间短，与“坚持了十年”矛盾；持续很久要用长期。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '884bc76d-2bca-4740-b392-561903b984d1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90603, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "短期", "is_correct": true, "explanation": "正确：短期修饰“汉语班”，指时间较短的班，句子通顺。"}, {"text": "钢铁", "is_correct": false, "explanation": "语义：钢铁不能修饰班级，“钢铁的汉语班”说不通。"}, {"text": "木头", "is_correct": false, "explanation": "语义：木头不能修饰班级，句子说不通。"}, {"text": "冰箱", "is_correct": false, "explanation": "搭配：“冰箱”不能用来修饰“汉语班”，搭配不当。"}], "explanations": {"短期": "正确：短期修饰“汉语班”，指时间较短的班，句子通顺。", "钢铁": "语义：钢铁不能修饰班级，“钢铁的汉语班”说不通。", "木头": "语义：木头不能修饰班级，句子说不通。", "冰箱": "搭配：“冰箱”不能用来修饰“汉语班”，搭配不当。"}, "sentence_index": 6, "correct_answer": "短期"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他找到一根短期的木棍，正好拿来撑衣服。", "explanation": "这里应该用〈短〉。短期只指时间，不用来形容木棍的长短。"}, {"text": "这条短期的河很浅，船开不进去。", "explanation": "这里应该用〈长〉。短期只指时间，不指河流的长度。"}, {"text": "这块短期的布做不成一件衣服。", "explanation": "这里应该用〈短〉。短期只指时间，不用来描述布料的长短。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '884bc76d-2bca-4740-b392-561903b984d1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90603, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "她找了一份短期内工作。", "corrected_sentence": "她找了一份短期工作。", "error_description": "错误：「短期内工作」；正确：「短期工作」。「短期内」表示时间范围，作状语；作定语修饰「工作」要说「短期工作」，去掉「内」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '884bc76d-2bca-4740-b392-561903b984d1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90603, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我很短期内买了一台新电脑。", "corrected_sentence": "我在短期内买了一台新电脑。", "error_description": "错误：“很”不能修饰时间状语“短期内”；应改为介词“在”，“在短期内”表示时间范围。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '884bc76d-2bca-4740-b392-561903b984d1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90604, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "长期", "is_correct": true, "explanation": "长期与“短期”互为反义词，指较长的一段时间，与较短的一段时间相对。"}, {"text": "灯泡", "is_correct": false, "explanation": "灯泡与“短期”没有反义关系，是不同类的名词。"}, {"text": "公园", "is_correct": false, "explanation": "公园与“短期”没有反义关系，不是时间概念。"}, {"text": "雨伞", "is_correct": false, "explanation": "雨伞与“短期”没有反义关系，不在同一语义范围内。"}], "correct_answer": "长期", "explanations": {"长期": "长期与“短期”互为反义词，指较长的一段时间，与较短的一段时间相对。", "灯泡": "灯泡与“短期”没有反义关系，是不同类的名词。", "公园": "公园与“短期”没有反义关系，不是时间概念。", "雨伞": "雨伞与“短期”没有反义关系，不在同一语义范围内。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '884bc76d-2bca-4740-b392-561903b984d1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
