INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90604, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "较短的一段时间。", "primary_collocate": null, "pronunciation": "duǎn qī", "ipa": "tuan˨˩˦ tɕʰi˥˥", "syllable_count": 2, "sentences": [{"text": "短期内他不会回国，因为工作很忙。", "target_word": "短期", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "公司的短期目标是多卖一百台。", "target_word": "短期", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这种药短期吃没问题，长期吃不好。", "target_word": "短期", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "短期的困难很快就会过去。", "target_word": "短期", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他在短期内学会了游泳。", "target_word": "短期", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们先做短期安排，以后再说。", "target_word": "短期", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "短期贷款一年以内就要还。", "target_word": "短期", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这家店只做短期出租，最长三个月。", "target_word": "短期", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "短期看，天气会一直很热。", "target_word": "短期", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他的短期计划是先把工作找到。", "target_word": "短期", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "短期内", "label": "复合"}, {"form": "短期目标", "label": "复合"}], "register": "中性", "sense_fingerprint": "短期：较短的一段时间，常与长期对比", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd3f4d125-09bd-4a29-83b8-15c3ccd853c7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90604, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "短期", "is_correct": true, "explanation": "正确：duǎn qī 指较短的一段时间。"}, {"text": "断气", "is_correct": false, "explanation": "duàn（第四声）与 duǎn（第三声）声调不同，qì 与 qī 声调也不同，意思是停止呼吸。"}, {"text": "远期", "is_correct": false, "explanation": "yuǎn 与 duǎn 声母不同（y 与 d），意思是遥远的将来。"}, {"text": "缓期", "is_correct": false, "explanation": "huǎn 与 duǎn 声母不同（h 与 d），意思是推迟、延后的时期。"}], "explanations": {"短期": "正确：duǎn qī 指较短的一段时间。", "断气": "duàn（第四声）与 duǎn（第三声）声调不同，qì 与 qī 声调也不同，意思是停止呼吸。", "远期": "yuǎn 与 duǎn 声母不同（y 与 d），意思是遥远的将来。", "缓期": "huǎn 与 duǎn 声母不同（h 与 d），意思是推迟、延后的时期。"}, "sentence_index": null, "correct_answer": "短期"}, "level_3": {"options": [{"text": "短期", "is_correct": true, "explanation": "正确：“短期内”指较短的时间之内，符合句意。"}, {"text": "厨房", "is_correct": false, "explanation": "语义：厨房是地点，不能表示时间范围，“厨房内他不会回国”说不通。"}, {"text": "书桌", "is_correct": false, "explanation": "语义：书桌是地点，不能表示时间范围，句子说不通。"}, {"text": "中国", "is_correct": false, "explanation": "搭配：“中国内”不是常用说法，且“中国内他不会回国”语义别扭，不能填入。"}], "explanations": {"短期": "正确：“短期内”指较短的时间之内，符合句意。", "厨房": "语义：厨房是地点，不能表示时间范围，“厨房内他不会回国”说不通。", "书桌": "语义：书桌是地点，不能表示时间范围，句子说不通。", "中国": "搭配：“中国内”不是常用说法，且“中国内他不会回国”语义别扭，不能填入。"}, "sentence_index": 0, "correct_answer": "短期"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这首歌的短期很长，听了半个小时还没结束。", "explanation": "这里应该用〈时长〉。短期指较短的一段时间，不能用“很长”修饰；说歌曲长度要用时长。"}, {"text": "这只乌龟的短期很长，已经活了一百年。", "explanation": "这里应该用〈寿命〉。短期指较短的一段时间，不能用“很长”修饰，也不用来指生物的寿命。"}, {"text": "这块石头的短期是一万年。", "explanation": "这里应该用〈年龄〉。短期指不长的一段时间，不用来说事物的年龄。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '884bc76d-2bca-4740-b392-561903b984d1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90604, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "短期", "is_correct": true, "explanation": "正确：短期修饰“贷款”，指一年以内的短期借款，符合句意。"}, {"text": "白云", "is_correct": false, "explanation": "语义：白云不能修饰贷款，“白云贷款”说不通。"}, {"text": "木头", "is_correct": false, "explanation": "语义：木头不能修饰贷款，句子说不通。"}, {"text": "早饭", "is_correct": false, "explanation": "搭配：“贷款”不能用早饭来修饰，搭配不当。"}], "explanations": {"短期": "正确：短期修饰“贷款”，指一年以内的短期借款，符合句意。", "白云": "语义：白云不能修饰贷款，“白云贷款”说不通。", "木头": "语义：木头不能修饰贷款，句子说不通。", "早饭": "搭配：“贷款”不能用早饭来修饰，搭配不当。"}, "sentence_index": 6, "correct_answer": "短期"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这根木棍的短期刚好能撑起衣服。", "explanation": "这里应该用〈短〉。短期指时间，不用来形容木棍的长短。"}, {"text": "这块布的短期不够做一件衣服。", "explanation": "这里应该用〈短〉。短期只指时间，不用来形容布料的长短。"}, {"text": "这条河的短期太短，船开不进去。", "explanation": "这里应该用〈长度〉。短期只指时间，不指河流的长度。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '884bc76d-2bca-4740-b392-561903b984d1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90604, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他短期内的学会了开车。", "corrected_sentence": "他短期内学会了开车。", "error_description": "错误：「短期内的学会」；正确：「短期内学会」。「短期内」是时间状语，后面直接接动词，不加「的」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '884bc76d-2bca-4740-b392-561903b984d1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90604, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这家店很短期内就关门了。", "corrected_sentence": "这家店短期内就关门了。", "error_description": "错误：“很”不能修饰时间状语“短期内”；去掉“很”即可，“短期内”直接修饰后面的动词短语。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '884bc76d-2bca-4740-b392-561903b984d1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
