INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90609, 1, 'prompt1_core', '{"pos": "副词", "semantic_class": "function", "definition": "想不到会这样，让人吃惊。", "primary_collocate": null, "pronunciation": "jìng", "ipa": "tɕiŋ˥˩", "syllable_count": 1, "sentences": [{"text": "这么简单的题，他竟不会做。", "target_word": "竟", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我等了半天，他竟没来。", "target_word": "竟", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小孩子竟会说三种语言。", "target_word": "竟", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "那家店看着很小，竟有一百多种茶。", "target_word": "竟", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他平时很安静，今天竟大声唱歌了。", "target_word": "竟", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "昨天还下雪，今天竟热起来了。", "target_word": "竟", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我找了一个早上，钥匙竟在自己手里。", "target_word": "竟", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这么大的雨，她竟一个人走回家。", "target_word": "竟", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他学了一年中文，竟能看懂报纸。", "target_word": "竟", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师竟记得我三年前说过的话。", "target_word": "竟", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "竟然", "label": "复合词"}, {"form": "究竟", "label": "复合词"}], "register": "中性", "sense_fingerprint": "副词，表示结果出乎意料，让人吃惊", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5ac86440-8f5a-4834-8135-427d86e72be0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90609, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "竟", "is_correct": true, "explanation": "竟（jìng），本题目标词，表示想不到会这样。"}, {"text": "经", "is_correct": false, "explanation": "jīng（第一声）与 jìng（第四声）声调不同，意思是经过。"}, {"text": "进", "is_correct": false, "explanation": "jìn 与 jìng 韵尾不同（-n 与 -ng），意思是进入。"}, {"text": "警", "is_correct": false, "explanation": "jǐng（第三声）与 jìng（第四声）声调不同，意思是警察。"}, {"text": "庆", "is_correct": false, "explanation": "qìng 与 jìng 声母不同（q 与 j），意思是庆祝。"}], "explanations": {"竟": "竟（jìng），本题目标词，表示想不到会这样。", "经": "jīng（第一声）与 jìng（第四声）声调不同，意思是经过。", "进": "jìn 与 jìng 韵尾不同（-n 与 -ng），意思是进入。", "警": "jǐng（第三声）与 jìng（第四声）声调不同，意思是警察。", "庆": "qìng 与 jìng 声母不同（q 与 j），意思是庆祝。"}, "sentence_index": null, "correct_answer": "竟"}, "level_3": {"options": [{"text": "竟", "is_correct": true, "explanation": "正确：「竟」表示想不到他不会做，与「这么简单」形成对比。"}, {"text": "马上", "is_correct": false, "explanation": "语义：「马上」表示立即或即将，与「这么简单的题」所作的能力判断无关，句意不通。"}, {"text": "正在", "is_correct": false, "explanation": "语法：“正在”表示进行中，不能与“不会做”这一状态搭配，此处不通。"}, {"text": "刚刚", "is_correct": false, "explanation": "语义：“刚刚”表示时间刚过，与“这么简单的题”所作的能力判断不相合。"}], "explanations": {"竟": "正确：「竟」表示想不到他不会做，与「这么简单」形成对比。", "马上": "语义：「马上」表示立即或即将，与「这么简单的题」所作的能力判断无关，句意不通。", "正在": "语法：“正在”表示进行中，不能与“不会做”这一状态搭配，此处不通。", "刚刚": "语义：“刚刚”表示时间刚过，与“这么简单的题”所作的能力判断不相合。"}, "sentence_index": 0, "correct_answer": "竟"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "天气预报说今天会下雨，竟下雨了。", "explanation": "这里应该用〈果然〉。竟表示出乎意料，而天气预报已经预告会下雨，结果在意料之中，不该用竟。"}, {"text": "他是中国人，竟会说中文。", "explanation": "这里应该用〈当然〉。竟表示出乎意料，而中国人会说中文是理所当然的事，不值得吃惊，不该用竟。"}, {"text": "两加二竟等于四。", "explanation": "这里应该用〈本来〉。竟表示出乎意料，而两加二等于四是本来如此的常识，说不上出乎意料。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '54d136a2-1535-496c-b74e-b1f72dabe9c2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90609, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "竟", "is_correct": true, "explanation": "竟（jìng），本题目标词，表示想不到会这样。"}, {"text": "近", "is_correct": false, "explanation": "jìn 与 jìng 韵尾不同（-n 与 -ng），意思是靠近。"}, {"text": "景", "is_correct": false, "explanation": "jǐng（第三声）与 jìng（第四声）声调不同，意思是风景。"}, {"text": "精", "is_correct": false, "explanation": "jīng（第一声）与 jìng（第四声）声调不同，意思是精细。"}, {"text": "性", "is_correct": false, "explanation": "xìng 与 jìng 声母不同（x 与 j），意思是性格。"}], "explanations": {"竟": "竟（jìng），本题目标词，表示想不到会这样。", "近": "jìn 与 jìng 韵尾不同（-n 与 -ng），意思是靠近。", "景": "jǐng（第三声）与 jìng（第四声）声调不同，意思是风景。", "精": "jīng（第一声）与 jìng（第四声）声调不同，意思是精细。", "性": "xìng 与 jìng 声母不同（x 与 j），意思是性格。"}, "sentence_index": null, "correct_answer": "竟"}, "level_3": {"options": [{"text": "竟", "is_correct": true, "explanation": "正确：「竟」表示想不到钥匙会在自己手里，与「找了一个早上」形成对比。"}, {"text": "将", "is_correct": false, "explanation": "语域：「将」是书面语，且表示将来，与前面「找了一个早上」的过去相矛盾。"}, {"text": "立刻", "is_correct": false, "explanation": "语义：「立刻」表示马上，与「找了一个早上」的漫长过程矛盾。"}, {"text": "刚刚", "is_correct": false, "explanation": "语义：「刚刚」指刚才，与「找了一个早上」的时间跨度冲突。"}], "explanations": {"竟": "正确：「竟」表示想不到钥匙会在自己手里，与「找了一个早上」形成对比。", "将": "语域：「将」是书面语，且表示将来，与前面「找了一个早上」的过去相矛盾。", "立刻": "语义：「立刻」表示马上，与「找了一个早上」的漫长过程矛盾。", "刚刚": "语义：「刚刚」指刚才，与「找了一个早上」的时间跨度冲突。"}, "sentence_index": 6, "correct_answer": "竟"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这门课他从不复习，成绩竟不好。", "explanation": "这里应该用〈必然〉。竟表示出乎意料，而不复习就考不好是必然的结果，不会让人吃惊。"}, {"text": "春天到了，天气竟会变暖。", "explanation": "这里应该用〈自然〉。竟表示出乎意料，而春天变暖是常理，不值得吃惊。"}, {"text": "这家店每天九点开门，竟是老规矩。", "explanation": "这里应该用〈照常〉。竟表示出乎意料，而店铺每天九点开门是照常营业，不值得吃惊，不该用竟。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '54d136a2-1535-496c-b74e-b1f72dabe9c2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90609, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这么晚了，竟他还在公司加班。", "corrected_sentence": "这么晚了，他竟还在公司加班。", "error_description": "「竟」位置错误：副词「竟」应放在主语「他」之后、「还在」之前，写成「竟他」不成立，正确的是「他竟还在公司加班」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '54d136a2-1535-496c-b74e-b1f72dabe9c2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90609, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这么热的天，他还竟穿着棉袄。", "corrected_sentence": "这么热的天，他竟还穿着棉袄。", "error_description": "「竟」位置错误：「竟」应紧接在主语「他」之后，不能放在「还」之后，正确的是「他竟还穿着棉袄」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '54d136a2-1535-496c-b74e-b1f72dabe9c2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90611, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "富裕", "is_correct": true, "explanation": "富裕与贫困互为反义，指家境或生活宽裕、钱财充足。"}, {"text": "繁华", "is_correct": false, "explanation": "繁华形容城市或地方热闹兴旺，与“贫困”不构成反义关系。"}, {"text": "宽敞", "is_correct": false, "explanation": "宽敞形容空间大，与“贫困”不构成反义关系。"}, {"text": "辽阔", "is_correct": false, "explanation": "辽阔形容土地或空间广阔，与“贫困”不构成反义关系。"}], "correct_answer": "富裕", "explanations": {"富裕": "富裕与贫困互为反义，指家境或生活宽裕、钱财充足。", "繁华": "繁华形容城市或地方热闹兴旺，与“贫困”不构成反义关系。", "宽敞": "宽敞形容空间大，与“贫困”不构成反义关系。", "辽阔": "辽阔形容土地或空间广阔，与“贫困”不构成反义关系。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '77fea57d-2c72-4f76-b2b2-2be0aacd67c3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
