INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90611, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "贫困是很穷，没有钱买吃的和穿的。", "primary_collocate": null, "pronunciation": "pín kùn", "ipa": "pʰin˧˥ kʰuən˥˩", "syllable_count": 2, "sentences": [{"text": "他小时候家里很贫困，常常吃不饱。", "target_word": "贫困", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "那家人太贫困了，冬天连厚衣服都没有。", "target_word": "贫困", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她出生在一个贫困的家庭，从小没吃过肉。", "target_word": "贫困", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "因为家里贫困，孩子穿的都是旧衣服。", "target_word": "贫困", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "爷爷年轻时生活贫困，一天只吃一顿饭。", "target_word": "贫困", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们一家过得很贫困，连米饭都吃不起。", "target_word": "贫困", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个孩子很贫困，没有钱买新鞋。", "target_word": "贫困", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "虽然他很贫困，但是每天都笑着生活。", "target_word": "贫困", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老人贫困得连饭也吃不上。", "target_word": "贫困", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "在贫困的日子里，母亲给我们缝旧衣服。", "target_word": "贫困", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "貧困", "label": "繁体"}, {"form": "贫困户", "label": "复合"}, {"form": "贫困生", "label": "复合"}], "register": "中性", "sense_fingerprint": "个人或家庭很穷，吃穿都买不起", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '897c13e4-9594-468f-af81-93c04019cc00') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90611, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "贫困", "is_correct": true, "explanation": "贫困：形容家境穷，与后句“常常吃不饱”一致。"}, {"text": "富裕", "is_correct": false, "explanation": "语义：“富裕”指家境宽裕，与后句“常常吃不饱”矛盾。"}, {"text": "年轻", "is_correct": false, "explanation": "搭配：“年轻”形容人，不能用来形容“家里”。"}, {"text": "健壮", "is_correct": false, "explanation": "搭配：“健壮”形容人的体格，不能用来形容“家里”。"}], "explanations": {"贫困": "贫困：形容家境穷，与后句“常常吃不饱”一致。", "富裕": "语义：“富裕”指家境宽裕，与后句“常常吃不饱”矛盾。", "年轻": "搭配：“年轻”形容人，不能用来形容“家里”。", "健壮": "搭配：“健壮”形容人的体格，不能用来形容“家里”。"}, "sentence_index": 0, "correct_answer": "贫困"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他的词汇很贫困，连简单的句子都说不好。", "explanation": "这里应该用〈贫乏〉。贫困指人或家庭缺钱财物资，形容词汇、知识不足要用〈贫乏〉。"}, {"text": "他的演讲很贫困，听众都觉得没意思。", "explanation": "这里应该用〈空洞〉。贫困指物质缺乏，形容讲话没有实际内容要用〈空洞〉。"}, {"text": "这道数学题很贫困，我想了一个小时也没做出来。", "explanation": "这里应该用〈困难〉。贫困指生活缺钱财物资，形容题目难要用〈困难〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '77fea57d-2c72-4f76-b2b2-2be0aacd67c3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90611, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "贫困", "is_correct": true, "explanation": "贫困：形容这个孩子家境穷，与“没有钱买新鞋”一致。"}, {"text": "富有", "is_correct": false, "explanation": "语义：“富有”指钱财多，与“没有钱买新鞋”矛盾。"}, {"text": "老练", "is_correct": false, "explanation": "搭配：“老练”形容人办事有经验，不用来形容孩子。"}, {"text": "硬朗", "is_correct": false, "explanation": "搭配：“硬朗”多形容老人身体强健，不用来描述孩子的家境。"}], "explanations": {"贫困": "贫困：形容这个孩子家境穷，与“没有钱买新鞋”一致。", "富有": "语义：“富有”指钱财多，与“没有钱买新鞋”矛盾。", "老练": "搭配：“老练”形容人办事有经验，不用来形容孩子。", "硬朗": "搭配：“硬朗”多形容老人身体强健，不用来描述孩子的家境。"}, "sentence_index": 6, "correct_answer": "贫困"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他们的训练很贫困，每天都要跑十公里。", "explanation": "这里应该用〈艰苦〉。贫困形容生活缺钱财，训练的辛苦要用〈艰苦〉。"}, {"text": "他的英语基础很贫困，还需要多练习。", "explanation": "这里应该用〈薄弱〉。贫困说的是生活物资，基础不牢要用〈薄弱〉。"}, {"text": "这首歌的旋律很贫困，听了几遍就腻了。", "explanation": "这里应该用〈单调〉。贫困不能形容旋律，变化少要用〈单调〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '77fea57d-2c72-4f76-b2b2-2be0aacd67c3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90611, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "那个老人贫困地连米都买不起。", "corrected_sentence": "那个老人贫困得连米都买不起。", "error_description": "“地”用错：表示程度的补语要用“得”，应写作“贫困得连米都买不起”，不能用“地”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '77fea57d-2c72-4f76-b2b2-2be0aacd67c3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90611, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这是一个贫困得地区。", "corrected_sentence": "这是一个贫困的地区。", "error_description": "“得”用错：修饰名词“地区”要用“的”，应写作“一个贫困的地区”，不能用“得”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '77fea57d-2c72-4f76-b2b2-2be0aacd67c3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
