INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90615, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "管着一个地方或一些东西的人。", "primary_collocate": null, "pronunciation": "guǎn lǐ rén", "ipa": "kwan˨˩˦ li˨˩˦ ʐən˧˥", "syllable_count": 3, "sentences": [{"text": "公园的管理人每天早上打开大门。", "target_word": "管理人", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "仓库的管理人把钥匙交给了我。", "target_word": "管理人", "complexity_tier": "T3", "furigana": "cāngkù de guǎnlǐrén bǎ yào shi jiāo gěi le wǒ.", "sentence_source": "generated"}, {"text": "这栋楼的管理人住在一楼。", "target_word": "管理人", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请去问图书室的管理人。", "target_word": "管理人", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "停车场的管理人正在门口收费。", "target_word": "管理人", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个小区的管理人很熟悉每一位住户。", "target_word": "管理人", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "管理人把花园的门锁好了。", "target_word": "管理人", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他在山上的小庙里做管理人。", "target_word": "管理人", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老张是这个果园的管理人。", "target_word": "管理人", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "游泳馆的管理人提醒大家不要跑。", "target_word": "管理人", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "位", "label": "量词"}, {"form": "管理人员", "label": "复合"}], "register": "中性", "sense_fingerprint": "看管公园、仓库、楼房等场所或物品的人", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5cea4ba9-e5df-4d1b-8c6e-7471ef55d20e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90615, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "管理人", "is_correct": true, "explanation": "正确。管理人指看管场所的人，每天早上开公园大门的正是管理人。"}, {"text": "歌手", "is_correct": false, "explanation": "语义：「歌手」指唱歌的人，与「开公园的大门」毫无关系。"}, {"text": "司机", "is_correct": false, "explanation": "搭配：「司机」常与「开车」搭配，不能与「打开大门」搭配。"}, {"text": "厨师", "is_correct": false, "explanation": "语义：「厨师」指做饭的人，与公园的大门不相干，句子说不通。"}], "explanations": {"管理人": "正确。管理人指看管场所的人，每天早上开公园大门的正是管理人。", "歌手": "语义：「歌手」指唱歌的人，与「开公园的大门」毫无关系。", "司机": "搭配：「司机」常与「开车」搭配，不能与「打开大门」搭配。", "厨师": "语义：「厨师」指做饭的人，与公园的大门不相干，句子说不通。"}, "sentence_index": 0, "correct_answer": "管理人"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "售票处的一只管理人正在门口收费。", "explanation": "这里量词用错。管理人指人，可用〈位〉或〈个〉，不能用〈只〉（〈只〉多用于动物或单个物品）。"}, {"text": "我们小区的一条管理人很热心。", "explanation": "这里量词用错。管理人指人，可用〈位〉或〈个〉，不能用〈条〉（〈条〉多用于长条形的东西）。"}, {"text": "我们学校的一台管理人负责锁门。", "explanation": "这里量词用错。管理人指人，可用〈位〉或〈个〉，不能用〈台〉（〈台〉多用于机器、设备）。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '17403514-88bd-43ce-bf3d-11fb4f8b017e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90615, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "管理人", "is_correct": true, "explanation": "正确。管理人指看管场所的人，把花园的门锁好的是管理人。"}, {"text": "作家", "is_correct": false, "explanation": "语义：「作家」指写作的人，与「锁花园的门」无关，句子说不通。"}, {"text": "演员", "is_correct": false, "explanation": "语义：「演员」指表演的人，与锁门的动作不相干。"}, {"text": "医生", "is_correct": false, "explanation": "搭配：「医生」多与「治病」「看病」搭配，不能与「锁门」搭配。"}], "explanations": {"管理人": "正确。管理人指看管场所的人，把花园的门锁好的是管理人。", "作家": "语义：「作家」指写作的人，与「锁花园的门」无关，句子说不通。", "演员": "语义：「演员」指表演的人，与锁门的动作不相干。", "医生": "搭配：「医生」多与「治病」「看病」搭配，不能与「锁门」搭配。"}, "sentence_index": 6, "correct_answer": "管理人"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这座体育馆的管理人正在唱歌。", "explanation": "这里应该用〈歌手〉。管理人指看管场所或物品的人，唱歌的是〈歌手〉。"}, {"text": "这家医院的管理人负责给病人打针。", "explanation": "这里应该用〈护士〉。管理人指看管场所或物品的人，给病人打针的是〈护士〉。"}, {"text": "这间教室的管理人正在给学生上课。", "explanation": "这里应该用〈老师〉。管理人指看管场所或物品的人，给学生上课的是〈老师〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '17403514-88bd-43ce-bf3d-11fb4f8b017e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90615, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "宿舍来了一只新的管理人。", "corrected_sentence": "宿舍来了一位新的管理人。", "error_description": "量词错误：指人的「管理人」可用量词「位」或「个」，不能用「只」。错句中的「一只」应改为「一位」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '17403514-88bd-43ce-bf3d-11fb4f8b017e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90615, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "公园里新来了一位的管理人。", "corrected_sentence": "公园里新来了一位管理人。", "error_description": "结构助词错误：数量短语「一位」修饰名词时不加「的」，应写作「一位管理人」，错句中多出的「的」应删去。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '17403514-88bd-43ce-bf3d-11fb4f8b017e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
