INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90616, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "负责管理某事物的人。", "primary_collocate": null, "pronunciation": "guǎn lǐ rén", "ipa": "kwan˨˩˦ li˨˩˦ ʐən˧˥", "syllable_count": 3, "sentences": [{"text": "他是这笔钱的管理人。", "target_word": "管理人", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "爷爷去世后，哥哥成了房子的管理人。", "target_word": "管理人", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "公司请了一位新的管理人。", "target_word": "管理人", "complexity_tier": "T3", "furigana": "gōngsī qǐng le yí wèi xīn de guǎnlǐrén.", "sentence_source": "generated"}, {"text": "这笔遗产的管理人还没有确定。", "target_word": "管理人", "complexity_tier": "T3", "furigana": "zhè bǐ yíchǎn de guǎnlǐrén hái méiyǒu quèdìng.", "sentence_source": "generated"}, {"text": "谁是这个项目的管理人？", "target_word": "管理人", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "管理人每个月都会检查账目。", "target_word": "管理人", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他当过这家银行的管理人。", "target_word": "管理人", "complexity_tier": "T3", "furigana": "tā dāng guò zhè jiā yínháng de guǎnlǐrén.", "sentence_source": "generated"}, {"text": "管理人要对大家的钱负责。", "target_word": "管理人", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这笔基金的管理人是王老师。", "target_word": "管理人", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这些财产的管理人是她。", "target_word": "管理人", "complexity_tier": "T3", "furigana": "zhè xiē cáichǎn de guǎnlǐrén shì tā.", "sentence_source": "generated"}], "morphological_forms": [{"form": "位", "label": "量词"}, {"form": "管理人员", "label": "复合"}], "register": "中性", "sense_fingerprint": "负责管理钱财、房产、项目等事务的人", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5cea4ba9-e5df-4d1b-8c6e-7471ef55d20e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90616, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "管理人", "is_correct": true, "explanation": "正确。管理人指负责管理钱财、房产等事务的人，与「这笔钱」相符。"}, {"text": "作者", "is_correct": false, "explanation": "语义：「作者」指写作、创作作品的人，「这笔钱」不是作品，不能说「这笔钱的作者」。"}, {"text": "厨师", "is_correct": false, "explanation": "语义：「厨师」指做饭的人，与「这笔钱」毫无关系，句子说不通。"}, {"text": "司机", "is_correct": false, "explanation": "搭配：「司机」常与「开车」搭配，不能与「这笔钱」搭配。"}], "explanations": {"管理人": "正确。管理人指负责管理钱财、房产等事务的人，与「这笔钱」相符。", "作者": "语义：「作者」指写作、创作作品的人，「这笔钱」不是作品，不能说「这笔钱的作者」。", "厨师": "语义：「厨师」指做饭的人，与「这笔钱」毫无关系，句子说不通。", "司机": "搭配：「司机」常与「开车」搭配，不能与「这笔钱」搭配。"}, "sentence_index": 0, "correct_answer": "管理人"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这台晚会的管理人正在台上唱歌。", "explanation": "这里应该用〈歌手〉。管理人指负责管理钱财、房产等事务的人，台上唱歌的是〈歌手〉，与「管理」无关。"}, {"text": "这次旅行的管理人正在修理汽车。", "explanation": "这里应该用〈修理工〉。管理人指负责管理钱财、房产等事务的人，修理汽车的是〈修理工〉，与「管理」无关。"}, {"text": "这场婚礼的管理人正在弹钢琴。", "explanation": "这里应该用〈钢琴师〉。管理人指负责管理钱财、房产等事务的人，弹钢琴的是〈钢琴师〉，与「管理」无关。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '17403514-88bd-43ce-bf3d-11fb4f8b017e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90616, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "管理人", "is_correct": true, "explanation": "正确。「当过」后接的是负责管理钱财的职务，「管理人」与「这家银行」相符。"}, {"text": "学生", "is_correct": false, "explanation": "语义：「学生」指学习的人，银行不是学校，「这家银行的学生」说不通。"}, {"text": "病人", "is_correct": false, "explanation": "搭配：「当过」后接的是职业或职务，「病人」不是职务，不能说「当过……的病人」。"}, {"text": "乘客", "is_correct": false, "explanation": "语义：「乘客」指乘坐交通工具的人，与「银行」无关，句子不通。"}], "explanations": {"管理人": "正确。「当过」后接的是负责管理钱财的职务，「管理人」与「这家银行」相符。", "学生": "语义：「学生」指学习的人，银行不是学校，「这家银行的学生」说不通。", "病人": "搭配：「当过」后接的是职业或职务，「病人」不是职务，不能说「当过……的病人」。", "乘客": "语义：「乘客」指乘坐交通工具的人，与「银行」无关，句子不通。"}, "sentence_index": 6, "correct_answer": "管理人"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这些财产的一只管理人是她。", "explanation": "这里量词用错。管理人指人，可用〈位〉或〈个〉，不能用〈只〉（〈只〉多用于动物或单个物品）。"}, {"text": "一条管理人帮我们看管了这些财产。", "explanation": "这里量词用错。管理人指人，可用〈位〉或〈个〉，不能用〈条〉（〈条〉多用于长条形的东西）。"}, {"text": "我请了一台管理人来处理这些财产。", "explanation": "这里量词用错。管理人指人，可用〈位〉或〈个〉，不能用〈台〉（〈台〉多用于机器、设备）。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '17403514-88bd-43ce-bf3d-11fb4f8b017e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90616, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "法院为这笔遗产指定了一只新的管理人。", "corrected_sentence": "法院为这笔遗产指定了一位新的管理人。", "error_description": "量词错误：指人的「管理人」可用量词「位」或「个」，不能用「只」。错句中的「一只」应改为「一位」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '17403514-88bd-43ce-bf3d-11fb4f8b017e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90616, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这笔房产的一件管理人是律师。", "corrected_sentence": "这笔房产的一位管理人是律师。", "error_description": "量词错误：指人的「管理人」可用量词「位」或「个」，不能用「件」。错句中的「一件」应改为「一位」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '17403514-88bd-43ce-bf3d-11fb4f8b017e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
