INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90622, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "机构中的工作岗位及其地位。", "primary_collocate": null, "pronunciation": "zhí wèi", "ipa": "ʈʂɨ˧˥ wei˥˩", "syllable_count": 2, "sentences": [{"text": "他在政府里有重要的职位。", "target_word": "职位", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "校长的职位很重要。", "target_word": "职位", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他靠努力得到了现在的职位。", "target_word": "职位", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "医院里这个职位需要有经验的人。", "target_word": "职位", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他的职位不高，但很受尊敬。", "target_word": "职位", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这所大学有一个空着的职位。", "target_word": "职位", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他离开了军队，放弃了原来的职位。", "target_word": "职位", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她在学校的职位是老师。", "target_word": "职位", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "市长这个职位责任很大。", "target_word": "职位", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他想用关系得到一个更高的职位。", "target_word": "职位", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "个", "label": "量词"}, {"form": "職位", "label": "繁体"}], "register": "中性", "sense_fingerprint": "政府、学校、医院等机构中的岗位及其地位", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5cea4ba9-e5df-4d1b-8c6e-7471ef55d20e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90622, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "职位", "is_correct": true, "explanation": "正确：职位指政府中的岗位，与“重要的”搭配自然。"}, {"text": "颜色", "is_correct": false, "explanation": "语义：颜色不是政府里的岗位，“重要的颜色”说不通。"}, {"text": "草坪", "is_correct": false, "explanation": "语义：草坪是一片草地，不能是政府中的岗位。"}, {"text": "体重", "is_correct": false, "explanation": "搭配：“有重要的体重”不成立，“体重”不能与“有重要的”搭配。"}], "explanations": {"职位": "正确：职位指政府中的岗位，与“重要的”搭配自然。", "颜色": "语义：颜色不是政府里的岗位，“重要的颜色”说不通。", "草坪": "语义：草坪是一片草地，不能是政府中的岗位。", "体重": "搭配：“有重要的体重”不成立，“体重”不能与“有重要的”搭配。"}, "sentence_index": 0, "correct_answer": "职位"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他的职位很开朗。", "explanation": "这里应该用〈性格〉。职位指岗位，不能用来形容人的性情。"}, {"text": "这辆车的职位很快。", "explanation": "这里应该用〈速度〉。职位指机构中的岗位，不能用来形容车辆的快慢。"}, {"text": "这个职位很便宜。", "explanation": "这里应该用〈价格〉。职位指岗位，不能用“便宜”来形容，说价钱低才用“便宜”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '17403514-88bd-43ce-bf3d-11fb4f8b017e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90622, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "职位", "is_correct": true, "explanation": "正确：职位是机构中的岗位，与“放弃了原来的”搭配自然。"}, {"text": "天气", "is_correct": false, "explanation": "语义：天气不能被放弃，不能说“放弃了原来的天气”。"}, {"text": "年龄", "is_correct": false, "explanation": "搭配：“放弃”后不接“年龄”，年龄不能被放弃。"}, {"text": "体重", "is_correct": false, "explanation": "搭配：“放弃了原来的体重”不成立，体重不说放弃。"}], "explanations": {"职位": "正确：职位是机构中的岗位，与“放弃了原来的”搭配自然。", "天气": "语义：天气不能被放弃，不能说“放弃了原来的天气”。", "年龄": "搭配：“放弃”后不接“年龄”，年龄不能被放弃。", "体重": "搭配：“放弃了原来的体重”不成立，体重不说放弃。"}, "sentence_index": 6, "correct_answer": "职位"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "今天的职位很好。", "explanation": "这里应该用〈天气〉。职位指岗位，不能用来形容天气。"}, {"text": "他的职位很好听。", "explanation": "这里应该用〈声音〉。职位指岗位，不能用来形容声音。"}, {"text": "这件衣服的职位很漂亮。", "explanation": "这里应该用〈颜色〉。职位指岗位，不能用来描述衣服的外观。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '17403514-88bd-43ce-bf3d-11fb4f8b017e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90622, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他担任一座重要的职位。", "corrected_sentence": "他担任一个重要的职位。", "error_description": "量词错误：“职位”应用量词“个”，“座”用于山、楼等大型物体。正确说法是“一个重要的职位”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '17403514-88bd-43ce-bf3d-11fb4f8b017e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90622, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "她换着一次职位。", "corrected_sentence": "她换过一次职位。", "error_description": "“着”误用：“换”后表示曾经换过应用“过”，“着”表示持续状态，与“一次”的完成意义矛盾。正确说法是“换过一次职位”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '17403514-88bd-43ce-bf3d-11fb4f8b017e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90633, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "放弃", "is_correct": true, "explanation": "反义：放弃是主动不去行使（权利），与“行使”构成反义关系。"}, {"text": "接受", "is_correct": false, "explanation": "“接受”表示收下或同意，与“行使”没有反义关系。"}, {"text": "完成", "is_correct": false, "explanation": "“完成”表示做完某件事，与“行使”没有反义关系。"}, {"text": "保持", "is_correct": false, "explanation": "“保持”表示维持原状，与“行使”没有反义关系。"}], "correct_answer": "放弃", "explanations": {"放弃": "反义：放弃是主动不去行使（权利），与“行使”构成反义关系。", "接受": "“接受”表示收下或同意，与“行使”没有反义关系。", "完成": "“完成”表示做完某件事，与“行使”没有反义关系。", "保持": "“保持”表示维持原状，与“行使”没有反义关系。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b20cafd5-e15b-4ea5-a683-a410d336d823') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90633, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "放弃", "is_correct": true, "explanation": "反义：放弃是主动不去行使（权利），与“行使”构成反义关系。"}, {"text": "参加", "is_correct": false, "explanation": "“参加”表示加入某项活动，与“行使”没有反义关系。"}, {"text": "赞成", "is_correct": false, "explanation": "“赞成”表示同意，与“行使”没有反义关系。"}, {"text": "坚持", "is_correct": false, "explanation": "“坚持”的反义词是“放弃”，但它与“行使”没有反义关系。"}], "correct_answer": "放弃", "explanations": {"放弃": "反义：放弃是主动不去行使（权利），与“行使”构成反义关系。", "参加": "“参加”表示加入某项活动，与“行使”没有反义关系。", "赞成": "“赞成”表示同意，与“行使”没有反义关系。", "坚持": "“坚持”的反义词是“放弃”，但它与“行使”没有反义关系。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b20cafd5-e15b-4ea5-a683-a410d336d823') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90633, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "用自己有的权力去做事。", "primary_collocate": null, "pronunciation": "xíng shǐ", "ipa": "ɕiŋ˧˥ ʂʅ˨˩˦", "syllable_count": 2, "sentences": [{"text": "公民要依法行使自己的权利。", "target_word": "行使", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他在会上行使了投票的权利。", "target_word": "行使", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老板不能随便行使自己的权力。", "target_word": "行使", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "到了十八岁，你就可以行使选举权了。", "target_word": "行使", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "经理没有行使他的否决权。", "target_word": "行使", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "法律保护公民行使自己的权利。", "target_word": "行使", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她第一次行使投票权，心里很紧张。", "target_word": "行使", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "股东有权在会议上行使表决权。", "target_word": "行使", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "家长不应该乱行使自己的权力。", "target_word": "行使", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "未成年人也要学会依法行使自己的权利。", "target_word": "行使", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "行使了", "label": "体标"}, {"form": "行使着", "label": "体标"}, {"form": "行使过", "label": "体标"}], "register": "书面语", "sense_fingerprint": "行使：个人运用自己拥有的权利或权力去做事", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '56b12eb9-afc4-4062-9387-4ca205bf21c6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90633, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "行使", "is_correct": true, "explanation": "正确答案。行使（xíng shǐ）指运用权利或权力去做事，第二个音节 shǐ 为第三声。"}, {"text": "形势", "is_correct": false, "explanation": "shì（第四声）与 shǐ（第三声）声调不同，形势指事物发展的局面。"}, {"text": "形式", "is_correct": false, "explanation": "shì（第四声）与 shǐ（第三声）声调不同，形式指事物的外在样子或格式。"}, {"text": "刑事", "is_correct": false, "explanation": "shì（第四声）与 shǐ（第三声）声调不同，刑事指与刑罚有关的案件。"}, {"text": "行事", "is_correct": false, "explanation": "shì（第四声）与 shǐ（第三声）声调不同，行事指做事、办事。"}], "explanations": {"行使": "正确答案。行使（xíng shǐ）指运用权利或权力去做事，第二个音节 shǐ 为第三声。", "形势": "shì（第四声）与 shǐ（第三声）声调不同，形势指事物发展的局面。", "形式": "shì（第四声）与 shǐ（第三声）声调不同，形式指事物的外在样子或格式。", "刑事": "shì（第四声）与 shǐ（第三声）声调不同，刑事指与刑罚有关的案件。", "行事": "shì（第四声）与 shǐ（第三声）声调不同，行事指做事、办事。"}, "sentence_index": null, "correct_answer": "行使"}, "level_3": {"options": [{"text": "行使", "is_correct": true, "explanation": "与“依法”“权利”搭配，表示依照法律运用权利，符合句意。"}, {"text": "打听", "is_correct": false, "explanation": "语义：“打听”指探问消息，不能用于权利，与句意不符。"}, {"text": "完成", "is_correct": false, "explanation": "语义：“完成”指做完任务或工作，与“依法运用权利”的意思不合。"}, {"text": "增长", "is_correct": false, "explanation": "搭配：“增长”用于数量、能力、知识，不说“增长权利”。"}], "explanations": {"行使": "与“依法”“权利”搭配，表示依照法律运用权利，符合句意。", "打听": "语义：“打听”指探问消息，不能用于权利，与句意不符。", "完成": "语义：“完成”指做完任务或工作，与“依法运用权利”的意思不合。", "增长": "搭配：“增长”用于数量、能力、知识，不说“增长权利”。"}, "sentence_index": 0, "correct_answer": "行使"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我每天都行使这台电脑。", "explanation": "这里应该用〈使用〉。行使只用于权力、权利，不能用于电脑这类具体物品。"}, {"text": "他在会上行使了一个建议。", "explanation": "这里应该用〈提出〉。行使的对象是权利或权力，不能是建议，提出建议要说“提出”。"}, {"text": "他行使了这份工作。", "explanation": "这里应该用〈担任〉。行使表示运用权利或权力，不能用来表示担任、从事某份工作。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b20cafd5-e15b-4ea5-a683-a410d336d823') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90633, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "行使", "is_correct": true, "explanation": "正确答案。行使（xíng shǐ）指运用权利或权力去做事。"}, {"text": "行市", "is_correct": false, "explanation": "shì（第四声）与 shǐ（第三声）声调不同，行市指商品的市场价格。"}, {"text": "型式", "is_correct": false, "explanation": "shì（第四声）与 shǐ（第三声）声调不同，型式指样式或类型。"}, {"text": "幸事", "is_correct": false, "explanation": "xìng（第四声）与 xíng（第二声）声调不同，shì 与 shǐ 的声调也不同，幸事指令人高兴的事。"}, {"text": "姓氏", "is_correct": false, "explanation": "xìng（第四声）与 xíng（第二声）声调不同，姓氏指姓的统称。"}], "explanations": {"行使": "正确答案。行使（xíng shǐ）指运用权利或权力去做事。", "行市": "shì（第四声）与 shǐ（第三声）声调不同，行市指商品的市场价格。", "型式": "shì（第四声）与 shǐ（第三声）声调不同，型式指样式或类型。", "幸事": "xìng（第四声）与 xíng（第二声）声调不同，shì 与 shǐ 的声调也不同，幸事指令人高兴的事。", "姓氏": "xìng（第四声）与 xíng（第二声）声调不同，姓氏指姓的统称。"}, "sentence_index": null, "correct_answer": "行使"}, "level_3": {"options": [{"text": "行使", "is_correct": true, "explanation": "与“投票权”搭配，表示运用投票的权利，符合句意。"}, {"text": "感到", "is_correct": false, "explanation": "搭配：“感到”后接感觉、压力，不能说“感到投票权”。"}, {"text": "买", "is_correct": false, "explanation": "语义：投票权是法定权利，不能用“买”，与句意相悖。"}, {"text": "打破", "is_correct": false, "explanation": "搭配：“打破”用于纪录、局面、规定，不说“打破投票权”。"}], "explanations": {"行使": "与“投票权”搭配，表示运用投票的权利，符合句意。", "感到": "搭配：“感到”后接感觉、压力，不能说“感到投票权”。", "买": "语义：投票权是法定权利，不能用“买”，与句意相悖。", "打破": "搭配：“打破”用于纪录、局面、规定，不说“打破投票权”。"}, "sentence_index": 6, "correct_answer": "行使"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他每天都行使身体，很健康。", "explanation": "这里应该用〈锻炼〉。行使用于权力、权利，不能用于身体。"}, {"text": "他在会上行使了自己的看法。", "explanation": "这里应该用〈发表〉。行使用于权利、权力，不能用于表达看法。"}, {"text": "我们要行使自己的未来。", "explanation": "这里应该用〈选择〉。行使指运用权利或权力，不能用于选择未来这类事情。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b20cafd5-e15b-4ea5-a683-a410d336d823') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90633, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他决定在下次选举中行使了自己的投票权。", "corrected_sentence": "他决定在下次选举中行使自己的投票权。", "error_description": "“行使了”的“了”表示动作已经完成，与“下次选举”这样的将来时间矛盾，应去掉“了”，改为“行使”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b20cafd5-e15b-4ea5-a683-a410d336d823') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90633, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "老人第一次行使着投票权，很激动。", "corrected_sentence": "老人第一次行使投票权，很激动。", "error_description": "“行使着”表示动作正在持续，与“第一次”这种一次性的事件矛盾，应去掉“着”，改为“行使”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b20cafd5-e15b-4ea5-a683-a410d336d823') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
