INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90634, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "执行；使用（职权等）。", "primary_collocate": null, "pronunciation": "xíng shǐ", "ipa": "ɕiŋ˧˥ ʂʅ˨˩˦", "syllable_count": 2, "sentences": [{"text": "警察依法行使职权。", "target_word": "行使", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "法官在法庭上行使审判权。", "target_word": "行使", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "市长不能超出范围行使职权。", "target_word": "行使", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "政府要按规定行使管理权力。", "target_word": "行使", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "检察官正在行使自己的职权。", "target_word": "行使", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这位官员从不乱行使职权。", "target_word": "行使", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "国家机关必须依法行使权力。", "target_word": "行使", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "海关人员有权行使检查的职权。", "target_word": "行使", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "校长行使了最后的决定权。", "target_word": "行使", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "警察行使职权时，要出示证件。", "target_word": "行使", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "行使了", "label": "体标"}, {"form": "行使着", "label": "体标"}, {"form": "行使过", "label": "体标"}], "register": "书面语", "sense_fingerprint": "行使：官员或机关执行、使用职权", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '56b12eb9-afc4-4062-9387-4ca205bf21c6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
