EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90634, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "行使", "is_correct": true, "explanation": "正确答案。行使（xíng shǐ）指官员或机关执行、使用职权。"}, {"text": "形式", "is_correct": false, "explanation": "shì（第四声）与 shǐ（第三声）声调不同，形式指外在样子或格式。"}, {"text": "行事", "is_correct": false, "explanation": "shì（第四声）与 shǐ（第三声）声调不同，行事指做事、办事。"}, {"text": "幸事", "is_correct": false, "explanation": "xìng（第四声）与 xíng（第二声）声调不同，shì 与 shǐ 的声调也不同，幸事指令人高兴的事。"}, {"text": "姓氏", "is_correct": false, "explanation": "xìng（第四声）与 xíng（第二声）声调不同，姓氏指姓的统称。"}], "explanations": {"行使": "正确答案。行使（xíng shǐ）指官员或机关执行、使用职权。", "形式": "shì（第四声）与 shǐ（第三声）声调不同，形式指外在样子或格式。", "行事": "shì（第四声）与 shǐ（第三声）声调不同，行事指做事、办事。", "幸事": "xìng（第四声）与 xíng（第二声）声调不同，shì 与 shǐ 的声调也不同，幸事指令人高兴的事。", "姓氏": "xìng（第四声）与 xíng（第二声）声调不同，姓氏指姓的统称。"}, "sentence_index": null, "correct_answer": "行使"}, "level_3": {"options": [{"text": "行使", "is_correct": true, "explanation": "与“依法”“权力”搭配，表示依照法律执行权力，符合句意。"}, {"text": "夺取", "is_correct": false, "explanation": "语义：“夺取”指用强力取得，与“依法”的要求相悖。"}, {"text": "兑现", "is_correct": false, "explanation": "搭配：“兑现”搭配承诺、支票，不说“兑现权力”。"}, {"text": "挑选", "is_correct": false, "explanation": "语义：“挑选”的对象是人或物，与“依法履行权力”的语境不符。"}], "explanations": {"行使": "与“依法”“权力”搭配，表示依照法律执行权力，符合句意。", "夺取": "语义：“夺取”指用强力取得，与“依法”的要求相悖。", "兑现": "搭配：“兑现”搭配承诺、支票，不说“兑现权力”。", "挑选": "语义：“挑选”的对象是人或物，与“依法履行权力”的语境不符。"}, "sentence_index": 6, "correct_answer": "行使"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "工人要按规定行使机器。", "explanation": "这里应该用〈操作〉。行使指运用权力，不指操作机器。"}, {"text": "老人在晚上行使了一个故事。", "explanation": "这里应该用〈讲述〉。行使只用于权利、权力，不能用于讲故事。"}, {"text": "工厂每天行使很多汽车。", "explanation": "这里应该用〈制造〉。行使指运用权力，不能用于生产汽车。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b20cafd5-e15b-4ea5-a683-a410d336d823') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90634, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "法院将依法行使了职权。", "corrected_sentence": "法院将依法行使职权。", "error_description": "“行使了”的“了”表示动作已经完成，与“将”表示的将来矛盾，应去掉“了”，改为“行使”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b20cafd5-e15b-4ea5-a683-a410d336d823') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90634, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "城管昨天依法行使着执法权。", "corrected_sentence": "城管昨天依法行使了执法权。", "error_description": "“行使着”表示动作持续，与“昨天”这样的已完成时间矛盾，应把“着”改为“了”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b20cafd5-e15b-4ea5-a683-a410d336d823') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
