INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90637, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "property", "definition": "显得是让别人看起来是这个样子。", "primary_collocate": null, "pronunciation": "xiǎn de", "ipa": "ɕjɛn˨˩ tɤ", "syllable_count": 2, "sentences": [{"text": "她穿上新衣服，显得很年轻。", "target_word": "显得", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他今天剪了头发，显得更精神了。", "target_word": "显得", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这件白衬衫让他显得很高。", "target_word": "显得", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他笑着说话，显得很友好。", "target_word": "显得", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她化了妆，显得比平时漂亮。", "target_word": "显得", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "戴上眼镜后，哥哥显得很有学问。", "target_word": "显得", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他不说话，显得有点儿紧张。", "target_word": "显得", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这条裤子太短，让你显得很矮。", "target_word": "显得", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "老人穿得很干净，显得很有精神。", "target_word": "显得", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他穿着西装，显得很正式。", "target_word": "显得", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "顯得", "label": "繁体"}], "register": "中性", "sense_fingerprint": "显得：人的外表或神态给人的印象", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a7cb592a-ebe9-461b-8879-76b618f34d38') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90637, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "显得", "is_correct": true, "explanation": "正确答案：显得（xiǎn de），意思是让别人看起来是某种样子。"}, {"text": "闲得", "is_correct": false, "explanation": "xián（第二声）与 xiǎn（第三声）声调不同，意思是闲得无聊。"}, {"text": "懒得", "is_correct": false, "explanation": "lǎn 与 xiǎn 声母不同（l 与 x），意思是懒得做某事。"}, {"text": "想得", "is_correct": false, "explanation": "xiǎng 与 xiǎn 韵尾不同（ng 与 n），意思是想得到、想到。"}, {"text": "喊得", "is_correct": false, "explanation": "hǎn 与 xiǎn 声母不同（h 与 x），意思是大声喊。"}], "explanations": {"显得": "正确答案：显得（xiǎn de），意思是让别人看起来是某种样子。", "闲得": "xián（第二声）与 xiǎn（第三声）声调不同，意思是闲得无聊。", "懒得": "lǎn 与 xiǎn 声母不同（l 与 x），意思是懒得做某事。", "想得": "xiǎng 与 xiǎn 韵尾不同（ng 与 n），意思是想得到、想到。", "喊得": "hǎn 与 xiǎn 声母不同（h 与 x），意思是大声喊。"}, "sentence_index": null, "correct_answer": "显得"}, "level_3": {"options": [{"text": "显得", "is_correct": true, "explanation": "“显得”表示人的外表、神态给人的印象，与“很年轻”的评价相符。"}, {"text": "使得", "is_correct": false, "explanation": "配价：“使得”后面需要带宾语，句中没有宾语，不能单独作谓语。"}, {"text": "有", "is_correct": false, "explanation": "搭配：“有”后不能直接接“很年轻”这样的形容词短语，“有很年轻”不通。"}, {"text": "说", "is_correct": false, "explanation": "语义：“说”指说话，与“穿上新衣服”所描写的外在印象不相关。"}], "explanations": {"显得": "“显得”表示人的外表、神态给人的印象，与“很年轻”的评价相符。", "使得": "配价：“使得”后面需要带宾语，句中没有宾语，不能单独作谓语。", "有": "搭配：“有”后不能直接接“很年轻”这样的形容词短语，“有很年轻”不通。", "说": "语义：“说”指说话，与“穿上新衣服”所描写的外在印象不相关。"}, "sentence_index": 0, "correct_answer": "显得"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这份报告显得我们的进步很大。", "explanation": "这里应该用〈显示〉。“显得”表示人或事物的外表、神态给人的印象，报告展示进步要用“显示”。"}, {"text": "这份数据显得销量增加了许多。", "explanation": "这里应该用〈显示〉。“显得”表示外表或神态给人的印象，展示数量变化要用“显示”。"}, {"text": "这个数字显得公司利润很高。", "explanation": "这里应该用〈反映〉。“显得”表示看起来的样子，数字反映情况要用“反映”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd3a268d3-f614-4983-a57d-533698cf7a82') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90637, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "显得", "is_correct": true, "explanation": "正确答案：显得（xiǎn de），意思是让别人看起来是某种样子。"}, {"text": "小得", "is_correct": false, "explanation": "xiǎo 与 xiǎn 韵尾不同（o 与 n），意思是小得很。"}, {"text": "闪得", "is_correct": false, "explanation": "shǎn 与 xiǎn 声母不同（sh 与 x），意思是闪得很快。"}, {"text": "浅得", "is_correct": false, "explanation": "qiǎn 与 xiǎn 声母不同（q 与 x），意思是浅得很。"}, {"text": "闲得", "is_correct": false, "explanation": "xián（第二声）与 xiǎn（第三声）声调不同，意思是闲得无聊。"}], "explanations": {"显得": "正确答案：显得（xiǎn de），意思是让别人看起来是某种样子。", "小得": "xiǎo 与 xiǎn 韵尾不同（o 与 n），意思是小得很。", "闪得": "shǎn 与 xiǎn 声母不同（sh 与 x），意思是闪得很快。", "浅得": "qiǎn 与 xiǎn 声母不同（q 与 x），意思是浅得很。", "闲得": "xián（第二声）与 xiǎn（第三声）声调不同，意思是闲得无聊。"}, "sentence_index": null, "correct_answer": "显得"}, "level_3": {"options": [{"text": "显得", "is_correct": true, "explanation": "“显得”表示外在表现给人的印象，与“有点儿紧张”的神态相符。"}, {"text": "看", "is_correct": false, "explanation": "搭配：“看”后不能直接接形容词短语，应说“看起来”，“看有点儿紧张”不通。"}, {"text": "听", "is_correct": false, "explanation": "搭配：“听”后不能直接接形容词短语，应说“听起来”，“听有点儿紧张”不通。"}, {"text": "说", "is_correct": false, "explanation": "语义：“说”指言语行为，与句中“不说话”相矛盾。"}], "explanations": {"显得": "“显得”表示外在表现给人的印象，与“有点儿紧张”的神态相符。", "看": "搭配：“看”后不能直接接形容词短语，应说“看起来”，“看有点儿紧张”不通。", "听": "搭配：“听”后不能直接接形容词短语，应说“听起来”，“听有点儿紧张”不通。", "说": "语义：“说”指言语行为，与句中“不说话”相矛盾。"}, "sentence_index": 6, "correct_answer": "显得"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这次培训显得员工的能力提升了。", "explanation": "这里应该用〈表明〉。“显得”表示外表给人的印象，说明能力提升要用“表明”。"}, {"text": "这次演出显得大家的努力很多。", "explanation": "这里应该用〈显示〉。“显得”表示外表给人的印象，不能表示展现努力，展现成果要用“显示”。"}, {"text": "这次会议显得大家的意见很一致。", "explanation": "这里应该用〈表明〉。“显得”表示外表或神态的印象，意见一致的情况要用“表明”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd3a268d3-f614-4983-a57d-533698cf7a82') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90637, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "她换了新发型，显得的很精神。", "corrected_sentence": "她换了新发型，显得很精神。", "error_description": "“的”不能插在“显得”与形容词之间。“显得”后直接接形容词，应说“显得很精神”，不能说“显得的很精神”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd3a268d3-f614-4983-a57d-533698cf7a82') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90637, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这张照片让他显得得很年轻。", "corrected_sentence": "这张照片让他显得很年轻。", "error_description": "“显得”已含“得”，后面不能再加“得”。应删去多出的“得”，说“显得很年轻”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd3a268d3-f614-4983-a57d-533698cf7a82') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
