INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90638, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "property", "definition": "表现出某种情形或样子。", "primary_collocate": null, "pronunciation": "xiǎn de", "ipa": "ɕjɛn˨˩ tɤ", "syllable_count": 2, "sentences": [{"text": "房间里没有人，显得很安静。", "target_word": "显得", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "和大楼比起来，小房子显得很矮。", "target_word": "显得", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "灯一关，屋子里显得更黑了。", "target_word": "显得", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "墙刷成白色后，客厅显得很大。", "target_word": "显得", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "雨停以后，街道显得特别干净。", "target_word": "显得", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "桌子放在中间，房间显得有点儿挤。", "target_word": "显得", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "夜里的海边显得格外冷清。", "target_word": "显得", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这个问题在他看来显得很简单。", "target_word": "显得", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "下雪以后，公园显得很漂亮。", "target_word": "显得", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "沙发太大，小屋子显得更小了。", "target_word": "显得", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "顯得", "label": "繁体"}], "register": "中性", "sense_fingerprint": "显得：地方或事物呈现出某种情形", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a7cb592a-ebe9-461b-8879-76b618f34d38') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90638, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "显得", "is_correct": true, "explanation": "正确答案：显得（xiǎn de），意思是地方或事物呈现出某种情形。"}, {"text": "闲得", "is_correct": false, "explanation": "xián（第二声）与 xiǎn（第三声）声调不同，意思是闲得无聊。"}, {"text": "懒得", "is_correct": false, "explanation": "lǎn 与 xiǎn 声母不同（l 与 x），意思是懒得做某事。"}, {"text": "想得", "is_correct": false, "explanation": "xiǎng 与 xiǎn 韵尾不同（ng 与 n），意思是想得到、想到。"}, {"text": "喊得", "is_correct": false, "explanation": "hǎn 与 xiǎn 声母不同（h 与 x），意思是大声喊。"}], "explanations": {"显得": "正确答案：显得（xiǎn de），意思是地方或事物呈现出某种情形。", "闲得": "xián（第二声）与 xiǎn（第三声）声调不同，意思是闲得无聊。", "懒得": "lǎn 与 xiǎn 声母不同（l 与 x），意思是懒得做某事。", "想得": "xiǎng 与 xiǎn 韵尾不同（ng 与 n），意思是想得到、想到。", "喊得": "hǎn 与 xiǎn 声母不同（h 与 x），意思是大声喊。"}, "sentence_index": null, "correct_answer": "显得"}, "level_3": {"options": [{"text": "显得", "is_correct": true, "explanation": "“显得”表示房间呈现的情形，与“没有人，很安静”的描述相符。"}, {"text": "使得", "is_correct": false, "explanation": "配价：“使得”后面需要带宾语，句中没有宾语，不能单独作谓语。"}, {"text": "有", "is_correct": false, "explanation": "搭配：“有”后不能直接接“很安静”这样的形容词短语，“有很安静”不通。"}, {"text": "叫", "is_correct": false, "explanation": "搭配：“叫”表示称呼或发出声音，不能与“很安静”组合成谓语。"}], "explanations": {"显得": "“显得”表示房间呈现的情形，与“没有人，很安静”的描述相符。", "使得": "配价：“使得”后面需要带宾语，句中没有宾语，不能单独作谓语。", "有": "搭配：“有”后不能直接接“很安静”这样的形容词短语，“有很安静”不通。", "叫": "搭配：“叫”表示称呼或发出声音，不能与“很安静”组合成谓语。"}, "sentence_index": 0, "correct_answer": "显得"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这次改革显得大家的收入增加了。", "explanation": "这里应该用〈表明〉。“显得”表示给人的外观印象，说明收入变化要用“表明”。"}, {"text": "墙刷成白色后，大家显得客厅很大。", "explanation": "配价：“显得”的主语应是客厅这类被看的事物，“大家”不能作主语再带小句指向客厅；应说“客厅显得很大”。"}, {"text": "墙刷成白色后，客厅显得她很年轻。", "explanation": "这里“显得”的主语是客厅，却用来评价人的年龄外表，搭配不通；“显得”描述的是事物呈现的情形，应说“客厅显得很大”之类。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd3a268d3-f614-4983-a57d-533698cf7a82') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90638, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "显得", "is_correct": true, "explanation": "正确答案：显得（xiǎn de），意思是地方或事物呈现出某种情形。"}, {"text": "小得", "is_correct": false, "explanation": "xiǎo 与 xiǎn 韵尾不同（o 与 n），意思是小得很。"}, {"text": "闪得", "is_correct": false, "explanation": "shǎn 与 xiǎn 声母不同（sh 与 x），意思是闪得很快。"}, {"text": "浅得", "is_correct": false, "explanation": "qiǎn 与 xiǎn 声母不同（q 与 x），意思是浅得很。"}, {"text": "闲得", "is_correct": false, "explanation": "xián（第二声）与 xiǎn（第三声）声调不同，意思是闲得无聊。"}], "explanations": {"显得": "正确答案：显得（xiǎn de），意思是地方或事物呈现出某种情形。", "小得": "xiǎo 与 xiǎn 韵尾不同（o 与 n），意思是小得很。", "闪得": "shǎn 与 xiǎn 声母不同（sh 与 x），意思是闪得很快。", "浅得": "qiǎn 与 xiǎn 声母不同（q 与 x），意思是浅得很。", "闲得": "xián（第二声）与 xiǎn（第三声）声调不同，意思是闲得无聊。"}, "sentence_index": null, "correct_answer": "显得"}, "level_3": {"options": [{"text": "显得", "is_correct": true, "explanation": "“显得”表示海边呈现的冷清情形，与“格外冷清”的描述相符。"}, {"text": "看", "is_correct": false, "explanation": "搭配：“看”后不能直接接形容词短语，应说“看起来”，“看格外冷清”不通。"}, {"text": "装", "is_correct": false, "explanation": "语义：“装”表示假装，只用于有意图的人，海边不能“装”冷清，“装格外冷清”不通。"}, {"text": "说", "is_correct": false, "explanation": "配价：“说”需要说话的对象和内容，单独接“格外冷清”不成立。"}], "explanations": {"显得": "“显得”表示海边呈现的冷清情形，与“格外冷清”的描述相符。", "看": "搭配：“看”后不能直接接形容词短语，应说“看起来”，“看格外冷清”不通。", "装": "语义：“装”表示假装，只用于有意图的人，海边不能“装”冷清，“装格外冷清”不通。", "说": "配价：“说”需要说话的对象和内容，单独接“格外冷清”不成立。"}, "sentence_index": 6, "correct_answer": "显得"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这次改造显得房间的面积很大。", "explanation": "这里应该用〈显示〉。“显得”表示外观给人的印象，不能说改造展现了面积。"}, {"text": "沙发太大，它显得小屋子更小了。", "explanation": "这里漏了使动的“让”：“显得”的主语应是小屋子，应说“沙发太大，它让小屋子显得更小了”，而不是“它显得小屋子更小了”。"}, {"text": "沙发太大，小屋子显得很大。", "explanation": "这里与“沙发太大”的因果相反：沙发太大应使小屋子显得更小，不能说“显得很大”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd3a268d3-f614-4983-a57d-533698cf7a82') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90638, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "走进空房间，显得了格外空旷。", "corrected_sentence": "走进空房间，显得格外空旷。", "error_description": "“显得”后面多加了“了”，应删去。“显得”后直接接补语“格外空旷”，不能在它后面加“了”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd3a268d3-f614-4983-a57d-533698cf7a82') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90638, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "屋子里的家具太少，显得很格外空荡。", "corrected_sentence": "屋子里的家具太少，显得格外空荡。", "error_description": "“很”与“格外”都表示程度，不能连用。应删去“很”，说“显得格外空荡”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd3a268d3-f614-4983-a57d-533698cf7a82') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
