INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90639, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "人和车常常经过的重要的路。", "primary_collocate": null, "pronunciation": "yào dào", "ipa": "jau˥˩ tau˥˩", "syllable_count": 2, "sentences": [{"text": "这条要道上人来车往，非常热闹。", "target_word": "要道", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "车站前面的要道总是很堵。", "target_word": "要道", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我每天上班都要经过这条要道。", "target_word": "要道", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "要道上的红绿灯坏了，车都停着。", "target_word": "要道", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子们不能在要道上玩。", "target_word": "要道", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "这条要道通向城外的大市场。", "target_word": "要道", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "为了安全，要道上装了很多摄像头。", "target_word": "要道", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他家就在两条要道交叉的地方。", "target_word": "要道", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这座桥是进城的要道，每天很多人走。", "target_word": "要道", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "要道上有一家小饭店，生意很好。", "target_word": "要道", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "一条要道", "label": "量词"}, {"form": "交通要道", "label": "复合"}], "register": "中性", "sense_fingerprint": "要道-人和车常常经过的重要的路", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5ac86440-8f5a-4834-8135-427d86e72be0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90639, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "要道", "is_correct": true, "explanation": "正确：「要道」指人和车常经过的重要道路，与「人来车往」相合。"}, {"text": "河流", "is_correct": false, "explanation": "语义：河上不会车来车往，与句意矛盾。"}, {"text": "课本", "is_correct": false, "explanation": "搭配：「这条」不能修饰「课本」，且「人来车往」与课本无关。"}, {"text": "学校", "is_correct": false, "explanation": "搭配：「这条」只修饰道路、河流，不能用于「学校」。"}], "explanations": {"要道": "正确：「要道」指人和车常经过的重要道路，与「人来车往」相合。", "河流": "语义：河上不会车来车往，与句意矛盾。", "课本": "搭配：「这条」不能修饰「课本」，且「人来车往」与课本无关。", "学校": "搭配：「这条」只修饰道路、河流，不能用于「学校」。"}, "sentence_index": 0, "correct_answer": "要道"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "做事的要道是细心。", "explanation": "这里用的是另一个义项：要道指重要的道理，不是人和车经过的道路；这种用法不能用来指路。"}, {"text": "这首歌是人和车常经过的要道。", "explanation": "这里用错了对象。要道指道路，歌曲不是道路，不能说是人和车经过的要道。"}, {"text": "这家饭店是人和车常经过的要道。", "explanation": "这里用错了对象。要道指道路，饭店是建筑，不能说是人和车经过的要道。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '54d136a2-1535-496c-b74e-b1f72dabe9c2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90639, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "要道", "is_correct": true, "explanation": "正确：「要道」指道路，装摄像头是为了道路上的安全。"}, {"text": "雨伞", "is_correct": false, "explanation": "语义：雨伞是遮雨的用具，「为了安全」装摄像头的语境不适用于雨伞，句意不通。"}, {"text": "房间", "is_correct": false, "explanation": "搭配：方位词「上」多与道路、桌面搭配，「房间上」不自然，应说「房间里」。"}, {"text": "饼干", "is_correct": false, "explanation": "语义：「饼干」是食品，与「为了安全」装摄像头的语境不符。"}], "explanations": {"要道": "正确：「要道」指道路，装摄像头是为了道路上的安全。", "雨伞": "语义：雨伞是遮雨的用具，「为了安全」装摄像头的语境不适用于雨伞，句意不通。", "房间": "搭配：方位词「上」多与道路、桌面搭配，「房间上」不自然，应说「房间里」。", "饼干": "语义：「饼干」是食品，与「为了安全」装摄像头的语境不符。"}, "sentence_index": 6, "correct_answer": "要道"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他把这条要道装进了口袋。", "explanation": "这里应该用〈走〉。要道是道路，人是在上面行走，不能说装进口袋。"}, {"text": "这条要道昨天结婚了。", "explanation": "这里用错了对象。要道是道路，道路不能结婚，这句话只能用于人。"}, {"text": "我们每天给这条要道洗澡。", "explanation": "这里应该用〈修〉。要道是道路，要说修路，不能说洗澡。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '54d136a2-1535-496c-b74e-b1f72dabe9c2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90639, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这辆要道上每天都有施工。", "corrected_sentence": "这条要道上每天都有施工。", "error_description": "量词错误：「要道」是道路，应用量词「条」；「辆」用于车辆，不能修饰道路，正确的是「这条要道上每天都有施工」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '54d136a2-1535-496c-b74e-b1f72dabe9c2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90639, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "工人们正在修这台要道。", "corrected_sentence": "工人们正在修这条要道。", "error_description": "量词错误：道路应用「条」，「台」用于机器等物件，正确的是「这条要道」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '54d136a2-1535-496c-b74e-b1f72dabe9c2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
