INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90648, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "用户在系统中登记的名称和编号。", "primary_collocate": null, "pronunciation": "zhàng hào", "ipa": "ʈʂɑŋ˥˩ xɑʊ˥˩", "syllable_count": 2, "sentences": [{"text": "请先输入你的账号。", "target_word": "账号", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "我忘了这个账号的密码。", "target_word": "账号", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "公司给每个员工一个账号。", "target_word": "账号", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这个账号已经有人用了。", "target_word": "账号", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "登录系统需要账号和密码。", "target_word": "账号", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "新同学还没有学校系统的账号。", "target_word": "账号", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "你可以用手机号当账号。", "target_word": "账号", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "一个人只能注册一个账号。", "target_word": "账号", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "请把你的账号写在这张表上。", "target_word": "账号", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "账号不对，所以进不去系统。", "target_word": "账号", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "一个账号", "label": "量词"}, {"form": "账号密码", "label": "复合"}, {"form": "帳號", "label": "繁体"}], "register": "通用", "sense_fingerprint": "账号：用户在系统中登记的名称和编号", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f55774ed-ddc3-49eb-a960-56e3f2d39f09') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90648, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "站号", "is_correct": false, "explanation": "zhàn 与 zhàng 的韵母不同（-n 与 -ng），意思是车站的编号。"}, {"text": "账号", "is_correct": true, "explanation": "账号：用户在系统中登记的名称和编号。"}, {"text": "上号", "is_correct": false, "explanation": "shàng 与 zhàng 的声母不同（sh 与 zh），意思是（游戏中）登录账号。"}, {"text": "降号", "is_correct": false, "explanation": "jiàng 与 zhàng 的声母不同（j 与 zh），意思是音乐中的降号。"}], "explanations": {"站号": "zhàn 与 zhàng 的韵母不同（-n 与 -ng），意思是车站的编号。", "账号": "账号：用户在系统中登记的名称和编号。", "上号": "shàng 与 zhàng 的声母不同（sh 与 zh），意思是（游戏中）登录账号。", "降号": "jiàng 与 zhàng 的声母不同（j 与 zh），意思是音乐中的降号。"}, "sentence_index": null, "correct_answer": "账号"}, "level_3": {"options": [{"text": "书", "is_correct": false, "explanation": "搭配：“输入”用于账号、密码等信息，不能输入书。"}, {"text": "账号", "is_correct": true, "explanation": "正确：“输入账号”是登录系统时的常见说法。"}, {"text": "早饭", "is_correct": false, "explanation": "语义：早饭不是可以输入系统的信息，句子说不通。"}, {"text": "眼睛", "is_correct": false, "explanation": "语义：眼睛是身体部位，不能被输入系统，句子说不通。"}], "explanations": {"书": "搭配：“输入”用于账号、密码等信息，不能输入书。", "账号": "正确：“输入账号”是登录系统时的常见说法。", "早饭": "语义：早饭不是可以输入系统的信息，句子说不通。", "眼睛": "语义：眼睛是身体部位，不能被输入系统，句子说不通。"}, "sentence_index": 0, "correct_answer": "账号"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "出门以后，我用账号开门。", "explanation": "这里应该用〈钥匙〉。钥匙是实物，可以用来开门；账号是登录系统用的名称和编号，不能开门。"}, {"text": "我用账号换台，电视突然变了。", "explanation": "这里应该用〈遥控器〉。遥控器是实物，用来换台；账号不能用来换台。"}, {"text": "我有一本账号，一直没用。", "explanation": "这里应该用〈个〉。“本”用于书、本子等，账号要用“个”，不说“一本账号”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '71686fda-6fd9-4849-9233-e16873699209') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90648, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "桌子", "is_correct": false, "explanation": "语义：手机号不能当桌子使用，句子说不通。"}, {"text": "颜色", "is_correct": false, "explanation": "搭配：“当”后面接身份或名称类的词，颜色不能这样用。"}, {"text": "账号", "is_correct": true, "explanation": "正确：手机号可以作为登录账号使用。"}, {"text": "汽车", "is_correct": false, "explanation": "语义：手机号不能当汽车，句子说不通。"}], "explanations": {"桌子": "语义：手机号不能当桌子使用，句子说不通。", "颜色": "搭配：“当”后面接身份或名称类的词，颜色不能这样用。", "账号": "正确：手机号可以作为登录账号使用。", "汽车": "语义：手机号不能当汽车，句子说不通。"}, "sentence_index": 6, "correct_answer": "账号"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他是我的账号，我很喜欢他。", "explanation": "账号是名称和编号，指的不是人。这里把账号当成了人，说不通。"}, {"text": "我把账号放进了书包。", "explanation": "账号是抽象的名称和编号，不是实物，不能放进书包。"}, {"text": "这个账号很重，我背不动。", "explanation": "账号没有重量，“很重”只能用于实物，这里用错了对象。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '71686fda-6fd9-4849-9233-e16873699209') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90648, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "请你给每个学生一张账号。", "corrected_sentence": "请你给每个学生一个账号。", "error_description": "量词错误：“张”用于纸张、卡片等扁平的东西，账号要用“个”。应把“一张账号”改为“一个账号”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '71686fda-6fd9-4849-9233-e16873699209') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90648, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我换了一只新账号，忘了旧的密码。", "corrected_sentence": "我换了一个新账号，忘了旧的密码。", "error_description": "量词错误：“只”多用于动物或成对的东西，账号要用“个”。应把“一只新账号”改为“一个新账号”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '71686fda-6fd9-4849-9233-e16873699209') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
