INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90650, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '77fea57d-2c72-4f76-b2b2-2be0aacd67c3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90650, 1, 'prompt1_core', '{"pos": "副词", "semantic_class": "function", "definition": "副词，表示没有把握，不能肯定。", "primary_collocate": null, "pronunciation": "bù yí dìng", "ipa": "pu˥˩ i˧˥ tiŋ˥˩", "syllable_count": 3, "sentences": [{"text": "我不一定能赶上最后一班车。", "target_word": "不一定", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他不一定记得我们的约会。", "target_word": "不一定", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这件事不一定是他做的。", "target_word": "不一定", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你问问他，他不一定同意。", "target_word": "不一定", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "明天不一定有时间，我先问问。", "target_word": "不一定", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他不一定看见你了，再叫他一声。", "target_word": "不一定", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这次考试，我不一定能考好。", "target_word": "不一定", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "那家店周日不一定开门。", "target_word": "不一定", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我不太清楚，他不一定在家。", "target_word": "不一定", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "飞机不一定准时到，别等太久。", "target_word": "不一定", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "口语", "sense_fingerprint": "对某事没有把握，不能肯定", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '897c13e4-9594-468f-af81-93c04019cc00') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90650, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "不一定", "is_correct": true, "explanation": "不一定：表示没有把握，与后句“能赶上”的不确定相合。"}, {"text": "从不", "is_correct": false, "explanation": "语义：“从不”表示永远不，与句意“没有把握”不符。"}, {"text": "正在", "is_correct": false, "explanation": "搭配：“正在”表示动作进行，不能与“能”连用，句子不通。"}, {"text": "太", "is_correct": false, "explanation": "搭配：“太”修饰形容词，不能修饰“能赶上”。"}], "explanations": {"不一定": "不一定：表示没有把握，与后句“能赶上”的不确定相合。", "从不": "语义：“从不”表示永远不，与句意“没有把握”不符。", "正在": "搭配：“正在”表示动作进行，不能与“能”连用，句子不通。", "太": "搭配：“太”修饰形容词，不能修饰“能赶上”。"}, "sentence_index": 0, "correct_answer": "不一定"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这件事我不一定知道，是我亲手做的。", "explanation": "这里不能用〈不一定〉。事情是我亲手做的，应表示确定，直接用〈确实〉。"}, {"text": "这里不一定停车，请大家遵守。", "explanation": "这里应该用〈不准〉。不一定表示不确定，不能表示禁止；禁止停车要用〈不准〉。"}, {"text": "他不一定迟到了，他早就到了。", "explanation": "这里不能用〈不一定〉。“早就到了”是已经发生的事实，应用〈确实〉而不是表示没有把握的〈不一定〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '77fea57d-2c72-4f76-b2b2-2be0aacd67c3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90650, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "不一定", "is_correct": true, "explanation": "不一定：表示没有把握，与“这次考试”的未知结果相合。"}, {"text": "早就", "is_correct": false, "explanation": "语义：“早就”表示已经很久，与尚未发生的“这次考试”矛盾。"}, {"text": "好好", "is_correct": false, "explanation": "搭配：“好好”是修饰动作的副词，与“能考好”搭配不通。"}, {"text": "已", "is_correct": false, "explanation": "语域：“已”偏书面语，在这样的口语语境里不自然。"}], "explanations": {"不一定": "不一定：表示没有把握，与“这次考试”的未知结果相合。", "早就": "语义：“早就”表示已经很久，与尚未发生的“这次考试”矛盾。", "好好": "搭配：“好好”是修饰动作的副词，与“能考好”搭配不通。", "已": "语域：“已”偏书面语，在这样的口语语境里不自然。"}, "sentence_index": 6, "correct_answer": "不一定"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这次考试我不一定及格，我已经考了满分。", "explanation": "这里不能用〈不一定〉。考了满分是确定的结果，应直接用〈肯定〉而不是表示没有把握的〈不一定〉。"}, {"text": "快走吧，不一定就要迟到了。", "explanation": "这里应该用〈不然〉。不一定表示不确定，表示“否则”的条件关系要用〈不然〉。"}, {"text": "这么做不一定会出错，错误已经发生了。", "explanation": "这里不能用〈不一定〉。错误已经发生，是确定的结果，应用〈必然〉表示，而不是表示没有把握的〈不一定〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '77fea57d-2c72-4f76-b2b2-2be0aacd67c3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90650, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "明天他没不一定会来，我们再等等。", "corrected_sentence": "明天他不一定会来，我们再等等。", "error_description": "“没”用错：“不一定”本身已含否定，不能与“没”连用，应删去“没”，写作“明天他不一定会来”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '77fea57d-2c72-4f76-b2b2-2be0aacd67c3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90650, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这家饭馆周末没不一定营业。", "corrected_sentence": "这家饭馆周末不一定营业。", "error_description": "“没”用错：“不一定”本身已含否定，不能与“没”连用，应删去“没”，写作“这家饭馆周末不一定营业”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '77fea57d-2c72-4f76-b2b2-2be0aacd67c3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90654, 1, 'llm_types_A', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '77fea57d-2c72-4f76-b2b2-2be0aacd67c3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90654, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '77fea57d-2c72-4f76-b2b2-2be0aacd67c3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90654, 1, 'prompt1_core', '{"pos": "连词", "semantic_class": "function", "definition": "连词，常与“而且”连用，表示意思更进一层。", "primary_collocate": null, "pronunciation": "bú dàn", "ipa": "pu˧˥ tan˥˩", "syllable_count": 2, "sentences": [{"text": "他不但会唱歌，而且会跳舞。", "target_word": "不但", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个菜不但好吃，而且很便宜。", "target_word": "不但", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她不但聪明，而且很努力。", "target_word": "不但", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这里不但风景美，而且空气好。", "target_word": "不但", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我的老师不但很年轻，而且很有耐心。", "target_word": "不但", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他不但会说汉语，而且写得很好。", "target_word": "不但", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "那家饭馆不但干净，而且服务很好。", "target_word": "不但", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "骑车不但省钱，而且对身体好。", "target_word": "不但", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她不但帮我做饭，而且帮我洗了衣服。", "target_word": "不但", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这本书不但有意思，而且让我学到很多。", "target_word": "不但", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "中性", "sense_fingerprint": "递进连词，常与“而且”搭配，后面意思更进一层", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '897c13e4-9594-468f-af81-93c04019cc00') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90654, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "不但", "is_correct": true, "explanation": "不但读作 bú dàn，表示进一层，常与“而且”连用。"}, {"text": "不断", "is_correct": false, "explanation": "dàn 与 duàn 的韵母不同，duàn 多一个 u，不断意思是持续，不是不但。"}, {"text": "不大", "is_correct": false, "explanation": "dàn 与 dà 的韵尾不同，dàn 有 n，dà 没有，不大意思是不是很大。"}, {"text": "不带", "is_correct": false, "explanation": "dàn 与 dài 的韵尾不同，n 变成了 i，不带意思是不携带。"}, {"text": "不当", "is_correct": false, "explanation": "韵尾不同：dàng 是 ng，dàn 是 n；不当意思是不恰当，不是不但。"}], "explanations": {"不但": "不但读作 bú dàn，表示进一层，常与“而且”连用。", "不断": "dàn 与 duàn 的韵母不同，duàn 多一个 u，不断意思是持续，不是不但。", "不大": "dàn 与 dà 的韵尾不同，dàn 有 n，dà 没有，不大意思是不是很大。", "不带": "dàn 与 dài 的韵尾不同，n 变成了 i，不带意思是不携带。", "不当": "韵尾不同：dàng 是 ng，dàn 是 n；不当意思是不恰当，不是不但。"}, "sentence_index": null, "correct_answer": "不但"}, "level_3": {"options": [{"text": "不但", "is_correct": true, "explanation": "不但：表示进一层，与后面的“而且”呼应，填入后句子通顺。"}, {"text": "虽然", "is_correct": false, "explanation": "语义：“虽然”表示让步，句中并无让步之意，与表递进的“而且”不合，句意不通。"}, {"text": "或者", "is_correct": false, "explanation": "语义：“或者”表示选择，与表递进的“而且”意思不合，句子不通。"}, {"text": "只要", "is_correct": false, "explanation": "搭配：“只要”引出条件，后面须用“就”呼应，句中没有“就”，句意不通。"}], "explanations": {"不但": "不但：表示进一层，与后面的“而且”呼应，填入后句子通顺。", "虽然": "语义：“虽然”表示让步，句中并无让步之意，与表递进的“而且”不合，句意不通。", "或者": "语义：“或者”表示选择，与表递进的“而且”意思不合，句子不通。", "只要": "搭配：“只要”引出条件，后面须用“就”呼应，句中没有“就”，句意不通。"}, "sentence_index": 0, "correct_answer": "不但"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这里风景很美，不但空气不好。", "explanation": "这里应该用〈但是〉。不但表示进一层，前后应是同向补充；这里前后转折，要用“但是”。"}, {"text": "他很努力，不但没有成功。", "explanation": "这里应该用〈却〉。不但表示递进，不表示转折；“很努力”与“没有成功”意思相反，要用“却”。"}, {"text": "他不是老师，不但是医生。", "explanation": "这里应该用〈而是〉。不但不能用来引出对否定内容的更正，“不是……而是……”才是正确的格式。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '77fea57d-2c72-4f76-b2b2-2be0aacd67c3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90654, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "不但", "is_correct": true, "explanation": "不但：表示进一层，与后面的“而且”呼应，填入后句子通顺。"}, {"text": "所以", "is_correct": false, "explanation": "搭配：“所以”表示因果，前面要有“因为”呼应，与表递进的“而且”不合。"}, {"text": "然而", "is_correct": false, "explanation": "搭配：“然而”表示转折，多用于句首，接在主语后不通，与“而且”的递进意思也冲突。"}, {"text": "不然", "is_correct": false, "explanation": "语义：“不然”表示否则，引出不利后果，与“干净”“服务很好”的正面意思相反。"}], "explanations": {"不但": "不但：表示进一层，与后面的“而且”呼应，填入后句子通顺。", "所以": "搭配：“所以”表示因果，前面要有“因为”呼应，与表递进的“而且”不合。", "然而": "搭配：“然而”表示转折，多用于句首，接在主语后不通，与“而且”的递进意思也冲突。", "不然": "语义：“不然”表示否则，引出不利后果，与“干净”“服务很好”的正面意思相反。"}, "sentence_index": 6, "correct_answer": "不但"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他没复习，不但考砸了。", "explanation": "这里应该用〈所以〉。不但表示递进，不表示因果；“没复习”与“考砸了”是原因和结果关系。"}, {"text": "不但刮风下雨，我们都要去跑步。", "explanation": "这里应该用〈无论〉。不但表示补充，不表示无论条件如何都要……；“无论……都……”才表示无条件。"}, {"text": "我们走了很久，不但到了目的地。", "explanation": "这里应该用〈终于〉。不但表示递进，不表示经过一段时间后出现的结果，“终于到了”才符合语境。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '77fea57d-2c72-4f76-b2b2-2be0aacd67c3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90654, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "她不但会弹钢琴，但是会唱歌。", "corrected_sentence": "她不但会弹钢琴，而且会唱歌。", "error_description": "连词用错：“但是”表示转折，与“不但”搭配不通，应为“而且”，即“她不但会弹钢琴，而且会唱歌”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '77fea57d-2c72-4f76-b2b2-2be0aacd67c3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90654, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他不但会画画，而是会写诗。", "corrected_sentence": "他不但会画画，还会写诗。", "error_description": "“而是”用错，应为“还”。“而是”表示对否定内容的更正，与表示递进的“不但”不搭，“不但……还……”才通顺。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '77fea57d-2c72-4f76-b2b2-2be0aacd67c3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
