INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90655, 1, 'prompt1_core', '{"pos": "代词", "semantic_class": "function", "definition": "什么事是问发生了什么，或者要做什么。", "primary_collocate": null, "pronunciation": "shén me shì", "ipa": "ʂən˧˥ mɤ ʂʐ̩˥˩", "syllable_count": 3, "sentences": [{"text": "你怎么了？出什么事了？", "target_word": "什么事", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这么晚了，你找我有什么事？", "target_word": "什么事", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "外面这么吵，出了什么事？", "target_word": "什么事", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你明天有什么事吗？想请你吃饭。", "target_word": "什么事", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他的脸色不好，是不是有什么事？", "target_word": "什么事", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "经理叫我去，要我做什么事？", "target_word": "什么事", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你敲门，有什么事要我帮忙吗？", "target_word": "什么事", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "大家都跑出去了，发生什么事了？", "target_word": "什么事", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他一直看着手机，有什么事吗？", "target_word": "什么事", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师很生气，你们做了什么事？", "target_word": "什么事", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "什麼事", "label": "繁体"}, {"form": "什么事情", "label": "复合"}], "register": "口语", "sense_fingerprint": "问发生了什么，或者要做什么", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cc24a53f-6254-4aa5-8e47-0703e4066dea') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90655, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "什么事", "is_correct": true, "explanation": "“出什么事”是固定说法，问发生了什么。"}, {"text": "什么人", "is_correct": false, "explanation": "搭配：“出了什么人”不成说法，发生的情况要说“出了什么事”。"}, {"text": "什么地方", "is_correct": false, "explanation": "搭配：“出什么地方”不成说法，发生情况应说“出什么事”。"}, {"text": "什么东西", "is_correct": false, "explanation": "搭配：“出什么东西”不是固定说法，问发生了什么应说“出什么事”。"}], "explanations": {"什么事": "“出什么事”是固定说法，问发生了什么。", "什么人": "搭配：“出了什么人”不成说法，发生的情况要说“出了什么事”。", "什么地方": "搭配：“出什么地方”不成说法，发生情况应说“出什么事”。", "什么东西": "搭配：“出什么东西”不是固定说法，问发生了什么应说“出什么事”。"}, "sentence_index": 0, "correct_answer": "什么事"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我们去超市买什么事。", "explanation": "这里应该用〈什么东西〉。买的是物品，不能用“什么事”。"}, {"text": "他每天都在看什么事。", "explanation": "这里应该用〈什么书〉。看的是书报，不能用“什么事”。"}, {"text": "这么晚了，你还听什么事？", "explanation": "这里应该用〈什么音乐〉。听的是音乐，不能用“什么事”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f710dbc2-d2ea-4067-9e4f-b056b043fa1c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90655, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "什么事", "is_correct": true, "explanation": "“有什么事”问有没有需要做的事，与“要我帮忙”相符。"}, {"text": "谁", "is_correct": false, "explanation": "语义：“谁”问的是人，句中要问的是需要帮忙的事情。"}, {"text": "哪个", "is_correct": false, "explanation": "语义：“哪个”是从几个中选，句中并没有可供选择的对象。"}, {"text": "多少", "is_correct": false, "explanation": "搭配：“有多少要我帮忙”问数量，与“敲门”的情境不搭。"}], "explanations": {"什么事": "“有什么事”问有没有需要做的事，与“要我帮忙”相符。", "谁": "语义：“谁”问的是人，句中要问的是需要帮忙的事情。", "哪个": "语义：“哪个”是从几个中选，句中并没有可供选择的对象。", "多少": "搭配：“有多少要我帮忙”问数量，与“敲门”的情境不搭。"}, "sentence_index": 6, "correct_answer": "什么事"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他一直喝什么事。", "explanation": "这里应该用〈什么酒〉。喝的是饮品，不能用“什么事”。"}, {"text": "我想请你吃什么事。", "explanation": "这里应该用〈什么饭〉。吃的是食物，不能用“什么事”。"}, {"text": "我们正在用什么事。", "explanation": "这里应该用〈什么软件〉。用的是工具，不能用“什么事”指工具。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f710dbc2-d2ea-4067-9e4f-b056b043fa1c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90655, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我想知道你有一件什么事。", "corrected_sentence": "我想知道你有什么事。", "error_description": "数量词错误：“什么事”是疑问短语，前面不能加“一件”，应说“有什么事”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f710dbc2-d2ea-4067-9e4f-b056b043fa1c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90655, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "大家都在等，你到底做了的什么事？", "corrected_sentence": "大家都在等，你到底做了什么事？", "error_description": "助词错误：“做了的什么事”多出“的”，“的”不能插在“做了”与疑问短语“什么事”之间，应说“做了什么事”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f710dbc2-d2ea-4067-9e4f-b056b043fa1c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
