INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90663, 1, 'prompt1_core', '{"pos": "副词", "semantic_class": "function", "definition": "表示不管怎么样，结果都一样。", "primary_collocate": null, "pronunciation": "zài zěn me", "ipa": "tsai˥˩ tsən˨˩ mə", "syllable_count": 3, "sentences": [{"text": "你再怎么说，他也不会听。", "target_word": "再怎么", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "再怎么劝，他还是不肯去。", "target_word": "再怎么", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "你再怎么解释，她也不信。", "target_word": "再怎么", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "我再怎么找，也找不到那本书。", "target_word": "再怎么", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "再怎么哭，妈妈也不会同意。", "target_word": "再怎么", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他再怎么跑，也追不上火车了。", "target_word": "再怎么", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "孩子再怎么求，爸爸都不答应。", "target_word": "再怎么", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "你再怎么想，这件事也改不了。", "target_word": "再怎么", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "再怎么练习，他的口音还是没变。", "target_word": "再怎么", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "你再怎么问，我也不会告诉你。", "target_word": "再怎么", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [], "register": "口语", "sense_fingerprint": "再怎么：不管怎样做，结果都不变", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '53f807e0-8acf-42ca-93b2-48cbb7eb4cad') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90663, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "再怎么", "is_correct": true, "explanation": "正确。“再怎么”表示无论怎样结果都不变，与后句“他也不会听”呼应。"}, {"text": "忽然", "is_correct": false, "explanation": "语义：“忽然”表示突然发生，不能引出“不管你怎样说”的让步关系。"}, {"text": "立刻", "is_correct": false, "explanation": "语义：“立刻”表示时间紧接，不能引出“不管你怎样说”的让步关系。"}, {"text": "马上", "is_correct": false, "explanation": "语义：“马上”表示时间紧接，不能与“他也不会听”构成让步关系。"}], "explanations": {"再怎么": "正确。“再怎么”表示无论怎样结果都不变，与后句“他也不会听”呼应。", "忽然": "语义：“忽然”表示突然发生，不能引出“不管你怎样说”的让步关系。", "立刻": "语义：“立刻”表示时间紧接，不能引出“不管你怎样说”的让步关系。", "马上": "语义：“马上”表示时间紧接，不能与“他也不会听”构成让步关系。"}, "sentence_index": 0, "correct_answer": "再怎么"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "你再怎么说，他就听了。", "explanation": "这里用“就”引出“他就听了”，像把〈再怎么〉当成〈只要…就…〉的条件关系用，与让步义相反。"}, {"text": "他再怎么努力，昨天就考上了大学。", "explanation": "这里时间与结果错位：〈再怎么〉表示让步，后句须是不受影响的结果；这里用“昨天就”，把它当成〈一…就…〉的先后顺序来用，与词义不符。"}, {"text": "孩子再怎么哭，妈妈就同意了。", "explanation": "这里用“就”把“哭”与“同意”说成条件关系，像〈只要…就…〉，与〈再怎么〉表示的让步义相反。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '718050bc-321d-406a-9188-a4a097c777a8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90663, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "再怎么", "is_correct": true, "explanation": "正确。“再怎么”表示无论怎样结果都不变，与“爸爸都不答应”呼应。"}, {"text": "猛然", "is_correct": false, "explanation": "语域：“猛然”偏书面，且表示突发，与这句口语的让步语气不合。"}, {"text": "根本", "is_correct": false, "explanation": "搭配：“根本”须与否定词连用（如“根本不”），此处无否定，句子不通。"}, {"text": "非常", "is_correct": false, "explanation": "搭配：“非常”是程度副词，不能修饰“求”这类动作动词，句子不通。"}], "explanations": {"再怎么": "正确。“再怎么”表示无论怎样结果都不变，与“爸爸都不答应”呼应。", "猛然": "语域：“猛然”偏书面，且表示突发，与这句口语的让步语气不合。", "根本": "搭配：“根本”须与否定词连用（如“根本不”），此处无否定，句子不通。", "非常": "搭配：“非常”是程度副词，不能修饰“求”这类动作动词，句子不通。"}, "sentence_index": 6, "correct_answer": "再怎么"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我再怎么忙，所以今天的作业做完了。", "explanation": "〈再怎么〉表示让步，后句须是不受影响的结果；这里用“所以”引出因果结果，把它当成〈因为…所以…〉来用，与让步义相反。"}, {"text": "他再怎么穷，就买了一辆新车。", "explanation": "〈再怎么〉表示让步，后句结果不受影响；这里用“就”引出结果，等于把它当成〈只要…就…〉的条件关系用，与让步义不符。"}, {"text": "这件衣服再怎么便宜，我就买了它。", "explanation": "〈再怎么〉表示让步，后句须是不受影响的结果；这里“就买了它”把结果说成因条件而改变，与词义不符。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '718050bc-321d-406a-9188-a4a097c777a8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90663, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "你再怎么催，他就会快一点。", "corrected_sentence": "你再怎么催，他也不会快一点。", "error_description": "错误：“也”误作“就”。“再怎么”后应接“也”或“都”，引出不受影响的结果；用“就”后句变成条件关系，与“再怎么”的让步意思不符。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '718050bc-321d-406a-9188-a4a097c777a8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90663, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "她再怎么胖，就很健康。", "corrected_sentence": "她再怎么胖，也很健康。", "error_description": "错误：“也”误作“就”。“再怎么”后句应用“也”或“都”，引出不受影响的结果；用“就”后句变成条件关系，与“再怎么”的让步意思不符。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '718050bc-321d-406a-9188-a4a097c777a8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
