INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90675, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "参加跑步、打球这些比赛的人。", "primary_collocate": null, "pronunciation": "yùn dòng yuán", "ipa": "yn˥˩ tʊŋ˥˩ ɥɛn˧˥", "syllable_count": 3, "sentences": [{"text": "这位运动员跑得很快。", "target_word": "运动员", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他是一名跑步运动员。", "target_word": "运动员", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "比赛前，运动员都在热身。", "target_word": "运动员", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我弟弟想当篮球运动员。", "target_word": "运动员", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "那个运动员正在打球。", "target_word": "运动员", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "运动员们在操场上比赛。", "target_word": "运动员", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她是我们学校的游泳运动员。", "target_word": "运动员", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "运动员听到哨声就跑了出去。", "target_word": "运动员", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "观众给运动员送上了花。", "target_word": "运动员", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这场比赛有五十个运动员参加。", "target_word": "运动员", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "名", "label": "量词"}, {"form": "位", "label": "量词"}, {"form": "个", "label": "量词"}, {"form": "运动员们", "label": "复数"}], "register": "中性", "sense_fingerprint": "运动员：参加跑步、打球等比赛的人", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '56b12eb9-afc4-4062-9387-4ca205bf21c6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90675, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "运动员", "is_correct": true, "explanation": "与“跑得很快”搭配，指参加跑步比赛的人，符合句意。"}, {"text": "病人", "is_correct": false, "explanation": "语义：病人身体不适，一般跑不快，与“跑得很快”的描述相矛盾。"}, {"text": "孕妇", "is_correct": false, "explanation": "语义：孕妇行动不便，与“跑得很快”的描述相矛盾。"}, {"text": "婴儿", "is_correct": false, "explanation": "体貌：婴儿身体尚未发育，无法跑得很快。"}], "explanations": {"运动员": "与“跑得很快”搭配，指参加跑步比赛的人，符合句意。", "病人": "语义：病人身体不适，一般跑不快，与“跑得很快”的描述相矛盾。", "孕妇": "语义：孕妇行动不便，与“跑得很快”的描述相矛盾。", "婴儿": "体貌：婴儿身体尚未发育，无法跑得很快。"}, "sentence_index": 0, "correct_answer": "运动员"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他是这次运动会的运动员，负责安排场地。", "explanation": "这里应该用〈工作人员〉。运动员指参加比赛的人，不负责安排场地；负责组织工作的人要说“工作人员”。"}, {"text": "这些运动员坐在看台上观看，今天没有人参加比赛。", "explanation": "这里应该用〈观众〉。运动员是参加比赛的人，今天没有人比赛，坐在看台上观看的人要说“观众”。"}, {"text": "运动员公平地判罚了犯规的球员。", "explanation": "这里应该用〈裁判〉。运动员是参加比赛的人，不负责判罚犯规的球员；执行判罚的人要说“裁判”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b20cafd5-e15b-4ea5-a683-a410d336d823') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90675, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "运动员", "is_correct": true, "explanation": "与“游泳”“学校”的语境搭配，指参加游泳比赛的人，符合句意。"}, {"text": "作家", "is_correct": false, "explanation": "搭配：“游泳”不能修饰“作家”，“游泳作家”不是常用说法。"}, {"text": "厨师", "is_correct": false, "explanation": "语义：厨师的工作与游泳比赛无关，与句意不符。"}, {"text": "律师", "is_correct": false, "explanation": "语义：律师的工作与游泳无关，与句意相悖。"}], "explanations": {"运动员": "与“游泳”“学校”的语境搭配，指参加游泳比赛的人，符合句意。", "作家": "搭配：“游泳”不能修饰“作家”，“游泳作家”不是常用说法。", "厨师": "语义：厨师的工作与游泳比赛无关，与句意不符。", "律师": "语义：律师的工作与游泳无关，与句意相悖。"}, "sentence_index": 6, "correct_answer": "运动员"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "运动员每天给病人打针。", "explanation": "这里应该用〈护士〉。运动员指参加比赛的人，不做医疗工作。"}, {"text": "我姐姐在饭店里当运动员，每天负责炒菜。", "explanation": "这里应该用〈厨师〉。运动员指参加比赛的人，不能用来指在饭店里炒菜的人。"}, {"text": "运动员每天在商场门口卖水果，从不参加比赛。", "explanation": "这里应该用〈小贩〉。运动员指参加比赛的人，不指在门口卖水果的人。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b20cafd5-e15b-4ea5-a683-a410d336d823') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90675, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他是一只优秀的运动员，每天训练很努力。", "corrected_sentence": "他是一名优秀的运动员，每天训练很努力。", "error_description": "“一只”是动物或物品的量词，指人的“运动员”应用“一名”，应把“只”改为“名”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b20cafd5-e15b-4ea5-a683-a410d336d823') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90675, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我们班有两名运动员们。", "corrected_sentence": "我们班有两名运动员。", "error_description": "“运动员们”表示复数，不能与具体数量“两名”连用，应去掉“们”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b20cafd5-e15b-4ea5-a683-a410d336d823') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
