INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90676, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "参加体育运动训练和比赛的人。", "primary_collocate": null, "pronunciation": "yùn dòng yuán", "ipa": "yn˥˩ tʊŋ˥˩ ɥɛn˧˥", "syllable_count": 3, "sentences": [{"text": "这位运动员每天都要进行六个小时的体能训练。", "target_word": "运动员", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这名运动员训练非常努力。", "target_word": "运动员", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "运动员要吃得健康，睡得早。", "target_word": "运动员", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他从小就是体校的运动员。", "target_word": "运动员", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "受伤的运动员不能参加比赛。", "target_word": "运动员", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "国家队的运动员住在一起。", "target_word": "运动员", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "教练带着运动员去外地比赛。", "target_word": "运动员", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她想成为一名优秀的运动员。", "target_word": "运动员", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "运动员的身体一定要好。", "target_word": "运动员", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这位老运动员已经退休了。", "target_word": "运动员", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "名", "label": "量词"}, {"form": "位", "label": "量词"}, {"form": "个", "label": "量词"}, {"form": "运动员们", "label": "复数"}], "register": "中性", "sense_fingerprint": "运动员：经常训练并参加体育比赛的人", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '56b12eb9-afc4-4062-9387-4ca205bf21c6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90676, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "运动员", "is_correct": true, "explanation": "与“体能训练”搭配，指经常训练的人，符合句意。"}, {"text": "作家", "is_correct": false, "explanation": "搭配：“训练”用于体能、技能，不说作家“训练六个小时”。"}, {"text": "厨师", "is_correct": false, "explanation": "搭配：“厨师”一般不说“训练六个小时”，与句意不合。"}, {"text": "病人", "is_correct": false, "explanation": "语义：病人身体不适，不宜每天训练六个小时，与句意相悖。"}], "explanations": {"运动员": "与“体能训练”搭配，指经常训练的人，符合句意。", "作家": "搭配：“训练”用于体能、技能，不说作家“训练六个小时”。", "厨师": "搭配：“厨师”一般不说“训练六个小时”，与句意不合。", "病人": "语义：病人身体不适，不宜每天训练六个小时，与句意相悖。"}, "sentence_index": 0, "correct_answer": "运动员"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他每次都坐在看台上观看比赛，从不参加训练，却是一名运动员。", "explanation": "这里应该用〈观众〉。运动员要参加训练和比赛，从不训练的人不能称为运动员；只坐在看台上观看的人要说“观众”。"}, {"text": "他每天在医院里给病人看病，是运动员。", "explanation": "这里应该用〈医生〉。运动员指参加比赛的人，不做看病的工作。"}, {"text": "运动员在比赛中公平地判罚了犯规的球员。", "explanation": "这里应该用〈裁判〉。运动员是参加训练和比赛的人，不负责判罚；执行判罚的人要说“裁判”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b20cafd5-e15b-4ea5-a683-a410d336d823') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90676, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "运动员", "is_correct": true, "explanation": "与“教练带着”“去外地比赛”的语境搭配，指参加比赛的人，符合句意。"}, {"text": "游客", "is_correct": false, "explanation": "语义：游客是观光的人，不参加比赛，与句意不符。"}, {"text": "冰箱", "is_correct": false, "explanation": "语义：冰箱是家用电器，不能参加比赛，与句意不符。"}, {"text": "乘客", "is_correct": false, "explanation": "语义：乘客是乘车或乘船的人，不参加比赛，与句意不符。"}], "explanations": {"运动员": "与“教练带着”“去外地比赛”的语境搭配，指参加比赛的人，符合句意。", "游客": "语义：游客是观光的人，不参加比赛，与句意不符。", "冰箱": "语义：冰箱是家用电器，不能参加比赛，与句意不符。", "乘客": "语义：乘客是乘车或乘船的人，不参加比赛，与句意不符。"}, "sentence_index": 6, "correct_answer": "运动员"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这位运动员每天在教室里给学生讲数学。", "explanation": "这里应该用〈教师〉。运动员指参加比赛的人，不做教书的工作。"}, {"text": "这位运动员从不训练，每天只在舞台上唱歌。", "explanation": "这里应该用〈歌手〉。运动员要参加体育训练和比赛，从不训练、只在舞台上唱歌的人要说“歌手”。"}, {"text": "运动员每天在家写历史书，从不参加任何训练。", "explanation": "这里应该用〈作家〉。运动员要参加体育训练和比赛，不训练而在家写书的人要说“作家”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b20cafd5-e15b-4ea5-a683-a410d336d823') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90676, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他是一只运动员，每天训练很辛苦。", "corrected_sentence": "他是一名运动员，每天训练很辛苦。", "error_description": "“一只”是动物或物品的量词，指人的“运动员”应用“一名”，应把“只”改为“名”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b20cafd5-e15b-4ea5-a683-a410d336d823') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90676, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "比赛结束后，两名运动员们都很累。", "corrected_sentence": "比赛结束后，两名运动员都很累。", "error_description": "“运动员们”表示复数，不能与具体数量“两名”连用，应去掉“们”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b20cafd5-e15b-4ea5-a683-a410d336d823') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
