INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90687, 1, 'prompt1_core', '{"pos": "副词", "semantic_class": "function", "definition": "在此是在这个地方，或者在这个时候。", "primary_collocate": null, "pronunciation": "zài cǐ", "ipa": "tsai˥˩ tsʰɿ˨˩˦", "syllable_count": 2, "sentences": [{"text": "我们在此等你。", "target_word": "在此", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请大家在此休息一下。", "target_word": "在此", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "在此，我要谢谢大家。", "target_word": "在此", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请不要在此停车。", "target_word": "在此", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我在此住了三年。", "target_word": "在此", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师在此等着大家。", "target_word": "在此", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "会议在此结束，谢谢大家。", "target_word": "在此", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "今天能在此见面，我很高兴。", "target_word": "在此", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他曾经在此学习过。", "target_word": "在此", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "在此之前，我从没来过这里。", "target_word": "在此", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "书面", "sense_fingerprint": "在此：在这个地方，或在这个时候（书面）", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e47ca02c-da77-46cf-8e0b-0a9f8df1a1a3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90687, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "在此", "is_correct": true, "explanation": "正确：“我们在此等你”中的“在此”，表示在这个地方。"}, {"text": "忽然", "is_correct": false, "explanation": "语义：“忽然”表示突然，与“等你”这种持续的等待不合。"}, {"text": "立刻", "is_correct": false, "explanation": "语义：“立刻”表示马上，与“等你”这种持续的等待不合。"}, {"text": "格外", "is_correct": false, "explanation": "搭配：“格外”表示特别、分外，不用来修饰“等”这种动作。"}], "explanations": {"在此": "正确：“我们在此等你”中的“在此”，表示在这个地方。", "忽然": "语义：“忽然”表示突然，与“等你”这种持续的等待不合。", "立刻": "语义：“立刻”表示马上，与“等你”这种持续的等待不合。", "格外": "搭配：“格外”表示特别、分外，不用来修饰“等”这种动作。"}, "sentence_index": 0, "correct_answer": "在此"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "在此，我昨天收到了一封信。", "explanation": "这里应该用〈那时〉。“在此”指说话的这个时候，不能与过去的时间同用。"}, {"text": "在此，我明年要去国外读书。", "explanation": "这里应该用〈以后〉。“在此”指说话的这个时候，不能与将来的时间同用。"}, {"text": "我明天要在此去上海。", "explanation": "这里应该用〈从这里〉。“在此”表示位置，不能表示出发的地点。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '19390a79-ee61-422e-b23d-01f3660db1ca') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90687, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "在此", "is_correct": true, "explanation": "正确：“会议在此结束”中的“在此”，表示在这个地方或这个时候。"}, {"text": "反复", "is_correct": false, "explanation": "语义：“反复”表示多次重复，与一次性的“结束”不合。"}, {"text": "偶尔", "is_correct": false, "explanation": "语义：“偶尔”表示有时，与会议的结束这一事件不合。"}, {"text": "格外", "is_correct": false, "explanation": "搭配：“格外”修饰程度，不用来修饰“结束”这种动作。"}], "explanations": {"在此": "正确：“会议在此结束”中的“在此”，表示在这个地方或这个时候。", "反复": "语义：“反复”表示多次重复，与一次性的“结束”不合。", "偶尔": "语义：“偶尔”表示有时，与会议的结束这一事件不合。", "格外": "搭配：“格外”修饰程度，不用来修饰“结束”这种动作。"}, "sentence_index": 6, "correct_answer": "在此"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "在此我去年来过三次北京。", "explanation": "这里应该用〈那时〉。“在此”指说话的这个时候，不能用来叙述过去的一段时间。"}, {"text": "在此，我们明天就要出发。", "explanation": "这里应该用〈以后〉。“在此”指说话的这个时候，不能与将来的时间同用。"}, {"text": "我们在此去上海玩吧。", "explanation": "这里应该用〈从这里〉。“在此”表示位置，不能表示出发的地点。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '19390a79-ee61-422e-b23d-01f3660db1ca') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90687, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "请大家在此这里签名。", "corrected_sentence": "请大家在此签名。", "error_description": "“在此”已表示地点，后面不能再加“这里”，应说“在此签名”，错误是多出了“这里”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '19390a79-ee61-422e-b23d-01f3660db1ca') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90687, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他在在此工作了三年。", "corrected_sentence": "他在此工作了三年。", "error_description": "“在”和“此”合成一个词“在此”，不能重复“在”，应说“在此工作”，错误是多出了一个“在”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '19390a79-ee61-422e-b23d-01f3660db1ca') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90693, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "窄", "is_correct": true, "explanation": "窄：与“宽”反义，指从一边到另一边的距离小。"}, {"text": "深", "is_correct": false, "explanation": "“深”说纵向的深浅，不与“宽”构成横向距离的反义。"}, {"text": "厚", "is_correct": false, "explanation": "“厚”说上下的厚薄，不与“宽”构成反义。"}, {"text": "高", "is_correct": false, "explanation": "“高”说纵向的高低，不与“宽”构成横向距离的反义。"}], "correct_answer": "窄", "explanations": {"窄": "窄：与“宽”反义，指从一边到另一边的距离小。", "深": "“深”说纵向的深浅，不与“宽”构成横向距离的反义。", "厚": "“厚”说上下的厚薄，不与“宽”构成反义。", "高": "“高”说纵向的高低，不与“宽”构成横向距离的反义。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '77fea57d-2c72-4f76-b2b2-2be0aacd67c3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90693, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "窄", "is_correct": true, "explanation": "窄：与“宽”反义，指从一边到另一边的距离小。"}, {"text": "浅", "is_correct": false, "explanation": "“浅”说深浅，不与“宽”构成横向距离的反义。"}, {"text": "薄", "is_correct": false, "explanation": "“薄”说厚薄，不与“宽”构成反义。"}, {"text": "短", "is_correct": false, "explanation": "“短”说长短，不与“宽”构成横向距离的反义。"}], "correct_answer": "窄", "explanations": {"窄": "窄：与“宽”反义，指从一边到另一边的距离小。", "浅": "“浅”说深浅，不与“宽”构成横向距离的反义。", "薄": "“薄”说厚薄，不与“宽”构成反义。", "短": "“短”说长短，不与“宽”构成横向距离的反义。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '77fea57d-2c72-4f76-b2b2-2be0aacd67c3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90693, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "宽是从这一边到那一边很远。路很宽，车就好走。", "primary_collocate": null, "pronunciation": "kuān", "ipa": "kʰuan˥", "syllable_count": 1, "sentences": [{"text": "这条路很宽。", "target_word": "宽", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "河面很宽，对岸看不清。", "target_word": "宽", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "路很宽，两辆车可以一起走。", "target_word": "宽", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这张桌子太宽，放不进小房间。", "target_word": "宽", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他的肩膀很宽，背着大包也不累。", "target_word": "宽", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "门不够宽，大沙发搬不进来。", "target_word": "宽", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这条街比那条街宽多了。", "target_word": "宽", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "我们走过了一条很宽的大街。", "target_word": "宽", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你的床有多宽？", "target_word": "宽", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "这座桥又宽又平，车可以并排开。", "target_word": "宽", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "宽宽的", "label": "重叠"}, {"form": "宽大", "label": "复合"}, {"form": "宽度", "label": "复合"}, {"form": "寬", "label": "繁体"}], "register": "中性", "sense_fingerprint": "物体或地方从一边到另一边的距离大，如路宽、河宽", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '897c13e4-9594-468f-af81-93c04019cc00') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90693, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "宽", "is_correct": true, "explanation": "宽：从一边到另一边的距离大，用来形容路，句子通顺。"}, {"text": "深", "is_correct": false, "explanation": "语义：“深”说纵向的深浅，路面不说深，句子不通。"}, {"text": "厚", "is_correct": false, "explanation": "语义：“厚”说物体上下的厚度，不用于说路的横向距离。"}, {"text": "胖", "is_correct": false, "explanation": "体貌：“胖”只用于人或动物的身形，不能用来形容路。"}], "explanations": {"宽": "宽：从一边到另一边的距离大，用来形容路，句子通顺。", "深": "语义：“深”说纵向的深浅，路面不说深，句子不通。", "厚": "语义：“厚”说物体上下的厚度，不用于说路的横向距离。", "胖": "体貌：“胖”只用于人或动物的身形，不能用来形容路。"}, "sentence_index": 0, "correct_answer": "宽"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这个假期很宽，我们可以去很多地方。", "explanation": "这里应该用〈长〉。宽说横向距离，时间的长短要用“长”。"}, {"text": "他的声音很宽，大家都听得清。", "explanation": "这里应该用〈大〉。宽只用于物体或地方的横向距离，声音的强弱要用“大”。"}, {"text": "这件衣服的价格很宽。", "explanation": "这里应该用〈高〉。宽不用于价格，价格的高低要用“高”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '77fea57d-2c72-4f76-b2b2-2be0aacd67c3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90693, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "宽", "is_correct": true, "explanation": "宽：这里比较两条街的横向距离，填入后句子通顺。"}, {"text": "轻", "is_correct": false, "explanation": "语义：“轻”说重量，街道不用轻重来比较，句子不通。"}, {"text": "矮", "is_correct": false, "explanation": "语义：“矮”说高度，街道的横向距离不用“矮”来形容。"}, {"text": "瘦", "is_correct": false, "explanation": "体貌：“瘦”只用于人或动物的身形，不能用来比较街道。"}], "explanations": {"宽": "宽：这里比较两条街的横向距离，填入后句子通顺。", "轻": "语义：“轻”说重量，街道不用轻重来比较，句子不通。", "矮": "语义：“矮”说高度，街道的横向距离不用“矮”来形容。", "瘦": "体貌：“瘦”只用于人或动物的身形，不能用来比较街道。"}, "sentence_index": 6, "correct_answer": "宽"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这首歌的节奏很宽。", "explanation": "这里应该用〈慢〉。宽说横向距离，节奏的快慢要用“慢”或“快”。"}, {"text": "他的病情很宽。", "explanation": "这里应该用〈好〉。宽不用于病情，病情的好坏要用“好”。"}, {"text": "今天的天气很宽。", "explanation": "这里应该用〈热〉。宽不用于天气，天气的冷热要用“热”或“冷”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '77fea57d-2c72-4f76-b2b2-2be0aacd67c3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90693, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这座门宽很，大车能开进去。", "corrected_sentence": "这座门很宽，大车能开进去。", "error_description": "语序错误：程度副词“很”要放在形容词前面，“宽很”错误，应为“很宽”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '77fea57d-2c72-4f76-b2b2-2be0aacd67c3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90693, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这个广场很宽度，可以放很多桌子。", "corrected_sentence": "这个广场很宽，可以放很多桌子。", "error_description": "用词错误：“宽度”是名词，形容词“宽”后不能直接加“度”，这里应说“很宽”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '77fea57d-2c72-4f76-b2b2-2be0aacd67c3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
