INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90703, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "property", "definition": "像香蕉皮、像太阳一样的颜色。", "primary_collocate": null, "pronunciation": "huáng sè", "ipa": "xwaŋ˧˥ sɤ˥˩", "syllable_count": 2, "sentences": [{"text": "香蕉熟了，皮是黄色的。", "target_word": "黄色", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这件雨衣是黄色的，下雨时很显眼。", "target_word": "黄色", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我喜欢黄色的衣服，像太阳一样。", "target_word": "黄色", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "她的新书包是黄色的。", "target_word": "黄色", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "请把黄色的笔给我。", "target_word": "黄色", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这辆出租车是黄色的，很容易看见。", "target_word": "黄色", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "小鸡身上的毛是黄色的。", "target_word": "黄色", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "他把房间的墙刷成了黄色。", "target_word": "黄色", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "黄色和蓝色放在一起很好看。", "target_word": "黄色", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "孩子画了一个黄色的太阳。", "target_word": "黄色", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "黃色", "label": "繁体"}, {"form": "淡黄色", "label": "复合"}], "register": "中性", "sense_fingerprint": "黄色-像香蕉皮、太阳的颜色", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5ac86440-8f5a-4834-8135-427d86e72be0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90703, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "黄色", "is_correct": true, "explanation": "香蕉熟后皮呈黄色，与“熟了”相符。"}, {"text": "蓝色", "is_correct": false, "explanation": "语义：香蕉熟了以后，皮不会变成蓝色，与“熟了”的颜色变化相矛盾。"}, {"text": "绿色", "is_correct": false, "explanation": "语义：绿色是未熟香蕉的颜色，与“熟了”相矛盾。"}, {"text": "赭色", "is_correct": false, "explanation": "语域：赭色是书面色名，口语描述香蕉皮一般不用；且赭色偏暗褐，与“熟了”后的鲜黄不符。"}], "explanations": {"黄色": "香蕉熟后皮呈黄色，与“熟了”相符。", "蓝色": "语义：香蕉熟了以后，皮不会变成蓝色，与“熟了”的颜色变化相矛盾。", "绿色": "语义：绿色是未熟香蕉的颜色，与“熟了”相矛盾。", "赭色": "语域：赭色是书面色名，口语描述香蕉皮一般不用；且赭色偏暗褐，与“熟了”后的鲜黄不符。"}, "sentence_index": 0, "correct_answer": "黄色"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他这几天没睡好，脸色黄色的。", "explanation": "这里应该用〈蜡黄〉形容病后的脸色。〈黄色〉是颜色名，不能直接用来描述脸色。"}, {"text": "他这次考试的黄色很好。", "explanation": "这里应该用〈成绩〉。〈黄色〉只表示颜色，不能指考试结果。"}, {"text": "这是一次难得的黄色机会。", "explanation": "这里应该用〈黄金〉，表示珍贵、难得。〈黄色〉只表示颜色，不能用来修饰“机会”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '54d136a2-1535-496c-b74e-b1f72dabe9c2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90703, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "黄色", "is_correct": true, "explanation": "小鸡身上的绒毛常见黄色，与句意相符。"}, {"text": "紫色", "is_correct": false, "explanation": "语义：小鸡身上的毛不是紫色，与“小鸡”的常见毛色不符。"}, {"text": "红色", "is_correct": false, "explanation": "语义：小鸡的毛通常不是红色，句中也没有暗示这种颜色。"}, {"text": "绛色", "is_correct": false, "explanation": "语域：绛色是书面色名，口语描述小鸡毛色不用；且绛为深红，与小鸡的浅色绒毛不符。"}], "explanations": {"黄色": "小鸡身上的绒毛常见黄色，与句意相符。", "紫色": "语义：小鸡身上的毛不是紫色，与“小鸡”的常见毛色不符。", "红色": "语义：小鸡的毛通常不是红色，句中也没有暗示这种颜色。", "绛色": "语域：绛色是书面色名，口语描述小鸡毛色不用；且绛为深红，与小鸡的浅色绒毛不符。"}, "sentence_index": 6, "correct_answer": "黄色"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这件衣服的价格很黄色，大家都觉得贵。", "explanation": "这里“黄色”是颜色词，不能用来形容价格。应说〈贵〉或〈便宜〉。"}, {"text": "明天的天气很黄色，我们别出门了。", "explanation": "这里“黄色”只表示颜色，不能形容天气。应说〈阴沉〉或〈晴朗〉。"}, {"text": "这道菜的味道很黄色，我吃不下去。", "explanation": "这里“黄色”只表示颜色，不能形容味道。应说〈咸〉或〈难吃〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '54d136a2-1535-496c-b74e-b1f72dabe9c2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90703, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我的书包很黄色的，很好认。", "corrected_sentence": "我的书包是黄色的，很好认。", "error_description": "“黄色”作表语要用“是……的”，不能直接受“很”修饰。应说“是黄色的”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '54d136a2-1535-496c-b74e-b1f72dabe9c2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90703, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这张纸很黄色的，有点旧了。", "corrected_sentence": "这张纸是黄色的，有点旧了。", "error_description": "“黄色”作表语要用“是……的”，不能直接受“很”修饰。应说“是黄色的”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '54d136a2-1535-496c-b74e-b1f72dabe9c2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
