INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90704, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "property", "definition": "像成熟的香蕉皮、向日葵花那样的颜色。", "primary_collocate": null, "pronunciation": "huáng sè", "ipa": "xwaŋ˧˥ sɤ˥˩", "syllable_count": 2, "sentences": [{"text": "向日葵开花了，花瓣是黄色的。", "target_word": "黄色", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "熟透的香蕉皮变成了黄色。", "target_word": "黄色", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这片向日葵田，一眼看去全是黄色。", "target_word": "黄色", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "青香蕉放几天，就会变成黄色。", "target_word": "黄色", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "花瓶里插着黄色的向日葵。", "target_word": "黄色", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "成熟的香蕉是漂亮的黄色。", "target_word": "黄色", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "向日葵的花盘四周是明亮的黄色。", "target_word": "黄色", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "她用黄色的颜料画向日葵。", "target_word": "黄色", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这根香蕉的皮是黄色的，已经熟了。", "target_word": "黄色", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "夏天的田野里，黄色的向日葵开得很美。", "target_word": "黄色", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "黃色", "label": "繁体"}, {"form": "淡黄色", "label": "复合"}], "register": "中性", "sense_fingerprint": "黄色-像成熟香蕉皮、向日葵花的颜色", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5ac86440-8f5a-4834-8135-427d86e72be0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90704, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "黄色", "is_correct": true, "explanation": "向日葵的花瓣呈黄色，与句意相符。"}, {"text": "蓝色", "is_correct": false, "explanation": "语义：向日葵的花瓣不是蓝色，与“向日葵开花”的常见颜色不符。"}, {"text": "紫色", "is_correct": false, "explanation": "语义：向日葵的花瓣不是紫色，与句中的“向日葵”不相符。"}, {"text": "绛色", "is_correct": false, "explanation": "语域：绛色是书面色名，口语描述向日葵花瓣不用；且绛为深红，与向日葵不符。"}], "explanations": {"黄色": "向日葵的花瓣呈黄色，与句意相符。", "蓝色": "语义：向日葵的花瓣不是蓝色，与“向日葵开花”的常见颜色不符。", "紫色": "语义：向日葵的花瓣不是紫色，与句中的“向日葵”不相符。", "绛色": "语域：绛色是书面色名，口语描述向日葵花瓣不用；且绛为深红，与向日葵不符。"}, "sentence_index": 0, "correct_answer": "黄色"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这次面试的结果很黄色，大家都没想到。", "explanation": "这里“黄色”只表示颜色，不能形容结果。应说〈意外〉或〈出人意料〉。"}, {"text": "这首歌的节奏很黄色，听着很舒服。", "explanation": "这里“黄色”只表示颜色，不能形容节奏。应说〈轻快〉或〈缓慢〉。"}, {"text": "这次会议的气氛很黄色，大家都不说话。", "explanation": "这里“黄色”不能形容气氛。应说〈沉闷〉或〈热烈〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '54d136a2-1535-496c-b74e-b1f72dabe9c2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90704, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "黄色", "is_correct": true, "explanation": "向日葵的花盘呈明亮的黄色，与句意相符。"}, {"text": "红色", "is_correct": false, "explanation": "语义：向日葵的花盘四周不是红色，与“向日葵”的颜色不符。"}, {"text": "墨绿色", "is_correct": false, "explanation": "语义：墨绿色偏暗沉，与“明亮”的描述相矛盾。"}, {"text": "赭色", "is_correct": false, "explanation": "语域：赭色是书面色名，口语描述花盘颜色不用；且赭色暗褐，与“明亮”不符。"}], "explanations": {"黄色": "向日葵的花盘呈明亮的黄色，与句意相符。", "红色": "语义：向日葵的花盘四周不是红色，与“向日葵”的颜色不符。", "墨绿色": "语义：墨绿色偏暗沉，与“明亮”的描述相矛盾。", "赭色": "语域：赭色是书面色名，口语描述花盘颜色不用；且赭色暗褐，与“明亮”不符。"}, "sentence_index": 6, "correct_answer": "黄色"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "中国经济迎来了黄色时代。", "explanation": "这里应该用〈黄金〉，表示最好的时期。〈黄色〉只表示颜色，不能用来指一个时代。"}, {"text": "裁判向他拿出了黄色。", "explanation": "这里应该用〈黄牌〉，指足球比赛中的警告牌。〈黄色〉只表示颜色，不能指比赛中的牌子。"}, {"text": "这次考试的黄色很好，大家都很高兴。", "explanation": "这里应该用〈成绩〉。〈黄色〉只表示颜色，不能指考试结果。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '54d136a2-1535-496c-b74e-b1f72dabe9c2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90704, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "妈妈的围裙很黄色的，上面绣着花。", "corrected_sentence": "妈妈的围裙是黄色的，上面绣着花。", "error_description": "“黄色”作表语要用“是……的”，不能直接受“很”修饰。应说“是黄色的”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '54d136a2-1535-496c-b74e-b1f72dabe9c2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90704, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这串香蕉全熟了，皮很黄色的。", "corrected_sentence": "这串香蕉全熟了，皮是黄色的。", "error_description": "“黄色”作表语要用“是……的”，不能直接受“很”修饰。应说“是黄色的”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '54d136a2-1535-496c-b74e-b1f72dabe9c2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90707, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "成年", "is_correct": true, "explanation": "正确：成年与未成年互为反义词，指已经长大、达到成年年龄。"}, {"text": "健壮", "is_correct": false, "explanation": "健壮形容身体状况，不是“未成年”的反义词。"}, {"text": "温柔", "is_correct": false, "explanation": "温柔形容性情，与“未成年”的年龄概念无关，不构成反义。"}, {"text": "认真", "is_correct": false, "explanation": "认真形容做事的态度，与“未成年”没有反义关系。"}], "correct_answer": "成年", "explanations": {"成年": "正确：成年与未成年互为反义词，指已经长大、达到成年年龄。", "健壮": "健壮形容身体状况，不是“未成年”的反义词。", "温柔": "温柔形容性情，与“未成年”的年龄概念无关，不构成反义。", "认真": "认真形容做事的态度，与“未成年”没有反义关系。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '884bc76d-2bca-4740-b392-561903b984d1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90707, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "成年", "is_correct": true, "explanation": "正确：成年与未成年互为反义词，指已经长大、达到成年年龄。"}, {"text": "乐观", "is_correct": false, "explanation": "乐观形容对待生活的态度，不是“未成年”的反义词。"}, {"text": "稳重", "is_correct": false, "explanation": "稳重形容性格沉稳，与“未成年”没有反义关系。"}, {"text": "富有", "is_correct": false, "explanation": "富有形容拥有财富或某种丰富的品质，与“未成年”无关，不构成反义。"}], "correct_answer": "成年", "explanations": {"成年": "正确：成年与未成年互为反义词，指已经长大、达到成年年龄。", "乐观": "乐观形容对待生活的态度，不是“未成年”的反义词。", "稳重": "稳重形容性格沉稳，与“未成年”没有反义关系。", "富有": "富有形容拥有财富或某种丰富的品质，与“未成年”无关，不构成反义。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '884bc76d-2bca-4740-b392-561903b984d1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90707, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "未成年是说年纪还小，还没有长成大人。", "primary_collocate": null, "pronunciation": "wèi chéng nián", "ipa": "wei˥˩ ʈʂʰəŋ˧˥ njɛn˧˥", "syllable_count": 3, "sentences": [{"text": "他们还未成年，需要大人照顾。", "target_word": "未成年", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这些孩子都未成年，别让他们喝酒。", "target_word": "未成年", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他未成年，所以没有工作。", "target_word": "未成年", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个孩子未成年，还不懂很多事。", "target_word": "未成年", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她未成年的时候就一个人出国了。", "target_word": "未成年", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "未成年的弟弟很喜欢踢球。", "target_word": "未成年", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我侄子还未成年，平时只在家里玩。", "target_word": "未成年", "complexity_tier": "T3", "furigana": "wèi chéng nián", "sentence_source": "generated"}, {"text": "那个小男孩未成年，家里人都很爱他。", "target_word": "未成年", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "未成年的孩子要多睡觉。", "target_word": "未成年", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我妹妹还未成年，不能一个人去远处。", "target_word": "未成年", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "未成年人", "label": "复合"}, {"form": "未成年的", "label": "复合"}], "register": "中性", "sense_fingerprint": "未成年：年纪还小，还没长成大人", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd3f4d125-09bd-4a29-83b8-15c3ccd853c7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90707, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "未成年", "is_correct": true, "explanation": "正确：“未成年”说年纪还小，需要大人照顾，与句意相符。"}, {"text": "成年", "is_correct": false, "explanation": "语义：成年后一般不需要大人照顾，与后句“需要大人照顾”矛盾。"}, {"text": "独立", "is_correct": false, "explanation": "语义：独立的人不需要大人照顾，与后句“需要大人照顾”矛盾。"}, {"text": "健壮", "is_correct": false, "explanation": "体貌：“健壮”描写体格，不说“还健壮”，与“需要大人照顾”也不相符。"}], "explanations": {"未成年": "正确：“未成年”说年纪还小，需要大人照顾，与句意相符。", "成年": "语义：成年后一般不需要大人照顾，与后句“需要大人照顾”矛盾。", "独立": "语义：独立的人不需要大人照顾，与后句“需要大人照顾”矛盾。", "健壮": "体貌：“健壮”描写体格，不说“还健壮”，与“需要大人照顾”也不相符。"}, "sentence_index": 0, "correct_answer": "未成年"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他的未成年很快乐，常和朋友玩。", "explanation": "这里应该用〈童年〉。未成年指还没长大的状态，不指一段时期，那段时光要说“童年”。"}, {"text": "这台机器还未成年，所以总是出故障。", "explanation": "这里应该用〈调试〉。未成年只用于指人，机器应说“还没调试好”。"}, {"text": "这座新房子还未成年，还不能住人。", "explanation": "这里应该用〈竣工〉。未成年只用于指人，房子应说“还未竣工”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '884bc76d-2bca-4740-b392-561903b984d1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90707, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "未成年", "is_correct": true, "explanation": "正确：“未成年”说年纪小，与“平时只在家里玩”相符。"}, {"text": "外向", "is_correct": false, "explanation": "语义：外向的人爱外出活动，与“平时只在家里玩”矛盾。"}, {"text": "高大", "is_correct": false, "explanation": "体貌：“高大”说身材，与“平时只在家里玩”没有关系，且不说“还高大”。"}, {"text": "精明", "is_correct": false, "explanation": "语义：精明的人懂得谋生和外出办事，与“平时只在家里玩”不相符。"}], "explanations": {"未成年": "正确：“未成年”说年纪小，与“平时只在家里玩”相符。", "外向": "语义：外向的人爱外出活动，与“平时只在家里玩”矛盾。", "高大": "体貌：“高大”说身材，与“平时只在家里玩”没有关系，且不说“还高大”。", "精明": "语义：精明的人懂得谋生和外出办事，与“平时只在家里玩”不相符。"}, "sentence_index": 6, "correct_answer": "未成年"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这门语言还未成年，很多词还在变。", "explanation": "这里应该用〈发展〉。未成年只用于指人，语言应说“还在发展”。"}, {"text": "这座桥还未成年，还不能通车。", "explanation": "这里应该用〈建成〉。未成年只用于指人，桥应说“还没建成”。"}, {"text": "这家餐厅还未成年，还在试营业。", "explanation": "这里应该用〈开业〉。未成年只用于指人，餐厅应说“还没开业”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '884bc76d-2bca-4740-b392-561903b984d1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90707, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "那个未成年地男孩需要大人照顾。", "corrected_sentence": "那个未成年的男孩需要大人照顾。", "error_description": "错误：修饰名词要用“的”，不用“地”。应说“未成年的男孩”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '884bc76d-2bca-4740-b392-561903b984d1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90707, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这个孩子很未成年，所以还不懂事。", "corrected_sentence": "这个孩子未成年，所以还不懂事。", "error_description": "错误：“未成年”前不能加程度副词“很”。应说“这个孩子未成年”，去掉“很”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '884bc76d-2bca-4740-b392-561903b984d1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
