INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90708, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "还没有达到成年的法定年龄。", "primary_collocate": null, "pronunciation": "wèi chéng nián", "ipa": "wei˥˩ ʈʂʰəŋ˧˥ njɛn˧˥", "syllable_count": 3, "sentences": [{"text": "他还未成年，不能自己开车。", "target_word": "未成年", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "未成年的孩子不能进网吧。", "target_word": "未成年", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她今年才十六岁，还未成年。", "target_word": "未成年", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "法律上，未成年的学生不能结婚。", "target_word": "未成年", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "因为未成年，他不能买酒。", "target_word": "未成年", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个游戏不让未成年的孩子玩。", "target_word": "未成年", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "未成年的他不能签合同。", "target_word": "未成年", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们都未成年，不能一个人住酒店。", "target_word": "未成年", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "十七岁的哥哥还未成年。", "target_word": "未成年", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "未成年的客人请家长陪同。", "target_word": "未成年", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "未成年人", "label": "复合"}, {"form": "未成年的", "label": "复合"}], "register": "中性", "sense_fingerprint": "未成年：尚未达到法定成年年龄", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd3f4d125-09bd-4a29-83b8-15c3ccd853c7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90708, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "未成年", "is_correct": true, "explanation": "正确：“未成年”说明没到法定年龄，与“不能自己开车”相符。"}, {"text": "成年", "is_correct": false, "explanation": "语义：成年人可以自己开车，与后句“不能自己开车”矛盾。"}, {"text": "熟练", "is_correct": false, "explanation": "语义：“熟练”说明驾驶能力强，与“不能自己开车”矛盾。"}, {"text": "完整", "is_correct": false, "explanation": "搭配：“完整”不用来形容人的年龄或资格，“他还完整”不通。"}], "explanations": {"未成年": "正确：“未成年”说明没到法定年龄，与“不能自己开车”相符。", "成年": "语义：成年人可以自己开车，与后句“不能自己开车”矛盾。", "熟练": "语义：“熟练”说明驾驶能力强，与“不能自己开车”矛盾。", "完整": "搭配：“完整”不用来形容人的年龄或资格，“他还完整”不通。"}, "sentence_index": 0, "correct_answer": "未成年"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这个计划还未成年，需要再讨论。", "explanation": "这里应该用〈成熟〉。未成年只用于指人，指没到法定年龄；计划应说“还未成熟”。"}, {"text": "这家公司还未成年，不能参加招标。", "explanation": "这里应该用〈成立〉。未成年只用于指人，公司应说“还未成立”。"}, {"text": "这辆新车还未成年，现在还不能上路。", "explanation": "这里应该用〈上牌〉。未成年只用于指人，车应说“还没上牌”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '884bc76d-2bca-4740-b392-561903b984d1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90708, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "未成年", "is_correct": true, "explanation": "正确：“未成年”说明没到法定年龄，与“不能签合同”相符。"}, {"text": "老练", "is_correct": false, "explanation": "语义：“老练”说明能力强，与“不能签合同”矛盾。"}, {"text": "有钱", "is_correct": false, "explanation": "语义：有钱与能否签合同无关，“有钱的他不能签合同”不通。"}, {"text": "高大", "is_correct": false, "explanation": "体貌：“高大”说身材，与签合同的资格无关，句子不通。"}], "explanations": {"未成年": "正确：“未成年”说明没到法定年龄，与“不能签合同”相符。", "老练": "语义：“老练”说明能力强，与“不能签合同”矛盾。", "有钱": "语义：有钱与能否签合同无关，“有钱的他不能签合同”不通。", "高大": "体貌：“高大”说身材，与签合同的资格无关，句子不通。"}, "sentence_index": 6, "correct_answer": "未成年"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这盆花还未成年，还不能开花。", "explanation": "这里应该用〈长大〉。未成年只用于指人，植物应说“还没长大”。"}, {"text": "这次项目还未成年，还要等审批。", "explanation": "这里应该用〈启动〉。未成年只用于指人，项目应说“还未启动”。"}, {"text": "这套制度还未成年，还需要磨合。", "explanation": "这里应该用〈成熟〉。未成年只用于指人，制度应说“还不成熟”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '884bc76d-2bca-4740-b392-561903b984d1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90708, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这家店不卖酒给一个未成年。", "corrected_sentence": "这家店不卖酒给一个未成年人。", "error_description": "错误：“未成年”指人时要说“未成年人”。“一个未成年”不说，应说“一个未成年人”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '884bc76d-2bca-4740-b392-561903b984d1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90708, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "那位未成年地顾客需要家长陪同。", "corrected_sentence": "那位未成年的顾客需要家长陪同。", "error_description": "错误：修饰名词要用“的”，不用“地”。“地”用于修饰动词，应说“未成年的顾客”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '884bc76d-2bca-4740-b392-561903b984d1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
