INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90709, 1, 'prompt1_core', '{"pos": "量词", "semantic_class": "function", "definition": "两个在一起的人或东西。", "primary_collocate": null, "pronunciation": "yí duì", "ipa": "i˧˥ tweɪ˥˩", "syllable_count": 2, "sentences": [{"text": "公园里有一对老夫妻在散步。", "target_word": "一对", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "那一对年轻人走进了咖啡店。", "target_word": "一对", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们是一对好朋友。", "target_word": "一对", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们班有一对双胞胎。", "target_word": "一对", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "桌子旁边坐着一对母女。", "target_word": "一对", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "那一对情侣每天一起上班。", "target_word": "一对", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "门口站着一对小兄妹。", "target_word": "一对", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这是一对很幸福的夫妻。", "target_word": "一对", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "照片上是一对笑着的老人。", "target_word": "一对", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "一对新人正在拍照。", "target_word": "一对", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "两对", "label": "数量"}, {"form": "几对", "label": "数量"}], "register": "中性", "sense_fingerprint": "用于两个在一起的人，如夫妻、情侣、朋友", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3de9c1b0-5d2b-4ce9-8be1-a5bea4e21f01') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90709, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "一对", "is_correct": true, "explanation": "正确：yí duì，指两个在一起的人或东西。"}, {"text": "一堆", "is_correct": false, "explanation": "一堆读 yì duī，duī（第一声）与 duì（第四声）声调不同，意思是堆在一起的许多东西。"}, {"text": "一岁", "is_correct": false, "explanation": "一岁读 yí suì，suì 与 duì 同韵同调，仅声母不同（s 与 d）；意思是年龄满一岁。"}, {"text": "一退", "is_correct": false, "explanation": "「退」读 tuì，与 duì 仅声母送气与否不同，属最小对立对；「一退」指后退一次，与「一对」意义不同。"}], "explanations": {"一对": "正确：yí duì，指两个在一起的人或东西。", "一堆": "一堆读 yì duī，duī（第一声）与 duì（第四声）声调不同，意思是堆在一起的许多东西。", "一岁": "一岁读 yí suì，suì 与 duì 同韵同调，仅声母不同（s 与 d）；意思是年龄满一岁。", "一退": "「退」读 tuì，与 duì 仅声母送气与否不同，属最小对立对；「一退」指后退一次，与「一对」意义不同。"}, "sentence_index": null, "correct_answer": "一对"}, "level_3": {"options": [{"text": "一对", "is_correct": true, "explanation": "正确：“一对”指两个成对的人，老夫妻正是两个人成对。"}, {"text": "一只", "is_correct": false, "explanation": "搭配：“只”用于动物或单个物品，不能用来数人。"}, {"text": "一个", "is_correct": false, "explanation": "语义：“个”表示单个，与“老夫妻”指两人成对的意思相冲突。"}, {"text": "一把", "is_correct": false, "explanation": "搭配：“把”用于有柄的器具，不能用来计量老夫妻。"}], "explanations": {"一对": "正确：“一对”指两个成对的人，老夫妻正是两个人成对。", "一只": "搭配：“只”用于动物或单个物品，不能用来数人。", "一个": "语义：“个”表示单个，与“老夫妻”指两人成对的意思相冲突。", "一把": "搭配：“把”用于有柄的器具，不能用来计量老夫妻。"}, "sentence_index": 0, "correct_answer": "一对"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "教室里有一对窗户。", "explanation": "这里应该用〈一扇〉。窗户是单个的物件，用“扇”计量，不能用“一对”。"}, {"text": "他买了一对牛奶。", "explanation": "这里应该用〈一瓶〉或〈一盒〉。牛奶按容器计量，不能用“一对”。"}, {"text": "我们班有一对黑板。", "explanation": "这里应该用〈一块〉。黑板是单个的大件，用“块”计量，不能用“一对”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0ad29345-9e09-4401-9042-9607036c5fe7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90709, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "一对", "is_correct": true, "explanation": "正确：“一对”指成对的两个人，小兄妹正是两个人。"}, {"text": "一条", "is_correct": false, "explanation": "搭配：“条”用于细长的物件，不能用来数人。"}, {"text": "一棵", "is_correct": false, "explanation": "搭配：“棵”用于植物，与“小兄妹”是人不相符。"}, {"text": "一头", "is_correct": false, "explanation": "语义：“头”多用于牲畜，用来计量小兄妹不合适。"}], "explanations": {"一对": "正确：“一对”指成对的两个人，小兄妹正是两个人。", "一条": "搭配：“条”用于细长的物件，不能用来数人。", "一棵": "搭配：“棵”用于植物，与“小兄妹”是人不相符。", "一头": "语义：“头”多用于牲畜，用来计量小兄妹不合适。"}, "sentence_index": 6, "correct_answer": "一对"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "桌上摆着一对筷子。", "explanation": "这里应该用〈一双〉。筷子成双使用，用“双”计量；“一对”指两个在一起的人。"}, {"text": "他是一对很好的医生。", "explanation": "这里应该用〈一位〉。“一对”要求两个在一起的人或东西，只说一个人时要用〈一位〉。"}, {"text": "我买了一对面包。", "explanation": "这里应该用〈一个〉或〈一块〉。面包是单个的，不是成对的东西，不能用“一对”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0ad29345-9e09-4401-9042-9607036c5fe7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90709, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这位同学是一对恋人。", "corrected_sentence": "这两位同学是一对恋人。", "error_description": "错误形式「这位同学是一对恋人」；正确形式「这两位同学是一对恋人」。「一对」指两个成对的人，「这位同学」只指一人，二者不能搭配，应说「这两位同学」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0ad29345-9e09-4401-9042-9607036c5fe7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90709, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他是一对出色的舞伴。", "corrected_sentence": "他俩是一对出色的舞伴。", "error_description": "错误形式「他是一对出色的舞伴」；正确形式「他俩是一对出色的舞伴」。「一对」指两个成对的人，「他」只指一人，二者不能搭配，应说「他俩」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0ad29345-9e09-4401-9042-9607036c5fe7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
