INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90717, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "根是花草树木长在土里的部分，能吸水，让它们站稳。", "primary_collocate": null, "pronunciation": "gēn", "ipa": "kən˥", "syllable_count": 1, "sentences": [{"text": "花的根在土里。", "target_word": "根", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "根能吸水，让树站稳。", "target_word": "根", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "这种花的根很短，容易倒。", "target_word": "根", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "给花浇水要浇到根上。", "target_word": "根", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "种花的时候，要让根都在土里。", "target_word": "根", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "小草的根虽然细，但是能把草固定在地上。", "target_word": "根", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我把花拿出来一看，根已经黑了。", "target_word": "根", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "树的根太浅，大风一来就倒了。", "target_word": "根", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这棵树长得很高，因为根扎得深。", "target_word": "根", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "水太多，花的根会烂。", "target_word": "根", "complexity_tier": "T1", "sentence_source": "generated"}], "morphological_forms": [{"form": "条", "label": "量词"}, {"form": "树根", "label": "复合"}, {"form": "根须", "label": "复合"}], "register": "中性", "sense_fingerprint": "花草树木长在土里、能吸水并让植物站稳的部分", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '897c13e4-9594-468f-af81-93c04019cc00') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90717, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "根", "is_correct": true, "explanation": "根：读 gēn（第一声），指花草长在土里、吸水的部分。"}, {"text": "干", "is_correct": false, "explanation": "「gān（第一声）与 gēn 韵母不同，意思是干」。"}, {"text": "耕", "is_correct": false, "explanation": "「gēng（第一声）与 gēn 韵母不同（eng 与 en），意思是耕种」。"}, {"text": "奔", "is_correct": false, "explanation": "「bēn（第一声）与 gēn 声母不同（b 与 g），意思是跑」。"}], "explanations": {"根": "根：读 gēn（第一声），指花草长在土里、吸水的部分。", "干": "「gān（第一声）与 gēn 韵母不同，意思是干」。", "耕": "「gēng（第一声）与 gēn 韵母不同（eng 与 en），意思是耕种」。", "奔": "「bēn（第一声）与 gēn 声母不同（b 与 g），意思是跑」。"}, "sentence_index": null, "correct_answer": "根"}, "level_3": {"options": [{"text": "根", "is_correct": true, "explanation": "根：花长在土里的部分，「在土里」指的就是根，符合句意。"}, {"text": "叶", "is_correct": false, "explanation": "语义：「叶」长在枝上，不会在土里。"}, {"text": "花瓣", "is_correct": false, "explanation": "语义：「花瓣」长在花上，不会在土里。"}, {"text": "颜色", "is_correct": false, "explanation": "搭配：「颜色」不能指在土里的东西。"}], "explanations": {"根": "根：花长在土里的部分，「在土里」指的就是根，符合句意。", "叶": "语义：「叶」长在枝上，不会在土里。", "花瓣": "语义：「花瓣」长在花上，不会在土里。", "颜色": "搭配：「颜色」不能指在土里的东西。"}, "sentence_index": 0, "correct_answer": "根"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这朵花有一只根很短。", "explanation": "这里应该用〈条〉。根是细长的东西，量词用条；只有动物才用只。"}, {"text": "这个花瓶的根很稳。", "explanation": "这里应该用〈底部〉。说花瓶下面的部分要用底部，根只指植物长在土里的部分。"}, {"text": "我把花盆放在窗台的根下。", "explanation": "这里应该用〈底下〉。说窗台下面的位置要用底下，根不能指物体的下方。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '77fea57d-2c72-4f76-b2b2-2be0aacd67c3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90717, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "根", "is_correct": true, "explanation": "根：读 gēn（第一声），指花草长在土里、吸水的部分。"}, {"text": "奔", "is_correct": false, "explanation": "「bēn（第一声）与 gēn 声母不同（b 与 g），意思是跑」。"}, {"text": "羹", "is_correct": false, "explanation": "「gēng（第一声）与 gēn 韵母不同（eng 与 en），意思是汤羹」。"}, {"text": "甘", "is_correct": false, "explanation": "「gān（第一声）与 gēn 韵母不同（a 与 e），意思是甘甜」。"}], "explanations": {"根": "根：读 gēn（第一声），指花草长在土里、吸水的部分。", "奔": "「bēn（第一声）与 gēn 声母不同（b 与 g），意思是跑」。", "羹": "「gēng（第一声）与 gēn 韵母不同（eng 与 en），意思是汤羹」。", "甘": "「gān（第一声）与 gēn 韵母不同（a 与 e），意思是甘甜」。"}, "sentence_index": null, "correct_answer": "根"}, "level_3": {"options": [{"text": "根", "is_correct": true, "explanation": "根：花长在土里的部分，拿出来后会黑的是根，符合句意。"}, {"text": "味道", "is_correct": false, "explanation": "语义：「味道」是嗅觉或味觉的对象，不会变黑。"}, {"text": "声音", "is_correct": false, "explanation": "语义：「声音」是听觉的对象，不会变黑。"}, {"text": "年龄", "is_correct": false, "explanation": "搭配：「年龄」不能与「黑了」搭配。"}], "explanations": {"根": "根：花长在土里的部分，拿出来后会黑的是根，符合句意。", "味道": "语义：「味道」是嗅觉或味觉的对象，不会变黑。", "声音": "语义：「声音」是听觉的对象，不会变黑。", "年龄": "搭配：「年龄」不能与「黑了」搭配。"}, "sentence_index": 6, "correct_answer": "根"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他要做出根的改变。", "explanation": "这里应该用〈根本〉。修饰「改变」表示彻底要用根本，根只指植物的部分。"}, {"text": "这座铁塔的根很牢。", "explanation": "这里应该用〈地基〉。建筑物的基础要用地基，根只指植物长在土里的部分。"}, {"text": "这片田的根很肥沃。", "explanation": "这里应该用〈土壤〉。说土地的肥力要用土壤，根不能指土地。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '77fea57d-2c72-4f76-b2b2-2be0aacd67c3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90717, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这株花的根了烂。", "corrected_sentence": "这株花的根烂了。", "error_description": "错误：「了」的位置。正确：「烂了」。「了」要放在动词或形容词之后，不能放在「烂」前面。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '77fea57d-2c72-4f76-b2b2-2be0aacd67c3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90717, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "根草很细，能固定土壤。", "corrected_sentence": "草的根很细，能固定土壤。", "error_description": "错误：「根草」，修饰语序颠倒。正确：「草的根」。表示草的根部时，「草」要放在「根」前面修饰它，不能说「根草」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '77fea57d-2c72-4f76-b2b2-2be0aacd67c3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
