INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90718, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "植物生长在土里的部分，起固定和吸收养分的作用。", "primary_collocate": null, "pronunciation": "gēn", "ipa": "kən˥", "syllable_count": 1, "sentences": [{"text": "这棵树的根很深。", "target_word": "根", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "根在土里，我们看不见。", "target_word": "根", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "大树的根能吸收水和养分。", "target_word": "根", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "风很大，但是树的根抓得很紧。", "target_word": "根", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "草的根很细，却很长。", "target_word": "根", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "这盆花的根烂了，叶子都黄了。", "target_word": "根", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他用手把小树的根轻轻埋进土里。", "target_word": "根", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我看见路边的大树露着根。", "target_word": "根", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "根有固定树的作用，树才不会倒。", "target_word": "根", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "春天来了，树的根开始吸水。", "target_word": "根", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "条", "label": "量词"}, {"form": "树根", "label": "复合"}, {"form": "草根", "label": "复合"}, {"form": "根部", "label": "复合"}], "register": "中性", "sense_fingerprint": "植物长在土里、固定植株并吸收水分养分的部分", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '897c13e4-9594-468f-af81-93c04019cc00') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90718, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "根", "is_correct": true, "explanation": "根：读 gēn（第一声），指植物长在土里的部分。"}, {"text": "干", "is_correct": false, "explanation": "「gān（第一声）与 gēn 韵母不同，意思是干」。"}, {"text": "耕", "is_correct": false, "explanation": "「gēng（第一声）与 gēn 韵母不同（eng 与 en），意思是耕种」。"}, {"text": "奔", "is_correct": false, "explanation": "「bēn（第一声）与 gēn 声母不同（b 与 g），意思是跑」。"}], "explanations": {"根": "根：读 gēn（第一声），指植物长在土里的部分。", "干": "「gān（第一声）与 gēn 韵母不同，意思是干」。", "耕": "「gēng（第一声）与 gēn 韵母不同（eng 与 en），意思是耕种」。", "奔": "「bēn（第一声）与 gēn 声母不同（b 与 g），意思是跑」。"}, "sentence_index": null, "correct_answer": "根"}, "level_3": {"options": [{"text": "根", "is_correct": true, "explanation": "根：指树在土里的部分，与「很深」搭配，符合句意。"}, {"text": "叶", "is_correct": false, "explanation": "语义：「叶」长在枝上，不能用「深」来形容。"}, {"text": "花", "is_correct": false, "explanation": "搭配：「花」与「很深」不能搭配。"}, {"text": "果", "is_correct": false, "explanation": "语义：「果」长在枝头，不能用「深」来形容。"}], "explanations": {"根": "根：指树在土里的部分，与「很深」搭配，符合句意。", "叶": "语义：「叶」长在枝上，不能用「深」来形容。", "花": "搭配：「花」与「很深」不能搭配。", "果": "语义：「果」长在枝头，不能用「深」来形容。"}, "sentence_index": 0, "correct_answer": "根"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这棵树有一只根很深。", "explanation": "这里应该用〈条〉。根是细长的东西，量词用条；只有动物才用只。"}, {"text": "这把椅子的根很结实。", "explanation": "这里应该用〈腿〉。椅子下面支撑座面的部分叫腿，根只指植物长在土里的部分。"}, {"text": "我把书放在桌子的根下。", "explanation": "这里应该用〈底下〉。说桌子下面的位置要用底下，根不能指物体的下方。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '77fea57d-2c72-4f76-b2b2-2be0aacd67c3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90718, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "根", "is_correct": true, "explanation": "根：读 gēn（第一声），指植物长在土里的部分。"}, {"text": "奔", "is_correct": false, "explanation": "「bēn（第一声）与 gēn 声母不同（b 与 g），意思是跑」。"}, {"text": "羹", "is_correct": false, "explanation": "「gēng（第一声）与 gēn 韵母不同（eng 与 en），意思是汤羹」。"}, {"text": "甘", "is_correct": false, "explanation": "「gān（第一声）与 gēn 韵母不同（a 与 e），意思是甘甜」。"}], "explanations": {"根": "根：读 gēn（第一声），指植物长在土里的部分。", "奔": "「bēn（第一声）与 gēn 声母不同（b 与 g），意思是跑」。", "羹": "「gēng（第一声）与 gēn 韵母不同（eng 与 en），意思是汤羹」。", "甘": "「gān（第一声）与 gēn 韵母不同（a 与 e），意思是甘甜」。"}, "sentence_index": null, "correct_answer": "根"}, "level_3": {"options": [{"text": "根", "is_correct": true, "explanation": "根：树在土里的部分，「埋进土里」的是根，符合句意。"}, {"text": "花瓣", "is_correct": false, "explanation": "语义：「花瓣」是花的部分，不是小树的部分，不能埋进土里当作树根。"}, {"text": "石头", "is_correct": false, "explanation": "语义：小树没有「石头」这一部分，句中说的是树的部分。"}, {"text": "玻璃", "is_correct": false, "explanation": "搭配：「玻璃」不能说成「小树的玻璃」。"}], "explanations": {"根": "根：树在土里的部分，「埋进土里」的是根，符合句意。", "花瓣": "语义：「花瓣」是花的部分，不是小树的部分，不能埋进土里当作树根。", "石头": "语义：小树没有「石头」这一部分，句中说的是树的部分。", "玻璃": "搭配：「玻璃」不能说成「小树的玻璃」。"}, "sentence_index": 6, "correct_answer": "根"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我们要找到根的解决办法。", "explanation": "这里应该用〈根本〉。修饰「解决办法」表示彻底要用根本，根只指植物的部分。"}, {"text": "这座雕像的根很稳。", "explanation": "这里应该用〈底座〉。雕像的底部要用底座，根只指植物长在土里的部分。"}, {"text": "这块地的根很肥。", "explanation": "这里应该用〈土壤〉。说土地的肥力要用土壤，根不能指土地。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '77fea57d-2c72-4f76-b2b2-2be0aacd67c3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90718, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这棵小草有一只很短的根。", "corrected_sentence": "这棵小草有一条很短的根。", "error_description": "错误：量词「只」。正确：量词「条」。根是细长的东西，量词用「条」，「只」一般用于动物。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '77fea57d-2c72-4f76-b2b2-2be0aacd67c3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90718, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这棵大树的根树很粗。", "corrected_sentence": "这棵大树的树根很粗。", "error_description": "错误：「根树」。正确：「树根」。表示树的根时要用复合词「树根」，语序不能颠倒。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '77fea57d-2c72-4f76-b2b2-2be0aacd67c3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90727, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "收", "is_correct": true, "explanation": "收与付相对：付是把钱给出去，收是接过钱来。"}, {"text": "吃", "is_correct": false, "explanation": "“吃”是进食的动作，与“付”的给钱之义没有反义关系。"}, {"text": "唱", "is_correct": false, "explanation": "“唱”指发声演唱，与“付”没有反义关系。"}, {"text": "睡", "is_correct": false, "explanation": "“睡”指闭眼休息，与“付”没有反义关系。"}], "correct_answer": "收", "explanations": {"收": "收与付相对：付是把钱给出去，收是接过钱来。", "吃": "“吃”是进食的动作，与“付”的给钱之义没有反义关系。", "唱": "“唱”指发声演唱，与“付”没有反义关系。", "睡": "“睡”指闭眼休息，与“付”没有反义关系。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5e9b95af-f526-4674-ab65-567f5b1a2aea') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90727, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "收", "is_correct": true, "explanation": "收与付相对：付是把钱给出去，收是接过钱来。"}, {"text": "跑", "is_correct": false, "explanation": "“跑”指快速移动，与“付”没有反义关系。"}, {"text": "笑", "is_correct": false, "explanation": "“笑”指表情或声音的流露，与“付”没有反义关系。"}, {"text": "写", "is_correct": false, "explanation": "“写”指记录文字，与“付”没有反义关系。"}], "correct_answer": "收", "explanations": {"收": "收与付相对：付是把钱给出去，收是接过钱来。", "跑": "“跑”指快速移动，与“付”没有反义关系。", "笑": "“笑”指表情或声音的流露，与“付”没有反义关系。", "写": "“写”指记录文字，与“付”没有反义关系。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5e9b95af-f526-4674-ab65-567f5b1a2aea') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90727, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "把钱给别人，买东西或请人做事。", "primary_collocate": null, "pronunciation": "fù", "ipa": "fu˥˩", "syllable_count": 1, "sentences": [{"text": "今天吃饭我来付。", "target_word": "付", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你想用现金付，还是用手机付？", "target_word": "付", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "师傅修好车，我就付了钱。", "target_word": "付", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你付了钱，老板才会给你东西。", "target_word": "付", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他请了一位老师，每个月付她工资。", "target_word": "付", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "在这家店可以用手机付钱。", "target_word": "付", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "谁付钱，谁就可以选餐厅。", "target_word": "付", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "出租车到了，我付钱下了车。", "target_word": "付", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "朋友帮我搬家，我想付他一点钱。", "target_word": "付", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她付了钱，拿着买好的书走了。", "target_word": "付", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "付了", "label": "体标"}, {"form": "付过", "label": "体标"}, {"form": "付费", "label": "复合"}], "register": "中性", "sense_fingerprint": "为买东西或请人做事而把钱给别人", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '91fb0def-17e1-49a7-8369-e06c80e75a82') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90727, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "付", "is_correct": true, "explanation": "付是正确答案，指把钱给别人以买东西或请人做事。"}, {"text": "夫", "is_correct": false, "explanation": "fū（第一声）与 fù（第四声）声调不同，意思是丈夫。"}, {"text": "府", "is_correct": false, "explanation": "fǔ（第三声）与 fù（第四声）声调不同，意思是政府、府第。"}, {"text": "户", "is_correct": false, "explanation": "h 与 f 声母不同，两者都是第四声，意思是户口、家庭。"}, {"text": "物", "is_correct": false, "explanation": "w 与 f 声母不同，两者都是第四声，意思是东西、物品。"}], "explanations": {"付": "付是正确答案，指把钱给别人以买东西或请人做事。", "夫": "fū（第一声）与 fù（第四声）声调不同，意思是丈夫。", "府": "fǔ（第三声）与 fù（第四声）声调不同，意思是政府、府第。", "户": "h 与 f 声母不同，两者都是第四声，意思是户口、家庭。", "物": "w 与 f 声母不同，两者都是第四声，意思是东西、物品。"}, "sentence_index": null, "correct_answer": "付"}, "level_3": {"options": [{"text": "付", "is_correct": true, "explanation": "正确：付指把钱给别人，与“吃饭”“我来”的付钱场合相合。"}, {"text": "踢", "is_correct": false, "explanation": "语义：“踢”指用脚击打，与饭局付钱无关。"}, {"text": "摔", "is_correct": false, "explanation": "语义：“摔”指跌落，与付钱的意思不合。"}, {"text": "咬", "is_correct": false, "explanation": "搭配：“咬”不能与付钱的场合搭配，不能说咬钱。"}], "explanations": {"付": "正确：付指把钱给别人，与“吃饭”“我来”的付钱场合相合。", "踢": "语义：“踢”指用脚击打，与饭局付钱无关。", "摔": "语义：“摔”指跌落，与付钱的意思不合。", "咬": "搭配：“咬”不能与付钱的场合搭配，不能说咬钱。"}, "sentence_index": 0, "correct_answer": "付"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我付大家一个好消息。", "explanation": "这里应该用〈告诉〉。付只表示把钱交出去，传递消息要说告诉，不能说付。"}, {"text": "老师付我们英语。", "explanation": "这里应该用〈教〉。付不能用于传授知识。"}, {"text": "妈妈付我逛了一下午街。", "explanation": "这里应该用〈陪〉。付只能指付钱，不能表示陪伴。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5e9b95af-f526-4674-ab65-567f5b1a2aea') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90727, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "付", "is_correct": true, "explanation": "付是正确答案，指把钱给别人以买东西或请人做事。"}, {"text": "服", "is_correct": false, "explanation": "fú（第二声）与 fù（第四声）声调不同，意思是服从、衣服。"}, {"text": "护", "is_correct": false, "explanation": "h 与 f 声母不同，两者都是第四声，意思是保护。"}, {"text": "务", "is_correct": false, "explanation": "w 与 f 声母不同，两者都是第四声，意思是事务、任务。"}, {"text": "辅", "is_correct": false, "explanation": "fǔ（第三声）与 fù（第四声）声调不同，意思是辅助。"}], "explanations": {"付": "付是正确答案，指把钱给别人以买东西或请人做事。", "服": "fú（第二声）与 fù（第四声）声调不同，意思是服从、衣服。", "护": "h 与 f 声母不同，两者都是第四声，意思是保护。", "务": "w 与 f 声母不同，两者都是第四声，意思是事务、任务。", "辅": "fǔ（第三声）与 fù（第四声）声调不同，意思是辅助。"}, "sentence_index": null, "correct_answer": "付"}, "level_3": {"options": [{"text": "付", "is_correct": true, "explanation": "正确：付指把钱给别人，与“谁”“钱”“选餐厅”的付钱语境相合。"}, {"text": "吐", "is_correct": false, "explanation": "搭配：“吐”不能与钱款搭配，不能说吐钱。"}, {"text": "掐", "is_correct": false, "explanation": "语义：“掐”指用指甲夹住，与付钱无关。"}, {"text": "踩", "is_correct": false, "explanation": "语义：“踩”指用脚压住，与付钱无关。"}], "explanations": {"付": "正确：付指把钱给别人，与“谁”“钱”“选餐厅”的付钱语境相合。", "吐": "搭配：“吐”不能与钱款搭配，不能说吐钱。", "掐": "语义：“掐”指用指甲夹住，与付钱无关。", "踩": "语义：“踩”指用脚压住，与付钱无关。"}, "sentence_index": 6, "correct_answer": "付"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "她付了我一封信。", "explanation": "这里应该用〈写〉。付表示把钱交出去，写信要说写，不能说付。"}, {"text": "她付了我一个问题。", "explanation": "这里应该用〈问〉。付只用于钱款，提问题要说问，不能说付。"}, {"text": "她付了我一个电话。", "explanation": "这里应该用〈打〉。付只表示把钱交出去，打电话要说打，不能说付。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5e9b95af-f526-4674-ab65-567f5b1a2aea') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90727, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我以前付了过房租。", "corrected_sentence": "我以前付过房租。", "error_description": "错误在“过”前多加了“了”。“付过”表示曾经有过的经历，中间不能插入“了”，应说“以前付过房租”，不能说“付了过房租”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5e9b95af-f526-4674-ab65-567f5b1a2aea') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90727, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我把车费付了司机。", "corrected_sentence": "我把车费付给了司机。", "error_description": "错误在于漏掉了“给”。付钱给某人时要说“付给”，应说“付给了司机”，不能说“付了司机”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5e9b95af-f526-4674-ab65-567f5b1a2aea') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
